BOOL runtimeProjectedPtInRect(const RuntimeInputPixelRect& rect, POINT point) {
    const RECT nativeRect = runtimeRenderPlacementNativeRect(rect);
    return ::PtInRect(&nativeRect, point);
}

BOOL runtimeProjectedEqualRect(const RuntimeInputPixelRect& left, const RECT& right) {
    const RECT nativeLeft = runtimeRenderPlacementNativeRect(left);
    return ::EqualRect(&nativeLeft, &right);
}

BOOL runtimeProjectedEqualRect(const RuntimeInputPixelRect& left,
    const RuntimeInputPixelRect& right) {
    return runtimeProjectedEqualRect(left, runtimeRenderPlacementNativeRect(right));
}


BOOL runtimeProjectedIntersectRect(RECT& out, const RuntimeInputPixelRect& left,
    const RECT& right) {
    const RECT nativeLeft = runtimeRenderPlacementNativeRect(left);
    return ::IntersectRect(&out, &nativeLeft, &right);
}

BOOL runtimeProjectedIntersectRect(RECT& out, const RuntimeInputPixelRect& left,
    const RuntimeInputPixelRect& right) {
    return runtimeProjectedIntersectRect(out, left, runtimeRenderPlacementNativeRect(right));
}



