// A palette lookup may probe several files. Share it only within a paint or
// simulation batch, so the next batch still observes changed resources.








std::wstring widenRuntimeSubtitleText(const std::string& value) {
    if (value.empty()) {
        return L"";
    }

    int required = MultiByteToWideChar(
        CP_UTF8,
        MB_ERR_INVALID_CHARS,
        value.data(),
        static_cast<int>(value.size()),
        nullptr,
        0
    );
    UINT codePage = CP_UTF8;
    DWORD flags = MB_ERR_INVALID_CHARS;
    if (required <= 0) {
        // Retail evamd.ini is Windows-1252 and contains smart punctuation in
        // Text=. Keep UTF-8 mod text intact, but decode the original fallback
        // explicitly rather than through the machine's locale-dependent ACP.
        codePage = 1252;
        flags = 0;
        required = MultiByteToWideChar(
            codePage,
            flags,
            value.data(),
            static_cast<int>(value.size()),
            nullptr,
            0
        );
    }
    if (required <= 0) {
        return std::wstring(value.begin(), value.end());
    }

    std::wstring result(static_cast<std::size_t>(required), L'\0');
    MultiByteToWideChar(
        codePage,
        flags,
        value.data(),
        static_cast<int>(value.size()),
        result.data(),
        required
    );
    return result;
}



std::string formatBool(bool value) {
    return value ? "yes" : "no";
}

std::string formatBytes(std::uintmax_t bytes) {
    constexpr double kib = 1024.0;
    const char* units[] = {"B", "KiB", "MiB", "GiB"};

    double value = static_cast<double>(bytes);
    int unitIndex = 0;
    while (value >= kib && unitIndex < 3) {
        value /= kib;
        ++unitIndex;
    }

    std::ostringstream stream;
    if (unitIndex == 0) {
        stream << bytes << " " << units[unitIndex];
    } else {
        stream << std::fixed << std::setprecision(1)
               << value << " " << units[unitIndex];
    }
    return stream.str();
}

std::wstring formatRuntimeMs(double value) {
    std::wostringstream stream;
    stream << std::fixed << std::setprecision(1) << value;
    return stream.str();
}

std::string formatResourceCoverage(const ResourceMountReport& resources) {
    return "rules=" + formatBool(resources.hasRules)
        + " art=" + formatBool(resources.hasArt)
        + " maps=" + formatBool(resources.hasMaps)
        + " theater=" + formatBool(resources.hasTheaterIni)
        + " palette=" + formatBool(resources.hasPalette)
        + " mix=" + formatBool(resources.hasMix);
}

std::string formatLayerCounts(const ResourceMountLayerReport& layer) {
    return "files=" + std::to_string(layer.fileCount)
        + " mix=" + std::to_string(layer.mixCount)
        + " ini=" + std::to_string(layer.iniCount)
        + " map=" + std::to_string(layer.mapCount)
        + " pal=" + std::to_string(layer.palCount)
        + " shp=" + std::to_string(layer.shpCount)
        + " tmp=" + std::to_string(layer.tmpCount)
        + " vxl=" + std::to_string(layer.vxlCount)
        + " hva=" + std::to_string(layer.hvaCount);
}

std::string formatMapDimensions(const RuntimeMapSummary& map) {
    if (map.width < 0 || map.height < 0) {
        return "-";
    }

    return std::to_string(map.width) + "x" + std::to_string(map.height);
}

std::string formatWorldBounds(const GameWorldSummary& world) {
    if (world.minCellX < 0
        || world.minCellY < 0
        || world.maxCellX < 0
        || world.maxCellY < 0) {
        return "-";
    }

    return std::to_string(world.minCellX)
        + ","
        + std::to_string(world.minCellY)
        + " -> "
        + std::to_string(world.maxCellX)
        + ","
        + std::to_string(world.maxCellY);
}











