struct RuntimeTiberiumScanRuleExpectation {
    bool loaded = false;
    int shortScan = 0;
    int longScan = 0;
};

RuntimeTiberiumScanRuleExpectation loadRuntimeTiberiumScanRuleExpectation(
    const RuntimeConfig& config
) {
    RuntimeTiberiumScanRuleExpectation expectation;
    IniFile rulesIni;
    if (!loadRuntimeIniSource(
            config,
            RuntimeCampaignIniKind::Rules,
            rulesIni
        )) {
        return expectation;
    }

    const int shortScan = parseRuntimeIntOrDefault(
        rulesIni.getValue("General", "TiberiumShortScan", ""),
        -1
    );
    const int longScan = parseRuntimeIntOrDefault(
        rulesIni.getValue("General", "TiberiumLongScan", ""),
        -1
    );
    if (shortScan <= 0 || longScan <= 0) {
        return expectation;
    }

    expectation.loaded = true;
    expectation.shortScan = shortScan;
    expectation.longScan = std::max(shortScan, longScan);
    return expectation;
}

std::string resolveRuntimeArtPath(const RuntimeConfig& config) {
    return resolveRuntimeIniSource(
        config,
        RuntimeCampaignIniKind::Art
    ).displayPath;
}













std::string runtimeRenderSmokeOwner() {
    std::string smokeOwner = "Americans";
    if (const char* rawOwner = std::getenv("CONCORD_RENDER_SMOKE_OWNER")) {
        const std::string parsedOwner = trimAsciiLocal(rawOwner);
        if (!parsedOwner.empty()) {
            smokeOwner = parsedOwner;
        }
    }
    return smokeOwner;
}

COLORREF runtimeRemapColorFromToken(
    const RuntimeConfig& config,
    const std::string& colorToken,
    COLORREF fallback
) {
    const RuntimeOwnerRemapColorTable colorTable =
        loadRuntimeRemapColorTable(config);
    const std::string colorKey = toLowerAsciiLocal(colorToken);
    const auto found = colorTable.find(colorKey);
    if (found != colorTable.end()) {
        return found->second;
    }

    const std::optional<COLORREF> inlineColor =
        runtimeColorFromHsvString(colorToken);
    if (inlineColor.has_value()) {
        return *inlineColor;
    }

    return fallback;
}

COLORREF runtimeRenderSmokeRemapColor(const RuntimeConfig& config) {
    std::string colorToken = "DarkBlue";
    if (const char* rawColor = std::getenv("CONCORD_RENDER_SMOKE_REMAP")) {
        const std::string parsedColor = trimAsciiLocal(rawColor);
        if (!parsedColor.empty()) {
            colorToken = parsedColor;
        }
    }

    return runtimeRemapColorFromToken(
        config,
        colorToken,
        RGB(74, 135, 220)
    );
}

std::string resolveRuntimeTheaterPath(
    const RuntimeConfig& config,
    const std::string& mapTheater
) {
    return resolveRuntimeCampaignTheaterSource(
        runtimeCampaignDataSourceOptions(config),
        mapTheater
    ).displayPath;
}







std::string runtimeIniSectionValueNoCase(
    const IniFile::Section* section,
    const std::string& wanted,
    const std::string& fallback = ""
) {
    if (section == nullptr) {
        return fallback;
    }
    const std::string key = toUpperAsciiLocal(trimAsciiLocal(wanted));
    for (auto it = section->rbegin(); it != section->rend(); ++it) {
        if (toUpperAsciiLocal(trimAsciiLocal(it->first)) == key) {
            return trimAsciiLocal(it->second);
        }
    }
    return fallback;
}



std::vector<std::string> buildRuntimeTextLines(
    const RuntimeConfig& config,
    const RuntimeStartupReport& report,
    int tick,
    double fps
) {
    std::vector<std::string> lines;
    lines.push_back("ConcordRTS Runtime Shell");
    lines.push_back("status: Phase 17 resource mounting shell");
    lines.push_back("tick: " + std::to_string(tick));
    lines.push_back("fps: " + std::to_string(static_cast<int>(fps + 0.5)));
    lines.push_back("fixed tick hz: " + std::to_string(config.fixedTickHz));
    lines.push_back("target fps: " + std::to_string(config.targetFps));
    lines.push_back("config: " + report.configPath
        + " loaded=" + formatBool(report.configFileLoaded));
    lines.push_back("resource root: " + report.resourceRootPath
        + " exists=" + formatBool(report.resourceRootExists));
    lines.push_back("local data root: " + report.localDataRootPath
        + " exists=" + formatBool(report.localDataRootExists));
    if (!report.modRootPath.empty()) {
        lines.push_back("mod root: " + report.modRootPath
            + " exists=" + formatBool(report.modRootExists));
    }
    lines.push_back("resource layers: "
        + std::to_string(report.resources.existingLayerCount)
        + "/"
        + std::to_string(report.resources.mountedLayerCount)
        + " existing, files="
        + std::to_string(report.resources.totalFiles)
        + ", bytes="
        + formatBytes(report.resources.totalBytes));
    lines.push_back("resource counts: mix="
        + std::to_string(report.resources.totalMixFiles)
        + " ini="
        + std::to_string(report.resources.totalIniFiles)
        + " map="
        + std::to_string(report.resources.totalMapFiles)
        + " pal="
        + std::to_string(report.resources.totalPalFiles)
        + " shp="
        + std::to_string(report.resources.totalShpFiles)
        + " tmp="
        + std::to_string(report.resources.totalTmpFiles)
        + " vxl="
        + std::to_string(report.resources.totalVxlFiles)
        + " hva="
        + std::to_string(report.resources.totalHvaFiles));
    lines.push_back("resource coverage: "
        + formatResourceCoverage(report.resources));
    lines.push_back("map: " + report.map.path);
    lines.push_back("map loaded: " + formatBool(report.map.loaded));
    lines.push_back("rules: " + formatMaybe(report.rulesPath)
        + " loaded=" + formatBool(report.rulesLoaded));
    lines.push_back("art: " + formatMaybe(report.artPath)
        + " loaded=" + formatBool(report.artLoaded));
    lines.push_back("theater ini: " + formatMaybe(report.theaterPath)
        + " loaded=" + formatBool(report.theaterLoaded));

    if (report.map.loaded) {
        lines.push_back("map name: " + formatMaybe(report.map.name));
        lines.push_back("theater: " + formatMaybe(report.map.theater));
        lines.push_back("header bounds: " + formatMapDimensions(report.map));
        lines.push_back("local size: " + formatMaybe(report.map.localSize));
        lines.push_back("iso tiles: " + std::to_string(report.map.isoTiles));
        lines.push_back("overlay cells: " + std::to_string(report.map.overlayCells));
        lines.push_back("objects: structures="
            + std::to_string(report.map.structures)
            + " units="
            + std::to_string(report.map.units)
            + " infantry="
            + std::to_string(report.map.infantry));
        lines.push_back("triggers: " + std::to_string(report.map.triggers));
    }

    lines.push_back("world loaded: " + formatBool(report.world.loaded));
    if (report.world.loaded) {
        lines.push_back("world counts match map: "
            + formatBool(report.world.countsMatchMap));
        lines.push_back("world cells: terrain="
            + std::to_string(report.world.terrainCells)
            + " overlay="
            + std::to_string(report.world.overlayCells)
            + " ore="
            + std::to_string(report.world.overlayOreCells)
            + " gems="
            + std::to_string(report.world.overlayGemCells));
        lines.push_back("world objects: terrain="
            + std::to_string(report.world.terrainObjects)
            + " structures="
            + std::to_string(report.world.structures)
            + " units="
            + std::to_string(report.world.units)
            + " infantry="
            + std::to_string(report.world.infantry)
            + " total="
            + std::to_string(report.world.objectInstances));
        lines.push_back("world players: "
            + std::to_string(report.world.players)
            + " waypoints="
            + std::to_string(report.world.waypoints)
            + " bounds="
            + formatWorldBounds(report.world));
    }

    if (!report.warnings.empty()) {
        lines.push_back("warnings:");
        for (const std::string& warning : report.warnings) {
            lines.push_back("  - " + warning);
        }
    }

    lines.push_back("");
    lines.push_back("Phase 19 renderer active:");
    lines.push_back("arrow keys / WASD scroll the runtime map view");
    lines.push_back("TMP terrain, SHP objects, VXL sprites, lighting, shadows, and z-order are enabled.");
    return lines;
}

