void resetRuntimePerfPeaks(RuntimePerfCounters& perf) {
    perf.peakSimulationMs = 0.0;
    perf.peakSimMoveMs = 0.0;
    perf.peakSimPathMs = 0.0;
    perf.peakSimRepathCount = 0;
    perf.peakSimPathRequests = 0;
    perf.peakWorldObjectsMs = 0.0;
    perf.peakWorldObjectSortMs = 0.0;
}

void updateRuntimeSimulationPerfPeaks(RuntimePerfCounters& perf) {
    perf.peakSimulationMs =
        std::max(perf.peakSimulationMs, perf.lastSimulationMs);
    perf.peakSimMoveMs =
        std::max(perf.peakSimMoveMs, perf.lastSimMoveMs);
    perf.peakSimPathMs =
        std::max(perf.peakSimPathMs, perf.lastSimPathMs);
    perf.peakSimRepathCount =
        std::max(perf.peakSimRepathCount, perf.lastSimRepathCount);
    perf.peakSimPathRequests =
        std::max(perf.peakSimPathRequests, perf.lastSimPathRequests);
}

double runtimeLastMeasuredSimulationMs(const RuntimePerfCounters& perf) {
    return perf.lastSimEffectsMs
        + perf.lastSimEconomyMs
        + perf.lastSimTriggersMs
        + perf.lastSimBuildMs
        + perf.lastSimGuardMs
        + perf.lastSimMoveMs
        + perf.lastSimAttackMs;
}

void updateRuntimeRenderPerfPeaks(
    RuntimePerfCounters& perf,
    const RuntimeMapRenderStats& stats
) {
    perf.peakWorldObjectsMs =
        std::max(perf.peakWorldObjectsMs, stats.worldObjectsMs);
    perf.peakWorldObjectSortMs =
        std::max(perf.peakWorldObjectSortMs, stats.worldObjectSortMs);
}


