void refreshRuntimeParticleRenderSnapshots(
    RuntimeWindowState& state,
    RuntimeMapRenderContext& context
) {
    ensureRuntimeParticlesInitialized(state);
    state.particleRenderSnapshots = state.particles.renderSnapshots(
        state.rules,
        state.artLoaded ? &state.art : nullptr
    );
    state.particleBeamRenderSnapshots =
        state.particles.beamSnapshots(state.rules);
    state.particleLocalLightRenderSnapshots =
        state.particles.localLightSnapshots(state.rules);
    context.particleSnapshots = &state.particleRenderSnapshots;
    context.particleBeamSnapshots = &state.particleBeamRenderSnapshots;
    context.localLightSnapshots = &state.particleLocalLightRenderSnapshots;
}

















































































