RECT runtimeSidebarRect(const RECT& clientRect) {
    const auto sidebar = runtimeInputPixelSidebarRect(
        {clientRect.left, clientRect.top, clientRect.right, clientRect.bottom},
        runtimeSidebarWidth);
    return {sidebar.left, sidebar.top, sidebar.right, sidebar.bottom};
}

RECT runtimeRadarRect(const RECT& sidebar) {
    return {
        sidebar.left,
        sidebar.top + runtimeSidebarRadarOffset,
        sidebar.right,
        sidebar.top + runtimeSidebarRadarOffset + runtimeSidebarRadarHeight
    };
}

RECT runtimeRadarInteriorRect(const RECT& radarRect) {
    return {
        radarRect.left + 13,
        radarRect.top,
        radarRect.right - 15,
        radarRect.bottom
    };
}

int runtimeSidebarRepeaterCount(const RECT& sidebar) {
    const int sidebarHeight =
        std::max(0, static_cast<int>(sidebar.bottom - sidebar.top));
    const int availableHeight = std::max(
        0,
        sidebarHeight
            - runtimeSidebarListOffset
            - runtimeSidebarSide3Height
            - runtimeSidebarAddonHeight
    );
    return availableHeight / runtimeSidebarSide2Height;
}

int runtimeSidebarListBottom(const RECT& sidebar) {
    return std::min<int>(
        sidebar.bottom,
        sidebar.top
            + runtimeSidebarListOffset
            + (runtimeSidebarRepeaterCount(sidebar) * runtimeSidebarSide2Height)
    );
}

int runtimeSidebarSide3Top(const RECT& sidebar) {
    return runtimeSidebarListBottom(sidebar);
}

bool ensureRuntimeCameoPalette(RuntimeWindowState& state);
bool pointInRectInclusive(const RECT& rect, POINT point);

int runtimeSidebarAddonTop(const RECT& sidebar) {
    return std::min<int>(
        sidebar.bottom,
        runtimeSidebarSide3Top(sidebar) + runtimeSidebarSide3Height
    );
}

std::vector<const SuperWeaponSidebarSnapshot*> runtimeVisibleSuperWeapons(
    const RuntimeWindowState& state
) {
    std::vector<const SuperWeaponSidebarSnapshot*> visible;
    const std::string owner = toLowerAsciiLocal(trimAsciiLocal(state.economy.owner));
    for (const SuperWeaponSidebarSnapshot& snapshot :
            state.superWeapons.sidebarSnapshots()) {
        if (!owner.empty()
            && toLowerAsciiLocal(trimAsciiLocal(snapshot.owner)) != owner) {
            continue;
        }
        const SuperWeaponRule* rule = state.rules.findSuperWeaponType(
            snapshot.superWeaponId
        );
        if (rule != nullptr && rule->postClick) {
            continue;
        }
        visible.push_back(&snapshot);
    }
    return visible;
}

bool runtimeSuperWeaponTimerVisible(
    const SuperWeaponSidebarSnapshot& snapshot
) {
    return snapshot.showTimer
        && snapshot.state != SuperWeaponRuntimeState::Unavailable;
}

int runtimeSuperWeaponRemainingSeconds(
    const SuperWeaponSidebarSnapshot& snapshot,
    int fixedTickHz
) {
    const int hz = std::max(1, fixedTickHz);
    const long long remaining = std::max(0, snapshot.remainingTicks);
    return static_cast<int>(std::min<long long>(
        std::numeric_limits<int>::max(),
        (remaining + hz - 1LL) / hz
    ));
}

int runtimeSuperWeaponTargetRingCount(
    const SuperWeaponSidebarSnapshot& snapshot
) {
    return 1 + std::max(0, snapshot.targetLineMultiplier);
}

int runtimeSuperWeaponFlashDurationTicks(
    int authoredFrames,
    int fixedTickHz
) {
    if (authoredFrames < 0) {
        return -1;
    }
    if (authoredFrames == 0) {
        return 0;
    }
    return std::max(
        1,
        static_cast<int>(std::llround(
            static_cast<double>(authoredFrames)
                * static_cast<double>(std::max(1, fixedTickHz))
                / 15.0
        ))
    );
}

bool runtimeSuperWeaponShouldFlashSidebarTab(
    const SuperWeaponSidebarSnapshot& snapshot,
    int tick,
    int fixedTickHz
) {
    if (snapshot.state != SuperWeaponRuntimeState::Ready
        || snapshot.flashSidebarTabFrames == 0) {
        return false;
    }
    const int elapsed = tick - snapshot.stateStartTick;
    if (elapsed < 0) {
        return false;
    }
    const int duration = runtimeSuperWeaponFlashDurationTicks(
        snapshot.flashSidebarTabFrames,
        fixedTickHz
    );
    return duration < 0 || elapsed < duration;
}

bool runtimeSuperWeaponFlashHighlightPhase(int tick, int fixedTickHz) {
    const int phaseTicks = std::max(1, std::max(1, fixedTickHz) / 4);
    return ((std::max(0, tick) / phaseTicks) % 2) == 0;
}

bool runtimeDefenseSidebarTabShouldFlash(const RuntimeWindowState& state) {
    if (state.activeBuildTab == RuntimeBuildKind::Defense) {
        return false;
    }
    for (const SuperWeaponSidebarSnapshot* snapshot :
            runtimeVisibleSuperWeapons(state)) {
        if (snapshot != nullptr
            && runtimeSuperWeaponShouldFlashSidebarTab(
                *snapshot,
                state.tick,
                state.config.fixedTickHz
            )) {
            return true;
        }
    }
    return false;
}

RuntimeCameoIconCacheEntry* loadRuntimeSuperWeaponIcon(
    RuntimeWindowState& state,
    const SuperWeaponSidebarSnapshot& snapshot
) {
    const std::string cacheKey =
        toLowerAsciiLocal(snapshot.superWeaponId)
        + "|"
        + toLowerAsciiLocal(snapshot.sidebarImage)
        + "|"
        + runtimeAssetRootPath(state.config);
    auto [it, inserted] = state.superWeaponIconsByKey.try_emplace(cacheKey);
    RuntimeCameoIconCacheEntry& entry = it->second;
    if (entry.loadAttempted) {
        return entry.loaded ? &entry : nullptr;
    }
    (void)inserted;
    entry.loadAttempted = true;
    if (snapshot.sidebarImage.empty() || !ensureRuntimeCameoPalette(state)) {
        entry.errorMessage = snapshot.sidebarImage.empty()
            ? "missing SidebarImage"
            : "missing cameo palette";
        return nullptr;
    }
    RuntimeMapRenderContext renderContext;
    renderContext.theater = state.theaterLoaded ? &state.theater : nullptr;
    renderContext.art = state.artLoaded ? &state.art : nullptr;
    renderContext.rules = state.rulesLoaded ? &state.rules : nullptr;
    renderContext.mapFacts = state.mapFactsLoaded ? &state.mapFacts : nullptr;
    renderContext.tileRootPath = runtimeTileRootPath(state.config, state.report.map);
    renderContext.palettePath = runtimePalettePath(state.config, state.report.map);
    renderContext.assetRootPath = runtimeAssetRootPath(state.config);
    renderContext.structureRootPath = runtimeStructureRootPath(state.config, state.report.map);
    renderContext.structurePalettePath = runtimeStructurePalettePath(state.config, state.report.map);
    renderContext.animationTick = state.tick;
    renderContext.fixedTickHz = state.config.fixedTickHz;
    std::string resolvedImageId;
    std::string sourcePath;
    std::string errorMessage;
    if (!loadRuntimeAuxiliaryShpFrameImage(
            renderContext,
            state.renderCache,
            snapshot.sidebarImage,
            0,
            entry.image,
            resolvedImageId,
            sourcePath,
            errorMessage
        )) {
        entry.errorMessage = errorMessage;
        return nullptr;
    }
    entry.loaded = true;
    entry.cameoId = resolvedImageId.empty()
        ? snapshot.sidebarImage
        : resolvedImageId;
    entry.sourcePath = sourcePath;
    return &entry;
}

constexpr int runtimeRadarFrameCount = 33;
constexpr int runtimeRadarFrameDurationMs = 50;

int runtimeRadarTransitionFrame(const RuntimeWindowState& state) {
    if (state.runtimeRadarTransitionDirection == 0
        || state.runtimeRadarTransitionStartTick < 0) {
        return -1;
    }

    const long long elapsedTicks =
        std::max(0, state.tick - state.runtimeRadarTransitionStartTick);
    const int elapsedFrames = static_cast<int>(
        (elapsedTicks * 1000LL)
        / (static_cast<long long>(std::max(1, state.config.fixedTickHz))
            * runtimeRadarFrameDurationMs)
    );
    if (elapsedFrames >= runtimeRadarFrameCount) {
        return -1;
    }

    if (state.runtimeRadarTransitionDirection > 0) {
        return std::clamp(elapsedFrames, 0, runtimeRadarFrameCount - 1);
    }
    return std::clamp(
        runtimeRadarFrameCount - 1 - elapsedFrames,
        0,
        runtimeRadarFrameCount - 1
    );
}

bool runtimeRadarTransitionActive(const RuntimeWindowState& state) {
    return runtimeRadarTransitionFrame(state) >= 0;
}

int runtimeRadarFrameIndex(const RuntimeWindowState& state, bool radarActive) {
    const int transitionFrame = runtimeRadarTransitionFrame(state);
    if (transitionFrame >= 0) {
        return transitionFrame;
    }
    return radarActive ? runtimeRadarFrameCount - 1 : 0;
}

bool runtimeRadarMapVisible(const RuntimeWindowState& state, bool radarActive) {
    return radarActive && !runtimeRadarTransitionActive(state);
}

