int runtimeResourceStorageUnitsForCapacity(
    const RuntimeProductionHostState& state,
    int units,
    int storageCapacity
) {
    if (storageCapacity <= 0 || state.economy.resourceStorageCapacity <= 0) {
        return 0;
    }

    const long long scaled =
        static_cast<long long>(std::max(0, units))
        * storageCapacity
        + state.economy.resourceStorageCapacity
        - 1;
    return std::clamp(
        static_cast<int>(scaled / state.economy.resourceStorageCapacity),
        0,
        storageCapacity
    );
}

int runtimeResourceStorageFilledForCapacity(
    const RuntimeProductionHostState& state,
    int storageCapacity
) {
    return runtimeResourceStorageUnitsForCapacity(
        state,
        state.economy.storedResourceUnits,
        storageCapacity
    );
}








void recordRuntimeResourceDeliveryToStorage(
    RuntimeProductionHostState& state,
    int cargoUnits,
    int cargoGemUnits,
    int deliveredValue
) {
    refreshRuntimeResourceStorageCapacity(state);

    const int units = std::max(0, cargoUnits);
    const int gemUnits =
        std::clamp(cargoGemUnits, 0, units);
    const int value = std::max(0, deliveredValue);
    state.economy.lastResourceStorageCapacity =
        state.economy.resourceStorageCapacity;
    state.economy.lastResourceStoredUnits = 0;
    state.economy.lastResourceStoredValue = 0;
    state.economy.lastResourceStoredGemUnits = 0;
    state.economy.lastResourceStorageOverflowUnits = 0;
    if (units <= 0 && value <= 0) {
        return;
    }

    int acceptedUnits = units;
    if (state.economy.resourceStorageCapacity > 0) {
        const int availableUnits =
            std::max(
                0,
                state.economy.resourceStorageCapacity
                    - state.economy.storedResourceUnits
            );
        acceptedUnits = std::min(units, availableUnits);
        state.economy.lastResourceStorageOverflowUnits =
            std::max(0, units - acceptedUnits);
    }

    const int acceptedValue =
        runtimeScaleResourceValue(value, acceptedUnits, units);
    const int acceptedGemUnits =
        runtimeScaleResourceValue(gemUnits, acceptedUnits, units);
    state.economy.storedResourceUnits += acceptedUnits;
    state.economy.storedResourceValue += acceptedValue;
    state.economy.storedResourceGemUnits =
        std::clamp(
            state.economy.storedResourceGemUnits + acceptedGemUnits,
            0,
            state.economy.storedResourceUnits
        );
    state.economy.lastResourceStoredUnits = acceptedUnits;
    state.economy.lastResourceStoredValue = acceptedValue;
    state.economy.lastResourceStoredGemUnits = acceptedGemUnits;
}











std::string runtimeRadarStatusText(const RuntimeProductionHostState& state) {
    if (!state.campaignMode && runtimeLocalObserver(state.config)) return "Observer";
    if (!runtimeHasOwnedRadar(state)) {
        return "No Radar";
    }
    if (!runtimeRadarHasPower(state)) {
        return "Low Power";
    }
    if (state.spies.blackoutUntilTick(
            runtimeRepairDepotCanonicalOwnerId(state, state.economy.owner)
        ) > state.tick) {
        return "Spy Blackout";
    }
    return "Online";
}



bool runtimeEconomyLowPower(const RuntimeProductionHostState& state) {
    return state.economy.powerProduced - state.economy.powerUsed < 0
        || runtimeDiskDrainOwnerBlackout(state, state.economy.owner)
        || state.spies.blackoutUntilTick(
            runtimeRepairDepotCanonicalOwnerId(state, state.economy.owner)
        ) > state.tick;
}

int runtimeOwnedOrePurifierCount(const RuntimeProductionHostState& state) {
    if (runtimeEconomyLowPower(state)) {
        return 0;
    }

    int count = 0;
    for (const WorldObjectInstance& object : state.world.getObjects()) {
        if (!object.alive
            || object.owner != state.economy.owner
            || object.kind != WorldObjectKind::Structure) {
            continue;
        }

        const BuildingType* building =
            findRuntimeBuildingTypeById(state.rules, object.type);
        if (building != nullptr && building->orePurifier) {
            ++count;
        }
    }
    return count;
}



int runtimeComputerVirtualPurifierCount(const RuntimeProductionHostState& state) {
    if (!state.computerMiningScopeActive) return 0;
    if (state.campaignMode) {
        // Retail campaign values are fixed, independently of the MP INI list.
        const std::array<int, 3> campaignCounts{8, 4, 2};
        return campaignCounts[runtimeComputerMiningDifficultyIndex(state.config.campaignDifficulty)];
    }
    const auto ai = state.computerAiByOwner.find(
        runtimeRepairDepotCanonicalOwnerId(state, state.economy.owner));
    return ai == state.computerAiByOwner.end() ? 0
        : state.rules.getComputerMiningRules().virtualPurifiers[
            runtimeComputerMiningDifficultyIndex(ai->second.difficulty)];
}

int runtimeOrePurifierBonusValue(
    const RuntimeProductionHostState& state,
    int baseValue,
    int* purifierCountOutput = nullptr
) {
    const int purifierCount = runtimeOwnedOrePurifierCount(state)
        + runtimeComputerVirtualPurifierCount(state);
    if (purifierCountOutput != nullptr) {
        *purifierCountOutput = purifierCount;
    }
    if (baseValue <= 0 || purifierCount <= 0) {
        return 0;
    }

    const double purifierBonus =
        std::max(0.0, state.rules.getPurifierBonus());
    if (purifierBonus <= 0.0) {
        return 0;
    }

    const int bonusPerPurifier = std::max(
        0,
        static_cast<int>(
            std::floor(static_cast<double>(baseValue) * purifierBonus)
        )
    );
    return purifierCount * bonusPerPurifier;
}

















