void refreshRuntimeGateRenderSnapshots(RuntimeWindowState& state) {
    ensureRuntimeGatesInitialized(state);
    state.gateRenderSnapshots.clear();
    state.gateRenderSnapshots.reserve(state.gates.gates().size());
    for (const RuntimeGateInstanceState& gate : state.gates.gates()) {
        RuntimeGateRenderSnapshot snapshot;
        snapshot.objectId = gate.gateId;
        switch (gate.phase) {
        case RuntimeGatePhase::Closed:
            snapshot.phase = RuntimeGateRenderPhase::Closed;
            snapshot.normalizedProgress = 0.0;
            break;
        case RuntimeGatePhase::Open:
            snapshot.phase = RuntimeGateRenderPhase::Open;
            snapshot.normalizedProgress = 1.0;
            break;
        case RuntimeGatePhase::Opening:
        case RuntimeGatePhase::Closing:
        {
            snapshot.phase = gate.phase == RuntimeGatePhase::Opening
                ? RuntimeGateRenderPhase::Opening
                : RuntimeGateRenderPhase::Closing;
            const long long duration =
                static_cast<long long>(gate.phaseCompletesTick)
                - static_cast<long long>(gate.phaseStartedTick);
            const long long elapsed =
                static_cast<long long>(state.tick)
                - static_cast<long long>(gate.phaseStartedTick);
            snapshot.normalizedProgress = duration <= 0
                ? 0.0
                : std::clamp(
                    static_cast<double>(elapsed)
                        / static_cast<double>(duration),
                    0.0,
                    1.0
                );
            break;
        }
        }
        state.gateRenderSnapshots.push_back(snapshot);
    }
    std::sort(
        state.gateRenderSnapshots.begin(),
        state.gateRenderSnapshots.end(),
        [](const RuntimeGateRenderSnapshot& left,
           const RuntimeGateRenderSnapshot& right) {
            return left.objectId < right.objectId;
        }
    );
}


































































