std::string runtimeFirstAvailableSequenceName(
    const ArtType* art,
    std::initializer_list<const char*> candidates
) {
    if (art == nullptr) {
        return "";
    }

    for (const char* candidate : candidates) {
        const std::string candidateKey = toLowerAsciiLocal(candidate);
        for (const ArtType::SequenceFrame& frame : art->sequenceFrames) {
            if (frame.present
                && frame.frameCount > 0
                && toLowerAsciiLocal(frame.name) == candidateKey) {
                return frame.name;
            }
        }
    }
    return "";
}





