struct RuntimePathQueueNode {
    RuntimeCellPoint point;
    int cost = 0;
    int priority = 0;
};

struct RuntimePathQueueNodeGreater {
    bool operator()(const RuntimePathQueueNode& left, const RuntimePathQueueNode& right) const {
        if (left.priority != right.priority) {
            return left.priority > right.priority;
        }
        return left.cost > right.cost;
    }
};

int runtimePathHeuristic(
    const RuntimeCellPoint& left,
    const RuntimeCellPoint& right
) {
    return (std::abs(left.x - right.x) + std::abs(left.y - right.y)) * 8;
}

std::vector<RuntimeCellPoint> reconstructRuntimePath(
    const std::map<RuntimeCellPoint, RuntimeCellPoint, RuntimeCellPointLess>& previous,
    const RuntimeCellPoint& start,
    const RuntimeCellPoint& end
) {
    std::vector<RuntimeCellPoint> reversedPath;
    RuntimeCellPoint step = end;
    while (step != start) {
        reversedPath.push_back(step);
        const auto previousIt = previous.find(step);
        if (previousIt == previous.end()) {
            return {};
        }
        step = previousIt->second;
    }
    std::reverse(reversedPath.begin(), reversedPath.end());
    return reversedPath;
}






































