// Queue construction consumes this snapshot immediately. Callers that retain
// it across another builder call must take a value copy of the cache contents.

































std::vector<RuntimeCellPoint> findRuntimePathTowardRange(
    RuntimeWindowState& state,
    const WorldObjectInstance& mover,
    const WorldObjectInstance& target,
    double rangeCells,
    const std::unordered_set<int>* ignoredObjectIds = nullptr,
    bool forceFire = false
) {
    const RuntimeQueuedPathResult result = resolveRuntimePathTowardRange(
        state,
        mover,
        target,
        rangeCells,
        ignoredObjectIds,
        forceFire
    );
    return (result.reachable
            || (result.budgetExhausted && !result.path.empty()))
        ? result.path
        : std::vector<RuntimeCellPoint>{};
}















