bool runtimeTypeIsBuildableTech(int techLevel, int cost) {
    return techLevel >= 0 && techLevel <= 10 && cost > 0;
}



void addRuntimeRulesBuildCatalog(RuntimeWindowState& state) {
    const std::string playerCountry =
        runtimeCountryForOwner(state, state.economy.owner);
    for (const BuildingType& building : state.rules.getBuildingTypes()) {
        if (!runtimeTypeIsBuildableTech(building.techLevel, building.cost)
            || !runtimeTypeOwnerAllowsPlayer(building.owner, playerCountry)
            || building.buildCat.empty()) {
            continue;
        }
        addRuntimeBuildCatalogItem(
            state,
            runtimeBuildKindForBuildingType(building),
            building.id
        );
    }

    for (const UnitType& infantry : state.rules.getInfantryTypes()) {
        if (!runtimeTypeIsBuildableTech(infantry.techLevel, infantry.cost)
            || !runtimeTypeOwnerAllowsPlayer(infantry.owner, playerCountry)) {
            continue;
        }
        addRuntimeBuildCatalogItem(
            state,
            RuntimeBuildKind::Infantry,
            infantry.id
        );
    }

    for (const UnitType& unit : state.rules.getVehicleTypes()) {
        if (!runtimeTypeIsBuildableTech(unit.techLevel, unit.cost)
            || !runtimeTypeOwnerAllowsPlayer(unit.owner, playerCountry)) {
            continue;
        }
        addRuntimeBuildCatalogItem(state, RuntimeBuildKind::Unit, unit.id);
    }
}





































std::vector<RuntimePlacementCellCheck> runtimePlacementCellChecks(
    const RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item,
    const RuntimeCellPoint& cell,
    int ignoredObjectId = -1,
    const std::unordered_map<int, int>* occupiedByCellOverride = nullptr
) {
    std::vector<RuntimePlacementCellCheck> checks;
    if (item.kind != RuntimeBuildKind::Building
        && item.kind != RuntimeBuildKind::Defense) {
        return checks;
    }

    const RuntimeStructureFootprint footprint =
        runtimeStructureFootprintForBuildItem(state, item);
    const std::vector<RuntimeCellPoint> footprintCells =
        runtimeStructureFootprintCells(cell, footprint);
    checks.reserve(footprintCells.size());
    std::unordered_map<int, int> generatedOccupiedByCell;
    const std::unordered_map<int, int>* occupiedByCell =
        occupiedByCellOverride;
    if (occupiedByCell == nullptr) {
        generatedOccupiedByCell =
            buildRuntimeOccupancyLookup(state, ignoredObjectId);
        occupiedByCell = &generatedOccupiedByCell;
    }

    const auto rubbleCells = runtimeBuildingRubblePlacementCells(state);
    const auto committedCells=runtimeGroundMoveSegmentPlacementCells(state,ignoredObjectId);
    int baseLevel = std::numeric_limits<int>::min();
    const auto anchorIt = state.terrainByCell.find(runtimeCellKey(cell.x, cell.y));
    if (anchorIt != state.terrainByCell.end() && anchorIt->second != nullptr) {
        baseLevel = anchorIt->second->level;
    }

    for (const RuntimeCellPoint& current : footprintCells) {
        const int key = runtimeCellKey(current.x, current.y);
        RuntimePlacementCellCheck check;
        check.cell = current;

        const auto terrainIt = state.terrainByCell.find(key);
        if (terrainIt == state.terrainByCell.end()
            || terrainIt->second == nullptr) {
            check.reason = "missing terrain";
            checks.push_back(std::move(check));
            continue;
        }

        check.level = terrainIt->second->level;
        if (baseLevel == std::numeric_limits<int>::min()) {
            baseLevel = check.level;
        }

        if (state.visionEnabled
            && !state.vision.isCellExploredBy(
                state.economy.owner, current.x, current.y
            )) {
            check.reason = "shrouded";
            checks.push_back(std::move(check));
            continue;
        }

        if (occupiedByCell->find(key) != occupiedByCell->end() || committedCells.contains(key) || rubbleCells.contains(key)) {
            check.reason = "occupied";
            checks.push_back(std::move(check));
            continue;
        }

        if (runtimeResourceOverlayBlocksPlacement(
                state,
                *terrainIt->second
            )) {
            check.reason = terrainIt->second->overlayIsGem ? "gems" : "ore";
            checks.push_back(std::move(check));
            continue;
        }
        if (terrainIt->second->hasOverlay
            && !runtimeOverlayLooksBridge(*terrainIt->second)
            && !terrainIt->second->overlayIsOre
            && !terrainIt->second->overlayIsGem) {
            check.reason = "overlay";
            checks.push_back(std::move(check));
            continue;
        }

        const RuntimeTerrainInfo info =
            runtimeCachedTerrainInfoForCell(state, *terrainIt->second);
        // Beach TMP subtiles contain exposed shore, not a water foundation.
        // Authored fully submerged shore subtiles are already classified as water.
        const bool buildCellIsWater = info.water && !info.shore;
        if (item.waterBound && !buildCellIsWater) {
            check.reason = "needs water";
        } else if (!item.waterBound && info.water) {
            check.reason = "water";
        } else if (!item.waterBound && info.shore) {
            check.reason = "shore";
        } else if (!item.waterBound && info.cliff) {
            check.reason = "cliff";
        } else if (check.level != baseLevel) {
            check.reason = "uneven";
        } else {
            check.valid = true;
            check.reason = item.waterBound ? "water" : "flat";
        }
        checks.push_back(std::move(check));
    }

    if (!runtimeBuildingPlacementInRange(state, item, cell)) {
        for (auto& check : checks) {
            if (check.valid) {
                check.valid = false;
                check.reason = "outside base range";
            }
        }
    }
    return checks;
}

bool runtimePlacementChecksCacheMatches(
    const RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item,
    const RuntimeCellPoint& cell
) {
    RuntimeVisionGridView visionGrid;
    if (state.visionEnabled) {
        state.vision.gridViewFor(state.economy.owner, visionGrid);
    }
    return state.placementChecksCacheTick == state.tick
        && state.placementChecksCacheCell == cell
        && state.placementChecksCacheKind == item.kind
        && state.placementChecksCacheTypeId == item.typeId
        && state.placementChecksCacheOwner == state.economy.owner
        && state.placementChecksCacheInRange == runtimeBuildingPlacementInRange(state, item, cell)
        && state.placementChecksCacheVision.visibleCells == visionGrid.visibleCells
        && state.placementChecksCacheVision.layoutEpoch == visionGrid.layoutEpoch
        && state.placementChecksCacheVision.revision == visionGrid.revision;
}

const std::vector<RuntimePlacementCellCheck>& cachedRuntimePlacementCellChecks(
    RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item,
    const RuntimeCellPoint& cell
) {
    if (runtimePlacementChecksCacheMatches(state, item, cell)) {
        return state.placementChecksCache;
    }

    state.placementChecksCache =
        runtimePlacementCellChecks(state, item, cell);
    state.placementChecksCacheTick = state.tick;
    state.placementChecksCacheCell = cell;
    state.placementChecksCacheKind = item.kind;
    state.placementChecksCacheTypeId = item.typeId;
    state.placementChecksCacheOwner = state.economy.owner;
    state.placementChecksCacheInRange = runtimeBuildingPlacementInRange(state, item, cell);
    state.placementChecksCacheVision = RuntimeVisionGridView{};
    if (state.visionEnabled) {
        state.vision.gridViewFor(
            state.economy.owner, state.placementChecksCacheVision
        );
    }
    return state.placementChecksCache;
}





























#include "simulation/production/RuntimeBuildupRuntime.inl"





bool runtimeSubmergedInstanceStateContract(
    const RulesDatabase& rules,
    std::string& errorMessage
) {
    const auto underwaterIt = std::find_if(
        rules.getVehicleTypes().begin(),
        rules.getVehicleTypes().end(),
        [](const UnitType& unit) {
            return unit.underwater && !unit.id.empty();
        }
    );
    if (underwaterIt == rules.getVehicleTypes().end()) {
        errorMessage = "rules contain no authored underwater vehicle";
        return false;
    }

    WorldObjectInstance mapObject;
    mapObject.instanceId = 7101;
    mapObject.kind = WorldObjectKind::Unit;
    mapObject.type = underwaterIt->id;
    GameWorld hydratedWorld;
    hydratedWorld.accessObjects().push_back(mapObject);
    hydrateRuntimeObjectSubmergedState(hydratedWorld, rules);
    const bool mapHydrationValid =
        hydratedWorld.getObjects().size() == 1U
        && hydratedWorld.getObjects().front().submerged;

    RuntimeWindowState producedState;
    producedState.rules = rules;
    producedState.rulesLoaded = true;
    producedState.economy.owner = "SubmergedContract";
    WorldObjectInstance* produced = addRuntimeObjectInstance(
        producedState,
        RuntimeBuildKind::Unit,
        underwaterIt->id,
        {10, 10}
    );
    const bool producedStateValid = produced != nullptr
        && produced->submerged;

    std::vector<std::string> legacyTokens(29);
    const bool legacyFallbackValid = runtimeLoadedObjectSubmergedState(
        legacyTokens,
        rules,
        mapObject
    );
    std::vector<std::string> currentTokens(30);
    currentTokens[29] = "no";
    const bool surfacedOverrideValid = !runtimeLoadedObjectSubmergedState(
        currentTokens,
        rules,
        mapObject
    );
    currentTokens[29] = "yes";
    const bool submergedOverrideValid = runtimeLoadedObjectSubmergedState(
        currentTokens,
        rules,
        mapObject
    );

    const bool valid = mapHydrationValid
        && producedStateValid
        && legacyFallbackValid
        && surfacedOverrideValid
        && submergedOverrideValid;
    if (!valid) {
        errorMessage =
            "mapHydration=" + std::to_string(mapHydrationValid)
            + " produced=" + std::to_string(producedStateValid)
            + " legacyFallback=" + std::to_string(legacyFallbackValid)
            + " surfacedOverride=" + std::to_string(surfacedOverrideValid)
            + " submergedOverride=" + std::to_string(
                submergedOverrideValid
            );
    }
    return valid;
}

WorldObjectInstance makeRuntimePlacementPreviewObject(
    RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item,
    const RuntimeCellPoint& topLeftCell
) {
    WorldObjectInstance object;
    object.instanceId = -1;
    object.kind = runtimeKindForBuildItem(item.kind);
    object.owner = state.economy.owner;
    object.type = item.typeId;
    applyRuntimePlacementObjectPose(state, object, item.kind, topLeftCell);
    object.facing = runtimeInitialProducedFacing(
        state,
        item.kind,
        item.typeId
    );
    object.turretFacing = -1;
    object.subCell = -1;
    object.mission = "Guard";
    object.alive = true;
    if (const BuildingType* building =
            findRuntimeBuildingTypeById(state.rules, object.type)) {
        object.health = std::max(1, building->strength);
    }
    return object;
}









