int runtimeCompatibleAircraftDockCapacityForOwner(
    const RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item,
    const std::string& owner
) {
    const std::optional<RuntimeProductionLane> lane =
        runtimeProductionLaneForCatalogItem(state, item);
    if (!runtimeBuildItemIsAirportBound(state, item)
        || !lane.has_value()
        || *lane != RuntimeProductionLane::Aircraft) {
        return 0;
    }

    int available = 0;
    const std::vector<const WorldObjectInstance*> anchors =
        findRuntimeFactoryAnchorCandidatesForOwner(
            state,
            item,
            owner,
            false
        );
    for (const WorldObjectInstance* anchor : anchors) {
        if (anchor == nullptr
            || !runtimeAircraftCanDockAtStructureForOwner(
                state,
                item,
                *anchor,
                owner
            )) {
            continue;
        }
        const BuildingType* building =
            findRuntimeBuildingTypeById(state.rules, anchor->type);
        const int dockCount = building == nullptr
            ? 0
            : std::max(0, building->numberOfDocks);
        std::vector<bool> occupied(
            static_cast<std::size_t>(dockCount),
            false
        );
        for (const WorldObjectInstance& object : state.world.getObjects()) {
            if (object.alive
                && object.dockedToObjectId == anchor->instanceId
                && object.dockIndex >= 0
                && object.dockIndex < dockCount) {
                occupied[static_cast<std::size_t>(object.dockIndex)] = true;
            }
        }
        available += static_cast<int>(std::count(
            occupied.begin(),
            occupied.end(),
            false
        ));
    }
    return available;
}

