std::string runtimeDefaultSavePath(const RuntimeWindowState& state) {
    if (state.campaignMode
        || toUpperAsciiLocal(trimAsciiLocal(state.config.gameMode))
            == "CAMPAIGNMISSION") {
        if (!trimAsciiLocal(state.config.campaignSavePath).empty()) {
            return state.config.campaignSavePath;
        }
        return campaignSavePath(
            state.config.localDataRootPath,
            state.config.campaignId,
            state.config.campaignMissionId
        );
    }
    const std::filesystem::path root =
        state.config.localDataRootPath.empty()
            ? std::filesystem::path("local_data")
            : std::filesystem::path(state.config.localDataRootPath);
    return pathString(root / "runtime_save.ini");
}

using runtime_save_text::runtimeBoolText;





























std::optional<RuntimeHarvesterTask> parseRuntimeHarvesterTask(
    const std::string& value
) {
    const std::vector<std::string> tokens = splitRuntimeSaveFields(value);
    if (tokens.size() < 12) {
        return std::nullopt;
    }

    RuntimeHarvesterTask task;
    task.phase = runtimeHarvesterPhaseFromName(tokens[0]);
    task.targetOre.x = parseRuntimeIntOrDefault(tokens[1], -1);
    task.targetOre.y = parseRuntimeIntOrDefault(tokens[2], -1);
    task.dockCell.x = parseRuntimeIntOrDefault(tokens[3], -1);
    task.dockCell.y = parseRuntimeIntOrDefault(tokens[4], -1);
    const bool hasQueueCell = tokens.size() >= 14;
    int offset = 0;
    if (hasQueueCell) {
        task.queueCell.x = parseRuntimeIntOrDefault(tokens[5], -1);
        task.queueCell.y = parseRuntimeIntOrDefault(tokens[6], -1);
        offset = 2;
    }
    const bool hasGemUnits =
        tokens.size() >= static_cast<std::size_t>(13 + offset);
    task.targetRefineryId = parseRuntimeIntOrDefault(tokens[5 + offset], -1);
    task.cargoValue = parseRuntimeIntOrDefault(tokens[6 + offset], 0);
    task.cargoUnits = parseRuntimeIntOrDefault(tokens[7 + offset], 0);
    if (hasGemUnits) {
        task.cargoGemUnits =
            parseRuntimeIntOrDefault(tokens[8 + offset], 0);
        task.cargoCapacity =
            parseRuntimeIntOrDefault(tokens[9 + offset], 0);
        task.workTicksRemaining =
            parseRuntimeIntOrDefault(tokens[10 + offset], 0);
        task.cargoHasGems = parseRuntimeBool(tokens[11 + offset]);
        task.status = tokens[12 + offset];
    } else {
        task.cargoCapacity =
            parseRuntimeIntOrDefault(tokens[8 + offset], 0);
        task.workTicksRemaining =
            parseRuntimeIntOrDefault(tokens[9 + offset], 0);
        task.cargoHasGems = parseRuntimeBool(tokens[10 + offset]);
        task.status = tokens[11 + offset];
        task.cargoGemUnits =
            task.cargoHasGems ? std::min(task.cargoUnits, 1) : 0;
    }
    task.cargoGemUnits =
        std::clamp(task.cargoGemUnits, 0, std::max(0, task.cargoUnits));
    task.cargoHasGems = task.cargoHasGems || task.cargoGemUnits > 0;
    if (tokens.size() >= 16U
        && (!parseRuntimeInt(tokens[15], task.nextThinkTick) || task.nextThinkTick < 0)) return std::nullopt;
    return task;
}









