bool runtimeProductionLanePhaseBContract(
    const RulesDatabase& rules,
    std::string& errorMessage
) {
    RuntimeWindowState shell;
    shell.rules = rules;
    shell.rulesLoaded = true;
    shell.economy.owner = "Americans";
    initializeRuntimeLocalProductionLanes(shell.economy);
    shell.economy.credits = 1000000;
    shell.economy.storedResourceValue = 100000;
    shell.economy.storedResourceUnits = 100000;

    const BuildingType* power =
        findRuntimeBuildingTypeById(shell.rules, "GAPOWR");
    const BuildingType* wall =
        findRuntimeBuildingTypeById(shell.rules, "GAWALL");
    if (power == nullptr || wall == nullptr) {
        errorMessage = "Phase B contract rules lack GAPOWR/GAWALL";
        return false;
    }
    addRuntimeBuildCatalogItem(
        shell,
        runtimeBuildKindForBuildingType(*power),
        power->id
    );
    addRuntimeBuildCatalogItem(
        shell,
        runtimeBuildKindForBuildingType(*wall),
        wall->id
    );
    addRuntimeBuildCatalogItem(shell, RuntimeBuildKind::Infantry, "E1");
    addRuntimeBuildCatalogItem(shell, RuntimeBuildKind::Unit, "MTNK");
    addRuntimeBuildCatalogItem(shell, RuntimeBuildKind::Unit, "DEST");
    addRuntimeBuildCatalogItem(shell, RuntimeBuildKind::Unit, "ORCA");
    addRuntimeBuildCatalogItem(shell, RuntimeBuildKind::Building, "GAREFN");

    const auto itemByKey = [&shell](std::string_view key)
        -> const RuntimeBuildCatalogItem* {
        const std::optional<RuntimeProductionCatalogAdapter> catalog =
            runtimeProductionCatalogLookup(shell, key);
        return catalog.has_value() ? catalog->item : nullptr;
    };
    const RuntimeBuildCatalogItem* structure = itemByKey("GAPOWR");
    const RuntimeBuildCatalogItem* armory = itemByKey("GAWALL");
    const RuntimeBuildCatalogItem* infantry = itemByKey("E1");
    const RuntimeBuildCatalogItem* vehicle = itemByKey("MTNK");
    const RuntimeBuildCatalogItem* ship = itemByKey("DEST");
    const RuntimeBuildCatalogItem* aircraft = itemByKey("ORCA");
    const RuntimeBuildCatalogItem* refinery = itemByKey("GAREFN");
    if (structure == nullptr
        || armory == nullptr
        || infantry == nullptr
        || vehicle == nullptr
        || ship == nullptr
        || aircraft == nullptr
        || refinery == nullptr) {
        errorMessage = "Phase B contract catalog lacks a production lane";
        return false;
    }

    const BuildingType* factoryPlantRules =
        findRuntimeBuildingTypeById(shell.rules, "NAINDP");
    const int vehicleBaseCost = vehicle->cost;
    const int vehicleBaseBuildTicks = vehicle->buildTicks;
    const int aircraftBaseCost = aircraft->cost;
    const int refineryBaseCost = refinery->cost;
    RuntimeProductionLaneOrder factoryPlantOrder;
    factoryPlantOrder.itemKey = vehicle->typeId;
    factoryPlantOrder.cost = vehicleBaseCost;
    factoryPlantOrder.totalTicks = vehicleBaseBuildTicks;
    const RuntimeProductionQueueResult firstFactoryPlantQueue =
        runtimeQueueProductionOrder(
            shell.economy.localProductionLanes,
            RuntimeProductionLane::Vehicles,
            factoryPlantOrder,
            shell.rules.getMaximumQueuedObjects(),
            0
        );
    const RuntimeProductionQueueResult secondFactoryPlantQueue =
        runtimeQueueProductionOrder(
            shell.economy.localProductionLanes,
            RuntimeProductionLane::Vehicles,
            factoryPlantOrder,
            shell.rules.getMaximumQueuedObjects(),
            0
        );
    WorldObjectInstance factoryPlant;
    factoryPlant.instanceId = 950700;
    factoryPlant.kind = WorldObjectKind::Structure;
    factoryPlant.type = "NAINDP";
    factoryPlant.owner = shell.economy.owner;
    factoryPlant.health = factoryPlantRules == nullptr
        ? 0
        : std::max(1, factoryPlantRules->strength);
    factoryPlant.alive = true;
    factoryPlant.poweredOperational = false;
    shell.world.accessObjects().push_back(factoryPlant);
    const bool factoryPlantApplied = refreshRuntimeFactoryPlantCatalog(shell);
    const int discountedRefineryCost = refinery->cost;
    const int expectedVehicleDiscount = factoryPlantRules == nullptr
        ? vehicleBaseCost
        : static_cast<int>(
            static_cast<long double>(vehicleBaseCost)
                * factoryPlantRules->unitsCostBonus
        );
    const BuildingType* refineryRules =
        findRuntimeBuildingTypeById(shell.rules, refinery->typeId);
    const UnitType* refineryFreeUnit = refineryRules == nullptr
        ? nullptr
        : findRuntimeUnitTypeById(shell.rules, refineryRules->freeUnit);
    const int expectedRefineryDiscount = factoryPlantRules == nullptr
            || refineryFreeUnit == nullptr
        ? refineryBaseCost
        : std::max(0, refineryBaseCost - refineryFreeUnit->cost)
            + static_cast<int>(
                static_cast<long double>(refineryFreeUnit->cost)
                    * factoryPlantRules->unitsCostBonus
            );
    RuntimeProductionLaneState& factoryPlantLane =
        shell.economy.localProductionLanes.lanes[
            runtimeProductionLaneIndex(RuntimeProductionLane::Vehicles)
        ];
    const bool waitingOrdersDiscounted =
        factoryPlantLane.queued.size() == 2U
        && std::all_of(
            factoryPlantLane.queued.begin(),
            factoryPlantLane.queued.end(),
            [expectedVehicleDiscount](
                const RuntimeProductionLaneOrder& order
            ) {
                return order.cost == expectedVehicleDiscount;
            }
        );
    int factoryPlantCredits = 1000000;
    (void)runtimeAdvanceProductionLanes(
        shell.economy.localProductionLanes,
        factoryPlantCredits
    );
    shell.world.accessObjects().front().alive = false;
    const bool factoryPlantRemoved = refreshRuntimeFactoryPlantCatalog(shell);
    const bool activePriceStayedLocked = factoryPlantLane.active.has_value()
        && factoryPlantLane.active->cost == expectedVehicleDiscount;
    const bool waitingPriceRestored = factoryPlantLane.queued.size() == 1U
        && factoryPlantLane.queued.front().cost == vehicleBaseCost;
    if (factoryPlantRules == nullptr
        || firstFactoryPlantQueue.decision
            != RuntimeProductionQueueDecision::Accepted
        || secondFactoryPlantQueue.decision
            != RuntimeProductionQueueDecision::Accepted
        || !factoryPlantApplied
        || !factoryPlantRemoved
        || vehicle->cost != vehicleBaseCost
        || vehicle->buildTicks != vehicleBaseBuildTicks
        || aircraft->cost != aircraftBaseCost
        || refinery->cost != refineryBaseCost
        || discountedRefineryCost != expectedRefineryDiscount
        || !waitingOrdersDiscounted
        || !activePriceStayedLocked
        || !waitingPriceRestored) {
        errorMessage =
            "Phase B FactoryPlant pricing, timing, or queue snapshot failed";
        return false;
    }
    initializeRuntimeLocalProductionLanes(shell.economy);

    const std::array<const RuntimeBuildCatalogItem*, 6> timingItems{{
        structure,
        armory,
        infantry,
        vehicle,
        aircraft,
        ship
    }};
    for (const RuntimeBuildCatalogItem* item : timingItems) {
        const RuntimeProductionTimingResult timing =
            runtimeProductionTimingForItem(shell, *item, 1, 0.0, 0.0);
        if (!timing.valid || item->buildTicks != timing.base.fixedTicks) {
            errorMessage =
                "Phase B catalog duration diverged from production timing";
            return false;
        }
    }

    const RuntimeProductionTimingResult oneFactoryTiming =
        runtimeProductionTimingForItem(shell, *vehicle, 1, 100.0, 100.0);
    const RuntimeProductionTimingResult twoFactoryTiming =
        runtimeProductionTimingForItem(shell, *vehicle, 2, 100.0, 100.0);
    const RuntimeProductionTimingResult threeFactoryTiming =
        runtimeProductionTimingForItem(shell, *vehicle, 3, 100.0, 100.0);
    const RuntimeProductionTimingResult slightLowPowerTiming =
        runtimeProductionTimingForItem(shell, *vehicle, 1, 95.0, 100.0);
    const RuntimeProductionTimingResult severeLowPowerTiming =
        runtimeProductionTimingForItem(shell, *vehicle, 1, 0.0, 100.0);
    const auto rateLess = [](RuntimeProductionRate left,
                             RuntimeProductionRate right) {
        return static_cast<std::uint64_t>(left.numerator)
                * right.denominator
            < static_cast<std::uint64_t>(right.numerator)
                * left.denominator;
    };
    const ProductionRules& productionRules =
        shell.rules.getProductionRules();
    if (!oneFactoryTiming.valid
        || !twoFactoryTiming.valid
        || !threeFactoryTiming.valid
        || !slightLowPowerTiming.valid
        || !severeLowPowerTiming.valid
        || oneFactoryTiming.base.fixedTicks != vehicle->buildTicks
        || twoFactoryTiming.base.fixedTicks != vehicle->buildTicks
        || threeFactoryTiming.base.fixedTicks != vehicle->buildTicks
        || !rateLess(
            oneFactoryTiming.productionRate,
            twoFactoryTiming.productionRate
        )
        || !rateLess(
            twoFactoryTiming.productionRate,
            threeFactoryTiming.productionRate
        )
        || std::abs(
            slightLowPowerTiming.lowPowerSpeed
                - productionRules.maxLowPowerProductionSpeed
        ) > 1e-9
        || std::abs(
            severeLowPowerTiming.lowPowerSpeed
                - productionRules.minLowPowerProductionSpeed
        ) > 1e-9) {
        errorMessage =
            "Phase B dynamic factory or low-power timing contract failed";
        return false;
    }

    RuntimeProductionLanesState progressive;
    const std::array<const RuntimeBuildCatalogItem*, 6> laneItems{{
        structure,
        armory,
        infantry,
        vehicle,
        aircraft,
        ship
    }};
    for (const RuntimeBuildCatalogItem* item : laneItems) {
        const std::optional<RuntimeProductionLane> lane =
            runtimeProductionLaneForCatalogItem(shell, *item);
        RuntimeProductionLaneOrder order;
        order.itemKey = item->typeId;
        order.cost = item->cost;
        order.totalTicks = std::max(1, item->buildTicks);
        if (!lane.has_value()
            || runtimeQueueProductionOrder(
                progressive,
                *lane,
                std::move(order),
                shell.rules.getMaximumQueuedObjects(),
                1
            ).decision != RuntimeProductionQueueDecision::Accepted) {
            errorMessage = "Phase B six-lane queue setup failed";
            return false;
        }
    }

    const int creditsBefore = shell.economy.credits;
    const int storedBefore = shell.economy.storedResourceValue;
    int stagedCredits = creditsBefore;
    const std::vector<RuntimeProductionAdvanceEvent> firstTick =
        runtimeAdvanceProductionLanes(progressive, stagedCredits);
    std::vector<RuntimeProductionLane> startedOrder;
    int progressedLaneCount = 0;
    int debitedLaneCount = 0;
    int eventDebit = 0;
    for (const RuntimeProductionAdvanceEvent& event : firstTick) {
        if (event.kind == RuntimeProductionAdvanceKind::Started) {
            startedOrder.push_back(event.lane);
        }
        if (event.kind == RuntimeProductionAdvanceKind::Progressed) {
            ++progressedLaneCount;
        }
        if (event.creditsDebited > 0) {
            ++debitedLaneCount;
            eventDebit += event.creditsDebited;
        }
    }
    const std::vector<RuntimeProductionLane> expectedStarted{
        RuntimeProductionLane::Structures,
        RuntimeProductionLane::Armory,
        RuntimeProductionLane::Infantry,
        RuntimeProductionLane::Vehicles,
        RuntimeProductionLane::Ships,
        RuntimeProductionLane::Aircraft
    };
    const int stagedDebit = creditsBefore - stagedCredits;
    const bool ledgerCommitted = stagedDebit == 0
        || spendRuntimeCredits(shell, stagedDebit);
    if (startedOrder != expectedStarted
        || progressedLaneCount != 6
        || eventDebit != stagedDebit
        || stagedDebit < 0
        || !ledgerCommitted
        || shell.economy.credits != stagedCredits
        || shell.economy.storedResourceValue
            != storedBefore - stagedDebit) {
        std::ostringstream details;
        details << "Phase B same-tick ledger or Ships-before-Aircraft failed"
                << " started=";
        for (RuntimeProductionLane lane : startedOrder) {
            details << runtimeProductionLaneName(lane) << ",";
        }
        details << " expected=";
        for (RuntimeProductionLane lane : expectedStarted) {
            details << runtimeProductionLaneName(lane) << ",";
        }
        details << " progressedLanes=" << progressedLaneCount
                << " debitedLanes=" << debitedLaneCount
                << " eventDebit=" << eventDebit
                << " stagedDebit=" << stagedDebit
                << " credits=" << creditsBefore << "->"
                << stagedCredits << "/live=" << shell.economy.credits
                << " stored=" << storedBefore << "->"
                << shell.economy.storedResourceValue
                << " events=";
        for (const RuntimeProductionAdvanceEvent& event : firstTick) {
            details << "[" << runtimeProductionLaneName(event.lane)
                    << ":" << static_cast<int>(event.kind)
                    << ":" << event.itemKey
                    << ":remaining=" << event.remainingTicks
                    << ":spent=" << event.creditsSpent
                    << ":debit=" << event.creditsDebited << "]";
        }
        details << " candidates=";
        for (const RuntimeBuildCatalogItem* item : laneItems) {
            const std::optional<RuntimeProductionLane> lane =
                runtimeProductionLaneForCatalogItem(shell, *item);
            details << "[" << item->typeId << ":"
                    << (lane.has_value()
                        ? std::string(runtimeProductionLaneName(*lane))
                        : std::string("none"))
                    << ":cost=" << item->cost
                    << ":ticks=" << item->buildTicks
                    << ":rate=1/1]";
        }
        errorMessage = details.str();
        return false;
    }

    initializeRuntimeLocalProductionLanes(shell.economy);
    if (!stageRuntimeReadyPlacementForProbe(shell, *structure)) {
        errorMessage = "Phase B structure ready setup failed";
        return false;
    }
    const std::optional<RuntimeSelectedPlacement> structureReady =
        runtimeSelectedPlacement(shell);
    if (!stageRuntimeReadyPlacementForProbe(shell, *armory)) {
        errorMessage = "Phase B armory ready setup failed";
        return false;
    }
    const std::optional<RuntimeSelectedPlacement> armoryReady =
        runtimeSelectedPlacement(shell);
    if (!structureReady.has_value()
        || !armoryReady.has_value()
        || structureReady->lane != RuntimeProductionLane::Structures
        || armoryReady->lane != RuntimeProductionLane::Armory
        || runtimeProductionLaneOccupancy(
            shell.economy.localProductionLanes,
            RuntimeProductionLane::Structures
        ) != 1
        || runtimeProductionLaneOccupancy(
            shell.economy.localProductionLanes,
            RuntimeProductionLane::Armory
        ) != 1) {
        errorMessage = "Phase B dual ready lanes were not independent";
        return false;
    }

    const RuntimeProductionLanesState dualReadyLanes =
        shell.economy.localProductionLanes;
    const std::string dualReadySerialized =
        runtimeSerializeProductionLanes(dualReadyLanes);
    const std::string goodV8 =
        "[ProductionLanes]\nSchema=2\nDataHex="
        + runtimeHexEncode(dualReadySerialized)
        + "\nStateHash="
        + std::to_string(runtimeProductionLanesStateHash(dualReadyLanes))
        + "\nSelection=Structures|"
        + std::to_string(structureReady->order.serial)
        + "\n";
    IniFile goodIni;
    RuntimeSavedProductionCandidate goodCandidate;
    if (!goodIni.loadFromString(goodV8)
        || !loadRuntimeV8ProductionCandidate(
            shell,
            goodIni,
            goodCandidate,
            errorMessage
        )
        || goodCandidate.selectedPlacementLane
            != std::optional<RuntimeProductionLane>{
                RuntimeProductionLane::Structures
            }
        || goodCandidate.selectedPlacementSerial
            != structureReady->order.serial) {
        errorMessage = "Phase B v8 DataHex/hash/selection load failed";
        return false;
    }

    std::string schema3AliasText = goodV8;
    const std::string schema2Marker =
        "Schema="
        + std::to_string(runtimeProductionLanesSectionSchemaV2);
    const std::size_t schemaMarkerPosition =
        schema3AliasText.find(schema2Marker);
    if (schemaMarkerPosition == std::string::npos) {
        errorMessage = "Phase B schema 3 compatibility setup failed";
        return false;
    }
    schema3AliasText.replace(
        schemaMarkerPosition,
        schema2Marker.size(),
        "Schema="
            + std::to_string(runtimeProductionLanesSectionSchemaV3Alias)
    );
    IniFile schema3AliasIni;
    RuntimeSavedProductionCandidate schema3AliasCandidate;
    if (!schema3AliasIni.loadFromString(schema3AliasText)
        || !loadRuntimeV8ProductionCandidate(
            shell,
            schema3AliasIni,
            schema3AliasCandidate,
            errorMessage
        )
        || runtimeProductionLanesStateHash(schema3AliasCandidate.lanes)
            != runtimeProductionLanesStateHash(goodCandidate.lanes)
        || schema3AliasCandidate.selectedPlacementLane
            != goodCandidate.selectedPlacementLane
        || schema3AliasCandidate.selectedPlacementSerial
            != goodCandidate.selectedPlacementSerial) {
        errorMessage = "Phase B mislabeled schema 3 save was not recovered";
        return false;
    }

    std::string unsupportedSchemaText = schema3AliasText;
    unsupportedSchemaText.replace(
        schemaMarkerPosition,
        std::string("Schema=").size() + 1U,
        "Schema=4"
    );
    IniFile unsupportedSchemaIni;
    RuntimeSavedProductionCandidate unsupportedSchemaCandidate;
    std::string unsupportedSchemaError;
    if (!unsupportedSchemaIni.loadFromString(unsupportedSchemaText)
        || loadRuntimeV8ProductionCandidate(
            shell,
            unsupportedSchemaIni,
            unsupportedSchemaCandidate,
            unsupportedSchemaError
        )
        || unsupportedSchemaError
            != "invalid production lanes section schema") {
        errorMessage = "Phase B unsupported production schema was accepted";
        return false;
    }

    const std::string badV8 =
        "[ProductionLanes]\nSchema=2\nDataHex="
        + runtimeHexEncode(dualReadySerialized)
        + "\nStateHash="
        + std::to_string(runtimeProductionLanesStateHash(dualReadyLanes))
        + "\nSelection=Structures|"
        + std::to_string(armoryReady->order.serial)
        + "\n";
    IniFile badIni;
    RuntimeSavedProductionCandidate unchanged;
    unchanged.lanes.nextSerial = 777;
    unchanged.selectedPlacementLane = RuntimeProductionLane::Aircraft;
    unchanged.selectedPlacementSerial = 888;
    std::string badError;
    if (!badIni.loadFromString(badV8)
        || loadRuntimeV8ProductionCandidate(
            shell,
            badIni,
            unchanged,
            badError
        )
        || unchanged.lanes.nextSerial != 777
        || unchanged.selectedPlacementLane
            != std::optional<RuntimeProductionLane>{
                RuntimeProductionLane::Aircraft
            }
        || unchanged.selectedPlacementSerial != 888) {
        errorMessage = "Phase B bad v8 selection was not atomic";
        return false;
    }

    RuntimeProductionLanesState schema1Progress;
    RuntimeProductionLaneOrder schema1Active;
    schema1Active.itemKey = vehicle->typeId;
    schema1Active.cost = vehicle->cost;
    schema1Active.totalTicks = runtimeLegacyBuildTimeTicks(
        vehicle->cost,
        vehicle->wall
    );
    RuntimeProductionLaneOrder schema1Queued = schema1Active;
    const RuntimeProductionQueueResult schema1ActiveResult =
        runtimeQueueProductionOrder(
            schema1Progress,
            RuntimeProductionLane::Vehicles,
            schema1Active,
            shell.rules.getMaximumQueuedObjects(),
            0
        );
    const RuntimeProductionQueueResult schema1QueuedResult =
        runtimeQueueProductionOrder(
            schema1Progress,
            RuntimeProductionLane::Vehicles,
            schema1Queued,
            shell.rules.getMaximumQueuedObjects(),
            0
        );
    int schema1Credits = vehicle->cost;
    const int schema1ElapsedTicks = std::max(
        1,
        schema1Active.totalTicks / 2
    );
    for (int tick = 0; tick < schema1ElapsedTicks; ++tick) {
        runtimeAdvanceProductionLanes(schema1Progress, schema1Credits);
    }
    const RuntimeProductionLaneState& rawSchema1VehicleLane =
        schema1Progress.lanes[runtimeProductionLaneIndex(
            RuntimeProductionLane::Vehicles
        )];
    const int schema1CreditsSpent =
        rawSchema1VehicleLane.active.has_value()
            ? rawSchema1VehicleLane.active->creditsSpent
            : -1;
    const std::string schema1Serialized =
        runtimeSerializeProductionLanes(schema1Progress);
    const std::string schema1Text =
        "[ProductionLanes]\nSchema=1\nDataHex="
        + runtimeHexEncode(schema1Serialized)
        + "\nStateHash="
        + std::to_string(runtimeProductionLanesStateHash(schema1Progress))
        + "\nSelection=\n";
    IniFile schema1Ini;
    RuntimeSavedProductionCandidate schema1Candidate;
    if (schema1ActiveResult.decision
            != RuntimeProductionQueueDecision::Accepted
        || schema1QueuedResult.decision
            != RuntimeProductionQueueDecision::Accepted
        || schema1CreditsSpent <= 0
        || !schema1Ini.loadFromString(schema1Text)
        || !loadRuntimeV8ProductionCandidate(
            shell,
            schema1Ini,
            schema1Candidate,
            errorMessage
        )) {
        errorMessage = "Phase B schema 1 timing migration failed";
        return false;
    }
    const RuntimeProductionLaneState& migratedSchema1VehicleLane =
        schema1Candidate.lanes.lanes[runtimeProductionLaneIndex(
            RuntimeProductionLane::Vehicles
        )];
    const int expectedSchema1Remaining = static_cast<int>(
        (static_cast<std::uint64_t>(vehicle->buildTicks)
            * static_cast<std::uint64_t>(
                vehicle->cost - schema1CreditsSpent
            )
            + static_cast<std::uint64_t>(vehicle->cost) - 1U)
        / static_cast<std::uint64_t>(vehicle->cost)
    );
    if (!migratedSchema1VehicleLane.active.has_value()
        || migratedSchema1VehicleLane.active->totalTicks
            != vehicle->buildTicks
        || migratedSchema1VehicleLane.active->remainingTicks
            != expectedSchema1Remaining
        || migratedSchema1VehicleLane.active->creditsSpent
            != schema1CreditsSpent
        || migratedSchema1VehicleLane.active->creditRemainderMicros != 0
        || migratedSchema1VehicleLane.active->rateDivisionRemainder != 0
        || migratedSchema1VehicleLane.active->rateDivisionDenominator != 0
        || migratedSchema1VehicleLane.queued.size() != 1U
        || migratedSchema1VehicleLane.queued.front().totalTicks
            != vehicle->buildTicks
        || migratedSchema1VehicleLane.queued.front().remainingTicks
            != vehicle->buildTicks) {
        errorMessage =
            "Phase B schema 1 timing migration lost order progress";
        return false;
    }

    RuntimeProductionLanesState schema1Ready = dualReadyLanes;
    for (const RuntimeProductionLane lane : {
            RuntimeProductionLane::Structures,
            RuntimeProductionLane::Armory}) {
        RuntimeProductionLaneState& laneState =
            schema1Ready.lanes[runtimeProductionLaneIndex(lane)];
        if (!laneState.ready.has_value()) {
            errorMessage = "Phase B schema 1 ready setup lost order";
            return false;
        }
        const RuntimeBuildCatalogItem* readyItem = itemByKey(
            laneState.ready->itemKey
        );
        if (readyItem == nullptr) {
            errorMessage = "Phase B schema 1 ready item left catalog";
            return false;
        }
        laneState.ready->totalTicks = runtimeLegacyBuildTimeTicks(
            readyItem->cost,
            readyItem->wall
        );
    }
    const std::string schema1ReadySerialized =
        runtimeSerializeProductionLanes(schema1Ready);
    const std::string schema1ReadyText =
        "[ProductionLanes]\nSchema=1\nDataHex="
        + runtimeHexEncode(schema1ReadySerialized)
        + "\nStateHash="
        + std::to_string(runtimeProductionLanesStateHash(schema1Ready))
        + "\nSelection=Structures|"
        + std::to_string(structureReady->order.serial)
        + "\n";
    IniFile schema1ReadyIni;
    RuntimeSavedProductionCandidate schema1ReadyCandidate;
    if (!schema1ReadyIni.loadFromString(schema1ReadyText)
        || !loadRuntimeV8ProductionCandidate(
            shell,
            schema1ReadyIni,
            schema1ReadyCandidate,
            errorMessage
        )) {
        errorMessage = "Phase B schema 1 ready migration failed";
        return false;
    }
    const RuntimeProductionLaneState& migratedSchema1Structure =
        schema1ReadyCandidate.lanes.lanes[runtimeProductionLaneIndex(
            RuntimeProductionLane::Structures
        )];
    const RuntimeProductionLaneState& migratedSchema1Armory =
        schema1ReadyCandidate.lanes.lanes[runtimeProductionLaneIndex(
            RuntimeProductionLane::Armory
        )];
    if (!migratedSchema1Structure.ready.has_value()
        || !migratedSchema1Armory.ready.has_value()
        || migratedSchema1Structure.ready->totalTicks
            != structure->buildTicks
        || migratedSchema1Armory.ready->totalTicks != armory->buildTicks
        || migratedSchema1Structure.ready->remainingTicks != 0
        || migratedSchema1Armory.ready->remainingTicks != 0) {
        errorMessage = "Phase B schema 1 ready duration was not migrated";
        return false;
    }

    RuntimeProductionLanesState forgedSchema1 = schema1Ready;
    RuntimeProductionLaneState& forgedStructureLane =
        forgedSchema1.lanes[runtimeProductionLaneIndex(
            RuntimeProductionLane::Structures
        )];
    if (!forgedStructureLane.ready.has_value()) {
        errorMessage = "Phase B forged schema 1 setup lost ready order";
        return false;
    }
    forgedStructureLane.ready->totalTicks =
        runtimeLegacyBuildTimeTicks(structure->cost, structure->wall) + 1;
    const std::string forgedSchema1Serialized =
        runtimeSerializeProductionLanes(forgedSchema1);
    const std::string forgedSchema1Text =
        "[ProductionLanes]\nSchema=1\nDataHex="
        + runtimeHexEncode(forgedSchema1Serialized)
        + "\nStateHash="
        + std::to_string(runtimeProductionLanesStateHash(forgedSchema1))
        + "\nSelection=Structures|"
        + std::to_string(structureReady->order.serial)
        + "\n";
    IniFile forgedSchema1Ini;
    RuntimeSavedProductionCandidate unchangedTiming;
    unchangedTiming.lanes.nextSerial = 991;
    const std::uint64_t unchangedTimingHash =
        runtimeProductionLanesStateHash(unchangedTiming.lanes);
    std::string forgedSchema1Error;
    if (!forgedSchema1Ini.loadFromString(forgedSchema1Text)
        || loadRuntimeV8ProductionCandidate(
            shell,
            forgedSchema1Ini,
            unchangedTiming,
            forgedSchema1Error
        )
        || runtimeProductionLanesStateHash(unchangedTiming.lanes)
            != unchangedTimingHash) {
        errorMessage =
            "Phase B forged schema 1 timing was accepted or non-atomic";
        return false;
    }

    selectRuntimeReadyPlacement(shell, *structureReady, false);
    if (!runtimeConsumeReadyProduction(
            shell.economy.localProductionLanes,
            structureReady->lane,
            structureReady->order.serial
        ).has_value()) {
        errorMessage = "Phase B selected structure consume failed";
        return false;
    }
    shell.economy.selectedPlacementLane.reset();
    shell.economy.selectedPlacementSerial = 0;
    selectRuntimeOldestReadyPlacementIfNeeded(shell, false);
    const std::optional<RuntimeSelectedPlacement> remainingReady =
        runtimeSelectedPlacement(shell);
    if (!remainingReady.has_value()
        || remainingReady->lane != RuntimeProductionLane::Armory
        || remainingReady->order.serial != armoryReady->order.serial) {
        errorMessage = "Phase B independent ready selection did not advance";
        return false;
    }

    initializeRuntimeLocalProductionLanes(shell.economy);
    RuntimeProductionLaneOrder firstVehicle;
    firstVehicle.itemKey = vehicle->typeId;
    firstVehicle.cost = vehicle->cost;
    firstVehicle.totalTicks = std::max(1, vehicle->buildTicks);
    RuntimeProductionLaneOrder queuedVehicle = firstVehicle;
    const RuntimeProductionQueueResult firstVehicleResult =
        runtimeQueueProductionOrder(
            shell.economy.localProductionLanes,
            RuntimeProductionLane::Vehicles,
            firstVehicle,
            shell.rules.getMaximumQueuedObjects(),
            0
        );
    const RuntimeProductionQueueResult queuedVehicleResult =
        runtimeQueueProductionOrder(
            shell.economy.localProductionLanes,
            RuntimeProductionLane::Vehicles,
            queuedVehicle,
            shell.rules.getMaximumQueuedObjects(),
            0
        );
    RuntimeProductionAdvanceHooks zeroRate;
    zeroRate.productionRate = [](
        RuntimeProductionLane,
        const RuntimeProductionLaneOrder&
    ) {
        return RuntimeProductionRate{0, 1};
    };
    int noCredits = 0;
    runtimeAdvanceProductionLanes(
        shell.economy.localProductionLanes,
        noCredits,
        zeroRate
    );
    if (firstVehicleResult.decision
            != RuntimeProductionQueueDecision::Accepted
        || queuedVehicleResult.decision
            != RuntimeProductionQueueDecision::Accepted
        || !handleRuntimeBuildButtonSecondaryAction(shell, *vehicle)) {
        errorMessage = "Phase B queued-tail right-click setup failed";
        return false;
    }
    RuntimeProductionLaneState& vehicleLane =
        shell.economy.localProductionLanes.lanes[
            runtimeProductionLaneIndex(RuntimeProductionLane::Vehicles)
        ];
    if (!vehicleLane.active.has_value()
        || vehicleLane.active->serial != firstVehicleResult.serial
        || !vehicleLane.queued.empty()
        || vehicleLane.onHold) {
        errorMessage = "Phase B right-click did not cancel queued tail first";
        return false;
    }
    if (!handleRuntimeBuildButtonSecondaryAction(shell, *vehicle)
        || !vehicleLane.onHold
        || !handleRuntimeBuildButtonSecondaryAction(shell, *vehicle)
        || vehicleLane.active.has_value()) {
        errorMessage = "Phase B active hold/cancel sequence failed";
        return false;
    }

    const int legacyVehicleTotal = runtimeLegacyBuildTimeTicks(
        vehicle->cost,
        vehicle->wall
    );
    const int legacyRemaining = std::max(1, legacyVehicleTotal / 2);
    if (parseRuntimeBuildOrder(
            shell,
            "Unit|" + vehicle->typeId + "|not-an-int|yes|no"
        ).has_value()
        || parseRuntimeBuildOrder(
            shell,
            "Unit|" + vehicle->typeId + "|"
                + std::to_string(legacyRemaining) + "|maybe|no"
        ).has_value()
        || parseRuntimeBuildOrder(
            shell,
            "Unit|" + vehicle->typeId + "|"
                + std::to_string(legacyRemaining) + "|yes|maybe"
        ).has_value()) {
        errorMessage = "Phase B legacy order parser accepted invalid fields";
        return false;
    }
    IniFile legacyIni;
    const std::string legacyText =
        "[Economy]\nPlacementReady=no\nActiveOrder=Unit|"
        + vehicle->typeId
        + "|" + std::to_string(legacyRemaining)
        + "|yes|no\nQueueCount=0\n";
    RuntimeSavedProductionCandidate legacyCandidate;
    if (!legacyIni.loadFromString(legacyText)
        || !migrateRuntimeLegacyProductionCandidate(
            shell,
            legacyIni,
            legacyCandidate,
            errorMessage
        )) {
        errorMessage = "Phase B v7 partial-active migration failed";
        return false;
    }
    const RuntimeProductionLaneState& migratedVehicleLane =
        legacyCandidate.lanes.lanes[
            runtimeProductionLaneIndex(RuntimeProductionLane::Vehicles)
        ];
    if (!migratedVehicleLane.active.has_value()
        || migratedVehicleLane.active->creditsSpent <= 0
        || migratedVehicleLane.active->totalTicks != vehicle->buildTicks
        || legacyCandidate.legacyCreditRefund <= 0
        || migratedVehicleLane.active->creditsSpent
                + legacyCandidate.legacyCreditRefund
            != vehicle->cost) {
        errorMessage =
            "Phase B v7 migration would debit the active order twice";
        return false;
    }

    IniFile legacyQueuedIni;
    const std::string legacyQueuedText =
        "[Economy]\nPlacementReady=no\nActiveOrder=\nQueueCount=1\n"
        "[Queue]\n0=Unit|"
        + vehicle->typeId
        + "|" + std::to_string(legacyVehicleTotal)
        + "|no|no\n";
    RuntimeSavedProductionCandidate legacyQueuedCandidate;
    if (!legacyQueuedIni.loadFromString(legacyQueuedText)
        || !migrateRuntimeLegacyProductionCandidate(
            shell,
            legacyQueuedIni,
            legacyQueuedCandidate,
            errorMessage
        )) {
        errorMessage = "Phase B v7 queued timing migration failed";
        return false;
    }
    const RuntimeProductionLaneState& legacyQueuedVehicleLane =
        legacyQueuedCandidate.lanes.lanes[runtimeProductionLaneIndex(
            RuntimeProductionLane::Vehicles
        )];
    if (legacyQueuedVehicleLane.queued.size() != 1U
        || legacyQueuedVehicleLane.queued.front().totalTicks
            != vehicle->buildTicks
        || legacyQueuedVehicleLane.queued.front().remainingTicks
            != vehicle->buildTicks) {
        errorMessage = "Phase B v7 queued duration was not migrated";
        return false;
    }

    const BuildingType* vehicleFactoryType = nullptr;
    const std::string requiredVehicleFactory = toUpperAsciiLocal(
        trimAsciiLocal(vehicle->requiredFactory)
    );
    for (const BuildingType& building : shell.rules.getBuildingTypes()) {
        if (toUpperAsciiLocal(trimAsciiLocal(building.factory))
                == requiredVehicleFactory
            && building.weaponsFactory
            && !building.naval
            && !building.waterBound) {
            vehicleFactoryType = &building;
            break;
        }
    }
    if (vehicleFactoryType == nullptr) {
        errorMessage = "Phase B host gate probe lacks a vehicle factory";
        return false;
    }

    RuntimeWindowState hostProbe;
    hostProbe.rules = rules;
    hostProbe.rulesLoaded = true;
    hostProbe.config.fixedTickHz = shell.config.fixedTickHz;
    hostProbe.economy.owner = shell.economy.owner;
    hostProbe.economy.techLevel = 10;
    hostProbe.economy.credits = 1000000;
    hostProbe.economy.storedResourceValue = 100000;
    hostProbe.economy.storedResourceUnits = 100000;
    hostProbe.economy.powerProduced = 100;
    hostProbe.economy.powerUsed = 100;
    initializeRuntimeLocalProductionLanes(hostProbe.economy);
    addRuntimeBuildCatalogItem(
        hostProbe,
        RuntimeBuildKind::Unit,
        vehicle->typeId
    );
    RuntimeBuildCatalogItem* hostVehicle = nullptr;
    for (RuntimeBuildCatalogItem& item : hostProbe.economy.catalog) {
        if (toUpperAsciiLocal(item.typeId)
                == toUpperAsciiLocal(vehicle->typeId)) {
            hostVehicle = &item;
            break;
        }
    }
    if (hostVehicle == nullptr) {
        errorMessage = "Phase B host gate probe lost vehicle catalog item";
        return false;
    }
    hostVehicle->owner.clear();
    hostVehicle->requiredHouses.clear();
    hostVehicle->forbiddenHouses.clear();
    hostVehicle->techLevel = 0;
    hostVehicle->techTreeAllowed = true;
    hostVehicle->techTreeBlockedReason.clear();
    hostVehicle->prerequisite.clear();
    hostVehicle->prerequisiteOverride.clear();

    const auto appendHostFactory = [&hostProbe, vehicleFactoryType](int id) {
        WorldObjectInstance factory;
        factory.instanceId = id;
        factory.kind = WorldObjectKind::Structure;
        factory.owner = hostProbe.economy.owner;
        factory.type = vehicleFactoryType->id;
        factory.alive = true;
        factory.poweredOperational = true;
        hostProbe.world.accessObjects().push_back(std::move(factory));
    };
    appendHostFactory(71001);
    const auto hostFactoryCount = [&hostProbe, hostVehicle]() {
        return static_cast<int>(findRuntimeFactoryAnchorCandidatesForOwner(
            hostProbe,
            *hostVehicle,
            hostProbe.economy.owner,
            false
        ).size());
    };
    const int hostOneFactoryCount = hostFactoryCount();
    appendHostFactory(71002);
    const int hostTwoFactoryCount = hostFactoryCount();
    appendHostFactory(71003);
    const int hostThreeFactoryCount = hostFactoryCount();
    if (hostOneFactoryCount != 1
        || hostTwoFactoryCount != 2
        || hostThreeFactoryCount != 3) {
        errorMessage = "Phase B host factory count was not deterministic";
        return false;
    }
    for (WorldObjectInstance& object : hostProbe.world.accessObjects()) {
        if (object.instanceId == 71002 || object.instanceId == 71003) {
            object.alive = false;
        }
    }

    RuntimeProductionLaneOrder hostOrder;
    hostOrder.itemKey = hostVehicle->typeId;
    hostOrder.cost = hostVehicle->cost;
    hostOrder.totalTicks = hostVehicle->buildTicks;
    const RuntimeProductionQueueResult hostQueued =
        runtimeQueueProductionOrder(
            hostProbe.economy.localProductionLanes,
            RuntimeProductionLane::Vehicles,
            hostOrder,
            hostProbe.rules.getMaximumQueuedObjects(),
            0
        );
    advanceRuntimeProductionEconomy(hostProbe);
    const auto hostVehicleLane = [&hostProbe]()
        -> RuntimeProductionLaneState& {
        return hostProbe.economy.localProductionLanes.lanes[
            runtimeProductionLaneIndex(RuntimeProductionLane::Vehicles)
        ];
    };
    if (hostQueued.decision != RuntimeProductionQueueDecision::Accepted
        || !hostVehicleLane().active.has_value()) {
        errorMessage = "Phase B host canStart did not start valid order";
        return false;
    }

    hostVehicle->prerequisite = "__PHASE_B_REMOVED_PREREQUISITE__";
    const std::uint64_t beforeLostPrerequisite =
        runtimeProductionLanesStateHash(
            hostProbe.economy.localProductionLanes
        );
    advanceRuntimeProductionEconomy(hostProbe);
    const std::uint64_t afterLostPrerequisite =
        runtimeProductionLanesStateHash(
            hostProbe.economy.localProductionLanes
        );
    if (afterLostPrerequisite == beforeLostPrerequisite
        || !hostVehicleLane().active.has_value()) {
        errorMessage =
            "Phase B active order stopped after prerequisite loss";
        return false;
    }

    for (WorldObjectInstance& object : hostProbe.world.accessObjects()) {
        if (object.instanceId == 71001) {
            object.alive = false;
        }
    }
    const std::uint64_t beforeLostFactory =
        runtimeProductionLanesStateHash(
            hostProbe.economy.localProductionLanes
        );
    advanceRuntimeProductionEconomy(hostProbe);
    if (runtimeProductionLanesStateHash(
            hostProbe.economy.localProductionLanes
        ) != beforeLostFactory
        || !hostVehicleLane().active.has_value()) {
        errorMessage = "Phase B active order advanced without a factory";
        return false;
    }
    for (WorldObjectInstance& object : hostProbe.world.accessObjects()) {
        if (object.instanceId == 71001) {
            object.alive = true;
            object.poweredOperational = true;
        }
    }
    advanceRuntimeProductionEconomy(hostProbe);
    if (runtimeProductionLanesStateHash(
            hostProbe.economy.localProductionLanes
        ) == beforeLostFactory) {
        errorMessage = "Phase B active order did not resume with its factory";
        return false;
    }

    initializeRuntimeLocalProductionLanes(hostProbe.economy);
    RuntimeProductionLaneOrder blockedStartOrder;
    blockedStartOrder.itemKey = hostVehicle->typeId;
    blockedStartOrder.cost = hostVehicle->cost;
    blockedStartOrder.totalTicks = hostVehicle->buildTicks;
    if (runtimeQueueProductionOrder(
            hostProbe.economy.localProductionLanes,
            RuntimeProductionLane::Vehicles,
            blockedStartOrder,
            hostProbe.rules.getMaximumQueuedObjects(),
            0
        ).decision != RuntimeProductionQueueDecision::Accepted) {
        errorMessage = "Phase B blocked start queue setup failed";
        return false;
    }
    advanceRuntimeProductionEconomy(hostProbe);
    RuntimeProductionLaneState& blockedStartLane =
        hostProbe.economy.localProductionLanes.lanes[
            runtimeProductionLaneIndex(RuntimeProductionLane::Vehicles)
        ];
    if (blockedStartLane.active.has_value()
        || blockedStartLane.queued.size() != 1U) {
        errorMessage = "Phase B queued order ignored missing prerequisite";
        return false;
    }

    bool poweredFactoryCaseFound = false;
    bool poweredFactoryCasePassed = false;
    RuntimeWindowState poweredFactoryProbe;
    poweredFactoryProbe.rules = rules;
    poweredFactoryProbe.rulesLoaded = true;
    poweredFactoryProbe.economy.owner = shell.economy.owner;
    for (const BuildingType& building : rules.getBuildingTypes()) {
        if (!building.powered || trimAsciiLocal(building.factory).empty()) {
            continue;
        }
        WorldObjectInstance factory;
        factory.instanceId = 72001;
        factory.kind = WorldObjectKind::Structure;
        factory.owner = poweredFactoryProbe.economy.owner;
        factory.type = building.id;
        factory.alive = true;
        factory.poweredOperational = true;
        poweredFactoryProbe.world.accessObjects().clear();
        poweredFactoryProbe.world.accessObjects().push_back(factory);
        for (const RuntimeBuildCatalogItem* item : timingItems) {
            const std::optional<RuntimeProductionLane> lane =
                runtimeProductionLaneForCatalogItem(poweredFactoryProbe, *item);
            if (!lane.has_value()
                || !runtimeProductionFactoryEligibleForOwner(
                    poweredFactoryProbe,
                    poweredFactoryProbe.world.getObjects().front(),
                    poweredFactoryProbe.economy.owner,
                    *lane
                )) {
                continue;
            }
            poweredFactoryCaseFound = true;
            poweredFactoryProbe.world.accessObjects().front()
                .poweredOperational = false;
            const bool blocked =
                findRuntimeFactoryAnchorCandidatesForOwner(
                    poweredFactoryProbe,
                    *item,
                    poweredFactoryProbe.economy.owner,
                    false
                ).empty();
            poweredFactoryProbe.world.accessObjects().front()
                .poweredOperational = true;
            const bool restored =
                findRuntimeFactoryAnchorCandidatesForOwner(
                    poweredFactoryProbe,
                    *item,
                    poweredFactoryProbe.economy.owner,
                    false
                ).size() == 1U;
            poweredFactoryCasePassed = blocked && restored;
            break;
        }
        if (poweredFactoryCaseFound) {
            break;
        }
    }
    if (poweredFactoryCaseFound && !poweredFactoryCasePassed) {
        errorMessage = "Phase B Powered factory did not block and resume";
        return false;
    }
    return true;
}















