int runtimeShortestOreFieldRuleIntervalTicks(const RuntimeWindowState& state) {
    int shortest = std::numeric_limits<int>::max();
    for (const TiberiumType& tiberium : state.rules.getTiberiumTypes()) {
        if (runtimeOreRuleProbability(state, tiberium, false) > 0.0) {
            const int interval = runtimeOreRuleIntervalTicks(tiberium, false);
            if (interval > 0) {
                shortest = std::min(shortest, interval);
            }
        }
        if (runtimeOreRuleProbability(state, tiberium, true) > 0.0) {
            const int interval = runtimeOreRuleIntervalTicks(tiberium, true);
            if (interval > 0) {
                shortest = std::min(shortest, interval);
            }
        }
    }
    return shortest == std::numeric_limits<int>::max() ? 0 : shortest;
}





















struct RuntimeInitialOreSeedResult {
    int seeded = 0;
    int densified = 0;
};





int runtimeInitialOreTargetBailsForRadius(int radius) {
    if (radius <= 3) {
        return runtimeOreMaxBails;
    }
    if (radius == 4) {
        return 9;
    }
    if (radius == 5) {
        return 5;
    }
    return 2;
}

bool runtimeInitialOreSeedCellAllowed(
    const WorldTerrainObject& object,
    const RuntimeCellPoint& cell,
    int radius,
    int maxRadius
) {
    const long long dx = static_cast<long long>(cell.x - object.x);
    const long long dy = static_cast<long long>(cell.y - object.y);
    const long long maxDistance = std::max(0, maxRadius);
    if ((dx * dx) + (dy * dy) > maxDistance * maxDistance) {
        return false;
    }

    int threshold = 1000;
    if (radius == 3) {
        threshold = 900;
    } else if (radius == 4) {
        threshold = 800;
    } else if (radius == 5) {
        threshold = 650;
    } else if (radius >= 6) {
        threshold = 500;
    }

    std::uint64_t hash = runtimeStableHashString("runtimeInitialOreField");
    runtimeStableHashMixString(hash, object.type);
    runtimeStableHashMix(hash, object.x);
    runtimeStableHashMix(hash, object.y);
    runtimeStableHashMix(hash, cell.x);
    runtimeStableHashMix(hash, cell.y);
    runtimeStableHashMix(hash, radius);
    return static_cast<int>(hash % 1000) < threshold;
}

bool seedRuntimeInitialOreAtCell(
    RuntimeWindowState& state,
    const RuntimeCellPoint& cell,
    const RuntimeOreOverlayIdentity& identity,
    int targetBails,
    RuntimeInitialOreSeedResult& result
) {
    TerrainCell* terrain = findMutableRuntimeTerrainCellAt(state, cell);
    if (terrain == nullptr) {
        return false;
    }

    if (terrain->hasOverlay
        && (terrain->overlayIsOre || terrain->overlayIsGem)) {
        const int currentBails = runtimeResourceBailCountForTerrain(*terrain);
        const int maxBails = runtimeResourceMaxBailsForTerrain(*terrain);
        const int clampedTarget =
            std::clamp(targetBails, 1, maxBails);
        if (currentBails >= clampedTarget) {
            return false;
        }
        setRuntimeResourceTerrainBails(
            *terrain,
            runtimeResourceFamilyForTerrain(*terrain),
            clampedTarget
        );
        ++result.densified;
        return true;
    }
    if (terrain->hasOverlay) {
        return false;
    }

    const int clampedTarget = std::clamp(
        targetBails,
        1,
        runtimeResourceMaxBailsForFamily(identity.family)
    );
    RuntimeOreOverlayIdentity cellIdentity = identity.fixedVariant
        ? runtimeOreIdentityForVariant(
            identity.family,
            identity.variant,
            clampedTarget
        )
        : runtimeOreIdentityForCell(
            cell,
            identity.family,
            clampedTarget
        );
    terrain->hasOverlay = true;
    terrain->overlayIndex = cellIdentity.overlayIndex;
    terrain->overlayType = cellIdentity.type;
    terrain->overlayImage = cellIdentity.image;
    terrain->overlayFrame = clampedTarget - 1;
    terrain->overlayIsOre = !cellIdentity.gem;
    terrain->overlayIsGem = cellIdentity.gem;
    ++result.seeded;
    return true;
}






















































































