std::uint64_t runtimeMultiplayerHouseAuthorityHash(
    const RuntimeWindowState& state
) {
    std::uint64_t hash = 1469598103934665603ull;
    runtimeStableHashMixString(hash, "HumanHouseAuthority/1");
    std::vector<const RuntimeHumanHouseAuthority*> authorities;
    authorities.reserve(state.humanHouseAuthorities.size());
    for (const RuntimeHumanHouseAuthority& authority :
            state.humanHouseAuthorities) {
        authorities.push_back(&authority);
    }
    std::sort(
        authorities.begin(),
        authorities.end(),
        [](const RuntimeHumanHouseAuthority* left,
           const RuntimeHumanHouseAuthority* right) {
            return std::tie(left->canonicalOwner, left->slotIndex)
                < std::tie(right->canonicalOwner, right->slotIndex);
        }
    );
    runtimeStableHashMix(
        hash,
        static_cast<long long>(authorities.size())
    );
    for (const RuntimeHumanHouseAuthority* authority : authorities) {
        runtimeStableHashMixString(hash, authority->canonicalOwner);
        runtimeStableHashMixString(hash, authority->country);
        runtimeStableHashMix(
            hash,
            static_cast<long long>(authority->slotIndex)
        );
        const RuntimeEconomyState* economy =
            runtimeHumanHouseEconomy(state, authority->owner);
        if (economy == nullptr) {
            runtimeStableHashMix(hash, -1);
            continue;
        }
        runtimeStableHashMix(hash, economy->techLevel);
        runtimeStableHashMix(hash, economy->credits);
        runtimeStableHashMix(hash, economy->powerProduced);
        runtimeStableHashMix(hash, economy->powerUsed);
        runtimeStableHashMix(hash, economy->harvesters);
        runtimeStableHashMix(hash, economy->refineries);
        runtimeStableHashMix(hash, economy->incomeCooldownTicks);
        runtimeStableHashMix(hash, economy->storedResourceUnits);
        runtimeStableHashMix(hash, economy->storedResourceValue);
        runtimeStableHashMix(hash, economy->storedResourceGemUnits);
        runtimeStableHashMix(hash, economy->resourceStorageCapacity);
        runtimeStableHashMix(
            hash,
            static_cast<long long>(runtimeProductionLanesStateHash(
                economy->localProductionLanes
            ))
        );
        runtimeStableHashMix(
            hash,
            economy->selectedPlacementLane.has_value()
                ? static_cast<long long>(
                    static_cast<std::uint8_t>(
                        *economy->selectedPlacementLane
                    ) + 1
                  )
                : 0
        );
        runtimeStableHashMix(
            hash,
            static_cast<long long>(economy->selectedPlacementSerial)
        );
        runtimeStableHashMix(hash, economy->completedBuildings);
        runtimeStableHashMix(hash, economy->completedUnits);
        runtimeStableHashMix(hash, economy->completedInfantry);
        runtimeStableHashMix(hash, economy->resourceTrips);
        std::vector<std::tuple<std::string, int, int>> catalog;
        catalog.reserve(economy->catalog.size());
        for (const RuntimeBuildCatalogItem& item : economy->catalog) {
            catalog.emplace_back(item.typeId, item.cost, item.buildTicks);
        }
        std::sort(catalog.begin(), catalog.end());
        runtimeStableHashMix(
            hash,
            static_cast<long long>(catalog.size())
        );
        for (const auto& [typeId, cost, buildTicks] : catalog) {
            runtimeStableHashMixString(hash, typeId);
            runtimeStableHashMix(hash, cost);
            runtimeStableHashMix(hash, buildTicks);
        }
        runtimeStableHashMix(
            hash,
            state.computerAiByOwner.contains(authority->canonicalOwner)
                ? 1
                : 0
        );
    }
    std::vector<std::pair<int, int>> repairs(
        state.repairingStructureTicks.begin(),
        state.repairingStructureTicks.end()
    );
    std::sort(repairs.begin(), repairs.end());
    runtimeStableHashMix(hash, static_cast<long long>(repairs.size()));
    for (const auto& [objectId, ticks] : repairs) {
        runtimeStableHashMix(hash, objectId);
        runtimeStableHashMix(hash, ticks);
    }
    runtimeStableHashMix(
        hash,
        static_cast<long long>(state.world.deterministicSimulationStateHash())
    );
    return hash;
}

