std::uint64_t nextRuntimeMultiplayerSaveLoadProposalId(
    const RuntimeMultiplayerSessionState& session
) {
    std::uint64_t highest = 0;
    for (const RuntimeMultiplayerSaveLoadHandshake& handshake :
            session.saveLoadHandshakes()) {
        highest = std::max(highest, handshake.proposal.proposalId);
    }
    return highest == std::numeric_limits<std::uint64_t>::max()
        ? 0U
        : highest + 1U;
}



bool readRuntimeMultiplayerSnapshotFile(
    const std::string& path,
    std::vector<std::uint8_t>& bytes,
    std::string& errorMessage
) {
    std::ifstream input(path, std::ios::binary | std::ios::ate);
    if (!input) {
        errorMessage = "could not open multiplayer save";
        return false;
    }
    const std::streampos end = input.tellg();
    if (end < 0
        || static_cast<std::uint64_t>(end)
            > runtimeMultiplayerSnapshotDefaultMaximumBytes) {
        errorMessage = "multiplayer save size is invalid";
        return false;
    }
    std::vector<std::uint8_t> candidate(
        static_cast<std::size_t>(end)
    );
    input.seekg(0, std::ios::beg);
    if (!candidate.empty()) {
        input.read(
            reinterpret_cast<char*>(candidate.data()),
            static_cast<std::streamsize>(candidate.size())
        );
    }
    if (!input) {
        errorMessage = "could not read multiplayer save";
        return false;
    }
    bytes = std::move(candidate);
    errorMessage.clear();
    return true;
}

bool writeRuntimeMultiplayerSnapshotFile(
    const std::string& path,
    const std::vector<std::uint8_t>& bytes,
    std::string& errorMessage
) {
    return runtimeWriteFileAtomically(
        path,
        [&bytes](std::ostream& output, std::string& writerError) {
            if (!bytes.empty()) {
                output.write(
                    reinterpret_cast<const char*>(bytes.data()),
                    static_cast<std::streamsize>(bytes.size())
                );
            }
            if (!output) {
                writerError = "could not write multiplayer snapshot bytes";
                return false;
            }
            writerError.clear();
            return true;
        },
        errorMessage
    );
}



#include "network/session/RuntimeMultiplayerResumeRuntime.inl"

bool beginRuntimeMultiplayerFileOperation(
    RuntimeWindowState& state,
    bool save,
    std::string& errorMessage
) {
    RuntimeMultiplayerRuntimeBridge* bridge = state.multiplayerBridge;
    if (bridge == nullptr) {
        errorMessage = "multiplayer bridge is not attached";
        return false;
    }
    const RuntimeMultiplayerSessionState& session = bridge->lan().session();
    if (!bridge->localPeerIsHost() || bridge->localPeerIsSpectator()) {
        errorMessage = "only the host may save or load a multiplayer match";
        return false;
    }
    if (state.multiplayerPendingFileOperation.has_value()
        || session.hasActiveSaveLoadHandshake()) {
        errorMessage = "another multiplayer save/load is pending";
        return false;
    }
    if (state.tick != session.authoritativeTick() - 1
        || state.config.multiplayerTimelineEpoch
            != session.timelineEpoch()) {
        errorMessage = "multiplayer save/load barrier is not current";
        return false;
    }
    const std::uint64_t proposalId =
        nextRuntimeMultiplayerSaveLoadProposalId(session);
    if (proposalId == 0U) {
        errorMessage = "multiplayer save/load proposal ids are exhausted";
        return false;
    }

    const std::string path = runtimeDefaultSavePath(state);
    RuntimeMultiplayerSnapshotMemoryImage image;
    if (save) {
        RuntimeMultiplayerSnapshotIdentity identity;
        identity.proposalId = proposalId;
        identity.kind = RuntimeMultiplayerSnapshotKind::Save;
        identity.sourceTimelineEpoch = session.timelineEpoch();
        identity.barrierTick = state.tick;
        identity.snapshotTick = state.tick;
        identity.snapshotToken =
            "runtime-quicksave-" + std::to_string(proposalId);
        identity.gameplaySetupFingerprint =
            state.config.multiplayerSetupHash;
        identity.authoritativeStateHash =
            runtimeMultiplayerAuthoritativeStateHash(state, errorMessage);
        if (identity.authoritativeStateHash == 0U
            || !exportRuntimeMultiplayerSnapshotV15(
                state,
                identity,
                image,
                errorMessage
            )) {
            return false;
        }
        RuntimeMultiplayerSnapshotStagedState preflight;
        if (!stageRuntimeMultiplayerSnapshot(
                state,
                image.bytes,
                image.descriptor,
                preflight,
                errorMessage
            )) {
            return false;
        }
    } else {
        std::vector<std::uint8_t> savedBytes;
        if (!readRuntimeMultiplayerSnapshotFile(
                path,
                savedBytes,
                errorMessage
            )
            || !rebindRuntimeMultiplayerSaveAsLoad(
                state,
                savedBytes,
                proposalId,
                session.timelineEpoch(),
                state.tick,
                image,
                errorMessage
            )) {
            return false;
        }
    }

    RuntimeMultiplayerSaveLoadProposal proposal;
    proposal.timelineEpoch = session.timelineEpoch();
    proposal.proposalId = proposalId;
    proposal.kind = save
        ? RuntimeMultiplayerSaveLoadKind::Save
        : RuntimeMultiplayerSaveLoadKind::Load;
    proposal.proposerPeerId = bridge->lan().localPeerId();
    proposal.descriptor = image.descriptor;
    RuntimeMultiplayerPendingFileOperation pending;
    pending.proposalId = proposalId;
    pending.sourceTimelineEpoch = session.timelineEpoch();
    pending.kind = proposal.kind;
    pending.descriptor = image.descriptor;
    pending.path = path;
    if (save) pending.saveBytes = image.bytes;

    const RuntimeMultiplayerLanOperationResult proposed =
        bridge->proposeSaveLoad(proposal, std::move(image.bytes));
    if (!proposed.succeeded || !proposed.applied) {
        errorMessage = proposed.reason.empty()
            ? "multiplayer save/load proposal was rejected"
            : proposed.reason;
        return false;
    }
    state.multiplayerPendingFileOperation = std::move(pending);
    errorMessage.clear();
    return true;
}

bool refreshRuntimeMultiplayerPendingFileOperation(
    RuntimeWindowState& state,
    std::string& errorMessage
) {
    if (!state.multiplayerPendingFileOperation.has_value()
        || state.multiplayerBridge == nullptr) {
        errorMessage.clear();
        return true;
    }
    const RuntimeMultiplayerPendingFileOperation& pending =
        *state.multiplayerPendingFileOperation;
    const auto& handshakes =
        state.multiplayerBridge->lan().session().saveLoadHandshakes();
    const auto handshake = std::find_if(
        handshakes.begin(),
        handshakes.end(),
        [&pending](const RuntimeMultiplayerSaveLoadHandshake& candidate) {
            return candidate.proposal.proposalId == pending.proposalId
                && candidate.proposal.timelineEpoch
                    == pending.sourceTimelineEpoch;
        }
    );
    if (handshake == handshakes.end()) {
        errorMessage.clear();
        return true;
    }
    if (handshake->proposal.kind != pending.kind
        || handshake->proposal.descriptor != pending.descriptor) {
        state.multiplayerPendingFileOperation.reset();
        errorMessage = "multiplayer save/load handshake identity changed";
        return false;
    }
    if (handshake->status == RuntimeMultiplayerSaveLoadStatus::Rejected
        || handshake->status == RuntimeMultiplayerSaveLoadStatus::Aborted) {
        state.multiplayerPendingFileOperation.reset();
        errorMessage = "multiplayer save/load was rejected or aborted";
        return false;
    }
    if (handshake->status != RuntimeMultiplayerSaveLoadStatus::Committed) {
        errorMessage.clear();
        return true;
    }

    const bool save = pending.kind == RuntimeMultiplayerSaveLoadKind::Save;
    std::string path = pending.path;
    std::vector<std::uint8_t> bytes = pending.saveBytes;
    state.multiplayerPendingFileOperation.reset();
    if (save
        && !writeRuntimeMultiplayerSnapshotFile(
            path,
            bytes,
            errorMessage
        )) {
        return false;
    }
    state.interactionStatus = save
        ? "multiplayer save committed " + path
        : "multiplayer load committed";
    state.repaintRequested = true;
    errorMessage.clear();
    return true;
}

bool dispatchRuntimeSaveLoadFromUi(
    RuntimeWindowState& state,
    bool save,
    std::string& errorMessage
) {
    if (state.multiplayerBridge == nullptr) {
        const std::string path = runtimeDefaultSavePath(state);
        return save
            ? saveRuntimeState(state, path, errorMessage)
            : loadRuntimeState(state, path, errorMessage);
    }
    return beginRuntimeMultiplayerFileOperation(state, save, errorMessage);
}

