RECT normalizedRect(POINT first, POINT second) {
    return {
        std::min(first.x, second.x),
        std::min(first.y, second.y),
        std::max(first.x, second.x),
        std::max(first.y, second.y)
    };
}

bool rectsIntersect(const RECT& left, const RECT& right) {
    return runtimeInputPixelRectsIntersect(
        {left.left, left.top, left.right, left.bottom},
        {right.left, right.top, right.right, right.bottom});
}

bool rectIsEmpty(const RECT& rect) {
    return rect.left >= rect.right || rect.top >= rect.bottom;
}

RECT unionRects(const RECT& left, const RECT& right) {
    if (rectIsEmpty(left)) {
        return right;
    }
    if (rectIsEmpty(right)) {
        return left;
    }
    return {
        std::min(left.left, right.left),
        std::min(left.top, right.top),
        std::max(left.right, right.right),
        std::max(left.bottom, right.bottom)
    };
}

bool pointInRectInclusive(const RECT& rect, POINT point) {
    return runtimeInputPixelPointInRectInclusive(
        {rect.left, rect.top, rect.right, rect.bottom}, {point.x, point.y});
}

bool pointInRuntimeIsoDiamond(
    POINT point,
    POINT center,
    int halfWidth,
    int halfHeight
) {
    halfWidth = std::max(1, halfWidth);
    halfHeight = std::max(1, halfHeight);
    const double dx =
        std::abs(static_cast<double>(point.x - center.x))
        / static_cast<double>(halfWidth);
    const double dy =
        std::abs(static_cast<double>(point.y - center.y))
        / static_cast<double>(halfHeight);
    return dx + dy <= 1.0;
}

RECT runtimeFootprintDiamondBounds(
    const std::vector<RuntimeInputPixelPoint>& centers,
    int halfWidth,
    int halfHeight
) {
    halfWidth = std::max(1, halfWidth);
    halfHeight = std::max(1, halfHeight);
    RECT bounds{0, 0, 0, 0};
    bool initialized = false;
    for (const RuntimeInputPixelPoint& center : centers) {
        const RECT cellBounds{
            center.x - halfWidth,
            center.y - halfHeight,
            center.x + halfWidth,
            center.y + halfHeight
        };
        bounds = initialized ? unionRects(bounds, cellBounds) : cellBounds;
        initialized = true;
    }
    return initialized ? bounds : RECT{0, 0, 0, 0};
}






#include "render/core/RuntimeCombinedCameraBounds.inl"









bool scrollRuntimeMapCameraClamped(
    RuntimeWindowState& state,
    int deltaX,
    int deltaY
) {
    if (deltaX != 0 || deltaY != 0) state.playerLocalCommands.cameraFollow = false;
    const RECT viewport = runtimeRenderPlacementNativeRect(state.cameraClampViewport);
    if (viewport.right <= viewport.left || viewport.bottom <= viewport.top) {
        // Input can arrive before the first paint/resize establishes the map
        // viewport.  Deferring that scroll is safer than applying an
        // unclamped offset that could put the first rendered frame completely
        // beyond the map.
        return false;
    }
    const int beforeX = state.camera.worldOffsetX;
    const int beforeY = state.camera.worldOffsetY;
    scrollRuntimeMapCamera(state.camera, deltaX, deltaY);
    clampRuntimeMapCamera(state, viewport);
    return state.camera.worldOffsetX != beforeX
        || state.camera.worldOffsetY != beforeY;
}

// No simulation runs during a paint. Repeated overlay/picking queries can
// reuse its completed clamp for exactly the same state, viewport and camera.
// Nothing survives the paint; in-place terrain edits and loading remain safe.
struct RuntimePaintCameraMemoScope {
    static inline thread_local RuntimePaintCameraMemoScope* active = nullptr;
    RuntimePaintCameraMemoScope* previous = active;
    const RuntimeWindowState* state = nullptr;
    RECT viewport{};
    int x = 0, y = 0, width = 0, height = 0;
    RuntimePaintCameraMemoScope() { active = this; }
    ~RuntimePaintCameraMemoScope() { active = previous; }
    bool matches(const RuntimeWindowState& value, const RECT& rect) const {
        return state == &value && value.camera.initialized
            && EqualRect(&viewport, &rect)
            && x == value.camera.worldOffsetX && y == value.camera.worldOffsetY
            && width == value.camera.tileWidth && height == value.camera.tileHeight;
    }
    void remember(const RuntimeWindowState& value, const RECT& rect) {
        state = &value; viewport = rect;
        x = value.camera.worldOffsetX; y = value.camera.worldOffsetY;
        width = value.camera.tileWidth; height = value.camera.tileHeight;
    }
};

void ensureRuntimeCameraForViewport(
    RuntimeWindowState& state,
    const RECT& viewport
) {
    if (!state.world.getSummary().loaded) {
        return;
    }
    state.cameraClampViewport = runtimeRenderPlacementPixelRect(viewport);
    auto* memo = RuntimePaintCameraMemoScope::active;
    if (memo && !runtimePresentationReferenceEnabled() && memo->matches(state, viewport)) return;
    if (!state.camera.initialized) {
        const RuntimeCameraWorldBounds bounds = runtimeCameraWorldBounds(state);
        if (bounds.valid) {
            const int viewportWidth = std::max(
                1,
                static_cast<int>(viewport.right - viewport.left)
            );
            const int viewportHeight = std::max(
                1,
                static_cast<int>(viewport.bottom - viewport.top)
            );
            state.camera.worldOffsetX = bounds.left
                + ((bounds.right - bounds.left) / 2)
                - (viewportWidth / 2);
            state.camera.worldOffsetY = bounds.top
                + ((bounds.bottom - bounds.top) / 2)
                - (viewportHeight / 2);
            state.camera.initialized = true;
        } else {
            initializeRuntimeMapCamera(
                state.camera,
                state.world,
                viewport.right - viewport.left,
                viewport.bottom - viewport.top
            );
        }
    }
    if (clampRuntimeMapCamera(state, viewport)) {
        invalidateRuntimeObjectProjectionCache(state);
    }
    if (memo) memo->remember(state, viewport);
}

RECT runtimeProjectedFootprintBounds(
    const RuntimeWindowState& state,
    const RECT& viewport,
    const std::vector<RuntimeCellPoint>& cells
) {
    const int halfTileWidth = std::max(1, state.camera.tileWidth / 2);
    const int halfTileHeight = std::max(1, state.camera.tileHeight / 2);
    RECT bounds{0, 0, 0, 0};
    bool initialized = false;
    for (const RuntimeCellPoint& cell : cells) {
        const RuntimeProjectedPoint projected =
            runtimeProjectCellXY(
                cell.x,
                cell.y,
                terrainLevelAtRuntimeCell(state, cell.x, cell.y),
                state.camera
            );
        const POINT point = runtimeScreenPoint(
            projected,
            viewport,
            state.camera
        );
        const RECT cellBounds{
            point.x - halfTileWidth,
            point.y - halfTileHeight,
            point.x + halfTileWidth,
            point.y + halfTileHeight
        };
        if (!initialized) {
            bounds = cellBounds;
            initialized = true;
        } else {
            bounds.left = std::min(bounds.left, cellBounds.left);
            bounds.top = std::min(bounds.top, cellBounds.top);
            bounds.right = std::max(bounds.right, cellBounds.right);
            bounds.bottom = std::max(bounds.bottom, cellBounds.bottom);
        }
    }
    return initialized ? bounds : RECT{0, 0, 0, 0};
}

RECT hitBoundsForObject(
    const RuntimeWindowState& state,
    const WorldObjectInstance& object,
    const RECT& viewport,
    POINT center
) {
    int halfWidth = 8;
    int top = 18;
    int bottom = 5;
    if (runtimeObjectUsesStructureFootprint(state, object)) {
        const std::vector<RuntimeCellPoint> cells =
            runtimeStructureFootprintCellsForObject(state, object);
        const RECT bounds = runtimeProjectedFootprintBounds(state, viewport, cells);
        if (bounds.left == bounds.right || bounds.top == bounds.bottom) {
            return {center.x - 16, center.y - 8, center.x + 16, center.y + 8};
        }
        return bounds;
    } else if (object.kind == WorldObjectKind::Unit) {
        halfWidth = 18;
        top = 30;
        bottom = 10;
    }

    return {
        center.x - halfWidth,
        center.y - top,
        center.x + halfWidth,
        center.y + bottom
    };
}

POINT runtimeOverlayCenterForObject(
    const RuntimeWindowState& state,
    const WorldObjectInstance& object,
    const RECT& viewport
) {
    double drawX = runtimeObjectRenderX(object);
    double drawY = runtimeObjectRenderY(object);
    const WorldObjectCellOffset subCellOffset =
        worldObjectSubCellOffset(object);
    drawX += subCellOffset.x;
    drawY += subCellOffset.y;
    if (runtimeObjectUsesStructureFootprint(state, object)) {
        const RuntimeStructureFootprint footprint =
            runtimeStructureFootprintForObject(state, object);
        drawX += static_cast<double>(std::max(1, footprint.width) - 1) * 0.5;
        drawY += static_cast<double>(std::max(1, footprint.height) - 1) * 0.5;
    }

    const RuntimeProjectedPoint projected =
        runtimeProjectCellXY(
            drawX,
            drawY,
            runtimeDrawLevelForObject(object),
            state.camera
    );
    return runtimeScreenPoint(projected, viewport, state.camera);
}

constexpr int runtimeUnitSelectionFrameWidth = 36;
constexpr int runtimeUnitSelectionFrameHeight = 40;
constexpr int runtimeUnitSelectionFrameTop = 30;

RECT runtimeUnitSelectionBoundsForAnchor(POINT anchor, int pixelDelta = 0) {
    constexpr int halfWidth = runtimeUnitSelectionFrameWidth / 2;
    // Native screen pixels: positive is down. Leave the body/feet anchor alone.
    // Use wide arithmetic for malformed extreme mod values, with space for the bar.
    const LONG top = static_cast<LONG>(std::clamp<long long>(
        static_cast<long long>(anchor.y) - runtimeUnitSelectionFrameTop + pixelDelta,
        static_cast<long long>(std::numeric_limits<LONG>::min()) + 8,
        static_cast<long long>(std::numeric_limits<LONG>::max()) - runtimeUnitSelectionFrameHeight - 6));
    return {anchor.x - halfWidth, top,
        anchor.x - halfWidth + runtimeUnitSelectionFrameWidth, top + runtimeUnitSelectionFrameHeight};
}

RECT runtimeUnitHealthFrame(const RuntimeProjectedObject& projectedObject, bool applyBracketDelta = true) {
    const bool hasBase = projectedObject.selectionBaseBounds.right > projectedObject.selectionBaseBounds.left
        && projectedObject.selectionBaseBounds.bottom > projectedObject.selectionBaseBounds.top;
    const auto& bounds = hasBase ? projectedObject.selectionBaseBounds : projectedObject.selectionBounds;
    const int frameWidth = projectedObject.object != nullptr
        && projectedObject.object->kind == WorldObjectKind::Unit ? 36 : 18;
    const LONG left = bounds.left + (bounds.right - bounds.left) / 2 - frameWidth / 2;
    // Retail 0x6F6864/0x6F68FA and 0x6F68D5/0x6F6968 add the signed
    // TechnoType +0x3E0 value to PIPBRD/health-pip Y. It does not resize
    // the visible body or change picking; cargo pips keep the base anchor.
    const LONG top = static_cast<LONG>(std::clamp<long long>(
        static_cast<long long>(bounds.top) - 8
            + (applyBracketDelta ? projectedObject.healthPixelOffsetY : 0),
        static_cast<long long>(std::numeric_limits<LONG>::min()) + 2,
        static_cast<long long>(std::numeric_limits<LONG>::max()) - 6));
    return {left, top, left + frameWidth, top + 4};
}

RECT runtimeUnitSelectionBoundsForSprite(const RECT& sprite) {
    RECT base = sprite;
    InflateRect(&base, 3, 3);
    // Concord's body envelope remains independent of the native health-bar
    // displacement. Visible frame corners retain the existing click tolerance.
    return base;
}

POINT runtimeProjectedUnitSelectionCenter(
    const RuntimeProjectedObject& projectedObject
) {
    if (projectedObject.selectionBounds.right
            > projectedObject.selectionBounds.left
        && projectedObject.selectionBounds.bottom
            > projectedObject.selectionBounds.top) {
        return {
            projectedObject.selectionBounds.left
                + (projectedObject.selectionBounds.right - projectedObject.selectionBounds.left) / 2,
            projectedObject.selectionBounds.top
                + (projectedObject.selectionBounds.bottom - projectedObject.selectionBounds.top) / 2
        };
    }
    return runtimeRenderPlacementNativePoint(projectedObject.center);
}

bool runtimeRectEquals(const RECT& left, const RECT& right) {
    return left.left == right.left
        && left.top == right.top
        && left.right == right.right
        && left.bottom == right.bottom;
}

bool runtimeSpecialObjectHiddenForInteraction(
    const RuntimeWindowState& state,
    const WorldObjectInstance& object
) {
    if (!state.specialMechanismsInitialized) {
        return false;
    }
    if (state.specialMechanisms.isCarrierChildDocked(object.instanceId)
        || runtimeCarrierAircraftHasDeckProtection(state, object)
        || state.specialMechanisms.isChronoInTransit(object.instanceId)) {
        return true;
    }
    return state.visionEnabled
        && state.specialMechanisms.isCamouflaged(object.instanceId)
        && object.owner != state.economy.owner
        && !runtimeOwnersAreAllied(state, object.owner, state.economy.owner);
}

void runtimeHashMix(unsigned long long& hash, long long value) {
    hash ^= static_cast<unsigned long long>(value)
        + 0x9e3779b97f4a7c15ull
        + (hash << 6)
        + (hash >> 2);
}

int runtimeQuantizedRenderCoordinate(double value) {
    return static_cast<int>(std::llround(value * 256.0));
}

unsigned long long runtimeTerrainObjectsStateSignature(
    const RuntimeWindowState& state
) {
    unsigned long long hash = 1469598103934665603ull;
    for (std::size_t index = 0;
        index < state.world.getTerrainObjects().size();
        ++index) {
        const WorldTerrainObject& object =
            state.world.getTerrainObjects()[index];
        runtimeHashMix(hash, static_cast<long long>(index));
        for (unsigned char character : object.mapId) {
            runtimeHashMix(hash, character);
        }
        runtimeHashMix(hash, -1);
        for (unsigned char character : object.type) {
            runtimeHashMix(hash, character);
        }
        runtimeHashMix(hash, -2);
        runtimeHashMix(hash, object.x);
        runtimeHashMix(hash, object.y);
        runtimeHashMix(hash, object.strength);
        runtimeHashMix(hash, object.health);
        runtimeHashMix(hash, object.immune ? 1 : 0);
        runtimeHashMix(hash, object.alive ? 1 : 0);
        runtimeHashMix(hash, object.occupationBits);
        runtimeHashMix(hash, object.footprintWidth);
        runtimeHashMix(hash, object.footprintHeight);
        for (int subCell : object.occupiedSubCells) {
            runtimeHashMix(hash, subCell);
        }
        runtimeHashMix(hash, -3);
    }
    return hash;
}

unsigned long long runtimePersistentTransientStateHash(
    const RuntimeWindowState& state
) {
    std::uint64_t hash = 1469598103934665603ull;
    std::ostringstream transportEgress;
    writeRuntimeTransportTransferPresentation(state, transportEgress);
    if (!transportEgress.str().empty()) runtimeStableHashMixString(hash, transportEgress.str());
    if (!state.triggers.computerTacticsByOwner.empty()) {
        std::ostringstream computerTactics;
        writeRuntimeComputerTactics(computerTactics, state);
        runtimeStableHashMixString(hash, computerTactics.str());
    }

    mixRuntimeComputerMiningHash(hash, state.computerMiningByOwner);
    RuntimeWorldAudioSystemState hashedWorldAudio =
        state.worldAudioInitialized
        ? state.worldAudio
        : RuntimeWorldAudioSystemState(RuntimeWorldAudioConfig{
            std::max(1, state.config.fixedTickHz), 4096U
        });
    if (hashedWorldAudio.lastAdvancedTick() < state.tick
        && (!state.worldAudioInitialized
            || hashedWorldAudio.handles().empty())) {
        (void)hashedWorldAudio.tick(
            runtimeWorldAudioContext(state),
            state.tick
        );
    }
    RuntimeLightingSystemState hashedLighting = state.lightingInitialized
        ? state.lighting
        : RuntimeLightingSystemState(
            state.mapFacts.lighting,
            runtimeLightingConfigForState(state)
        );
    if (hashedLighting.lastAdvancedTick() < state.tick) {
        (void)hashedLighting.tick(state.tick);
    }
    RuntimeParticleSystemState hashedParticles = state.particlesInitialized
        ? state.particles
        : RuntimeParticleSystemState(std::max(1, state.config.fixedTickHz));
    if (hashedParticles.currentTick() < state.tick) {
        (void)hashedParticles.alignEmptyStateTick(state.tick);
    }
    SuperWeaponSystem hashedSuperWeapons;
    if (state.superWeaponsInitialized) {
        hashedSuperWeapons = state.superWeapons;
    } else {
        hashedSuperWeapons.reset(std::vector<SuperWeaponRule>{});
    }
    if (hashedSuperWeapons.lastTick() != state.tick) {
        (void)hashedSuperWeapons.alignEmptyStateTick(state.tick);
    }
    runtimeStableHashMixString(hash, "WorldAudioRuntime/1");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(state.worldAudioCatalog.stateHash())
    );
    runtimeStableHashMix(
        hash,
        static_cast<long long>(hashedWorldAudio.stateHash())
    );
    runtimeStableHashMixString(hash, "LightingRuntime/1");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(hashedLighting.stateHash())
    );
    for (const auto& [token, active] : state.activeLightingTokens) {
        runtimeStableHashMix(hash, static_cast<long long>(token));
        runtimeStableHashMix(
            hash,
            static_cast<long long>(active.mode)
        );
        runtimeStableHashMix(hash, active.startedTick);
    }
    runtimeStableHashMixString(hash, "ParticleRuntime/1");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(hashedParticles.stateHash())
    );
    runtimeStableHashMixString(hash, "SuperWeaponRuntime/2");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(hashedSuperWeapons.stateHash())
    );
    runtimeStableHashMixString(hash, "Projectiles/5");
    runtimeStableHashMix(hash, state.nextProjectileActorId);
    runtimeStableHashMix(
        hash,
        static_cast<long long>(state.projectiles.size())
    );
    for (const RuntimeProjectileEffect& projectile : state.projectiles) {
        auto authoritative = projectile;
        authoritative.sourceScreenOffsetX = authoritative.sourceScreenOffsetY = 0;
        authoritative.sourceNativeFixedX = authoritative.sourceNativeFixedY = 0;
        runtimeStableHashMixString(
            hash,
            serializeRuntimeProjectileEffect(authoritative)
        );
    }
    runtimeStableHashMixString(hash, "DeathWeaponRuntime/1");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(state.deathWeapons.stateHash())
    );
    runtimeStableHashMixString(hash, "CombatDetails/1");
    runtimeStableHashMix(hash, static_cast<long long>(state.combatDetails.deterministicHash()));
    runtimeStableHashMixString(hash, "RuntimePsychicStatus/2");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(state.psychicStatuses.stateHash())
    );
    runtimeStableHashMixString(hash, "RuntimeMagBeam/2");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(state.magBeams.stateHash())
    );
    runtimeStableHashMixString(hash, "AirstrikeRuntime/3");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(state.airstrikes.stateHash())
    );
    runtimeStableHashMixString(hash, "AirstrikeHost/1");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(state.airstrikePlanesByToken.size())
    );
    for (const auto& [planeToken, binding] :
            state.airstrikePlanesByToken) {
        runtimeStableHashMix(hash, planeToken);
        runtimeStableHashMix(hash, binding.strikeId);
        runtimeStableHashMix(hash, binding.objectId);
        runtimeStableHashMix(hash, binding.callerObjectId);
        runtimeStableHashMix(hash, binding.targetObjectId);
        runtimeStableHashMix(hash, binding.spawnTick);
        runtimeStableHashMix(hash, binding.bombTick);
        runtimeStableHashMix(hash, binding.egressStartTick);
        runtimeStableHashMix(hash, binding.despawnTick);
        runtimeStableHashMix(hash, binding.elite ? 1 : 0);
        runtimeStableHashMixString(hash, binding.owner);
        runtimeStableHashMixString(hash, binding.aircraftTypeId);
        runtimeStableHashMixString(hash, binding.weaponId);
        runtimeStableHashMixString(hash, binding.warheadId);
        runtimeStableHashMix(hash, binding.route.entry.x);
        runtimeStableHashMix(hash, binding.route.entry.y);
        runtimeStableHashMix(hash, binding.route.target.x);
        runtimeStableHashMix(hash, binding.route.target.y);
        runtimeStableHashMix(hash, binding.route.exit.x);
        runtimeStableHashMix(hash, binding.route.exit.y);
        if(binding.hasPreciseEgressOrigin) {
            runtimeStableHashMixString(hash,"AirstrikeEgressOrigin/1");
            runtimeMultiplayerAuthoritativeMixDouble(hash,binding.preciseEgressOriginX);
            runtimeMultiplayerAuthoritativeMixDouble(hash,binding.preciseEgressOriginY);
        }
    }
    runtimeStableHashMix(
        hash,
        static_cast<long long>(
            state.airstrikeRootAuthoritiesByActor.size()
        )
    );
    for (const auto& [rootActorId, authority] :
            state.airstrikeRootAuthoritiesByActor) {
        runtimeStableHashMix(hash, rootActorId);
        runtimeStableHashMix(hash, authority.strikeId);
        runtimeStableHashMix(hash, authority.planeToken);
        runtimeStableHashMix(hash, authority.planeObjectId);
        runtimeStableHashMix(hash, authority.callerObjectId);
        runtimeStableHashMix(hash, authority.targetObjectId);
        runtimeStableHashMix(hash, authority.launchTick);
        runtimeStableHashMix(hash, authority.terminalTick);
        runtimeStableHashMix(hash, authority.elite ? 1 : 0);
        runtimeStableHashMix(hash, authority.bombCell.x);
        runtimeStableHashMix(hash, authority.bombCell.y);
        runtimeStableHashMixString(hash, authority.owner);
        runtimeStableHashMixString(hash, authority.aircraftTypeId);
        runtimeStableHashMixString(hash, authority.weaponId);
        runtimeStableHashMixString(hash, authority.warheadId);
        runtimeStableHashMixString(hash, authority.projectileId);
        runtimeStableHashMix(hash, authority.roundsRemaining);
        runtimeStableHashMix(hash, authority.nextFireTick);
        runtimeStableHashMix(hash, static_cast<long long>(authority.rounds.size()));
        for (const auto& round : authority.rounds) {
            runtimeStableHashMix(hash, round.actorId);
            runtimeStableHashMix(hash, round.launchTick);
            runtimeStableHashMix(hash, round.terminalTick);
            runtimeStableHashMix(hash, round.sourceCell.x);
            runtimeStableHashMix(hash, round.sourceCell.y);
            runtimeStableHashMix(hash, round.damage);
        }
        runtimeStableHashMix(hash, authority.damage);
        runtimeStableHashMix(
            hash,
            static_cast<long long>(std::llround(
                authority.veteranDamageMultiplier * 1000000.0
            ))
        );
    }

    std::vector<std::pair<int, int>> gattlingTimers;
    gattlingTimers.reserve(state.gattlingWeaponTimers.size());
    for (const auto& [objectId, timer] : state.gattlingWeaponTimers) {
        const WorldObjectInstance* object = findObjectById(state, objectId);
        if (timer <= 0 || object == nullptr || !object->alive) {
            continue;
        }
        const RuntimeCachedCapabilityProfile& cached =
            runtimeCachedCapabilityProfileForObject(state, *object);
        if (!cached.gattling) {
            continue;
        }
        gattlingTimers.emplace_back(
            objectId,
            std::clamp(
                timer,
                0,
                runtimeGattlingTimerCap(cached, object->veterancy >= 2)
            )
        );
    }
    std::sort(gattlingTimers.begin(), gattlingTimers.end());
    runtimeStableHashMixString(hash, "GattlingWeaponTimers/1");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(gattlingTimers.size())
    );
    for (const auto& [objectId, timer] : gattlingTimers) {
        runtimeStableHashMix(hash, objectId);
        runtimeStableHashMix(hash, timer);
    }

    hashRuntimePublicBuildingLocations(hash, state);
    hashRuntimeWrecks(hash, state);
    hashRuntimeBuildingCollapses(hash, state);
    runtimeStableHashMixString(hash, "Crates/4");
    runtimeStableHashMix(hash, state.triggers.truckCrate ? 1 : 0);
    runtimeStableHashMix(hash, state.triggers.trainCrate ? 1 : 0);
    runtimeStableHashMix(
        hash,
        static_cast<long long>(state.skirmishCrates.size())
    );
    for (const RuntimeCrateState& crate : state.skirmishCrates) {
        runtimeStableHashMix(hash, crate.cell.x);
        runtimeStableHashMix(hash, crate.cell.y);
        runtimeStableHashMix(hash, crate.active ? 1 : 0);
        runtimeStableHashMix(hash, crate.respawnTick);
        runtimeStableHashMix(hash, crate.value);
        runtimeStableHashMix(hash, crate.water ? 1 : 0);
        runtimeStableHashMix(hash, crate.authored ? 1 : 0);
        runtimeStableHashMixString(hash, crate.powerupType);
        runtimeStableHashMixString(hash, crate.powerupAnimation);
        runtimeStableHashMixString(hash, crate.imageId);
        runtimeStableHashMix(
            hash,
            static_cast<long long>(std::llround(
                runtimeNormalizeCratePowerupData(crate.powerupData)
                    * 1000000.0
            ))
        );
    }
    runtimeStableHashMixString(hash, "Smudges/1");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(state.world.getSmudges().size())
    );
    for (const WorldSmudge& smudge : state.world.getSmudges()) {
        runtimeStableHashMixString(hash, smudge.mapId);
        runtimeStableHashMixString(hash, smudge.type);
        runtimeStableHashMix(hash, smudge.x);
        runtimeStableHashMix(hash, smudge.y);
        runtimeStableHashMix(hash, smudge.cell);
        runtimeStableHashMix(hash, smudge.level);
        runtimeStableHashMix(hash, smudge.data);
        runtimeStableHashMix(hash, smudge.authored ? 1 : 0);
    }
    std::vector<std::pair<int, int>> objectAmmo;
    objectAmmo.reserve(state.world.getObjects().size());
    for (const WorldObjectInstance& object : state.world.getObjects()) {
        objectAmmo.emplace_back(object.instanceId, object.currentAmmo);
    }
    std::sort(objectAmmo.begin(), objectAmmo.end());
    runtimeStableHashMixString(hash, "ObjectAmmo/1");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(objectAmmo.size())
    );
    for (const auto& [objectId, currentAmmo] : objectAmmo) {
        runtimeStableHashMix(hash, objectId);
        runtimeStableHashMix(hash, currentAmmo);
    }
    std::vector<std::tuple<int, int, int, int, int>> objectCombatStates;
    objectCombatStates.reserve(state.world.getObjects().size());
    for (const WorldObjectInstance& object : state.world.getObjects()) {
        objectCombatStates.emplace_back(
            object.instanceId,
            object.prone ? 1 : 0,
            object.proneTicksRemaining,
            object.weaponCooldownTicksRemaining,
            object.deployStateTicksRemaining
        );
    }
    std::sort(objectCombatStates.begin(), objectCombatStates.end());
    runtimeStableHashMixString(hash, "ObjectCombatStates/2");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(objectCombatStates.size())
    );
    for (const auto& [objectId, prone, proneTicks, weaponCooldown,
                     deployStateTicks] : objectCombatStates) {
        runtimeStableHashMix(hash, objectId);
        runtimeStableHashMix(hash, prone);
        runtimeStableHashMix(hash, proneTicks);
        runtimeStableHashMix(hash, weaponCooldown);
        runtimeStableHashMix(hash, deployStateTicks);
    }
    std::vector<int> capturedObjects;
    for (const auto& object : state.world.getObjects())
        if (object.hasBeenCaptured) capturedObjects.push_back(object.instanceId);
    if (!capturedObjects.empty()) {
        std::sort(capturedObjects.begin(), capturedObjects.end());
        runtimeStableHashMixString(hash, "CapturedCrew/1");
        for (int id : capturedObjects) runtimeStableHashMix(hash, id);
    }
    std::vector<int> suspendedHarvesters;
    for (const auto& object : state.world.getObjects()) {
        if (object.harvestAutoSearchSuspended) suspendedHarvesters.push_back(object.instanceId);
    }
    if (!suspendedHarvesters.empty()) {
        std::sort(suspendedHarvesters.begin(), suspendedHarvesters.end());
        runtimeStableHashMixString(hash, "HarvesterManualMove/1");
        for (int id : suspendedHarvesters) runtimeStableHashMix(hash, id);
    }
    std::vector<std::pair<int, int>> bioReactorAnimationStates;
    for (const auto& object : state.world.getObjects()) {
        if (object.bioReactorAnimationStartTick >= 0)
            bioReactorAnimationStates.emplace_back(object.instanceId, object.bioReactorAnimationStartTick);
    }
    if (!bioReactorAnimationStates.empty()) {
        std::sort(bioReactorAnimationStates.begin(), bioReactorAnimationStates.end());
        runtimeStableHashMixString(hash, "BioReactorAnimation/1");
        for (const auto& [id, tick] : bioReactorAnimationStates) {
            runtimeStableHashMix(hash, id);
            runtimeStableHashMix(hash, tick);
        }
    }
    std::vector<std::pair<int, int>> bioReactorPoweredAnimationStates;
    for (const auto& object : state.world.getObjects()) {
        if (object.bioReactorAnimationPoweredStartTick >= 0)
            bioReactorPoweredAnimationStates.emplace_back(object.instanceId, object.bioReactorAnimationPoweredStartTick);
    }
    if (!bioReactorPoweredAnimationStates.empty()) {
        std::sort(bioReactorPoweredAnimationStates.begin(), bioReactorPoweredAnimationStates.end());
        runtimeStableHashMixString(hash, "BioReactorPoweredAnimation/1");
        for (const auto& [id, tick] : bioReactorPoweredAnimationStates) {
            runtimeStableHashMix(hash, id);
            runtimeStableHashMix(hash, tick);
        }
    }
    std::vector<std::array<int, 5>> bunkerStates;
    for (const auto& object : state.world.getObjects()) {
        if (object.tankBunkerHostId >= 0 || object.tankBunkerOccupantId >= 0 || object.tankBunkerLowering) {
            bunkerStates.push_back({object.instanceId, object.tankBunkerHostId, object.tankBunkerOccupantId,
                object.tankBunkerAnimationStartTick, object.tankBunkerLowering ? 1 : 0});
        }
    }
    if (!bunkerStates.empty()) {
        std::sort(bunkerStates.begin(), bunkerStates.end());
        runtimeStableHashMixString(hash, "TankBunkers/1");
        for (const auto& row : bunkerStates) for (int value : row) runtimeStableHashMix(hash, value);
    }
    std::vector<std::pair<int, int>> objectSpecialCashDeadlines;
    objectSpecialCashDeadlines.reserve(state.world.getObjects().size());
    for (const WorldObjectInstance& object : state.world.getObjects()) {
        objectSpecialCashDeadlines.emplace_back(
            object.instanceId,
            object.specialCashNextTick
        );
    }
    std::sort(
        objectSpecialCashDeadlines.begin(),
        objectSpecialCashDeadlines.end()
    );
    runtimeStableHashMixString(hash, "ObjectSpecialCashDeadlines/1");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(objectSpecialCashDeadlines.size())
    );
    for (const auto& [objectId, nextTick] : objectSpecialCashDeadlines) {
        runtimeStableHashMix(hash, objectId);
        runtimeStableHashMix(hash, nextTick);
    }
    std::vector<std::pair<int, int>> objectCloneDeliveryLeases;
    objectCloneDeliveryLeases.reserve(state.world.getObjects().size());
    for (const WorldObjectInstance& object : state.world.getObjects()) {
        objectCloneDeliveryLeases.emplace_back(
            object.instanceId,
            object.specialCloneDeliveryObjectId
        );
    }
    std::sort(
        objectCloneDeliveryLeases.begin(),
        objectCloneDeliveryLeases.end()
    );
    runtimeStableHashMixString(hash, "ObjectCloneDeliveryLeases/1");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(objectCloneDeliveryLeases.size())
    );
    for (const auto& [objectId, cloneId] : objectCloneDeliveryLeases) {
        runtimeStableHashMix(hash, objectId);
        runtimeStableHashMix(hash, cloneId);
    }
    std::vector<std::tuple<int, long long, long long, long long, int>>
        objectCrateBonuses;
    objectCrateBonuses.reserve(state.world.getObjects().size());
    for (const WorldObjectInstance& object : state.world.getObjects()) {
        objectCrateBonuses.emplace_back(
            object.instanceId,
            static_cast<long long>(std::llround(
                object.crateArmorMultiplier * 1000000.0
            )),
            static_cast<long long>(std::llround(
                object.crateFirepowerMultiplier * 1000000.0
            )),
            static_cast<long long>(std::llround(
                object.crateSpeedMultiplier * 1000000.0
            )),
            object.crateCloakable ? 1 : 0
        );
    }
    std::sort(objectCrateBonuses.begin(), objectCrateBonuses.end());
    runtimeStableHashMixString(hash, "ObjectCrateBonuses/1");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(objectCrateBonuses.size())
    );
    for (const auto& [objectId, armor, firepower, speed, cloakable] :
            objectCrateBonuses) {
        runtimeStableHashMix(hash, objectId);
        runtimeStableHashMix(hash, armor);
        runtimeStableHashMix(hash, firepower);
        runtimeStableHashMix(hash, speed);
        runtimeStableHashMix(hash, cloakable);
    }
    std::vector<std::pair<int, int>> factoryClearanceSources;
    std::vector<std::tuple<int, int, int, std::int32_t>> movementTiming;
    movementTiming.reserve(state.behaviors.size());
    for (const auto& [objectId, behavior] : state.behaviors) {
        if (behavior.factoryExitClearanceHostId >= 0) {
            factoryClearanceSources.emplace_back(objectId, behavior.factoryExitClearanceHostId);
        }
        if (behavior.kind != RuntimeBehaviorKind::Move
            && behavior.kind != RuntimeBehaviorKind::Attack) {
            continue;
        }
        movementTiming.emplace_back(
            objectId,
            static_cast<int>(behavior.kind),
            std::max(0, behavior.moveCooldownTicks),
            behavior.moveIntervalRemainderQ16
        );
    }
    std::sort(movementTiming.begin(), movementTiming.end());
    runtimeStableHashMixString(hash, "MovementTiming/1");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(movementTiming.size())
    );
    for (const auto& [objectId, kind, cooldownTicks, remainderQ16] :
            movementTiming) {
        runtimeStableHashMix(hash, objectId);
        runtimeStableHashMix(hash, kind);
        runtimeStableHashMix(hash, cooldownTicks);
        runtimeStableHashMix(hash, remainderQ16);
    }
    if (!factoryClearanceSources.empty()) {
        std::sort(factoryClearanceSources.begin(), factoryClearanceSources.end());
        runtimeStableHashMixString(hash, "FactoryExitClearance/1");
        runtimeStableHashMix(hash, static_cast<long long>(factoryClearanceSources.size()));
        for (const auto& [objectId, hostId] : factoryClearanceSources) {
            runtimeStableHashMix(hash, objectId);
            runtimeStableHashMix(hash, hostId);
        }
    }
    runtimeStableHashMixString(hash, "ProductionLanes/2");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(runtimeProductionLanesStateHash(
            state.economy.localProductionLanes
        ))
    );
    const std::optional<RuntimeSelectedPlacement> canonicalPlacement =
        runtimeSelectedPlacement(state);
    runtimeStableHashMix(
        hash,
        canonicalPlacement.has_value()
            ? static_cast<long long>(
                static_cast<std::uint8_t>(
                    canonicalPlacement->lane
                ) + 1
              )
            : 0
    );
    runtimeStableHashMix(
        hash,
        canonicalPlacement.has_value()
            ? static_cast<long long>(
                canonicalPlacement->order.serial
              )
            : 0
    );
    runtimeStableHashMixString(hash, "GarrisonRuntime/1");
    runtimeStableHashMix(
        hash,
        state.garrisonsInitialized
            ? static_cast<long long>(
                state.garrisons.stateHash(state.world.getObjects())
              )
            : 0
    );
    std::vector<std::pair<int, int>> occupyIntents(
        state.pendingOccupyTargets.begin(),
        state.pendingOccupyTargets.end()
    );
    std::sort(occupyIntents.begin(), occupyIntents.end());
    runtimeStableHashMixString(hash, "OccupyIntents/1");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(occupyIntents.size())
    );
    for (const auto& [occupierId, targetId] : occupyIntents) {
        runtimeStableHashMix(hash, occupierId);
        runtimeStableHashMix(hash, targetId);
    }
    std::vector<std::pair<int, RuntimeTimedBombIntent>> timedBombIntents(
        state.pendingTimedBombIntents.begin(),
        state.pendingTimedBombIntents.end()
    );
    std::sort(
        timedBombIntents.begin(),
        timedBombIntents.end(),
        [](const auto& left, const auto& right) {
            return left.first < right.first;
        }
    );
    runtimeStableHashMixString(hash, "TimedBombIntents/1");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(timedBombIntents.size())
    );
    for (const auto& [sourceId, intent] : timedBombIntents) {
        runtimeStableHashMix(hash, sourceId);
        runtimeStableHashMix(hash, intent.targetObjectId);
        runtimeStableHashMix(
            hash,
            static_cast<long long>(intent.kind)
        );
    }
    runtimeStableHashMixString(hash, "SubcellRuntime/1");
    runtimeStableHashMix(
        hash,
        state.subcellsInitialized
            ? static_cast<long long>(state.subcells.stateHash(
                state.world.getObjects(),
                state.world.getTerrainObjects(),
                runtimeGroundPoseContext(state)
              ))
            : 0
    );
    runtimeStableHashMixString(hash, "GateRuntime/1");
    runtimeStableHashMix(
        hash,
        state.gatesInitialized
            ? static_cast<long long>(state.gates.stateHash())
            : 0
    );
    runtimeStableHashMixString(hash, "RepairDepotRuntime/4");
    const RuntimeRepairDepotSystemState canonicalRepairDepots =
        state.repairDepotsInitialized
            ? state.repairDepots
            : RuntimeRepairDepotSystemState(
                std::max(1, state.config.fixedTickHz)
              );
    runtimeStableHashMix(
        hash,
        static_cast<long long>(canonicalRepairDepots.stateHash())
    );
    runtimeStableHashMixString(hash, "PlayerCommands/1");
    runtimeStableHashMix(hash, static_cast<long long>(state.playerCommands.stateHash()));
    runtimeStableHashMixString(hash, "FunctionalDetailRules/1");
    runtimeStableHashMix(hash, static_cast<long long>(state.rules.getDetailRulesHash()));
    runtimeStableHashMixString(hash, "ClonePendingDeliveries/1");
    runtimeStableHashMix(hash, static_cast<long long>(runtimeClonePendingDeliveriesHash(state)));
    runtimeStableHashMixString(hash, "FactoryDeliveryRuntime/2");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(state.factoryDeliveries.stateHash())
    );
    runtimeStableHashMixString(hash, "GrindingRuntime/1");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(state.grinding.stateHash())
    );
    runtimeStableHashMixString(hash, "AircraftServiceRuntime/1");
    RuntimeAircraftServiceSystemState canonicalAircraftServices =
        state.aircraftServicesInitialized
            ? state.aircraftServices
            : RuntimeAircraftServiceSystemState(
                std::max(1, state.config.fixedTickHz)
              );
    canonicalAircraftServices.reconcile(
        makeRuntimeAircraftServiceContext(state)
    );
    runtimeStableHashMix(
        hash,
        static_cast<long long>(canonicalAircraftServices.stateHash())
    );
    runtimeStableHashMixString(hash, "SpecialMechanisms/2");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(state.specialMechanisms.stateHash())
    );
    runtimeStableHashMixString(hash, "SpyRuntime/2");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(state.spies.stateHash())
    );
    std::vector<std::pair<int, int>> parasiteStuns;
    parasiteStuns.reserve(
        state.parasiteStunUntilTickByObject.size()
    );
    for (const auto& [objectId, untilTick] :
            state.parasiteStunUntilTickByObject) {
        const WorldObjectInstance* object = findObjectById(state, objectId);
        if (object != nullptr && object->alive && object->health > 0
            && object->mission == "ParasiteStunned"
            && untilTick > state.tick) {
            parasiteStuns.emplace_back(objectId, untilTick);
        }
    }
    std::sort(parasiteStuns.begin(), parasiteStuns.end());
    runtimeStableHashMixString(hash, "ParasiteStuns/1");
    runtimeStableHashMix(
        hash,
        static_cast<long long>(parasiteStuns.size())
    );
    for (const auto& [objectId, untilTick] : parasiteStuns) {
        runtimeStableHashMix(hash, objectId);
        runtimeStableHashMix(hash, untilTick);
    }
    return hash;
}



unsigned long long runtimeProjectedObjectsSignatureUnmemoized(
    const RuntimeWindowState& state
) {
    const bool historyReference = runtimeHistoryQueryReference();
    unsigned long long hash = 1469598103934665603ull;
    runtimeHashMix(hash, state.tick);
    for (const auto& impact : state.impactEffects) {
        runtimeHashMix(hash, runtimeQuantizedRenderCoordinate(impact.hasWorldPosition ? impact.worldX : impact.cell.x));
        runtimeHashMix(hash, runtimeQuantizedRenderCoordinate(impact.hasWorldPosition ? impact.worldY : impact.cell.y));
        runtimeHashMix(hash, runtimeQuantizedRenderCoordinate(impact.hasWorldPosition ? impact.worldLevel : impact.level));
        runtimeHashMix(hash, impact.remainingTicks);
        runtimeHashMix(hash, impact.totalTicks);
        runtimeHashMix(hash, impact.damage);
        for (unsigned char value : impact.warheadId) runtimeHashMix(hash, value);
    }
    runtimeHashMix(hash, static_cast<long long>(state.impactEffects.size()));
    for (const auto& [id, until] : state.playerCommunication.cheerUntilTick) {
        runtimeHashMix(hash, id); runtimeHashMix(hash, until);
    }
    for (unsigned char character : state.economy.owner) {
        runtimeHashMix(hash, character);
    }
    runtimeHashMix(hash, -3);
    if (state.visionEnabled) {
        runtimeHashMix(
            hash,
            static_cast<long long>(
                state.vision.revisionFor(state.economy.owner)
            )
        );
    }
    if (state.specialMechanismsInitialized) {
        runtimeHashMix(
            hash,
            static_cast<long long>(state.specialMechanisms.stateHash())
        );
    }
    // Loading an older save materializes an empty Spy authority even when
    // the pre-save state had not lazily initialized it.  Hash the canonical
    // empty state as well so that implementation detail cannot change hit
    // projection/cache signatures across a round trip.
    runtimeHashMix(
        hash,
        static_cast<long long>(state.spies.stateHash())
    );
    if (state.gatesInitialized) {
        runtimeHashMix(
            hash,
            static_cast<long long>(state.gates.stateHash())
        );
        for (const RuntimeGateInstanceState& gate : state.gates.gates()) {
            runtimeHashMix(hash, gate.gateId);
            runtimeHashMix(hash, static_cast<int>(gate.phase));
            if (gate.phase == RuntimeGatePhase::Opening
                || gate.phase == RuntimeGatePhase::Closing) {
                const long long duration =
                    static_cast<long long>(gate.phaseCompletesTick)
                    - static_cast<long long>(gate.phaseStartedTick);
                const long long elapsed =
                    static_cast<long long>(state.tick)
                    - static_cast<long long>(gate.phaseStartedTick);
                const double progress = duration <= 0
                    ? 0.0
                    : std::clamp(
                        static_cast<double>(elapsed)
                            / static_cast<double>(duration),
                        0.0,
                        1.0
                    );
                runtimeHashMix(
                    hash,
                    static_cast<long long>(std::llround(progress * 1000000.0))
                );
            }
        }
    }
    runtimeHashMix(
        hash,
        static_cast<long long>(runtimeTerrainObjectsStateSignature(state))
    );
    for (const WorldObjectInstance& object : state.world.getObjects()) {
        runtimeHashMix(hash, object.instanceId);
        runtimeHashMix(hash, static_cast<int>(object.kind));
        // Dead mobile objects produce no projection. Keep their ordered identity
        // and liveness markers so revival, ID/kind replacement and reordering
        // still invalidate cached pointers. Dead structures can render rubble or
        // selling layers and affect live projections, so retain their full hash.
        if (!historyReference && !object.alive && object.kind != WorldObjectKind::Structure) {
            runtimeHashMix(hash, 0);
            continue;
        }
        runtimeHashMix(hash, object.facing);
        runtimeHashMix(hash, object.turretFacing);
        for (unsigned char value : object.owner) runtimeHashMix(hash, value);
        runtimeHashMix(hash, object.deployed);
        runtimeHashMix(hash, object.health);
        runtimeHashMix(hash, object.activeGunnerTurretIndex);
        runtimeHashMix(hash, object.dockedToObjectId);
        runtimeHashMix(hash, runtimeQuantizedRenderCoordinate(object.movementAnimationDistance));
        runtimeHashMix(hash, object.buildAnimTicksRemaining);
        runtimeHashMix(hash, object.workAnimationActive);
        runtimeHashMix(hash, object.poweredOperational);
        runtimeHashMix(hash, object.buildAnimTicksTotal);
        runtimeHashMix(hash, object.powerAnimationPausedAtTick);
        runtimeHashMix(hash, object.powerAnimationPausedTicks);
        runtimeHashMix(hash, object.structureRecoilStartTick);
        runtimeHashMix(hash, object.chargeTurretStartTick);
        runtimeHashMix(hash, object.factoryExitHostId);
        runtimeHashMix(hash, runtimeQuantizedRenderCoordinate(object.aircraftBuildingClearanceLevel));
        runtimeHashMix(hash, object.factoryExitAnimationStartTick);
        runtimeHashMix(hash, object.factoryExitAnimationEndTick);
        runtimeHashMix(hash, object.factoryExitAirborne ? 1 : 0);
        runtimeHashMix(hash, object.tankBunkerHostId);
        runtimeHashMix(hash, object.tankBunkerOccupantId);
        runtimeHashMix(hash, object.tankBunkerAnimationStartTick);
        runtimeHashMix(hash, object.tankBunkerLowering ? 1 : 0);
        if (object.bioReactorAnimationStartTick >= 0) {
            for (unsigned char value : std::string("BioReactorAnimation/1")) runtimeHashMix(hash, value);
            runtimeHashMix(hash, object.bioReactorAnimationStartTick);
        }
        if (object.bioReactorAnimationPoweredStartTick >= 0) {
            for (unsigned char value : std::string("BioReactorPoweredAnimation/1")) runtimeHashMix(hash, value);
            runtimeHashMix(hash, object.bioReactorAnimationPoweredStartTick);
        }
        if (object.bodyFacingClock.active() || object.turretFacingClock.active()) {
            for (const auto& encoded : {runtimeSerializeFacingClock(object.bodyFacingClock),
                    runtimeSerializeFacingClock(object.turretFacingClock)})
                for (unsigned char value : encoded) runtimeHashMix(hash, value);
        }
        runtimeHashMix(hash, object.submerged ? 1 : 0);
        runtimeHashMix(hash, object.cloaked ? 1 : 0);
        runtimeHashMix(hash, object.cloakCooldownTicks);
        runtimeHashMix(hash, object.submergeCooldownTicks);
        runtimeHashMix(hash, object.airborne ? 1 : 0);
        runtimeHashMix(hash, object.currentAmmo);
        runtimeHashMix(hash, object.deployStateTicksRemaining);
        runtimeHashMix(hash, object.specialCashNextTick);
        runtimeHashMix(hash, object.specialCloneDeliveryObjectId);
        runtimeHashMix(hash, object.prone ? 1 : 0);
        runtimeHashMix(hash, object.proneTicksRemaining);
        runtimeHashMix(hash, object.weaponCooldownTicksRemaining);
        for (unsigned char character : object.type) {
            runtimeHashMix(hash, character);
        }
        runtimeHashMix(hash, -1);
        for (unsigned char character : object.mission) {
            runtimeHashMix(hash, character);
        }
        runtimeHashMix(hash, -2);
        runtimeHashMix(hash, object.alive ? 1 : 0);
        if (!object.alive) {
            continue;
        }
        runtimeHashMix(hash, object.x);
        runtimeHashMix(hash, object.y);
        runtimeHashMix(hash, object.level);
        runtimeHashMix(hash, object.onBridge ? 1 : 0);
        runtimeHashMix(hash, object.subCell);
        runtimeHashMix(hash, object.hasRenderPosition ? 1 : 0);
        if (object.hasRenderPosition) {
            runtimeHashMix(hash, runtimeQuantizedRenderCoordinate(object.renderX));
            runtimeHashMix(hash, runtimeQuantizedRenderCoordinate(object.renderY));
            runtimeHashMix(hash, runtimeQuantizedRenderCoordinate(object.renderLevel));
        }
        runtimeHashMix(hash, object.renderMoveActive ? 1 : 0);
        if (object.renderMoveActive) {
            runtimeHashMix(
                hash,
                runtimeQuantizedRenderCoordinate(object.renderLevel)
            );
            runtimeHashMix(hash, object.renderOnBridge ? 1 : 0);
        }
    }
    return hash;
}

#include "ui/selection/RuntimePaintProjectionSignatureMemo.inl"

bool runtimePaintBuildingDepthCaptureAllowed(const GameWorld& world) {
    // A mobile-only map has no scene-Z capture consumer. Avoid computing the
    // complete projection signature just to request an unused map result.
    return runtimeHistoryQueryReference() || !runtimeSkipEmptyBuildingDepthScene(world);
}

const std::vector<RuntimeProjectedObject>& runtimeProjectedObjectsForViewport(
    RuntimeWindowState& state,
    const RECT& viewport
) {
    RuntimePerfTraceScope trace("runtimeProjectedObjectsForViewport", state.tick);
    ensureRuntimeCameraForViewport(state, viewport);

    const unsigned long long signature =
        runtimeProjectedObjectsSignature(state);
    if (state.projectedObjectsCacheValid
        && runtimeRectEquals(runtimeRenderPlacementNativeRect(state.projectedObjectsCacheViewport), viewport)
        && state.projectedObjectsCacheCameraX == state.camera.worldOffsetX
        && state.projectedObjectsCacheCameraY == state.camera.worldOffsetY
        && state.projectedObjectsCacheTileWidth == state.camera.tileWidth
        && state.projectedObjectsCacheTileHeight == state.camera.tileHeight
        && state.projectedObjectsCacheSignature == signature) {
        return state.projectedObjectsCache;
    }

    RuntimeRendererEnvironmentScope rendererEnvironment;
    std::vector<RuntimeProjectedObject> projectedObjects;
    projectedObjects.reserve(std::min<std::size_t>(state.world.getObjects().size(), 256));
    RuntimeMapRenderContext spriteContext;
    spriteContext.stableRenderConfiguration = true;
    spriteContext.theater =
        state.theaterLoaded ? &state.theater : nullptr;
    spriteContext.art = state.artLoaded ? &state.art : nullptr;
    spriteContext.rules = state.rulesLoaded ? &state.rules : nullptr;
    spriteContext.mapFacts =
        state.mapFactsLoaded ? &state.mapFacts : nullptr;
    spriteContext.ownerRemapColors =
        state.ownerRemapColors.empty() ? nullptr : &state.ownerRemapColors;
    spriteContext.neutralRemapOwners =
        state.neutralRemapOwners.empty() ? nullptr : &state.neutralRemapOwners;
    const RuntimeMapRenderContext* paintGeometryContext = runtimeGeometryBatchRenderContext();
    if (paintGeometryContext == nullptr) refreshRuntimeGateRenderSnapshots(state);
    spriteContext.gateSnapshots = &state.gateRenderSnapshots;
    if (paintGeometryContext == nullptr) refreshRuntimeSpecialMechanismRenderSnapshots(state);
    spriteContext.specialMechanismSnapshots = &state.specialMechanismRenderSnapshots;
    if (runtimeLocalVisionRestricted(state)) {
        spriteContext.vision = &state.vision;
        spriteContext.visionObserverOwner = state.economy.owner;
    }
    spriteContext.tileRootPath =
        runtimeTileRootPath(state.config, state.report.map);
    spriteContext.palettePath =
        runtimePalettePath(state.config, state.report.map);
    spriteContext.assetRootPath = runtimeAssetRootPath(state.config);
    spriteContext.structureRootPath =
        runtimeStructureRootPath(state.config, state.report.map);
    spriteContext.structurePalettePath =
        runtimeStructurePalettePath(state.config, state.report.map);
    spriteContext.animationTick = state.tick;
    spriteContext.fixedTickHz = state.config.fixedTickHz;
    spriteContext.impactActors = paintGeometryContext != nullptr
        ? paintGeometryContext->impactActors : runtimeImpactRenderActorsForRender(state);
    spriteContext.selectedObjectIds = &state.selectedObjectIds;
    spriteContext.playerCheerUntilTick = &state.playerCommunication.cheerUntilTick;
    if (paintGeometryContext != nullptr) spriteContext = *paintGeometryContext;
    RuntimeGeometryQueryScope geometryScope(state.world, runtimeRenderPlacementPixelRect(viewport), spriteContext,
        state.camera, state.renderCache, true);
    const bool traceProjection = std::getenv("CONCORD_RUNTIME_PERF_TRACE") != nullptr;
    const bool historyReference = runtimeHistoryQueryReference();
    std::array<double, 5> projectionMs{};
    for (const WorldObjectInstance& object : state.world.getObjects()) {
        if (!historyReference && !object.alive) continue;
        auto projectionStart = traceProjection ? std::chrono::steady_clock::now()
            : std::chrono::steady_clock::time_point{};
        const auto traceProjectionStage = [&](std::size_t stage) {
            if (!traceProjection) return;
            const auto now = std::chrono::steady_clock::now();
            projectionMs[stage] += std::chrono::duration<double, std::milli>(now - projectionStart).count();
            projectionStart = now;
        };
        if (!object.alive
            || !runtimeObjectVisibleToOwner(
                state,
                state.economy.owner,
                object
            )
            || runtimeSpecialObjectHiddenForInteraction(state, object)) {
            continue;
        }
        const RuntimeSpyObserverProjection spyProjection =
            runtimeSpyObserverProjectionForOwner(
                state,
                state.economy.owner,
                object,
                true
            );
        std::optional<WorldObjectInstance> observerObject;
        if (spyProjection.active) {
            observerObject.emplace(object);
            observerObject->type = spyProjection.type;
            observerObject->owner = spyProjection.owner;
            observerObject->kind = spyProjection.identity
                    == RuntimeSpyDisguiseIdentity::Vehicle
                ? WorldObjectKind::Unit
                : WorldObjectKind::Infantry;
            observerObject->authoredAircraft = false;
            observerObject->airborne = false;
            observerObject->submerged = false;
            observerObject->cloaked = false;
        }
        const WorldObjectInstance& observerView = spyProjection.active
            ? *observerObject
            : object;
        traceProjectionStage(0);
        const double drawLevel = runtimeDrawLevelForObject(observerView);
        const POINT center =
            runtimeOverlayCenterForObject(state, observerView, viewport);
        const bool usesStructureFootprint =
            runtimeObjectUsesStructureFootprint(state, observerView);
        const RuntimeNativeRenderPlacementWin32 renderPlacement = runtimeRenderPlacementNative(runtimeObjectWorldRenderPlacementWin32(
            observerView, state.world, viewport, spriteContext, state.camera, state.renderCache));
        const POINT renderCenter = renderPlacement.center;
        if (renderPlacement.airborneForeground && rectIsEmpty(renderPlacement.bodyViewport)) continue;
        const RuntimeProjectedPoint projected{
            usesStructureFootprint ? renderPlacement.sortPoint.x : center.x - viewport.left + state.camera.worldOffsetX,
            usesStructureFootprint ? renderPlacement.sortPoint.y : center.y - viewport.top + state.camera.worldOffsetY
        };
        traceProjectionStage(1);
        RuntimeProjectedObject screenObject;
        screenObject.object = &object;
        screenObject.observerType = observerView.type;
        screenObject.observerOwner = observerView.owner;
        screenObject.observerKind = observerView.kind;
        screenObject.spyDisguiseProjected = spyProjection.active;
        screenObject.center = runtimeRenderPlacementPixelPoint(center);
        screenObject.renderCenter = runtimeRenderPlacementPixelPoint(renderCenter);
        screenObject.airborneForeground = renderPlacement.airborneForeground;
        screenObject.hasBodyHitClip = observerView.factoryExitHostId >= 0 && renderPlacement.airborneForeground;
        screenObject.bodyHitClip = runtimeRenderPlacementPixelRect(renderPlacement.bodyViewport);
        screenObject.factoryForegroundHostId = renderPlacement.factoryForegroundHostId;
        screenObject.bounds = runtimeRenderPlacementPixelRect(hitBoundsForObject(
            state,
            observerView,
            viewport,
            usesStructureFootprint ? center : renderCenter
        ));
        screenObject.spriteBounds = screenObject.bounds;
        if (!usesStructureFootprint) {
            // Submerged bodies are deliberately sunk below the water-level
            // interaction anchor. Other mobile objects, including aircraft,
            // use the renderer's exact body anchor so the frame follows the
            // same lift policy as the sprite.
            const POINT selectionAnchor = observerView.submerged
                ? center
                : renderCenter;
            screenObject.selectionBaseBounds = runtimeRenderPlacementPixelRect(runtimeUnitSelectionBoundsForAnchor(selectionAnchor));
            const UnitType* selectionType = findRuntimeUnitType(state.rules, observerView);
            screenObject.healthPixelOffsetY = selectionType != nullptr
                ? selectionType->pixelSelectionBracketDelta : 0;
            screenObject.selectionBounds = screenObject.selectionBaseBounds;
            // Every visible part of the selection frame must also select the
            // unit. Infantry's small foot hitbox otherwise treats its bottom
            // corners as ground clicks, issuing an unintended move on reselect.
            runtimeUnionProjectedRect(screenObject.bounds, screenObject.selectionBounds);
        }
        const auto* missileType = findRuntimeUnitType(state.rules, observerView);
        RECT missileBounds{};
        if (missileType != nullptr && missileType->missileSpawn
            && resolveRuntimeSpawnedMissileSpriteBoundsWin32(observerView, renderCenter,
                spriteContext, state.camera, state.renderCache, missileBounds)) {
            screenObject.spriteBounds = runtimeRenderPlacementPixelRect(missileBounds);
            screenObject.hasMobileSpriteBounds = true;
            screenObject.selectionBaseBounds = screenObject.selectionBounds = screenObject.spriteBounds;
            RECT expandedBounds = missileBounds;
            InflateRect(&expandedBounds, 3, 3);
            screenObject.bounds = runtimeRenderPlacementPixelRect(expandedBounds);
        }
        screenObject.drawLevel = drawLevel;
        screenObject.projectedX = projected.x;
        screenObject.projectedY = projected.y;
        traceProjectionStage(2);
        if (!usesStructureFootprint && !(missileType != nullptr && missileType->missileSpawn)) {
            RECT resolvedSpriteBounds{};
            if (resolveRuntimeMobileObjectSpriteBoundsWin32(observerView, renderCenter,
                    spriteContext, state.camera, state.renderCache, resolvedSpriteBounds)) {
                if (observerView.factoryExitHostId >= 0 && renderPlacement.airborneForeground) {
                    RECT visibleBounds{};
                    if (!IntersectRect(&visibleBounds, &resolvedSpriteBounds, &renderPlacement.bodyViewport)) continue;
                    resolvedSpriteBounds = visibleBounds;
                }
                screenObject.spriteBounds = runtimeRenderPlacementPixelRect(resolvedSpriteBounds);
                screenObject.hasMobileSpriteBounds = true;
                screenObject.selectionBaseBounds = runtimeRenderPlacementPixelRect(runtimeUnitSelectionBoundsForSprite(resolvedSpriteBounds));
                screenObject.selectionBounds = screenObject.selectionBaseBounds;
                // This is the visible body envelope, including turret/barrel and
                // the current animation pose. No fixed-size phantom box remains.
                if (screenObject.hasBodyHitClip) {
                    RECT clipped{};
                    const RECT selection = runtimeRenderPlacementNativeRect(screenObject.selectionBounds);
                    const RECT body = runtimeRenderPlacementNativeRect(screenObject.bodyHitClip);
                    if (!IntersectRect(&clipped, &selection, &body)) continue;
                    screenObject.selectionBounds = runtimeRenderPlacementPixelRect(clipped);
                }
                screenObject.bounds = screenObject.selectionBounds;
            }
        }
        traceProjectionStage(3);
        if (usesStructureFootprint) {
            const std::vector<RuntimeCellPoint> cells =
                runtimeStructureFootprintCellsForObject(
                    state,
                    observerView
                );
            screenObject.usesFootprintHit = true;
            screenObject.footprintHalfWidth =
                std::max(1, state.camera.tileWidth / 2);
            screenObject.footprintHalfHeight =
                std::max(1, state.camera.tileHeight / 2);
            screenObject.footprintHitCenters.reserve(cells.size());
            for (const RuntimeCellPoint& cell : cells) {
                const RuntimeProjectedPoint footprintProjected =
                    runtimeProjectCellXY(
                        cell.x,
                        cell.y,
                        terrainLevelAtRuntimeCell(state, cell.x, cell.y),
                        state.camera
                    );
                screenObject.footprintHitCenters.push_back(
                    concord::runtime::session_detail::runtimeScreenPixelPoint(
                        footprintProjected,
                        runtimeRenderPlacementPixelRect(viewport),
                        state.camera
                    )
                );
            }
            const RECT footprintBounds =
                runtimeFootprintDiamondBounds(
                    screenObject.footprintHitCenters,
                    screenObject.footprintHalfWidth,
                    screenObject.footprintHalfHeight
                );
            screenObject.footprintBounds = runtimeRenderPlacementPixelRect(footprintBounds);
            if (!rectIsEmpty(footprintBounds)) screenObject.bounds = screenObject.footprintBounds;
            RuntimeStructureSpriteGeometry geometry;
            if (resolveRuntimeStructureSpriteGeometryWin32(observerView, renderCenter,
                    spriteContext, state.camera, state.renderCache, geometry)) {
                screenObject.hasStructureSpriteGeometry = true;
                screenObject.spriteBounds = {geometry.bounds.left, geometry.bounds.top,
                    geometry.bounds.right, geometry.bounds.bottom};
                screenObject.structureSpriteHitSpans = std::move(geometry.hitSpans);
                screenObject.structureForegroundHitSpans = std::move(geometry.foregroundHitSpans);
                runtimeUnionProjectedRect(screenObject.bounds, screenObject.spriteBounds);
            }
        }
        traceProjectionStage(4);
        projectedObjects.push_back(std::move(screenObject));
    }
    // Replay the current building and participating naval layers, including pixel depth, even
    // when this query happens before paint. Keep the original geometry for
    // bounds and footprint selection; visibility only filters body hits.
    std::unordered_map<int, std::vector<RuntimeSpriteHitSpan>> visibleBuildings;
    if (resolveRuntimeBuildingVisibleHitSpansWin32(state.world, viewport, spriteContext,
            state.camera, state.renderCache, visibleBuildings)) {
        for (auto& projected : projectedObjects) {
            if (!projected.object) continue;
            const auto visible = visibleBuildings.find(projected.object->instanceId);
            if (visible == visibleBuildings.end()) continue;
            projected.hasBuildingDepthVisibility = true;
            projected.visibleBuildingHitSpans = std::move(visible->second);
        }
    }
    if (traceProjection) {
        std::cerr << "Projection perf: tick=" << state.tick
            << " objects=" << projectedObjects.size()
            << " observerMs=" << projectionMs[0] << " placementMs=" << projectionMs[1]
            << " boundsMs=" << projectionMs[2] << " mobileMs=" << projectionMs[3]
            << " structureMs=" << projectionMs[4] << '\n';
    }
    // Occupants paint immediately after the bunker's rear layer; its front
    // wall is resolved separately at hit time, matching the existing renderer.
    for (auto& projected : projectedObjects) {
        if (!projected.object || projected.object->tankBunkerHostId < 0) continue;
        const auto host = std::find_if(projectedObjects.begin(), projectedObjects.end(), [&](const auto& candidate) {
            return candidate.object && candidate.object->instanceId == projected.object->tankBunkerHostId;
        });
        if (host == projectedObjects.end()) continue;
        projected.projectedX = host->projectedX; projected.projectedY = host->projectedY;
        projected.drawLevel = host->drawLevel;
        projected.hasHostedSortOverride = true;
        projected.hostedSortCellSum = runtimeObjectRenderX(*host->object) + runtimeObjectRenderY(*host->object);
    }

    std::sort(
        projectedObjects.begin(),
        projectedObjects.end(),
        [](const RuntimeProjectedObject& left, const RuntimeProjectedObject& right) {
            // The renderer draws flying bodies in a final foreground pass.
            if (left.airborneForeground != right.airborneForeground) return !left.airborneForeground;
            if (left.airborneForeground) {
                // Match buildRuntimeAirborneBodyDrawRecords: flight height
                // changes projected Y, but not the shared air-layer depth.
                // Keep the renderer's unrounded subcell-aware lepton key,
                // followed by the same level/X/cell/kind/id tie breakers.
                const auto depth = [](const WorldObjectInstance& object) {
                    const auto offset = worldObjectSubCellOffset(object);
                    return ((runtimeObjectRenderX(object) + offset.x)
                        + (runtimeObjectRenderY(object) + offset.y)) * 256.0;
                };
                const double leftDepth = depth(*left.object);
                const double rightDepth = depth(*right.object);
                if (leftDepth != rightDepth) return leftDepth < rightDepth;
            } else if (left.projectedY != right.projectedY) {
                return left.projectedY < right.projectedY;
            }
            if (left.drawLevel != right.drawLevel) {
                return left.drawLevel < right.drawLevel;
            }
            if (left.projectedX != right.projectedX) {
                return left.projectedX < right.projectedX;
            }
            const double leftCellSum = left.hasHostedSortOverride ? left.hostedSortCellSum
                : runtimeObjectRenderX(*left.object) + runtimeObjectRenderY(*left.object);
            const double rightCellSum = right.hasHostedSortOverride ? right.hostedSortCellSum
                : runtimeObjectRenderX(*right.object) + runtimeObjectRenderY(*right.object);
            if (leftCellSum != rightCellSum) {
                return leftCellSum < rightCellSum;
            }
            const int leftBias = runtimeObjectKindSortBias(left.observerKind);
            const int rightBias = runtimeObjectKindSortBias(right.observerKind);
            if (leftBias != rightBias) {
                return leftBias < rightBias;
            }
            return left.object->instanceId < right.object->instanceId;
        }
    );

    state.projectedObjectsCacheViewport = runtimeRenderPlacementPixelRect(viewport);
    state.projectedObjectsCacheCameraX = state.camera.worldOffsetX;
    state.projectedObjectsCacheCameraY = state.camera.worldOffsetY;
    state.projectedObjectsCacheTileWidth = state.camera.tileWidth;
    state.projectedObjectsCacheTileHeight = state.camera.tileHeight;
    state.projectedObjectsCacheSignature = signature;
    state.projectedObjectsCache = std::move(projectedObjects);
    state.projectedObjectsCacheValid = true;
    return state.projectedObjectsCache;
}

std::vector<RuntimeProjectedObject> buildProjectedObjects(
    RuntimeWindowState& state,
    const RECT& viewport
) {
    return runtimeProjectedObjectsForViewport(state, viewport);
}



















const RuntimeProjectedObject* findProjectedObjectAtPoint(
    const std::vector<RuntimeProjectedObject>& projectedObjects,
    POINT point
) {
    const RuntimeProjectedObject* footprintFallback = nullptr;
    const auto buildingPixelVisible = [&](const RuntimeProjectedObject& projected) {
        return !projected.hasBuildingDepthVisibility
            || runtimeSpriteHitSpansContainWin32(projected.visibleBuildingHitSpans, point);
    };
    for (auto it = projectedObjects.rbegin(); it != projectedObjects.rend(); ++it) {
        if (it->hasBodyHitClip) {
            const RECT bodyHitClip = runtimeRenderPlacementNativeRect(it->bodyHitClip);
            if (!PtInRect(&bodyHitClip, point)) continue;
        }
        if (it->usesFootprintHit) {
            if (runtimeSpriteHitSpansContainWin32(it->structureSpriteHitSpans, point)) {
                if (buildingPixelVisible(*it)) return &*it;
                // An authored building pixel hidden by another scene object
                // cannot become selectable again through its foundation.
                // Blank foundation pixels retain the existing fallback below.
                continue;
            }

            for (const RuntimeInputPixelPoint& center : it->footprintHitCenters) {
                if (pointInRuntimeIsoDiamond(
                        point,
                        runtimeRenderPlacementNativePoint(center),
                        it->footprintHalfWidth,
                        it->footprintHalfHeight
                    )) {
                    if (!footprintFallback) footprintFallback = &*it;
                }
            }
            continue;
        }
        if (pointInRectInclusive(runtimeRenderPlacementNativeRect(it->bounds), point)) {
            if (!buildingPixelVisible(*it)) continue;
            if (it->factoryForegroundHostId >= 0) {
                for (const auto& host : projectedObjects)
                    if (host.object && host.object->instanceId == it->factoryForegroundHostId
                        && runtimeSpriteHitSpansContainWin32(host.structureForegroundHitSpans, point)
                        && buildingPixelVisible(host)) return &host;
            }
            if (it->object && it->object->tankBunkerHostId >= 0) {
                for (const auto& host : projectedObjects)
                    if (host.object && host.object->instanceId == it->object->tankBunkerHostId
                        && runtimeSpriteHitSpansContainWin32(host.structureForegroundHitSpans, point)
                        && buildingPixelVisible(host)) return &host;
            }
            return &*it;
        }
    }

    return footprintFallback;
}



std::string describeObjectForHud(const WorldObjectInstance& object) {
    std::ostringstream stream;
    stream
        << toString(object.kind)
        << " "
        << object.type
        << " #"
        << object.instanceId
        << " "
        << object.owner
        << " hp "
        << object.health
        << " @ "
        << object.x
        << ","
        << object.y;
    if (!object.mission.empty()) {
        stream << " mission " << object.mission;
    }
    return stream.str();
}

std::string buildSelectionLine(const RuntimeWindowState& state) {
    std::ostringstream stream;
    stream << "selection " << state.selectedObjectIds.size();
    if (!state.selectedObjectIds.empty()) {
        const WorldObjectInstance* first =
            findObjectById(state, state.selectedObjectIds.front());
        if (first != nullptr) {
            stream << " | " << describeObjectForHud(*first);
            if (runtimeVeterancyObjectIsTrainable(state, *first)) {
                const int cap = std::clamp(
                    state.rules.getVeterancyRules().veteranCap,
                    0,
                    2
                );
                const char* rank = first->veterancy >= 2
                    ? "Elite"
                    : (first->veterancy >= 1 ? "Veteran" : "Rookie");
                stream << " | " << rank;
                if (first->veterancy < cap) {
                    stream << " XP "
                           << std::max(0, first->veterancyExperience)
                           << "/"
                           << runtimeVeterancyPromotionThreshold(
                                state,
                                *first
                              );
                }
            }
            const auto behaviorIt = state.behaviors.find(first->instanceId);
            if (behaviorIt != state.behaviors.end()) {
                stream << " | order " << toString(behaviorIt->second.state);
            }
            if (state.specialMechanismsInitialized) {
                const auto parentIt =
                    state.specialMechanisms.carrierParents().find(
                        first->instanceId
                    );
                if (parentIt != state.specialMechanisms.carrierParents().end()) {
                    int ready = 0;
                    int deployed = 0;
                    for (const auto& [slot, childId] : parentIt->second.childBySlot) {
                        (void)slot;
                        const auto childIt =
                            state.specialMechanisms.carrierChildren().find(childId);
                        if (childIt == state.specialMechanisms.carrierChildren().end()
                            || childIt->second.phase == CarrierChildPhase::Destroyed) {
                            continue;
                        }
                        if (childIt->second.phase == CarrierChildPhase::Docked) {
                            ++ready;
                        } else {
                            ++deployed;
                        }
                    }
                    int reload = 0;
                    for (const auto& [slot, readyTick] : parentIt->second.slotReadyTick) {
                        const auto childIt = parentIt->second.childBySlot.find(slot);
                        if (childIt != parentIt->second.childBySlot.end()
                            && childIt->second >= 0) {
                            continue;
                        }
                        reload = std::max(reload, std::max(0, readyTick - state.tick));
                    }
                    stream << " | spawned " << ready << "/"
                           << std::max(0, parentIt->second.capacity)
                           << " ready deployed " << deployed;
                    if (reload > 0) {
                        stream << " reload " << reload;
                    }
                }
            }
        }
        if (state.selectedObjectIds.size() > 1) {
            stream << " | group ready";
        }
    } else {
        stream << " | " << state.interactionStatus;
    }
    return stream.str();
}



