std::string buildRuntimeUiStateLine(
    const RuntimeWindowState& state,
    const WorldObjectInstance& object
) {
    const RuntimeCachedCapabilityProfile& cached =
        runtimeCachedCapabilityProfileForObject(state, object);
    const int maxHealth = runtimeMaxHealthForObject(state, object);
    const int powerNet =
        state.economy.powerProduced - state.economy.powerUsed;

    std::ostringstream stream;
    stream
        << "uiState #"
        << object.instanceId
        << " "
        << object.type
        << " strength="
        << object.health
        << "/"
        << maxHealth
        << " pip="
        << formatMaybe(cached.ui.pip)
        << " pipScale="
        << formatMaybe(cached.ui.pipScale)
        << " pipsDrawForAll="
        << formatBool(cached.ui.pipsDrawForAll)
        << " cameo="
        << formatMaybe(cached.ui.cameoId)
        << " powerProduced="
        << state.economy.powerProduced
        << " powerUsed="
        << state.economy.powerUsed
        << " powerNet="
        << powerNet
        << " lowPower="
        << formatBool(powerNet < 0)
        << " radar="
        << runtimeRadarStatusText(state);
    return stream.str();
}

std::string buildRuntimeCapabilityCacheLine(
    const RuntimeWindowState& state
) {
    const RuntimeCapabilityCacheStats& stats = state.capabilityCache.stats;
    std::ostringstream stream;
    stream
        << "capabilityCache types="
        << state.capabilityCache.profilesByType.size()
        << " lookups="
        << stats.profileLookups
        << " hits="
        << stats.profileHits
        << " misses="
        << stats.profileMisses
        << " weaponLookups="
        << stats.weaponLookups
        << " weaponCandidateHits="
        << stats.weaponCandidateHits
        << " weaponCandidateMisses="
        << stats.weaponCandidateMisses
        << " lastTickLookups="
        << stats.lastTickProfileLookups
        << " softBudget="
        << runtimeCapabilityProfileLookupSoftBudgetPerTick
        << " overBudget="
        << formatBool(
            stats.lastTickProfileLookups
                > runtimeCapabilityProfileLookupSoftBudgetPerTick
        )
        << " lastTickHits="
        << stats.lastTickProfileHits
        << " lastTickMisses="
        << stats.lastTickProfileMisses
        << " lastTickWeaponLookups="
        << stats.lastTickWeaponLookups
        << " lastTickWeaponCandidateHits="
        << stats.lastTickWeaponCandidateHits
        << " lastTickWeaponCandidateMisses="
        << stats.lastTickWeaponCandidateMisses
        << " missionTransitions="
        << stats.missionTransitions
        << " recentMissionDiagnostics="
        << state.capabilityCache.recentMissionDiagnostics.size();
    if (!state.capabilityCache.recentMissionDiagnostics.empty()) {
        stream
            << " lastMission=\""
            << state.capabilityCache.recentMissionDiagnostics.back()
            << "\"";
    }
    return stream.str();
}

