int spawnRuntimeWeaponProjectiles(
    RuntimeWindowState& state,
    const WorldObjectInstance& attacker,
    const WorldObjectInstance& target,
    const WeaponType& weapon,
    const RuntimeWeaponProfile& weaponProfile,
    int damage,
    double outgoingDamageMultiplier = -1.0
) {
    if (runtimeSpawnedMissileProfileForWeapon(state, attacker, weapon) == nullptr) {
        const double multiplier = outgoingDamageMultiplier >= 0.0 ? outgoingDamageMultiplier
            : runtimeVeterancyAbilityMultiplier(state, attacker, VeteranAbility::Firepower);
        return beginRuntimeCombatBurst(state, attacker, target, weapon, weaponProfile, multiplier);
    }
    int projectileCount = 1;
    if (runtimeSpawnedMissileProfileForWeapon(
            state,
            attacker,
            weapon
        ) != nullptr) {
        const UnitType* unit = findRuntimeUnitType(state.rules, attacker);
        projectileCount = unit == nullptr
            ? 1
            : std::clamp(unit->spawnsNumber, 1, 8);
    }
    for (int index = 0; index < projectileCount; ++index) {
        spawnRuntimeProjectile(
            state,
            attacker,
            target,
            weapon,
            weaponProfile,
            damage,
            -1,
            0,
            false,
            -1,
            outgoingDamageMultiplier
        );
    }
    return projectileCount;
}









