RuntimeMultiplayerGameplaySecondaryActionKind runtimeSecondaryDeploymentActionForObjects(
    const RuntimeWindowState& state,
    const std::vector<int>& objectIds
) {
    bool hasDeployment = false;
    for (int id : objectIds) {
        const auto* object = findObjectById(state, id);
        if (object == nullptr) continue;
        const std::optional<bool> deployed = runtimeSecondaryDeploymentState(state, *object);
        if (!deployed.has_value()) continue;
        hasDeployment = true;
        if (!*deployed) return RuntimeMultiplayerGameplaySecondaryActionKind::DeployAll;
    }
    return hasDeployment ? RuntimeMultiplayerGameplaySecondaryActionKind::UndeployAll
        : RuntimeMultiplayerGameplaySecondaryActionKind::Contextual;
}





bool executeRuntimeSecondaryActionForSelection(
    RuntimeWindowState& state
) {
    cleanRuntimeSelection(state);
    const std::vector<int> selectedIds = state.selectedObjectIds;
    const auto action = runtimeSecondaryDeploymentActionForObjects(state, selectedIds);
    if (action == RuntimeMultiplayerGameplaySecondaryActionKind::Contextual)
        state.playerCommands.cancel(selectedIds);
    const bool handled = executeRuntimeSecondaryActions(state, selectedIds, action);
    if (handled) {
        return true;
    }

    state.interactionStatus =
        "secondary failed: select deployable unit";
    state.economy.status = state.interactionStatus;
    emitRuntimeSound(state, "blocked");
    return false;
}



































































