bool runRuntimeStockCampaignEventSemanticProbe(std::string& errorMessage) {
    const auto fail = [&errorMessage](const std::string& message) {
        errorMessage = message;
        return false;
    };

    auto probeStorage = std::make_unique<RuntimeWindowState>();
    RuntimeWindowState& probe = *probeStorage;
    probe.campaignMode = true;
    probe.tick = 100;
    probe.economy.owner = "Player House";
    probe.triggers.campaignCountryByIndex[0] = "Player";
    probe.triggers.campaignCountryByIndex[16] = "BadGuy3";
    probe.triggers.campaignCanonicalHouseByAlias["player"] = "Player House";
    probe.triggers.campaignCanonicalHouseByAlias["player house"] =
        "Player House";
    probe.triggers.campaignCanonicalHouseByAlias["badguy3"] =
        "BadGuy3 House";
    probe.triggers.campaignCanonicalHouseByAlias["badguy3 house"] =
        "BadGuy3 House";

    constexpr int targetId = 990240;
    WorldObjectInstance target;
    target.instanceId = targetId;
    target.kind = WorldObjectKind::Structure;
    target.owner = "BadGuy3 House";
    target.type = "STOCKEVENTSTRUCTURE";
    target.mapId = "stock-event-probe";
    target.tag = "STOCK_EVENT_PROBE_TAG";
    target.health = 256;
    target.alive = true;
    target.x = 4;
    target.y = 4;
    target.cell = runtimeCellKey(target.x, target.y);
    probe.world.accessObjects().push_back(std::move(target));

    RuntimeTriggerDefinition trigger;
    trigger.id = "STOCK_EVENT_PROBE";
    trigger.house = "Player House";
    trigger.activationTick = 90;
    trigger.lastFiredTick = 80;
    trigger.tagIds.insert("stock_event_probe_tag");

    RuntimeTriggerEvent spiedEvent;
    spiedEvent.type = 2;
    spiedEvent.arguments = {"2", "0", "0"};
    probe.triggers.campaignEnteredTickByTargetObject[targetId] = probe.tick;
    probe.triggers.campaignEntrantHouseByTargetObject[targetId] =
        "Player House";
    if (runtimeCampaignEventSatisfied(probe, trigger, spiedEvent)) {
        return fail("Event 2 accepted a generic engineer/garrison entry");
    }
    probe.triggers.campaignSpiedTickByTargetObject[targetId] = probe.tick;
    probe.triggers.campaignSpyHouseByTargetObject[targetId] =
        "BadGuy3 House";
    if (runtimeCampaignEventSatisfied(probe, trigger, spiedEvent)) {
        return fail("Event 2 ignored its authored Spy house");
    }
    probe.triggers.campaignSpyHouseByTargetObject[targetId] = "Player House";
    if (!runtimeCampaignEventSatisfied(probe, trigger, spiedEvent)) {
        return fail("Event 2 rejected a matching authoritative Spy infiltration");
    }

    RuntimeTriggerEvent discoveredEvent;
    discoveredEvent.type = 5;
    discoveredEvent.arguments = {"5", "0", "16"};
    if (!runtimeCampaignEventSatisfied(probe, trigger, discoveredEvent)) {
        return fail("Event 5 did not detect the first explored object of a house");
    }
    probe.triggers.campaignPreviouslyDiscoveredObjects.insert(targetId);
    if (runtimeCampaignEventSatisfied(probe, trigger, discoveredEvent)) {
        return fail("Event 5 retriggered for an already discovered house object");
    }
    probe.triggers.campaignPreviouslyDiscoveredObjects.erase(targetId);

    RuntimeTriggerEvent halfHealthEvent;
    halfHealthEvent.type = 39;
    halfHealthEvent.arguments = {"39", "0", "0"};
    probe.triggers.campaignInitialHealthByObject[targetId] = 256;
    probe.triggers.campaignPreviousHealthByObject[targetId] = 129;
    probe.world.accessObjects().front().health = 128;
    probe.triggers.campaignAttackedTickByObject[targetId] = probe.tick;
    probe.triggers.campaignAttackerHouseByObject[targetId] = "Player House";
    if (!runtimeCampaignEventSatisfied(probe, trigger, halfHealthEvent)) {
        return fail("Event 39 missed a same-tick combat half-health crossing");
    }
    probe.triggers.campaignAttackedTickByObject[targetId] = probe.tick - 1;
    if (runtimeCampaignEventSatisfied(probe, trigger, halfHealthEvent)) {
        return fail("Event 39 accepted stale combat before later damage");
    }
    probe.triggers.campaignAttackedTickByObject.erase(targetId);
    if (runtimeCampaignEventSatisfied(probe, trigger, halfHealthEvent)) {
        return fail("Event 39 accepted environmental/script damage");
    }

    RuntimeTriggerEvent quarterHealthEvent;
    quarterHealthEvent.type = 40;
    quarterHealthEvent.arguments = {"40", "0", "0"};
    probe.triggers.campaignPreviousHealthByObject[targetId] = 65;
    probe.world.accessObjects().front().health = 64;
    probe.triggers.campaignAttackedTickByObject[targetId] = probe.tick;
    if (!runtimeCampaignEventSatisfied(probe, trigger, quarterHealthEvent)) {
        return fail("Event 40 missed a same-tick combat quarter-health crossing");
    }
    probe.triggers.campaignAttackedTickByObject.erase(targetId);
    if (runtimeCampaignEventSatisfied(probe, trigger, quarterHealthEvent)) {
        return fail("Event 40 accepted environmental/script damage");
    }
    if (probe.triggers.unsupportedEvents != 0) {
        return fail("stock event probe entered the unsupported-event branch");
    }
    errorMessage.clear();
    return true;
}

