bool replanRuntimeMovePath(
    RuntimeWindowState& state,
    WorldObjectInstance& object,
    RuntimeObjectBehavior& behavior,
    bool allowNearbyTarget
);



bool reserveRuntimeRepathBudget(
    RuntimeWindowState& state,
    RuntimeObjectBehavior& behavior,
    const WorldObjectInstance& object,
    const char* reason
) {
    if (state.tick < behavior.nextRepathTick) {
        behavior.state = RuntimeBehaviorState::Blocked;
        state.simulationStatus =
            "repath cooldown #"
            + std::to_string(object.instanceId)
            + " "
            + reason;
        return false;
    }

    if (state.actionSummary.repathsThisTick >= runtimeMaxRepathsPerTick) {
        behavior.state = RuntimeBehaviorState::Blocked;
        behavior.nextRepathTick =
            std::max(behavior.nextRepathTick, state.tick + 1);
        state.simulationStatus =
            "repath deferred #"
            + std::to_string(object.instanceId)
            + " "
            + reason;
        return false;
    }

    ++state.actionSummary.repathsThisTick;
    ++state.perf.lastSimRepathCount;
    behavior.nextRepathTick = state.tick + runtimeRepathCooldownTicks;
    return true;
}

// A visible departure retains its original cell/capacity wait. Body-only
// conflicts reach local avoidance without changing this accepted passage.












#include "simulation/movement/ground/RuntimeCrowdedMoveArrival.inl"







// Old saves granted C4 the same foundation permission as an actual entry.
// Migrate that permission only when the accepted order is about to advance.



#include "simulation/ai/RuntimeAirMoveBehavior.inl"
#include "simulation/ai/RuntimeAircraftMotion.inl"



bool runRuntimeStockTeamScriptActionSemanticProbe(
    RuntimeWindowState& state,
    std::string& errorMessage
) {
    const auto fail = [&errorMessage](const std::string& message) {
        errorMessage = message;
        return false;
    };

    constexpr std::array<int, 6> stockActions{{10, 13, 24, 25, 45, 48}};
    for (int action : stockActions) {
        if (!runtimeTeamScriptActionSupported(action)) {
            return fail("action " + std::to_string(action) + " is unsupported");
        }
    }

    std::string idleInfantryType;
    for (const UnitType& infantry : state.rules.getInfantryTypes()) {
        WorldObjectInstance artProbe;
        artProbe.kind = WorldObjectKind::Infantry;
        artProbe.type = infantry.id;
        artProbe.alive = true;
        artProbe.health = 1;
        const ArtType* art = runtimeArtTypeForObject(state, artProbe);
        if (runtimeArtSequenceFrameCount(art, "Idle1") > 0
            && runtimeArtSequenceFrameCount(art, "Idle2") > 0) {
            idleInfantryType = infantry.id;
            break;
        }
    }
    if (idleInfantryType.empty()) {
        return fail("no stock infantry exposes both Idle1 and Idle2");
    }
    if (state.rules.findUnitType("UnitType", "MTNK") == nullptr
        || state.rules.findUnitType("UnitType", "TRUCKA") == nullptr
        || state.rules.findUnitType("UnitType", "TRUCKB") == nullptr) {
        return fail("stock MTNK/TRUCKA/TRUCKB rules are missing");
    }

    constexpr const char* probeOwner = "Team Script Probe";
    WorldObjectInstance placementProbe;
    placementProbe.instanceId = -710000;
    placementProbe.kind = WorldObjectKind::Infantry;
    placementProbe.owner = probeOwner;
    placementProbe.type = idleInfantryType;
    placementProbe.alive = true;
    placementProbe.health = 1;
    const std::unordered_map<int, int> occupiedByCell =
        buildRuntimeOccupancyLookup(state, placementProbe.instanceId);
    std::vector<RuntimeCellPoint> passableCells;
    passableCells.reserve(state.world.getTerrainCells().size());
    for (const TerrainCell& terrain : state.world.getTerrainCells()) {
        const RuntimeCellPoint candidate{terrain.x, terrain.y};
        if (findRuntimePassableCellNear(
                state,
                placementProbe,
                candidate,
                0,
                -1,
                nullptr,
                nullptr,
                &occupiedByCell
            ).has_value()) {
            passableCells.push_back(candidate);
        }
    }
    if (passableCells.size() < 5U) {
        return fail("the RA2 smoke map has fewer than five free land cells");
    }

    RuntimeCellPoint actorCell{-1, -1};
    RuntimeCellPoint nearCell{-1, -1};
    RuntimeCellPoint farCell{-1, -1};
    RuntimeCellPoint relocationCell{-1, -1};
    RuntimeCellPoint truckCell{-1, -1};
    bool placementResolved = false;
    const std::size_t actorAttempts = std::min<std::size_t>(
        passableCells.size(),
        64U
    );
    for (std::size_t actorIndex = 0;
        actorIndex < actorAttempts && !placementResolved;
        ++actorIndex) {
        const RuntimeCellPoint candidateActor = passableCells[actorIndex];
        std::optional<RuntimeCellPoint> candidateNear;
        std::optional<RuntimeCellPoint> candidateFar;
        double nearDistance = std::numeric_limits<double>::max();
        double farDistance = -1.0;
        for (const RuntimeCellPoint& candidate : passableCells) {
            if (candidate == candidateActor) continue;
            const double distance = runtimeCellDistance(
                candidateActor,
                candidate
            );
            if (distance >= 6.0 && distance < nearDistance) {
                candidateNear = candidate;
                nearDistance = distance;
            }
            if (distance > farDistance) {
                candidateFar = candidate;
                farDistance = distance;
            }
        }
        if (!candidateNear.has_value() || !candidateFar.has_value()
            || farDistance < nearDistance + 8.0) {
            continue;
        }

        std::optional<RuntimeCellPoint> candidateRelocation;
        for (const RuntimeCellPoint& candidate : passableCells) {
            if (candidate == candidateActor || candidate == *candidateNear
                || candidate == *candidateFar) {
                continue;
            }
            if (runtimeCellDistance(candidateActor, candidate)
                    >= nearDistance + 5.0
                && runtimeCellDistance(*candidateNear, candidate) >= 7.0
                && runtimeCellDistance(*candidateFar, candidate) >= 3.0) {
                candidateRelocation = candidate;
                break;
            }
        }
        if (!candidateRelocation.has_value()) continue;

        std::optional<RuntimeCellPoint> candidateTruck;
        for (const RuntimeCellPoint& candidate : passableCells) {
            if (candidate == candidateActor || candidate == *candidateNear
                || candidate == *candidateFar
                || candidate == *candidateRelocation) {
                continue;
            }
            if (runtimeCellDistance(candidateActor, candidate) >= 3.0
                && runtimeCellDistance(*candidateNear, candidate) >= 3.0) {
                candidateTruck = candidate;
                break;
            }
        }
        if (!candidateTruck.has_value()) continue;

        actorCell = candidateActor;
        nearCell = *candidateNear;
        farCell = *candidateFar;
        relocationCell = *candidateRelocation;
        truckCell = *candidateTruck;
        placementResolved = true;
    }
    if (!placementResolved) {
        return fail("could not resolve deterministic Team Script probe cells");
    }

    WorldObjectInstance* actorAdded = addRuntimeObjectInstanceForOwner(
        state,
        probeOwner,
        RuntimeBuildKind::Infantry,
        idleInfantryType,
        actorCell
    );
    if (actorAdded == nullptr) {
        return fail("could not create the Idle/follow/scout probe infantry");
    }
    const int actorId = actorAdded->instanceId;
    WorldObjectInstance* nearAdded = addRuntimeObjectInstanceForOwner(
        state,
        probeOwner,
        RuntimeBuildKind::Unit,
        "MTNK",
        nearCell
    );
    if (nearAdded == nullptr) return fail("could not create the near friendly");
    const int nearId = nearAdded->instanceId;
    WorldObjectInstance* farAdded = addRuntimeObjectInstanceForOwner(
        state,
        probeOwner,
        RuntimeBuildKind::Unit,
        "MTNK",
        farCell
    );
    if (farAdded == nullptr) return fail("could not create the far friendly");
    const int farId = farAdded->instanceId;

    RuntimeTeamMissionState mission;
    mission.instanceId = 710001;
    mission.teamTypeId = "TEAM_SCRIPT_PROBE";
    mission.scriptId = "TEAM_SCRIPT_PROBE_SCRIPT";
    mission.objectIds = {actorId};
    mission.stepIndex = 0;

    const WorldObjectInstance* nearest =
        runtimeTeamNearestFriendlyFollowTarget(state, mission, {actorId});
    if (nearest == nullptr || nearest->instanceId != nearId
        || nearest->instanceId == farId) {
        return fail("action 10 did not choose the nearest friendly mover");
    }
    const RuntimeScriptStep followStep{10, 0};
    if (issueRuntimeTeamScriptStep(state, mission, followStep)
            != RuntimeTeamStepDisposition::Complete
        || mission.targetObjectId != nearId) {
        return fail("action 10 did not issue a persistent follow order");
    }
    auto followBehavior = state.behaviors.find(actorId);
    if (followBehavior == state.behaviors.end()
        || followBehavior->second.kind != RuntimeBehaviorKind::Move
        || !followBehavior->second.autoAcquired
        || followBehavior->second.targetObjectId != nearId) {
        return fail("action 10 follow marker was not stored on the mover");
    }
    const RuntimeCellPoint oldFollowDestination =
        followBehavior->second.moveTarget;
    WorldObjectInstance* movingFriendly = findMutableObjectById(state, nearId);
    if (movingFriendly == nullptr) return fail("near friendly disappeared");
    setRuntimeObjectCell(state, *movingFriendly, relocationCell);
    refreshRuntimeObjectOccupancyAfterLocalChange(state);
    WorldObjectInstance* followingActor = findMutableObjectById(state, actorId);
    followBehavior = state.behaviors.find(actorId);
    if (followingActor == nullptr || followBehavior == state.behaviors.end()) {
        return fail("follow actor or behavior disappeared during retarget");
    }
    (void)prepareRuntimeFollowMove(
        state,
        *followingActor,
        followBehavior->second
    );
    if (followBehavior->second.moveTarget == oldFollowDestination
        || followBehavior->second.targetObjectId != nearId
        || !followBehavior->second.autoAcquired) {
        return fail("action 10 did not retarget when the friendly moved");
    }

    eraseRuntimeBehavior(state, actorId);
    for (int idleArgument : {0, 1}) {
        const RuntimeScriptStep idleStep{13, idleArgument};
        if (issueRuntimeTeamScriptStep(state, mission, idleStep)
                != RuntimeTeamStepDisposition::Waiting) {
            return fail(
                "action 13 Idle" + std::to_string(idleArgument + 1)
                + " did not start"
            );
        }
        const std::optional<std::string> sequence =
            runtimeTeamIdleSequenceName(idleArgument);
        if (!sequence.has_value()) return fail("Idle sequence lookup failed");
        const int duration =
            runtimeTeamIdleAnimationTicks(state, mission, *sequence);
        if (duration <= 0
            || runtimeTeamScriptStepCompletion(state, mission, idleStep)
                != RuntimeTeamStepCompletion::Waiting) {
            return fail("action 13 did not wait for authored animation frames");
        }
        state.tick += duration;
        if (runtimeTeamScriptStepCompletion(state, mission, idleStep)
                != RuntimeTeamStepCompletion::Complete) {
            return fail("action 13 did not complete at its frame duration");
        }
        const WorldObjectInstance* idleActor = findObjectById(state, actorId);
        if (idleActor == nullptr || idleActor->mission != "Guard") {
            return fail("action 13 did not return the infantry to Guard");
        }
    }
    if (issueRuntimeTeamScriptStep(state, mission, {13, 4})
            != RuntimeTeamStepDisposition::Complete) {
        return fail("the stock trn01 action 13,4 artifact was not a safe no-op");
    }

    WorldObjectInstance* audioActor = findMutableObjectById(state, actorId);
    if (audioActor == nullptr) return fail("audio probe actor disappeared");
    audioActor->owner = "Russians";
    const std::string savedEconomyOwner = state.economy.owner;
    state.runtimeVoiceVolume = 0;
    state.runtimeSoundVolume = 0;
    state.runtimeSoundIntentHistory.clear();
    state.runtimeSoundPlaybackHistory.clear();
    state.runtimeEvaQueue.clear();
    state.runtimeEvaBusyUntilTick = 0;
    const std::optional<std::string> expectedSpeech =
        runtimeTeamIndexedAudioId(state.evaIni, "DialogList", 154);
    if (!expectedSpeech.has_value()
        || toLowerAsciiLocal(*expectedSpeech) != "mis_a8_tanyaturned") {
        return fail("action 24 did not resolve RA2 DialogList index 154");
    }
    if (issueRuntimeTeamScriptStep(state, mission, {24, 154})
            != RuntimeTeamStepDisposition::Complete
        || state.runtimeSoundIntentHistory.empty()
        || state.runtimeSoundIntentHistory.back()
            != "speech:" + *expectedSpeech
        || state.economy.owner != savedEconomyOwner) {
        return fail("action 24 did not emit owner-scoped EVA speech");
    }

    const std::optional<std::string> expectedSound =
        runtimeTeamIndexedAudioId(state.soundIni, "SoundList", 421);
    if (!expectedSound.has_value()
        || toLowerAsciiLocal(*expectedSound) != "civsovfemfear") {
        return fail("action 25 did not resolve RA2 SoundList index 421");
    }
    if (issueRuntimeTeamScriptStep(state, mission, {25, 421})
            != RuntimeTeamStepDisposition::Complete
        || state.runtimeSoundIntentHistory.empty()
        || state.runtimeSoundIntentHistory.back()
            != "sound:" + *expectedSound) {
        return fail("action 25 did not emit the indexed sound effect");
    }

    WorldObjectInstance* truckAdded = addRuntimeObjectInstanceForOwner(
        state,
        probeOwner,
        RuntimeBuildKind::Unit,
        "TRUCKA",
        truckCell
    );
    if (truckAdded == nullptr) return fail("could not create TRUCKA");
    const int truckId = truckAdded->instanceId;
    const int oldTruckMaximum = std::max(
        1,
        runtimeMaxHealthForObject(state, *truckAdded)
    );
    truckAdded->health = std::max(1, oldTruckMaximum / 2);
    const double oldTruckRatio =
        static_cast<double>(truckAdded->health) / oldTruckMaximum;
    mission.objectIds = {truckId};
    if (issueRuntimeTeamScriptStep(state, mission, {45, 0})
            != RuntimeTeamStepDisposition::Complete) {
        return fail("action 45 did not complete");
    }
    const WorldObjectInstance* loadedTruck = findObjectById(state, truckId);
    if (loadedTruck == nullptr
        || toUpperAsciiLocal(loadedTruck->type) != "TRUCKB") {
        return fail("action 45 did not transform TRUCKA into TRUCKB");
    }
    const int newTruckMaximum = std::max(
        1,
        runtimeMaxHealthForObject(state, *loadedTruck)
    );
    const double newTruckRatio =
        static_cast<double>(loadedTruck->health) / newTruckMaximum;
    if (std::abs(oldTruckRatio - newTruckRatio)
        > (1.0 / newTruckMaximum) + 0.001) {
        return fail("action 45 did not preserve the truck health fraction");
    }

    mission.objectIds = {actorId};
    mission.instanceId = 710048;
    mission.scriptId = "TEAM_SCRIPT_SCOUT_PROBE";
    mission.stepIndex = 3;
    eraseRuntimeBehavior(state, actorId);
    const std::optional<RuntimeCellPoint> firstScoutDestination =
        runtimeTeamScoutDestination(state, mission, {actorId});
    const std::optional<RuntimeCellPoint> secondScoutDestination =
        runtimeTeamScoutDestination(state, mission, {actorId});
    if (!firstScoutDestination.has_value()
        || firstScoutDestination != secondScoutDestination
        || runtimeCellDistance(
            runtimeCellPointForObject(*findObjectById(state, actorId)),
            *firstScoutDestination
        ) < 4.0) {
        return fail("action 48 did not choose a deterministic scout direction");
    }
    const RuntimeScriptStep scoutStep{48, 0};
    if (issueRuntimeTeamScriptStep(state, mission, scoutStep)
            != RuntimeTeamStepDisposition::Waiting
        || mission.targetCell != *firstScoutDestination) {
        return fail("action 48 did not issue the scout movement");
    }
    const auto scoutBehavior = state.behaviors.find(actorId);
    if (scoutBehavior == state.behaviors.end()
        || scoutBehavior->second.kind != RuntimeBehaviorKind::Move
        || scoutBehavior->second.autoAcquired
        || runtimeTeamScriptStepCompletion(state, mission, scoutStep)
            != RuntimeTeamStepCompletion::Waiting) {
        return fail("action 48 did not wait for its movement behavior");
    }
    eraseRuntimeBehavior(state, actorId);
    if (runtimeTeamScriptStepCompletion(state, mission, scoutStep)
            != RuntimeTeamStepCompletion::Complete) {
        return fail("action 48 did not complete after scouting movement ended");
    }
    return true;
}

bool replanRuntimeMovePath(
    RuntimeWindowState& state,
    WorldObjectInstance& object,
    RuntimeObjectBehavior& behavior,
    bool allowNearbyTarget
) {
    const RuntimeCellPoint current = runtimeCellPointForObject(object);
    replaceRuntimeBehaviorPath(
        behavior,
        findRuntimePath(
            state,
            object,
            current,
            behavior.moveTarget,
            behavior.pendingAllowedOccupiedObjectId
        )
    );
    if (!behavior.path.empty() || current == behavior.moveTarget) {
        behavior.blockedTicks = 0;
        behavior.state = RuntimeBehaviorState::Queued;
        return true;
    }

    if (!allowNearbyTarget) {
        return false;
    }

    const std::optional<RuntimeCellPoint> alternateTarget =
        findRuntimePassableCellNear(
            state,
            object,
            behavior.moveTarget,
            8,
            behavior.pendingAllowedOccupiedObjectId
        );
    if (!alternateTarget.has_value()
        || *alternateTarget == behavior.moveTarget) {
        return false;
    }

    behavior.moveTarget = *alternateTarget;
    replaceRuntimeBehaviorPath(
        behavior,
        findRuntimePath(
            state,
            object,
            current,
            behavior.moveTarget,
            behavior.pendingAllowedOccupiedObjectId
        )
    );
    if (behavior.path.empty() && current != behavior.moveTarget) {
        return false;
    }

    behavior.blockedTicks = 0;
    behavior.state = RuntimeBehaviorState::Queued;
    return true;
}























