bool validateRuntimeSkirmishIdentitySemantics(std::string& summary) {
    RuntimeWindowState probe;
    probe.config.playerCountry = "Americans";
    probe.config.gameMode = "Battle";

    const auto makeSlot = [](
        bool enabled,
        bool human,
        const std::string& country,
        const std::string& team
    ) {
        RuntimeConfig::PlayerSlot slot;
        slot.enabled = enabled;
        slot.human = human;
        slot.country = country;
        slot.team = team;
        return slot;
    };
    probe.config.playerSlots = {
        makeSlot(true, true, "Americans", "1"),
        makeSlot(true, false, "Americans", "1"),
        makeSlot(true, false, "Americans", "0"),
        makeSlot(true, false, "Russians", "-"),
        makeSlot(false, false, "YuriCountry", "1")
    };
    probe.economy.owner = probe.config.playerCountry;
    initializeRuntimeSkirmishPlayerIdentities(
        probe,
        probe.config.playerCountry
    );

    const std::array<std::string, 4> owners = {{
        runtimeSkirmishOwnerForSlot(0),
        runtimeSkirmishOwnerForSlot(1),
        runtimeSkirmishOwnerForSlot(2),
        runtimeSkirmishOwnerForSlot(3)
    }};
    const std::unordered_set<std::string> uniqueOwners(
        owners.begin(),
        owners.end()
    );
    const bool stableUniqueOwners =
        uniqueOwners.size() == owners.size()
        && probe.economy.owner == owners[0]
        && probe.skirmishCountryByOwner.find(
            toLowerAsciiLocal(runtimeSkirmishOwnerForSlot(4))
        ) == probe.skirmishCountryByOwner.end();
    const bool sameCountryDistinct =
        owners[0] != owners[1]
        && runtimeCountryForOwner(probe, owners[0]) == "Americans"
        && runtimeCountryForOwner(probe, owners[1]) == "Americans";
    const bool teamAlliance =
        runtimeOwnersAreAllied(probe, owners[0], owners[1]);
    const bool noTeamIsHostile =
        !runtimeOwnersAreAllied(probe, owners[0], owners[2])
        && !runtimeOwnersAreAllied(probe, owners[2], owners[3])
        && runtimeOwnersAreHostileForAutoTarget(
            probe,
            owners[0],
            owners[2]
        )
        && runtimeOwnersAreHostileForAutoTarget(
            probe,
            owners[2],
            owners[3]
        );
    const bool battleHostility = runtimeOwnersAreHostileForAutoTarget(
        probe,
        owners[1],
        owners[3]
    );
    probe.config.gameMode = "FreeForAll";
    const bool freeForAllHostility = runtimeOwnersAreHostileForAutoTarget(
        probe,
        owners[1],
        owners[3]
    );
    const bool freeForAllIgnoresTeams = runtimeOwnersAreHostileForAutoTarget(
        probe,
        owners[0],
        owners[1]
    );

    CooperativeScenarioDefinition cooperativeScenario;
    cooperativeScenario.campaignId = "runtime-shell-probe";
    cooperativeScenario.campaignSection = "RuntimeShellProbe";
    cooperativeScenario.campaignOrdinal = 1;
    cooperativeScenario.missionOrdinal = 1;
    cooperativeScenario.mapId = "COOPPROBE";
    cooperativeScenario.authoredMapIds = {cooperativeScenario.mapId};
    cooperativeScenario.playerCountries = {"Americans"};
    cooperativeScenario.enemyCountries = {"Russians"};
    cooperativeScenario.fingerprint = 0xC00A11E5ULL;
    cooperativeScenario.identity = "runtime-shell-cooperative-probe";
    CooperativeScenarioMapValidation cooperativeValidation;
    cooperativeValidation.valid = true;
    cooperativeValidation.identityFingerprint = 0xA11E5C00ULL;
    cooperativeValidation.identity = "runtime-shell-cooperative-map-probe";
    RuntimeCooperativeSessionBuildOptions cooperativeOptions;
    for (std::size_t index = 0;
         index < runtimeCooperativeSlotCount;
         ++index) {
        const bool playerCoalition = index < 2U;
        CooperativeScenarioSlot& slot = cooperativeScenario.slots[index];
        slot.slotIndex = static_cast<int>(index);
        slot.label = static_cast<char>('A' + index);
        slot.authoredOwnerId = 4475 + static_cast<int>(index);
        slot.waypointId = static_cast<int>(index);
        slot.role = index == 0U
            ? CooperativeSlotRole::LocalHuman
            : (index == 1U
                ? CooperativeSlotRole::AiAlly
                : CooperativeSlotRole::AiEnemy);
        slot.coalitionId = playerCoalition ? 0 : 1;
        slot.authoredHouse = std::string("<Player @ ")
            + static_cast<char>('A' + index) + ">";
        slot.allowedCountries = playerCoalition
            ? cooperativeScenario.playerCountries
            : cooperativeScenario.enemyCountries;
        slot.defaultCountry = slot.allowedCountries.front();
        cooperativeValidation.waypoints[index] = {
            static_cast<int>(index),
            10 + static_cast<int>(index),
            20 + static_cast<int>(index),
            20010 + static_cast<int>(index)
        };
        cooperativeOptions.owners[index] = owners[index];
        cooperativeOptions.countries[index] = slot.defaultCountry;
        for (std::size_t other = 0;
             other < runtimeCooperativeSlotCount;
             ++other) {
            cooperativeScenario.allianceMatrix[index][other] =
                playerCoalition == (other < 2U);
        }
        // Make the ordinary team fallback deliberately wrong. The active
        // cooperative session must still keep A/B hostile to C/D.
        probe.skirmishTeamByOwner[toLowerAsciiLocal(owners[index])] =
            "ONE-COOPERATIVE-TEAM";
    }
    probe.config.gameMode = "Cooperative";
    const RuntimeCooperativeSessionBuildResult cooperativeBuild =
        probe.cooperativeSession.begin(
            cooperativeScenario,
            cooperativeValidation,
            cooperativeOptions
        );
    const bool cooperativeAllianceMatrix = cooperativeBuild.accepted
        && runtimeOwnersAreAllied(probe, owners[0], owners[1])
        && runtimeOwnersAreAllied(probe, owners[2], owners[3])
        && !runtimeOwnersAreAllied(probe, owners[0], owners[2])
        && !runtimeOwnersAreAllied(probe, owners[0], owners[3])
        && !runtimeOwnersAreAllied(probe, owners[1], owners[2])
        && !runtimeOwnersAreAllied(probe, owners[1], owners[3]);
    const bool cooperativeAliases = cooperativeBuild.accepted
        && runtimeOwnersAreAllied(probe, "<Player @ A>", owners[1])
        && runtimeOwnersAreAllied(probe, owners[2], "4478")
        && !runtimeOwnersAreAllied(probe, "<Player @ A>", "4477")
        && runtimeOwnersAreAllied(probe, owners[0], "Americans")
        && runtimeOwnersAreAllied(probe, owners[2], "Russians")
        && !runtimeOwnersAreAllied(probe, "Americans", "Russians")
        && !runtimeOwnersAreAllied(probe, owners[0], "UnknownHouse");
    const bool cooperativeAutoTarget = cooperativeBuild.accepted
        && !runtimeOwnersAreHostileForAutoTarget(
            probe,
            owners[0],
            owners[1]
        )
        && runtimeOwnersAreHostileForAutoTarget(
            probe,
            owners[0],
            owners[2]
        );

    std::ostringstream output;
    output << "owners=" << uniqueOwners.size()
           << " stableUnique=" << formatBool(stableUniqueOwners)
           << " sameCountryDistinct=" << formatBool(sameCountryDistinct)
           << " teamAlliance=" << formatBool(teamAlliance)
           << " team0Hostile=" << formatBool(noTeamIsHostile)
           << " battleHostile=" << formatBool(battleHostility)
           << " freeForAllHostile=" << formatBool(freeForAllHostility)
           << " freeForAllIgnoresTeams=" << formatBool(freeForAllIgnoresTeams)
           << " cooperativeMatrix=" << formatBool(cooperativeAllianceMatrix)
           << " cooperativeAliases=" << formatBool(cooperativeAliases)
           << " cooperativeAutoTarget=" << formatBool(cooperativeAutoTarget);
    summary = output.str();
    return stableUniqueOwners
        && sameCountryDistinct
        && teamAlliance
        && noTeamIsHostile
        && battleHostility
        && freeForAllHostility
        && freeForAllIgnoresTeams
        && cooperativeAllianceMatrix
        && cooperativeAliases
        && cooperativeAutoTarget;
}

bool validateRuntimeCooperativeSessionStartup(
    const RuntimeConfig& config,
    std::string& summary
) {
    const std::filesystem::path scenarioPath =
        runtimeCooperativeScenarioPath(config);
    if (scenarioPath.empty()) {
        summary = "data=unavailable skipped=yes";
        return true;
    }

    IniFile scenarioIni;
    CooperativeScenarioDatabase database;
    if (!scenarioIni.loadFromFile(scenarioPath.generic_string())
        || !database.loadFromIni(scenarioIni)
        || database.scenarios().empty()) {
        summary = "data=invalid";
        return false;
    }
    const CooperativeScenarioDefinition& scenario =
        database.scenarios().front();
    const std::filesystem::path localDataRoot(config.localDataRootPath);
    const std::filesystem::path mapPath =
        localDataRoot / "resources" / "mix_exports" / "multimd"
        / (toLowerAsciiLocal(scenario.mapId) + ".map");
    std::error_code mapError;
    if (!std::filesystem::is_regular_file(mapPath, mapError)) {
        summary = "map=missing id=" + scenario.mapId;
        return false;
    }

    RuntimeWindowState probe;
    probe.config = config;
    probe.config.defaultMapPath = mapPath.generic_string();
    probe.config.gameMode = "Cooperative";
    probe.config.gameModeRulesOverride = "MPCoopMD.ini";
    probe.config.playerCountry = scenario.slots[0].defaultCountry;
    probe.config.playerSlots.clear();
    for (std::size_t index = 0;
         index < runtimeCooperativeSlotCount;
         ++index) {
        RuntimeConfig::PlayerSlot slot;
        slot.enabled = true;
        slot.human = index == 0U;
        slot.name = index == 0U
            ? "Cooperative Startup Human"
            : "Cooperative Startup Computer " + std::to_string(index);
        slot.country = scenario.slots[index].defaultCountry;
        slot.color = index == 0U ? "Gold" : "Random";
        // The session, not this ordinary team label, must establish A/B and
        // C/D. Keeping all four equal catches an accidental fallback here.
        slot.team = "ONE-STARTUP-PROBE-TEAM";
        slot.difficulty = "Medium";
        slot.startPosition = static_cast<int>(index) + 1;
        probe.config.playerSlots.push_back(std::move(slot));
    }

    const bool initialized = initializeRuntimeCooperativeSession(probe);
    const std::array<std::string, runtimeCooperativeSlotCount> owners = {{
        runtimeSkirmishOwnerForSlot(0),
        runtimeSkirmishOwnerForSlot(1),
        runtimeSkirmishOwnerForSlot(2),
        runtimeSkirmishOwnerForSlot(3)
    }};
    const bool matrix = initialized
        && probe.cooperativeSession.active()
        && probe.cooperativeSession.mapId() == scenario.mapId
        && runtimeOwnersAreAllied(probe, owners[0], owners[1])
        && runtimeOwnersAreAllied(probe, owners[2], owners[3])
        && !runtimeOwnersAreAllied(probe, owners[0], owners[2])
        && !runtimeOwnersAreAllied(probe, owners[1], owners[3]);

    std::ostringstream output;
    output << "data=loaded"
           << " map=" << scenario.mapId
           << " initialized=" << formatBool(initialized)
           << " active=" << formatBool(probe.cooperativeSession.active())
           << " matrix=" << formatBool(matrix)
           << " status=" << probe.cooperativeSessionStatus;
    summary = output.str();
    return matrix;
}

bool validateRuntimeSkirmishStartAndBuildAllySemantics(
    std::string& summary
) {
    RuntimeWindowState probe;
    probe.config.defaultMapPath = "semantic/start-assignment.map";
    probe.config.gameMode = "Battle";
    probe.config.playerCountry = "Americans";

    const auto makeSlot = [](
        bool enabled,
        bool human,
        const std::string& team,
        int startPosition
    ) {
        RuntimeConfig::PlayerSlot slot;
        slot.enabled = enabled;
        slot.human = human;
        slot.country = human ? "Americans" : "Russians";
        slot.team = team;
        slot.startPosition = startPosition;
        return slot;
    };
    probe.config.playerSlots = {
        makeSlot(true, true, "1", 2),
        makeSlot(true, false, "1", 2),
        makeSlot(true, false, "2", 99),
        makeSlot(true, false, "-", 0),
        makeSlot(true, false, "-", 4),
        makeSlot(false, false, "1", 1)
    };
    probe.economy.owner = probe.config.playerCountry;
    initializeRuntimeSkirmishPlayerIdentities(
        probe,
        probe.config.playerCountry
    );

    constexpr int candidateCount = 5;
    std::vector<std::vector<bool>> legalBySlot(
        probe.config.playerSlots.size(),
        std::vector<bool>(candidateCount, true)
    );
    // Slot zero's requested position 2 is illegal.  Slot one may therefore
    // reserve position 2; slot zero must take its deterministic fallback.
    legalBySlot[0][1] = false;
    const std::vector<int> first = resolveRuntimeSkirmishStartAssignments(
        probe,
        candidateCount,
        legalBySlot
    );
    const std::vector<int> second = resolveRuntimeSkirmishStartAssignments(
        probe,
        candidateCount,
        legalBySlot
    );

    std::unordered_set<int> uniqueEnabledAssignments;
    bool allEnabledAssigned = first.size() == probe.config.playerSlots.size();
    for (std::size_t slotIndex = 0; slotIndex < 5 && slotIndex < first.size();
        ++slotIndex) {
        allEnabledAssigned = allEnabledAssigned && first[slotIndex] >= 0;
        if (first[slotIndex] >= 0) {
            uniqueEnabledAssignments.insert(first[slotIndex]);
        }
    }
    const bool deterministicFallback = first == second;
    const bool uniqueAssignments =
        uniqueEnabledAssignments.size() == 5;
    const bool legalExplicitHonored =
        first.size() >= 5
        && first[0] != 1
        && first[1] == 1
        && first[4] == 3;
    const bool conflictAndRangeFallback =
        first.size() >= 6
        && first[0] >= 0
        && first[2] >= 0
        && first[3] >= 0
        && first[5] == -1;

    const std::string localOwner = runtimeSkirmishOwnerForSlot(0);
    const std::string alliedOwner = runtimeSkirmishOwnerForSlot(1);
    const std::string enemyOwner = runtimeSkirmishOwnerForSlot(2);
    probe.config.buildOffAlly = false;
    const bool allyDisabled =
        runtimeOwnerCanAnchorBuildingPlacement(probe, localOwner)
        && !runtimeOwnerCanAnchorBuildingPlacement(probe, alliedOwner);
    probe.config.buildOffAlly = true;
    const bool allyEnabled =
        runtimeOwnerCanAnchorBuildingPlacement(probe, alliedOwner)
        && !runtimeOwnerCanAnchorBuildingPlacement(probe, enemyOwner);

    std::ostringstream output;
    output << "deterministic=" << formatBool(deterministicFallback)
           << " unique=" << formatBool(uniqueAssignments)
           << " legalExplicit=" << formatBool(legalExplicitHonored)
           << " fallback=" << formatBool(conflictAndRangeFallback)
           << " allAssigned=" << formatBool(allEnabledAssigned)
           << " buildOffAllyOff=" << formatBool(allyDisabled)
           << " buildOffAllyOn=" << formatBool(allyEnabled);
    summary = output.str();
    return deterministicFallback
        && uniqueAssignments
        && legalExplicitHonored
        && conflictAndRangeFallback
        && allEnabledAssigned
        && allyDisabled
        && allyEnabled;
}

bool validateRuntimeSkirmishOptionSemantics(
    const RuntimeConfig& config,
    const RuntimeWindowState& loadedState,
    std::string& summary
) {
    // Keep the independent smoke fixtures off the Windows thread stack.
    auto modeProbeStorage = std::make_unique<RuntimeWindowState>();
    RuntimeWindowState& modeProbe = *modeProbeStorage;
    modeProbe.config = config;
    modeProbe.config.gameMode = "MeatGrind";
    modeProbe.config.gameModeRulesOverride = "MPMeatMD.ini";
    modeProbe.economy.catalog = loadedState.economy.catalog;
    loadAndApplyRuntimeSkirmishModeRules(modeProbe);
    bool modeRuleApplied = false;
    for (const RuntimeBuildCatalogItem& item : modeProbe.economy.catalog) {
        if (toUpperAsciiLocal(item.typeId) == "GATECH"
            && item.techLevel == 11) {
            modeRuleApplied = true;
            break;
        }
    }

    auto allianceProbeStorage = std::make_unique<RuntimeWindowState>();
    RuntimeWindowState& allianceProbe = *allianceProbeStorage;
    allianceProbe.config = config;
    allianceProbe.config.gameMode = "FreeForAll";
    allianceProbe.config.gameModeRulesOverride = "MPFreeForAllMD.ini";
    allianceProbe.skirmishTeamByOwner["left"] = "1";
    allianceProbe.skirmishTeamByOwner["right"] = "1";
    loadAndApplyRuntimeSkirmishModeRules(allianceProbe);
    const bool alliesAllowedApplied =
        allianceProbe.skirmishModeRulesLoaded
        && !allianceProbe.skirmishModeAlliesAllowed
        && !runtimeOwnersAreAllied(allianceProbe, "Left", "Right");

    auto teamProbeStorage = std::make_unique<RuntimeWindowState>();
    RuntimeWindowState& teamProbe = *teamProbeStorage;
    teamProbe.config = config;
    teamProbe.config.gameMode = "TeamGame";
    teamProbe.config.gameModeRulesOverride = "MPTeamMD.ini";
    teamProbe.config.playerSlots.clear();
    teamProbe.config.playerSlots.resize(2);
    teamProbe.config.playerSlots[0].enabled = true;
    teamProbe.config.playerSlots[0].team = "1";
    teamProbe.config.playerSlots[1].enabled = true;
    teamProbe.config.playerSlots[1].team = "2";
    loadAndApplyRuntimeSkirmishModeRules(teamProbe);
    std::string teamFailure;
    const bool teamSetupAccepted = runtimeSkirmishModeTeamSetupValid(
        teamProbe,
        teamFailure
    );
    teamProbe.config.playerSlots[1].team.clear();
    const bool teamSetupRejected = !runtimeSkirmishModeTeamSetupValid(
        teamProbe,
        teamFailure
    );
    const bool mustAllyApplied = teamProbe.skirmishModeRulesLoaded
        && teamProbe.skirmishModeAlliesAllowed
        && !teamProbe.skirmishModeAllyChangeAllowed
        && teamProbe.skirmishModeMustAlly
        && teamSetupAccepted
        && teamSetupRejected;

    auto unholyProbeStorage = std::make_unique<RuntimeWindowState>();
    RuntimeWindowState& unholyProbe = *unholyProbeStorage;
    unholyProbe.config = config;
    unholyProbe.config.gameMode = "UnholyAlliance";
    unholyProbe.config.gameModeRulesOverride = "MPUnholyMD.ini";
    unholyProbe.rules = loadedState.rules;
    unholyProbe.rulesLoaded = loadedState.rulesLoaded;
    unholyProbe.economy.owner = "SkirmishPlayer1";
    unholyProbe.skirmishCountryByOwner["skirmishplayer1"] = "Americans";
    loadAndApplyRuntimeSkirmishModeRules(unholyProbe);
    const auto unholyItem = [&unholyProbe](const std::string& id)
        -> const RuntimeBuildCatalogItem* {
        const std::string wanted = toUpperAsciiLocal(id);
        const auto found = std::find_if(
            unholyProbe.economy.catalog.begin(),
            unholyProbe.economy.catalog.end(),
            [&wanted](const RuntimeBuildCatalogItem& item) {
                return toUpperAsciiLocal(item.typeId) == wanted;
            }
        );
        return found == unholyProbe.economy.catalog.end()
            ? nullptr
            : &*found;
    };
    const RuntimeBuildCatalogItem* alliedMcv = unholyItem("AMCV");
    const RuntimeBuildCatalogItem* sovietMcv = unholyItem("SMCV");
    const RuntimeBuildCatalogItem* yuriMcv = unholyItem("PCV");
    const RuntimeBuildCatalogItem* sovietPower = unholyItem("NAPOWR");
    const RuntimeBuildCatalogItem* yuriPower = unholyItem("YAPOWR");
    const bool unholyOwnerApplied = alliedMcv != nullptr
        && sovietMcv != nullptr
        && yuriMcv != nullptr
        && alliedMcv->techLevel == 0
        && sovietMcv->techLevel == 0
        && yuriMcv->techLevel == 0
        && runtimeOwnerListAllowsHouse(alliedMcv->owner, "YuriCountry")
        && runtimeOwnerListAllowsHouse(sovietMcv->owner, "Americans")
        && runtimeOwnerListAllowsHouse(yuriMcv->owner, "Russians");
    const bool unholyCatalogApplied = sovietPower != nullptr
        && yuriPower != nullptr
        && runtimeBuildItemVisibleForCountry(
            unholyProbe,
            *sovietPower,
            "Americans"
        )
        && runtimeBuildItemVisibleForCountry(
            unholyProbe,
            *yuriPower,
            "Americans"
        );
    WorldObjectInstance alliedYard;
    alliedYard.kind = WorldObjectKind::Structure;
    alliedYard.type = "GACNST";
    alliedYard.alive = true;
    WorldObjectInstance sovietYard = alliedYard;
    sovietYard.type = "NACNST";
    const bool ownerFactoryApplied = sovietPower != nullptr
        && !runtimeFactoryOwnerCompatibleWithBuildItem(
            unholyProbe,
            alliedYard,
            *sovietPower
        )
        && runtimeFactoryOwnerCompatibleWithBuildItem(
            unholyProbe,
            sovietYard,
            *sovietPower
        );
    const std::vector<const UnitType*> additionalMcvs =
        runtimeUnholyAllianceAdditionalMcvTypes(
            unholyProbe,
            "Americans"
        );
    std::unordered_set<std::string> additionalMcvIds;
    for (const UnitType* unit : additionalMcvs) {
        if (unit != nullptr) {
            additionalMcvIds.insert(toUpperAsciiLocal(unit->id));
        }
    }
    const bool unholyMcvApplied = additionalMcvIds.size() == 2U
        && additionalMcvIds.find("SMCV") != additionalMcvIds.end()
        && additionalMcvIds.find("PCV") != additionalMcvIds.end();
    const bool unholyApplied = unholyProbe.skirmishModeRulesLoaded
        && runtimeIsUnholyAllianceMode(unholyProbe)
        && unholyOwnerApplied
        && unholyCatalogApplied
        && ownerFactoryApplied
        && unholyMcvApplied;

    auto megawealthProbeStorage = std::make_unique<RuntimeWindowState>();
    RuntimeWindowState& megawealthProbe = *megawealthProbeStorage;
    megawealthProbe.config = config;
    megawealthProbe.config.gameMode = "Megawealth";
    megawealthProbe.config.gameModeRulesOverride = "MPMWMD.ini";
    megawealthProbe.rules = loadedState.rules;
    megawealthProbe.rulesLoaded = loadedState.rulesLoaded;
    megawealthProbe.economy.owner = "SkirmishPlayer1";
    megawealthProbe.skirmishCountryByOwner["skirmishplayer1"] = "Americans";
    loadAndApplyRuntimeSkirmishModeRules(megawealthProbe);
    static const std::unordered_set<std::string> megawealthOreTypes = {
        "RIPARIUS", "CRUENTUS", "VINIFERA", "ABOREUS"
    };
    int disabledOreTypes = 0;
    bool megawealthOreApplied = true;
    for (const TiberiumType& tiberium :
            megawealthProbe.rules.getTiberiumTypes()) {
        if (megawealthOreTypes.find(toUpperAsciiLocal(tiberium.id))
            == megawealthOreTypes.end()) {
            continue;
        }
        ++disabledOreTypes;
        megawealthOreApplied = megawealthOreApplied
            && runtimeOreRuleProbability(
                megawealthProbe,
                tiberium,
                false
            ) == 0.0
            && runtimeOreRuleProbability(
                megawealthProbe,
                tiberium,
                true
            ) == 0.0;
    }
    megawealthOreApplied = megawealthOreApplied && disabledOreTypes == 4;
    const UnitType* megaHarvester = findRuntimeUnitTypeById(
        megawealthProbe.rules,
        "HARV"
    );
    const UnitType* megaChronoMiner = findRuntimeUnitTypeById(
        megawealthProbe.rules,
        "CMIN"
    );
    const UnitType* megaSlaveMiner = findRuntimeUnitTypeById(
        megawealthProbe.rules,
        "SMIN"
    );
    const bool megawealthCrateApplied = megaHarvester != nullptr
        && megaChronoMiner != nullptr
        && megaSlaveMiner != nullptr
        && !runtimeModeCrateGoodieForUnit(
            megawealthProbe,
            *megaHarvester
        )
        && !runtimeModeCrateGoodieForUnit(
            megawealthProbe,
            *megaChronoMiner
        )
        && !runtimeModeCrateGoodieForUnit(
            megawealthProbe,
            *megaSlaveMiner
        );
    const RuntimeBuildCatalogItem* megaHarvesterItem = nullptr;
    for (const RuntimeBuildCatalogItem& item :
            megawealthProbe.economy.catalog) {
        if (toUpperAsciiLocal(item.typeId) == "HARV") {
            megaHarvesterItem = &item;
            break;
        }
    }
    const bool megawealthApplied =
        megawealthProbe.skirmishModeRulesLoaded
        && megawealthOreApplied
        && megawealthCrateApplied
        && megaHarvesterItem != nullptr
        && megaHarvesterItem->techLevel == 11;

    const auto startingPoolIds = [](
        const std::vector<const UnitType*>& units
    ) {
        std::vector<std::string> ids;
        ids.reserve(units.size());
        for (const UnitType* unit : units) {
            if (unit != nullptr) {
                ids.push_back(toUpperAsciiLocal(unit->id));
            }
        }
        return ids;
    };
    const auto startingPoolMatches = [&startingPoolIds](
        const RuntimeSkirmishStartingUnitPools& pools,
        const std::vector<std::string>& infantry,
        const std::vector<std::string>& vehicles
    ) {
        return startingPoolIds(pools.infantry) == infantry
            && startingPoolIds(pools.vehicles) == vehicles;
    };

    auto stockStartingPoolProbeStorage = std::make_unique<RuntimeWindowState>();
    RuntimeWindowState& stockStartingPoolProbe = *stockStartingPoolProbeStorage;
    stockStartingPoolProbe.rules = loadedState.rules;
    stockStartingPoolProbe.rulesLoaded = loadedState.rulesLoaded;
    const RuntimeSkirmishStartingUnitPools stockAlliedPool =
        runtimeSkirmishStartingUnitPoolsForCountry(
            stockStartingPoolProbe,
            "Americans"
        );
    const RuntimeSkirmishStartingUnitPools stockSovietPool =
        runtimeSkirmishStartingUnitPoolsForCountry(
            stockStartingPoolProbe,
            "Russians"
        );
    const RuntimeSkirmishStartingUnitPools stockYuriPool =
        runtimeSkirmishStartingUnitPoolsForCountry(
            stockStartingPoolProbe,
            "YuriCountry"
        );
    const bool stockStartingPoolsApplied = startingPoolMatches(
            stockAlliedPool,
            {"E1"},
            {"MTNK"}
        )
        && startingPoolMatches(
            stockSovietPool,
            {"E2"},
            {"HTNK"}
        )
        && startingPoolMatches(
            stockYuriPool,
            {"INIT"},
            {"LTNK"}
        );

    auto duelStartingPoolProbeStorage = std::make_unique<RuntimeWindowState>();
    RuntimeWindowState& duelStartingPoolProbe = *duelStartingPoolProbeStorage;
    duelStartingPoolProbe.config = config;
    duelStartingPoolProbe.config.gameMode = "Duel";
    duelStartingPoolProbe.config.gameModeRulesOverride = "MPDuelMD.ini";
    duelStartingPoolProbe.rules = loadedState.rules;
    duelStartingPoolProbe.rulesLoaded = loadedState.rulesLoaded;
    loadAndApplyRuntimeSkirmishModeRules(duelStartingPoolProbe);
    const bool duelStartingPoolsApplied =
        duelStartingPoolProbe.skirmishModeRulesLoaded
        && startingPoolMatches(
            runtimeSkirmishStartingUnitPoolsForCountry(
                duelStartingPoolProbe,
                "Americans"
            ),
            {"ADOG"},
            {}
        )
        && startingPoolMatches(
            runtimeSkirmishStartingUnitPoolsForCountry(
                duelStartingPoolProbe,
                "Russians"
            ),
            {"DOG"},
            {}
        )
        && startingPoolMatches(
            runtimeSkirmishStartingUnitPoolsForCountry(
                duelStartingPoolProbe,
                "YuriCountry"
            ),
            {},
            {}
        );

    const bool megawealthStartingPoolsApplied = startingPoolMatches(
            runtimeSkirmishStartingUnitPoolsForCountry(
                megawealthProbe,
                "Americans"
            ),
            {"E1", "ENGINEER"},
            {"MTNK"}
        )
        && startingPoolMatches(
            runtimeSkirmishStartingUnitPoolsForCountry(
                megawealthProbe,
                "Russians"
            ),
            {"E2", "SENGINEER"},
            {"HTNK"}
        )
        && startingPoolMatches(
            runtimeSkirmishStartingUnitPoolsForCountry(
                megawealthProbe,
                "YuriCountry"
            ),
            {"YENGINEER", "INIT"},
            {"LTNK"}
        );

    auto modStartingPoolProbeStorage = std::make_unique<RuntimeWindowState>();
    RuntimeWindowState& modStartingPoolProbe = *modStartingPoolProbeStorage;
    modStartingPoolProbe.rules = loadedState.rules;
    modStartingPoolProbe.rulesLoaded = loadedState.rulesLoaded;
    modStartingPoolProbe.skirmishModeRulesLoaded =
        modStartingPoolProbe.skirmishModeRules.loadFromString(
            "[E1]\nAllowedToStartInMultiplayer=no\n"
            "[MTNK]\nAllowedToStartInMultiplayer=no\n"
            "[CLEG]\nAllowedToStartInMultiplayer=yes\n"
            "[FV]\nAllowedToStartInMultiplayer=yes\n"
            "[HTNK]\nAllowedToStartInMultiplayer=yes\n"
        );
    const bool modStartingPoolsApplied =
        modStartingPoolProbe.skirmishModeRulesLoaded
        && startingPoolMatches(
            runtimeSkirmishStartingUnitPoolsForCountry(
                modStartingPoolProbe,
                "Americans"
            ),
            {"CLEG"},
            {"FV"}
        );

    auto difficultyProbeStorage = std::make_unique<RuntimeWindowState>();
    RuntimeWindowState& difficultyProbe = *difficultyProbeStorage;
    difficultyProbe.skirmishDifficultyByOwner["easyai"] = "Easy";
    difficultyProbe.skirmishDifficultyByOwner["hardai"] = "Hard";
    const bool difficultyApplied =
        runtimeDifficultyAdjustedStartingUnits(difficultyProbe, "EasyAI", 12) == 9
        && runtimeDifficultyAdjustedStartingUnits(difficultyProbe, "HardAI", 12) == 16
        && runtimeDifficultyHealthScale(difficultyProbe, "EasyAI") < 1.0
        && runtimeDifficultyHealthScale(difficultyProbe, "HardAI") > 1.0;

    auto crateProbeStorage = std::make_unique<RuntimeWindowState>();
    RuntimeWindowState& crateProbe = *crateProbeStorage;
    crateProbe.config.crates = true;
    crateProbe.config.fixedTickHz = 30;
    crateProbe.economy.owner = "SkirmishPlayer1";
    crateProbe.economy.credits = 1000;
    RuntimeCrateState crate;
    crate.cell = {4, 4};
    crate.value = 2000;
    crateProbe.skirmishCrates.push_back(crate);
    WorldObjectInstance collector;
    collector.instanceId = 1;
    collector.kind = WorldObjectKind::Unit;
    collector.owner = crateProbe.economy.owner;
    collector.type = "MTNK";
    collector.health = 100;
    collector.x = 4;
    collector.y = 4;
    collector.cell = runtimeCellKey(4, 4);
    collector.alive = true;
    crateProbe.world.accessObjects().push_back(collector);
    crateProbe.tick = 10;
    const bool crateAdvanced = advanceRuntimeSkirmishCrates(crateProbe);
    const bool crateCreditsApplied = crateProbe.economy.credits == 3000;
    const bool crateConsumed = !crateProbe.skirmishCrates.front().active;
    const bool crateTypeApplied = runtimeCrateTypeIs(
            crateProbe.skirmishCrates.front().powerupType,
            "Money"
        );
    const bool crateSoundApplied = crateProbe.runtimeSoundEvents == 1
        && crateProbe.runtimeSoundIntentHistory.size() == 1U
        && crateProbe.runtimeSoundIntentHistory.back()
            == "sound:CrateMoney";
    const bool crateAnimationApplied = crateProbe.impactEffects.size() == 1U
        && crateProbe.impactEffects.front().animId == "MONEY";
    const bool crateApplied = crateAdvanced
        && crateCreditsApplied
        && crateConsumed
        && crateTypeApplied
        && crateSoundApplied
        && crateAnimationApplied;

    auto crateWeightProbeStorage = std::make_unique<RuntimeWindowState>();
    RuntimeWindowState& crateWeightProbe = *crateWeightProbeStorage;
    crateWeightProbe.config.fixedTickHz = 30;
    crateWeightProbe.rules = loadedState.rules;
    crateWeightProbe.rulesLoaded = loadedState.rulesLoaded;
    bool crateWeightsApplied = true;
    for (int salt = 0; salt < 128 && crateWeightsApplied; ++salt) {
        for (bool water : {false, true}) {
            RuntimeCrateState weighted;
            weighted.cell = {salt % 17, salt / 17};
            weighted.water = water;
            const bool domainHasWeight = std::any_of(
                crateWeightProbe.rules.getCrateRules().powerups.begin(),
                crateWeightProbe.rules.getCrateRules().powerups.end(),
                [water](const CratePowerupRule& powerup) {
                    return powerup.weight > 0
                        && (!water || powerup.availableOverWater);
                }
            );
            const bool selectedPowerup = runtimeChooseCratePowerup(
                crateWeightProbe,
                weighted,
                salt
            );
            if (selectedPowerup != domainHasWeight) {
                crateWeightsApplied = false;
                break;
            }
            if (!selectedPowerup) {
                continue;
            }
            const CratePowerupRule* selected = runtimeCrateRuleForType(
                crateWeightProbe,
                weighted.powerupType
            );
            if (selected == nullptr
                || selected->weight <= 0
                || (water && !selected->availableOverWater)) {
                crateWeightsApplied = false;
                break;
            }
        }
    }

    auto crateBonusProbeStorage = std::make_unique<RuntimeWindowState>();
    RuntimeWindowState& crateBonusProbe = *crateBonusProbeStorage;
    crateBonusProbe.rules = loadedState.rules;
    crateBonusProbe.rulesLoaded = loadedState.rulesLoaded;
    WorldObjectInstance bonusCollector;
    bonusCollector.instanceId = 101;
    bonusCollector.kind = WorldObjectKind::Unit;
    bonusCollector.owner = "CrateOwner";
    bonusCollector.type = "MTNK";
    bonusCollector.health = 100;
    bonusCollector.x = 4;
    bonusCollector.y = 4;
    bonusCollector.cell = runtimeCellKey(4, 4);
    bonusCollector.alive = true;
    WorldObjectInstance bonusNeighbor = bonusCollector;
    bonusNeighbor.instanceId = 102;
    bonusNeighbor.x = 4;
    bonusNeighbor.cell = runtimeCellKey(4, 4);
    WorldObjectInstance foreignNeighbor = bonusCollector;
    foreignNeighbor.instanceId = 103;
    foreignNeighbor.owner = "OtherOwner";
    foreignNeighbor.x = 5;
    foreignNeighbor.cell = runtimeCellKey(5, 4);
    crateBonusProbe.world.accessObjects() = {
        bonusCollector,
        bonusNeighbor,
        foreignNeighbor
    };
    RuntimeCrateState bonusCrate;
    bonusCrate.cell = {4, 4};
    const RuntimeCrateCollector bonusCollectorInfo{
        bonusCollector.instanceId,
        bonusCollector.owner,
        bonusCrate.cell
    };
    CratePowerupRule armorPowerup;
    armorPowerup.type = "Armor";
    armorPowerup.data = 1.5;
    CratePowerupRule firepowerPowerup;
    firepowerPowerup.type = "Firepower";
    firepowerPowerup.data = 2.0;
    CratePowerupRule speedPowerup;
    speedPowerup.type = "Speed";
    speedPowerup.data = 1.2;
    const bool firstArmor = runtimeGrantCrateUnitBonus(
        crateBonusProbe,
        bonusCrate,
        bonusCollectorInfo,
        armorPowerup,
        RuntimeCrateUnitBonus::Armor
    );
    const bool firepower = runtimeGrantCrateUnitBonus(
        crateBonusProbe,
        bonusCrate,
        bonusCollectorInfo,
        firepowerPowerup,
        RuntimeCrateUnitBonus::Firepower
    );
    const bool speed = runtimeGrantCrateUnitBonus(
        crateBonusProbe,
        bonusCrate,
        bonusCollectorInfo,
        speedPowerup,
        RuntimeCrateUnitBonus::Speed
    );
    armorPowerup.data = 2.0;
    const bool stackedArmor = runtimeGrantCrateUnitBonus(
        crateBonusProbe,
        bonusCrate,
        bonusCollectorInfo,
        armorPowerup,
        RuntimeCrateUnitBonus::Armor
    );
    const WorldObjectInstance* boostedCollector = findObjectById(
        crateBonusProbe,
        101
    );
    const WorldObjectInstance* boostedNeighbor = findObjectById(
        crateBonusProbe,
        102
    );
    const WorldObjectInstance* unboostedForeign = findObjectById(
        crateBonusProbe,
        103
    );
    const bool crateBonusesApplied = firstArmor
        && firepower
        && speed
        && !stackedArmor
        && boostedCollector != nullptr
        && boostedNeighbor != nullptr
        && unboostedForeign != nullptr
        && std::abs(boostedCollector->crateArmorMultiplier - 1.5) < 0.0001
        && std::abs(boostedCollector->crateFirepowerMultiplier - 2.0) < 0.0001
        && std::abs(boostedCollector->crateSpeedMultiplier - 1.2) < 0.0001
        && std::abs(boostedNeighbor->crateArmorMultiplier - 1.5) < 0.0001
        && std::abs(unboostedForeign->crateArmorMultiplier - 1.0) < 0.0001
        && std::abs(runtimeVeterancyAbilityMultiplier(
            crateBonusProbe,
            *boostedCollector,
            VeteranAbility::Stronger
        ) - 1.5) < 0.0001
        && std::abs(runtimeVeterancyAbilityMultiplier(
            crateBonusProbe,
            *boostedCollector,
            VeteranAbility::Firepower
        ) - 2.0) < 0.0001
        && std::abs(runtimeVeterancyAbilityMultiplier(
            crateBonusProbe,
            *boostedCollector,
            VeteranAbility::Faster
        ) - 1.2) < 0.0001;

    auto crateDomainProbeStorage = std::make_unique<RuntimeWindowState>();
    RuntimeWindowState& crateDomainProbe = *crateDomainProbeStorage;
    crateDomainProbe.rules = loadedState.rules;
    crateDomainProbe.rulesLoaded = loadedState.rulesLoaded;
    std::string navalType;
    std::string groundType;
    for (const UnitType& unit : crateDomainProbe.rules.getVehicleTypes()) {
        WorldObjectInstance movementProbe;
        movementProbe.kind = WorldObjectKind::Unit;
        movementProbe.type = unit.id;
        const PathMovementMode mode = runtimeObjectMovementMode(
            crateDomainProbe,
            movementProbe
        );
        if (navalType.empty() && mode == PathMovementMode::Naval) {
            navalType = unit.id;
        }
        if (groundType.empty() && mode == PathMovementMode::Ground) {
            groundType = unit.id;
        }
    }
    RuntimeTerrainInfo waterInfo;
    waterInfo.kind = RuntimeTerrainKind::Water;
    waterInfo.water = true;
    crateDomainProbe.terrainInfoByCell.emplace(
        runtimeCellKey(9, 9),
        waterInfo
    );
    WorldObjectInstance domainCollector;
    domainCollector.instanceId = 201;
    domainCollector.kind = WorldObjectKind::Unit;
    domainCollector.owner = "CrateOwner";
    domainCollector.type = navalType;
    domainCollector.health = 100;
    domainCollector.x = 9;
    domainCollector.y = 9;
    domainCollector.cell = runtimeCellKey(9, 9);
    domainCollector.alive = true;
    crateDomainProbe.world.accessObjects().push_back(domainCollector);
    RuntimeCrateState waterCrate;
    waterCrate.cell = {9, 9};
    waterCrate.water = true;
    const bool navalCollectsWater = !navalType.empty()
        && runtimeCrateCollectorAt(crateDomainProbe, waterCrate).has_value();
    crateDomainProbe.world.accessObjects().front().type = groundType;
    const bool groundRejectsWater = !groundType.empty()
        && !runtimeCrateCollectorAt(crateDomainProbe, waterCrate).has_value();
    crateDomainProbe.world.accessObjects().front().onBridge = true;
    crateDomainProbe.terrainInfoByCell.at(runtimeCellKey(9, 9)).bridge = true;
    RuntimeCrateState bridgeCrate;
    bridgeCrate.cell = {9, 9};
    bridgeCrate.water = false;
    const bool groundCollectsBridge =
        runtimeCrateCollectorAt(crateDomainProbe, bridgeCrate).has_value();
    const bool crateDomainsApplied = navalCollectsWater
        && groundRejectsWater
        && groundCollectsBridge;

    auto crateBoundaryProbeStorage = std::make_unique<RuntimeWindowState>();
    RuntimeWindowState& crateBoundaryProbe = *crateBoundaryProbeStorage;
    crateBoundaryProbe.rules = loadedState.rules;
    crateBoundaryProbe.rulesLoaded = loadedState.rulesLoaded;
    crateBoundaryProbe.config.fixedTickHz = 30;
    crateBoundaryProbe.economy.owner = "CrateBoundaryOwner";
    crateBoundaryProbe.economy.credits = 1000;
    WorldObjectInstance boundaryCollector;
    boundaryCollector.instanceId = 301;
    boundaryCollector.kind = WorldObjectKind::Unit;
    boundaryCollector.owner = crateBoundaryProbe.economy.owner;
    boundaryCollector.type = "MTNK";
    boundaryCollector.health = 100;
    boundaryCollector.x = 4;
    boundaryCollector.y = 4;
    boundaryCollector.cell = runtimeCellKey(4, 4);
    boundaryCollector.alive = true;
    crateBoundaryProbe.world.accessObjects().push_back(boundaryCollector);
    const RuntimeCrateCollector boundaryCollectorInfo{
        boundaryCollector.instanceId,
        boundaryCollector.owner,
        {4, 4}
    };
    RuntimeCrateState unsupportedCrate;
    unsupportedCrate.cell = {4, 4};
    unsupportedCrate.powerupType = "MysteryModReward";
    const RuntimeCrateAward unsupportedAward = runtimeGrantCratePowerup(
        crateBoundaryProbe,
        unsupportedCrate,
        boundaryCollectorInfo
    );
    const bool unknownRewardStayedEmpty = !unsupportedAward.granted
        && crateBoundaryProbe.economy.credits == 1000;

    RuntimeCrateState obsoleteCrate;
    obsoleteCrate.cell = {4, 4};
    obsoleteCrate.powerupType = "Invulnerability";
    obsoleteCrate.powerupAnimation = "ARMOR";
    const RuntimeCrateAward obsoleteAward = runtimeGrantCratePowerup(
        crateBoundaryProbe,
        obsoleteCrate,
        boundaryCollectorInfo
    );
    const bool obsoleteRewardHandled = obsoleteAward.granted
        && runtimeCrateTypeIs(obsoleteAward.type, "Invulnerability")
        && crateBoundaryProbe.economy.credits == 1000;

    RuntimeCrateState cloakCrate;
    cloakCrate.cell = {4, 4};
    cloakCrate.powerupType = "Cloak";
    const RuntimeCrateAward cloakAward = runtimeGrantCratePowerup(
        crateBoundaryProbe,
        cloakCrate,
        boundaryCollectorInfo
    );
    const WorldObjectInstance* cloakedCollector = findObjectById(
        crateBoundaryProbe,
        boundaryCollector.instanceId
    );
    const bool cloakRewardHandled = cloakAward.granted
        && cloakedCollector != nullptr
        && cloakedCollector->crateCloakable
        && runtimeObjectCanCloak(crateBoundaryProbe, *cloakedCollector);
    WorldObjectInstance crateModifierTarget = boundaryCollector;
    crateModifierTarget.instanceId = 302;
    crateModifierTarget.crateArmorMultiplier = 1.0;
    crateModifierTarget.crateFirepowerMultiplier = 1.0;
    crateModifierTarget.crateSpeedMultiplier = 1.0;
    crateModifierTarget.crateCloakable = false;
    if (cloakedCollector != nullptr) {
        runtimeTransferCrateModifiers(
            crateBoundaryProbe,
            *cloakedCollector,
            crateModifierTarget
        );
    }
    const bool crateModifiersTransfer = cloakedCollector != nullptr
        && std::abs(
            crateModifierTarget.crateArmorMultiplier
                - cloakedCollector->crateArmorMultiplier
        ) < 0.0001
        && std::abs(
            crateModifierTarget.crateFirepowerMultiplier
                - cloakedCollector->crateFirepowerMultiplier
        ) < 0.0001
        && std::abs(
            crateModifierTarget.crateSpeedMultiplier
                - cloakedCollector->crateSpeedMultiplier
        ) < 0.0001
        && crateModifierTarget.crateCloakable
        && runtimeObjectCanCloak(crateBoundaryProbe, crateModifierTarget);
    const bool action108BoundariesApplied =
        runtimeCampaignCratePowerupType(13) == "Invulnerability"
        && runtimeCampaignCratePowerupType(15) == "IonStorm"
        && runtimeCampaignCratePowerupType(18) == "Pod"
        && runtimeCampaignCratePowerupType(6) == "Money"
        && runtimeCampaignCratePowerupType(19).empty()
        && runtimeCampaignCratePowerupType(-1) == "Unsupported";
    const bool moneyRangeApplied = runtimeCrateMoneyAmount(2000.0, 0) == 2000
        && runtimeCrateMoneyAmount(2000.0, 900) == 2900
        && runtimeCrateMoneyAmount(2000.0, 901) == 2000
        && runtimeCrateMoneyAmount(-1.0, 0) == 0;
    CratePowerupRule extremePowerup;
    extremePowerup.type = "Explosion";
    extremePowerup.data = std::numeric_limits<double>::max();
    RuntimeCrateState normalizedPowerupCrate;
    runtimeConfigureCratePowerup(normalizedPowerupCrate, extremePowerup);
    const bool powerupDataNormalized =
        normalizedPowerupCrate.powerupData == runtimeCratePowerupDataLimit;
    bool specialRewardsHandled = true;
    for (const char* type : {
            "Explosion",
            "Napalm",
            "ICBM",
            "Gas",
            "Tiberium",
            "IonStorm",
            "Pod"
        }) {
        RuntimeCrateState specialCrate;
        specialCrate.cell = {4, 4};
        specialCrate.powerupType = type;
        specialCrate.powerupData = 0.0;
        const RuntimeCrateAward specialAward = runtimeGrantCratePowerup(
            crateBoundaryProbe,
            specialCrate,
            boundaryCollectorInfo
        );
        specialRewardsHandled = specialRewardsHandled
            && specialAward.granted
            && runtimeCrateTypeIs(specialAward.type, type)
            && crateBoundaryProbe.economy.credits == 1000;
    }
    const bool crateRewardBoundariesApplied = unknownRewardStayedEmpty
        && obsoleteRewardHandled
        && cloakRewardHandled
        && crateModifiersTransfer
        && action108BoundariesApplied
        && moneyRangeApplied
        && powerupDataNormalized
        && specialRewardsHandled;

    auto freeMcvProbeStorage = std::make_unique<RuntimeWindowState>();
    RuntimeWindowState& freeMcvProbe = *freeMcvProbeStorage;
    freeMcvProbe.rules = loadedState.rules;
    freeMcvProbe.rulesLoaded = loadedState.rulesLoaded;
    freeMcvProbe.economy.owner = "SkirmishPlayer1";
    freeMcvProbe.economy.credits = 1501;
    freeMcvProbe.skirmishCountryByOwner[
        toLowerAsciiLocal(freeMcvProbe.economy.owner)
    ] = "Americans";
    WorldObjectInstance freeMcvCollector = boundaryCollector;
    freeMcvCollector.instanceId = 401;
    freeMcvCollector.owner = freeMcvProbe.economy.owner;
    freeMcvProbe.world.accessObjects().push_back(freeMcvCollector);
    RuntimeCrateState freeMcvCrate;
    freeMcvCrate.cell = {4, 4};
    const RuntimeCrateCollector freeMcvCollectorInfo{
        freeMcvCollector.instanceId,
        freeMcvCollector.owner,
        freeMcvCrate.cell
    };
    const UnitType* forcedMcv = runtimeFreeMcvForCollector(
        freeMcvProbe,
        freeMcvCrate,
        freeMcvCollectorInfo
    );
    const bool freeMcvPositive = forcedMcv != nullptr
        && runtimeUnitTypeIsMcv(freeMcvProbe, *forcedMcv);
    WorldObjectInstance existingStructure;
    existingStructure.instanceId = 402;
    existingStructure.kind = WorldObjectKind::Structure;
    existingStructure.owner = freeMcvProbe.economy.owner;
    existingStructure.type = "GAPOWR";
    existingStructure.health = 100;
    existingStructure.alive = true;
    freeMcvProbe.world.accessObjects().push_back(existingStructure);
    const bool freeMcvBlockedByStructure = runtimeFreeMcvForCollector(
        freeMcvProbe,
        freeMcvCrate,
        freeMcvCollectorInfo
    ) == nullptr;
    freeMcvProbe.world.accessObjects().pop_back();
    freeMcvProbe.economy.credits = 1500;
    const bool freeMcvBlockedByCredits = runtimeFreeMcvForCollector(
        freeMcvProbe,
        freeMcvCrate,
        freeMcvCollectorInfo
    ) == nullptr;
    freeMcvProbe.economy.credits = 1501;
    freeMcvProbe.campaignMode = true;
    const bool freeMcvBlockedInCampaign = runtimeFreeMcvForCollector(
        freeMcvProbe,
        freeMcvCrate,
        freeMcvCollectorInfo
    ) == nullptr;
    const bool freeMcvApplied = freeMcvPositive
        && freeMcvBlockedByStructure
        && freeMcvBlockedByCredits
        && freeMcvBlockedInCampaign;

    auto campaignCrateProbeStorage = std::make_unique<RuntimeWindowState>();
    RuntimeWindowState& campaignCrateProbe = *campaignCrateProbeStorage;
    campaignCrateProbe.campaignMode = true;
    IniFile campaignCrateIni;
    const bool campaignCrateIniLoaded = campaignCrateIni.loadFromString(
        "[CrateRules]\n"
        "SilverCrate=Veteran\n"
        "SoloCrateMoney=6789\n"
        "WoodCrate=Money\n"
        "WaterCrate=Reveal\n"
        "WoodCrateImg=WOODBOX\n"
        "CrateImg=LANDBOX\n"
        "WaterCrateImg=WATERBOX\n"
        "[Powerups]\n"
        "Money=1,MONEY,yes,2000\n"
        "Reveal=1,REVEAL,yes\n"
        "Veteran=1,VETERAN,yes,1\n"
        "[InfantryTypes]\n"
        "[VehicleTypes]\n"
        "[AircraftTypes]\n"
        "[BuildingTypes]\n"
        "[OverlayTypes]\n"
        "0=WOODBOX\n1=LANDBOX\n2=WATERBOX\n3=CUSTOMBOX\n"
        "[WOODBOX]\nCrate=yes\nImage=WOODART\n"
        "[LANDBOX]\nCrate=yes\nImage=LANDART\n"
        "[WATERBOX]\nCrate=yes\nImage=WATERART\n"
        "[CUSTOMBOX]\nCrate=yes\nImage=WOODBOX\n"
        "[Tiberiums]\n[TerrainTypes]\n[Warheads]\n"
    );
    campaignCrateProbe.rulesLoaded = campaignCrateIniLoaded
        && campaignCrateProbe.rules.loadFromIni(campaignCrateIni);
    const std::array<std::pair<const char*, const char*>, 4> overlayProbes{{
        {"WOODBOX", "WOODART"},
        {"LANDBOX", "LANDART"},
        {"WATERBOX", "WATERART"},
        {"CUSTOMBOX", "WOODBOX"}
    }};
    for (std::size_t index = 0; index < overlayProbes.size(); ++index) {
        TerrainCell terrainCell;
        terrainCell.x = static_cast<int>(index);
        terrainCell.y = 0;
        terrainCell.cellIndex512 = static_cast<int>(index);
        terrainCell.hasOverlay = true;
        terrainCell.overlayIndex = static_cast<int>(index);
        terrainCell.overlayType = overlayProbes[index].first;
        terrainCell.overlayImage = overlayProbes[index].second;
        campaignCrateProbe.world.accessTerrainCells().push_back(
            std::move(terrainCell)
        );
    }
    const int campaignOverlayCrates =
        initializeRuntimeCampaignOverlayCrates(campaignCrateProbe);
    const bool campaignCrateRewards = campaignOverlayCrates == 4
        && campaignCrateProbe.skirmishCrates.size() == 4U
        && runtimeCrateArtImageId(
            campaignCrateProbe.rules,
            "WOODBOX"
        ) == "WOODART"
        && runtimeCrateArtImageId(
            campaignCrateProbe.rules,
            "LANDBOX"
        ) == "LANDART"
        && runtimeCrateArtImageId(
            campaignCrateProbe.rules,
            "WATERBOX"
        ) == "WATERART"
        && runtimeCrateTypeIs(
            campaignCrateProbe.skirmishCrates[0].powerupType,
            "Money"
        )
        && campaignCrateProbe.skirmishCrates[0].value == 6789
        && campaignCrateProbe.skirmishCrates[0].imageId == "WOODART"
        && runtimeCrateTypeIs(
            campaignCrateProbe.skirmishCrates[1].powerupType,
            "Veteran"
        )
        && campaignCrateProbe.skirmishCrates[1].imageId == "LANDART"
        && runtimeCrateTypeIs(
            campaignCrateProbe.skirmishCrates[2].powerupType,
            "Reveal"
        )
        && campaignCrateProbe.skirmishCrates[2].water
        && campaignCrateProbe.skirmishCrates[2].imageId == "WATERART"
        && runtimeCrateTypeIs(
            campaignCrateProbe.skirmishCrates[3].powerupType,
            "Money"
        )
        && campaignCrateProbe.skirmishCrates[3].value == 6789
        && campaignCrateProbe.skirmishCrates[3].imageId == "WOODBOX"
        && std::none_of(
            campaignCrateProbe.world.getTerrainCells().begin(),
            campaignCrateProbe.world.getTerrainCells().end(),
            [](const TerrainCell& terrainCell) {
                return terrainCell.hasOverlay;
            }
        );

    auto shortGameProbeStorage = std::make_unique<RuntimeWindowState>();
    RuntimeWindowState& shortGameProbe = *shortGameProbeStorage;
    shortGameProbe.economy.owner = "SkirmishPlayer1";
    shortGameProbe.config.shortGame = true;
    WorldObjectInstance yard;
    yard.instanceId = 1;
    yard.kind = WorldObjectKind::Structure;
    yard.owner = shortGameProbe.economy.owner;
    yard.type = "GACNST";
    yard.health = 1000;
    yard.alive = true;
    WorldObjectInstance survivor = collector;
    survivor.instanceId = 2;
    survivor.owner = shortGameProbe.economy.owner;
    shortGameProbe.world.accessObjects().push_back(yard);
    shortGameProbe.world.accessObjects().push_back(survivor);
    const bool shortGameKeepsBase = !runtimeSkirmishOwnerDefeated(
        shortGameProbe,
        shortGameProbe.economy.owner
    );
    shortGameProbe.world.accessObjects().front().alive = false;
    const bool shortGameDefeat = runtimeSkirmishOwnerDefeated(
        shortGameProbe,
        shortGameProbe.economy.owner
    );
    shortGameProbe.config.shortGame = false;
    const bool fullEliminationSurvives = !runtimeSkirmishOwnerDefeated(
        shortGameProbe,
        shortGameProbe.economy.owner
    );
    const bool shortGameApplied = shortGameKeepsBase
        && shortGameDefeat
        && fullEliminationSurvives;

    auto mcvProbeStorage = std::make_unique<RuntimeWindowState>();
    RuntimeWindowState& mcvProbe = *mcvProbeStorage;
    BuildingType constructionYard;
    constructionYard.constructionYard = true;
    mcvProbe.config.mcvRepacks = false;
    const bool mcvDisabled = !runtimeSkirmishAllowsStructureUndeploy(
        mcvProbe,
        constructionYard
    );
    mcvProbe.config.mcvRepacks = true;
    const bool mcvEnabled = runtimeSkirmishAllowsStructureUndeploy(
        mcvProbe,
        constructionYard
    );

    auto superweaponProbeStorage = std::make_unique<RuntimeWindowState>();
    RuntimeWindowState& superweaponProbe = *superweaponProbeStorage;
    superweaponProbe.config.superweapons = false;
    superweaponProbe.economy.catalog = loadedState.economy.catalog;
    const bool hadSuperweapon = std::any_of(
        superweaponProbe.economy.catalog.begin(),
        superweaponProbe.economy.catalog.end(),
        [](const RuntimeBuildCatalogItem& item) {
            return runtimeIsSuperweaponCatalogItem(item);
        }
    );
    applyRuntimeSuperweaponCatalogOption(superweaponProbe);
    const bool superweaponsApplied = hadSuperweapon
        && std::none_of(
            superweaponProbe.economy.catalog.begin(),
            superweaponProbe.economy.catalog.end(),
            [](const RuntimeBuildCatalogItem& item) {
                return runtimeIsSuperweaponCatalogItem(item);
            }
        );

    std::ostringstream output;
    output << "modeRules=" << formatBool(
        modeProbe.skirmishModeRulesLoaded && modeRuleApplied
    )
           << " alliesAllowed=" << formatBool(alliesAllowedApplied)
           << " mustAlly=" << formatBool(mustAllyApplied)
           << " ownerFactory=" << formatBool(ownerFactoryApplied)
           << " unholy=" << formatBool(unholyApplied)
           << " megawealth=" << formatBool(megawealthApplied)
           << " startingPools=" << formatBool(stockStartingPoolsApplied)
           << " duelStart=" << formatBool(duelStartingPoolsApplied)
           << " megawealthStart="
           << formatBool(megawealthStartingPoolsApplied)
           << " modStart=" << formatBool(modStartingPoolsApplied)
           << " difficulty=" << formatBool(difficultyApplied)
           << " crates=" << formatBool(crateApplied)
           << " crateAdvance=" << formatBool(crateAdvanced)
           << " crateCredits=" << formatBool(crateCreditsApplied)
           << " crateConsumed=" << formatBool(crateConsumed)
           << " crateType=" << formatBool(crateTypeApplied)
           << " crateSound=" << formatBool(crateSoundApplied)
           << " crateAnimation=" << formatBool(crateAnimationApplied)
           << " crateWeights=" << formatBool(crateWeightsApplied)
           << " crateBonuses=" << formatBool(crateBonusesApplied)
           << " crateDomains=" << formatBool(crateDomainsApplied)
           << " crateBoundaries="
           << formatBool(crateRewardBoundariesApplied)
           << " freeMCV=" << formatBool(freeMcvApplied)
           << " campaignCrates=" << formatBool(campaignCrateRewards)
           << " shortGame=" << formatBool(shortGameApplied)
           << " mcvRepacks=" << formatBool(mcvDisabled && mcvEnabled)
           << " superweapons=" << formatBool(superweaponsApplied);
    summary = output.str();
    return modeProbe.skirmishModeRulesLoaded
        && modeRuleApplied
        && alliesAllowedApplied
        && mustAllyApplied
        && ownerFactoryApplied
        && unholyApplied
        && megawealthApplied
        && stockStartingPoolsApplied
        && duelStartingPoolsApplied
        && megawealthStartingPoolsApplied
        && modStartingPoolsApplied
        && difficultyApplied
        && crateApplied
        && crateWeightsApplied
        && crateBonusesApplied
        && crateDomainsApplied
        && crateRewardBoundariesApplied
        && freeMcvApplied
        && campaignCrateRewards
        && shortGameApplied
        && mcvDisabled
        && mcvEnabled
        && superweaponsApplied;
}







int runtimeComputerAiOwnedTypeCount(
    const RuntimeWindowState& state,
    const std::string& owner,
    const std::string& typeId
) {
    const std::string wanted = toUpperAsciiLocal(trimAsciiLocal(typeId));
    return static_cast<int>(std::count_if(
        state.world.getObjects().begin(),
        state.world.getObjects().end(),
        [&](const WorldObjectInstance& object) {
            return object.alive
                && runtimeComputerAiOwnerMatches(object, owner)
                && toUpperAsciiLocal(trimAsciiLocal(object.type)) == wanted;
        }
    ));
}







































