POINT pointFromMouseMessage(LPARAM lParam) {
    const auto point = runtimeInputPixelPointFromPackedPosition(
        static_cast<std::uint32_t>(lParam));
    return {point.x, point.y};
}

POINT runtimeScreenPointForCell(
    const RuntimeWindowState& state,
    const RECT& viewport,
    const RuntimeCellPoint& cell,
    int level
) {
    const RuntimeProjectedPoint projected =
        runtimeProjectCellXY(cell.x, cell.y, level, state.camera);
    return runtimeScreenPoint(projected, viewport, state.camera);
}

std::optional<RuntimeCellPoint> runtimeRadarCellAtPoint(
    const RuntimeWindowState& state,
    const RECT& radarRect,
    POINT point
) {
    const RuntimeRadarProjection projection = buildRuntimeRadarProjection(state);
    const RECT radarInterior = runtimeRadarInteriorRect(radarRect);
    const RuntimeRadarLayout layout =
        runtimeRadarLayout(radarInterior, projection);
    if (!runtimeRadarAvailable(state)
        || runtimeRadarTransitionActive(state)
        || !projection.valid
        || layout.scaleX <= 0.0
        || layout.scaleY <= 0.0
        || !PtInRect(&layout.rect, point)) {
        return std::nullopt;
    }

    const RuntimeRadarDxyPoint clickedDxy{
        projection.minX
            + ((static_cast<double>(point.x - layout.rect.left) + 0.5)
                / layout.scaleX),
        projection.minY
            + ((static_cast<double>(point.y - layout.rect.top) + 0.5)
                / layout.scaleY)
    };
    if (!runtimeRadarProjectionContains(projection, clickedDxy)) {
        return std::nullopt;
    }

    const double approximateX =
        (clickedDxy.x + clickedDxy.y + 2.0) / 2.0;
    const double approximateY =
        (clickedDxy.y - clickedDxy.x
            + (2.0 * projection.fullMapWidth)) / 2.0;
    const int baseX = static_cast<int>(std::floor(approximateX));
    const int baseY = static_cast<int>(std::floor(approximateY));

    double bestScore = std::numeric_limits<double>::max();
    std::optional<RuntimeCellPoint> bestCell;
    for (int dy = -3; dy <= 3; ++dy) {
        for (int dx = -3; dx <= 3; ++dx) {
            const RuntimeCellPoint candidate{baseX + dx, baseY + dy};
            const auto terrainIt =
                state.terrainByCell.find(runtimeCellKey(candidate.x, candidate.y));
            if (terrainIt == state.terrainByCell.end()
                || terrainIt->second == nullptr) {
                continue;
            }
            RuntimeRadarDxyPoint candidateDxy = runtimeRadarDxyPoint(
                candidate.x,
                candidate.y,
                projection.fullMapWidth
            );
            candidateDxy.y += 1.0;
            const double score =
                std::pow(candidateDxy.x - clickedDxy.x, 2.0)
                + std::pow(candidateDxy.y - clickedDxy.y, 2.0);
            if (score < bestScore) {
                bestScore = score;
                bestCell = candidate;
            }
        }
    }

    return bestCell;
}



void drawRuntimeDiamond(
    HDC dc,
    const POINT& center,
    int radius
) {
    MoveToEx(dc, center.x, center.y - radius, nullptr);
    LineTo(dc, center.x + radius, center.y);
    LineTo(dc, center.x, center.y + radius);
    LineTo(dc, center.x - radius, center.y);
    LineTo(dc, center.x, center.y - radius);
}

void drawRuntimeIsoDiamond(
    HDC dc,
    const POINT& center,
    int halfWidth,
    int halfHeight
) {
    halfWidth = std::max(1, halfWidth);
    halfHeight = std::max(1, halfHeight);
    MoveToEx(dc, center.x, center.y - halfHeight, nullptr);
    LineTo(dc, center.x + halfWidth, center.y);
    LineTo(dc, center.x, center.y + halfHeight);
    LineTo(dc, center.x - halfWidth, center.y);
    LineTo(dc, center.x, center.y - halfHeight);
}

void drawRuntimeFilledIsoDiamond(
    HDC dc,
    const POINT& center,
    int halfWidth,
    int halfHeight
) {
    halfWidth = std::max(1, halfWidth);
    halfHeight = std::max(1, halfHeight);
    const POINT points[] = {
        {center.x, center.y - halfHeight},
        {center.x + halfWidth, center.y},
        {center.x, center.y + halfHeight},
        {center.x - halfWidth, center.y}
    };
    Polygon(dc, points, 4);
}

const BuildingType* findRuntimeBuildingType(
    const RulesDatabase& rules,
    const std::string& typeId
) {
    for (const BuildingType& building : rules.getBuildingTypes()) {
        if (building.id == typeId) {
            return &building;
        }
    }
    return nullptr;
}

const UnitType* findRuntimeUnitTypeInList(
    const std::vector<UnitType>& units,
    const std::string& typeId
) {
    for (const UnitType& unit : units) {
        if (unit.id == typeId) {
            return &unit;
        }
    }
    return nullptr;
}

const UnitType* runtimeUnitTypeForBuildItem(
    const RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item
) {
    if (item.kind == RuntimeBuildKind::Infantry) {
        return findRuntimeUnitTypeInList(
            state.rules.getInfantryTypes(),
            item.typeId
        );
    }
    if (item.kind != RuntimeBuildKind::Unit) {
        return nullptr;
    }
    if (const UnitType* vehicle = findRuntimeUnitTypeInList(
            state.rules.getVehicleTypes(),
            item.typeId
        )) {
        return vehicle;
    }
    return findRuntimeUnitTypeInList(
        state.rules.getAircraftTypes(),
        item.typeId
    );
}

const ArtType* runtimeArtTypeForBuildItem(
    const RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item
) {
    std::string artId = item.typeId;
    if (item.kind == RuntimeBuildKind::Building
        || item.kind == RuntimeBuildKind::Defense) {
        if (const BuildingType* building =
                findRuntimeBuildingType(state.rules, item.typeId)) {
            artId = building->image.empty() ? building->id : building->image;
        }
    } else {
        const UnitType* unit = runtimeUnitTypeForBuildItem(state, item);
        if (unit != nullptr) {
            artId = unit->image.empty() ? unit->id : unit->image;
        }
    }

    return state.art.findArtType(artId);
}

#include "ui/input/diagnostics/RuntimeKeyboardParentDiagnostics.inl"
#include "ui/input/RuntimeGameplayIntentRouting.inl"

std::string runtimeImageIdForBuildItem(
    const RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item
) {
    if (item.kind == RuntimeBuildKind::Building
        || item.kind == RuntimeBuildKind::Defense) {
        if (const BuildingType* building =
                findRuntimeBuildingType(state.rules, item.typeId)) {
            return building->image.empty() ? building->id : building->image;
        }
    } else {
        const UnitType* unit = runtimeUnitTypeForBuildItem(state, item);
        if (unit != nullptr) {
            return unit->image.empty() ? unit->id : unit->image;
        }
    }
    return item.typeId;
}

std::vector<std::string> runtimeCameoCandidateIds(
    const RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item
) {
    std::vector<std::string> candidates;
    if (const ArtType* art = runtimeArtTypeForBuildItem(state, item)) {
        for (const std::string& token : splitRuntimeTokenList(art->cameo)) {
            candidates.push_back(token);
        }
    }
    // Retail reads the primary Cameo from the resolved art section and uses
    // XXICON only when that value is empty or cannot be loaded. AltCameo is a
    // separate infiltrated-factory state, not a file-loading fallback. Avoid
    // synthetic TYPE+ICON guesses: ORCAICON is a valid legacy asset, but the
    // stock ORCA resolves through Image=FALC to Cameo=FALCICON.
    candidates.push_back("xxicon");

    std::vector<std::string> uniqueCandidates;
    std::unordered_set<std::string> seen;
    for (const std::string& candidate : candidates) {
        const std::string trimmed = trimAsciiLocal(candidate);
        if (trimmed.empty()) {
            continue;
        }
        const std::string key = toLowerAsciiLocal(trimmed);
        if (seen.insert(key).second) {
            uniqueCandidates.push_back(trimmed);
        }
    }
    return uniqueCandidates;
}

std::string runtimeCameoFileName(const std::string& cameoId) {
    std::string fileName = toLowerAsciiLocal(trimAsciiLocal(cameoId));
    if (fileName.size() < 4 || fileName.substr(fileName.size() - 4) != ".shp") {
        fileName += ".shp";
    }
    return fileName;
}

std::optional<std::string> findRuntimeCameoPath(
    const RuntimeWindowState& state,
    const std::string& cameoId
) {
    const std::string assetRootPath = runtimeAssetRootPath(state.config);
    if (assetRootPath.empty()) {
        return std::nullopt;
    }

    const std::filesystem::path assetRoot(assetRootPath);
    const std::string fileName = runtimeCameoFileName(cameoId);
    const std::filesystem::path roots[] = {
        assetRoot / "cameomd",
        assetRoot / "ra2md" / "localmd",
        assetRoot / "language",
        assetRoot / "langmd",
        assetRoot / "expandmd02",
        assetRoot / "expandmd01",
        assetRoot / "ra2md",
        assetRoot / "ra2"
    };

    for (const std::filesystem::path& root : roots) {
        const std::filesystem::path candidate = root / fileName;
        std::error_code errorCode;
        if (std::filesystem::exists(candidate, errorCode)
            && std::filesystem::is_regular_file(candidate, errorCode)) {
            return pathString(candidate);
        }
    }
    return std::nullopt;
}

std::string runtimeUiResourceFileName(
    const std::string& imageId,
    const std::string& extension
) {
    std::string fileName = toLowerAsciiLocal(trimAsciiLocal(imageId));
    if (fileName.size() >= 4) {
        const std::string currentExtension = fileName.substr(fileName.size() - 4);
        if (currentExtension == ".shp" || currentExtension == ".sha"
            || currentExtension == ".pcx") {
            fileName.resize(fileName.size() - 4);
        }
    }
    return fileName + extension;
}

std::optional<std::filesystem::path> findRuntimeLooseUiResourcePath(
    const RuntimeWindowState& state,
    const std::string& subdirectory,
    const std::string& imageId,
    const std::string& extension,
    bool modOnly
) {
    const std::string fileName = runtimeUiResourceFileName(imageId, extension);
    if (fileName == extension) {
        return std::nullopt;
    }

    std::vector<std::filesystem::path> roots;
    const auto addLayerRoots = [&](const std::filesystem::path& root) {
        if (root.empty()) {
            return;
        }
        const std::string kind = extension == ".pcx" ? "pcx" : "shp";
        if (!subdirectory.empty()) {
            roots.push_back(root / kind / subdirectory);
            roots.push_back(root / subdirectory);
        }
        roots.push_back(root / kind);
        roots.push_back(root);
    };

    if (!trimAsciiLocal(state.config.modRootPath).empty()) {
        addLayerRoots(std::filesystem::path(state.config.modRootPath));
    }
    if (!modOnly) {
        const std::filesystem::path assetRoot(runtimeAssetRootPath(state.config));
        if (!assetRoot.empty()) {
            // Keep the loose export tree in archive precedence. Expansion
            // MIX exports live at the asset root; only localmd is nested
            // below ra2md in this repository.
            addLayerRoots(assetRoot / "ra2md" / "localmd");
            addLayerRoots(assetRoot / "language");
            addLayerRoots(assetRoot / "langmd");
            addLayerRoots(assetRoot / "expandmd02");
            addLayerRoots(assetRoot / "expandmd01");
            addLayerRoots(assetRoot / "ra2md");
            addLayerRoots(assetRoot / "ra2");
            addLayerRoots(assetRoot);
        }
    }

    std::unordered_set<std::string> seen;
    for (const std::filesystem::path& root : roots) {
        const std::filesystem::path candidate = root / fileName;
        const std::string key = toLowerAsciiLocal(pathString(candidate));
        if (!seen.insert(key).second) {
            continue;
        }
        std::error_code errorCode;
        if (std::filesystem::exists(candidate, errorCode)
            && std::filesystem::is_regular_file(candidate, errorCode)) {
            return candidate;
        }
    }
    return std::nullopt;
}

std::string runtimeSidebarFactionKey(const RuntimeWindowState& state) {
    const std::string voice = runtimeEvaVoiceKeyForOwner(state);
    if (voice == "Russian") {
        return "soviet";
    }
    if (voice == "Yuri") {
        return "yuri";
    }
    return "allied";
}

std::filesystem::path runtimeSidebarMixPath(
    const RuntimeWindowState& state
) {
    const std::filesystem::path root(runtimeAssetRootPath(state.config));
    const std::string faction = runtimeSidebarFactionKey(state);
    return root / "ra2"
        / (faction == "allied" ? "sidec01.mix" : "sidec02.mix");
}

std::filesystem::path runtimeYuriSidebarOverrideMixPath(
    const RuntimeWindowState& state
) {
    return std::filesystem::path(runtimeAssetRootPath(state.config))
        / "ra2md" / "sidec02md.mix";
}

std::filesystem::path runtimeCampaignScoreResourceMixPath(
    const RuntimeWindowState& state,
    const std::string& resourceId
) {
    std::string normalized = toLowerAsciiLocal(trimAsciiLocal(resourceId));
    const std::string extension = toLowerAsciiLocal(
        std::filesystem::path(normalized).extension().string()
    );
    if (extension == ".shp" || extension == ".pal") {
        normalized.resize(normalized.size() - extension.size());
    }
    const bool alliedOrSovietScoreResource = normalized == "ascrbkmd"
        || normalized == "ascrtmd"
        || normalized == "ascramd"
        || normalized == "ascore"
        || normalized == "sscrbkmd"
        || normalized == "sscrtmd"
        || normalized == "sscramd"
        || normalized == "sscore";
    const bool yuriScoreResource = normalized == "sycrbkmd"
        || normalized == "sycrtmd"
        || normalized == "sycramd"
        || normalized == "yscore";
    const std::filesystem::path root(runtimeAssetRootPath(state.config));
    if (normalized == "grfxtxt") {
        return root / "ra2" / "cache.mix";
    }
    if (alliedOrSovietScoreResource) {
        return root / "ra2" / "neutral.mix";
    }
    if (yuriScoreResource) {
        return root / "ra2md" / "ntrlmd.mix";
    }
    return {};
}

std::string runtimeYuriSidebarOverrideImageId(
    const std::string& imageId
) {
    std::string normalized =
        toLowerAsciiLocal(trimAsciiLocal(imageId));
    if (normalized.size() >= 4
        && normalized.substr(normalized.size() - 4) == ".shp") {
        normalized.resize(normalized.size() - 4);
    }
    if (normalized == "bkgdsm") {
        return "bkgdsmy.shp";
    }
    if (normalized == "bkgdmd") {
        return "bkgdmdy.shp";
    }
    if (normalized == "bkgdlg") {
        return "bkgdlgy.shp";
    }
    if (normalized == "radar") {
        return "radary.shp";
    }
    return "";
}

#include "ui/resources/RuntimeInteractionUiResources.inl"

const std::vector<RuntimePaletteColor>* runtimeUiPaletteUnmemoized(
    RuntimeWindowState& state,
    const std::string& paletteId
) {
    const std::string resourceKey =
        toLowerAsciiLocal(trimAsciiLocal(paletteId));
    const bool factionUiResource = resourceKey == "sidebar"
        || resourceKey == "uibkgd"
        || resourceKey == "radar";
    const std::string sidebarFaction = factionUiResource
        ? runtimeSidebarFactionKey(state) : "";
    const std::string key = resourceKey + (sidebarFaction.empty() ? "" : "|" + sidebarFaction);
    auto paletteIt = state.uiPalettesByName.find(key);
    if (paletteIt != state.uiPalettesByName.end()) {
        return &paletteIt->second;
    }
    if (state.uiPaletteLoadAttempts[key]) {
        return nullptr;
    }
    state.uiPaletteLoadAttempts[key] = true;

    std::vector<RuntimePaletteColor> palette;
    std::string errorMessage;
    // Only an explicitly configured mod layer may override retail artwork.
    // Default UI resources come from the installed game's MIX archives and
    // their local export tree, never from third-party reference projects.
    if (!trimAsciiLocal(state.config.modRootPath).empty()) {
        const std::filesystem::path modRoot(state.config.modRootPath);
        std::string fileName = resourceKey;
        if (toLowerAsciiLocal(std::filesystem::path(fileName).extension().string())
            != ".pal") {
            fileName += ".pal";
        }
        for (const auto& candidate : {
                modRoot / "pal" / fileName,
                modRoot / "palettes" / fileName,
                modRoot / fileName
            }) {
            if (loadRuntimePaletteFile(pathString(candidate), palette, errorMessage)) {
                return &state.uiPalettesByName.emplace(key, std::move(palette))
                    .first->second;
            }
        }
    }
    if (factionUiResource) {
        std::filesystem::path mixPath = runtimeSidebarMixPath(state);
        std::string mixPaletteId =
            resourceKey == "radar" ? "sidebar" : resourceKey;
        if (sidebarFaction == "yuri" && resourceKey == "uibkgd") {
            mixPath = runtimeYuriSidebarOverrideMixPath(state);
            mixPaletteId = "uibkgdy";
        } else if (sidebarFaction == "yuri" && resourceKey == "radar") {
            mixPath = runtimeYuriSidebarOverrideMixPath(state);
            mixPaletteId = "radaryuri";
        }
        std::string sourcePath;
        if (loadRuntimePaletteFromMixArchive(
                pathString(mixPath),
                state.renderCache,
                mixPaletteId,
                palette,
                sourcePath,
                errorMessage
            )) {
            auto [insertedIt, inserted] =
                state.uiPalettesByName.emplace(key, std::move(palette));
            (void)inserted;
            return &insertedIt->second;
        }
    }

    const std::filesystem::path campaignScoreMix =
        runtimeCampaignScoreResourceMixPath(state, resourceKey);
    if (!campaignScoreMix.empty()) {
        std::string sourcePath;
        if (loadRuntimePaletteFromMixArchive(
                pathString(campaignScoreMix),
                state.renderCache,
                resourceKey,
                palette,
                sourcePath,
                errorMessage
            )) {
            auto [insertedIt, inserted] =
                state.uiPalettesByName.emplace(key, std::move(palette));
            (void)inserted;
            return &insertedIt->second;
        }
    }

    RuntimeMapRenderContext renderContext;
    renderContext.theater = state.theaterLoaded ? &state.theater : nullptr;
    renderContext.art = state.artLoaded ? &state.art : nullptr;
    renderContext.rules = state.rulesLoaded ? &state.rules : nullptr;
    renderContext.mapFacts = state.mapFactsLoaded ? &state.mapFacts : nullptr;
    renderContext.ownerRemapColors =
        state.ownerRemapColors.empty() ? nullptr : &state.ownerRemapColors;
    renderContext.neutralRemapOwners =
        state.neutralRemapOwners.empty() ? nullptr : &state.neutralRemapOwners;
    renderContext.tileRootPath = runtimeTileRootPath(state.config, state.report.map);
    renderContext.palettePath = runtimePalettePath(state.config, state.report.map);
    renderContext.assetRootPath = runtimeAssetRootPath(state.config);
    renderContext.structureRootPath =
        runtimeStructureRootPath(state.config, state.report.map);
    renderContext.structurePalettePath =
        runtimeStructurePalettePath(state.config, state.report.map);
    renderContext.animationTick = state.tick;
    renderContext.fixedTickHz = state.config.fixedTickHz;

    std::string sourcePath;
    if (!loadRuntimePaletteResource(
            renderContext,
            state.renderCache,
            resourceKey,
            palette,
            sourcePath,
            errorMessage
        )) {
        return nullptr;
    }

    auto [insertedIt, inserted] =
        state.uiPalettesByName.emplace(key, std::move(palette));
    (void)inserted;
    return &insertedIt->second;
}

const std::vector<RuntimePaletteColor>* runtimeUiPalette(
    RuntimeWindowState& state, const std::string& paletteId
) {
    auto* batch = RuntimeInteractionUiResourceScope::forState(state);
    if (!batch) return runtimeUiPaletteUnmemoized(state, paletteId);
    const auto found = batch->palettes.find(paletteId);
    if (found != batch->palettes.end()) return found->second;
    const auto* result = runtimeUiPaletteUnmemoized(state, paletteId);
    batch->palettes.emplace(paletteId, result);
    return result;
}

RuntimeUiShpCacheEntry* loadRuntimeUiShpFrameUnmemoized(
    RuntimeWindowState& state,
    const std::string& subdirectory,
    const std::string& imageId,
    int frameIndex
) {
    const bool sidebarResource =
        toLowerAsciiLocal(subdirectory) == "sidebar";
    const std::string sidebarFaction =
        sidebarResource ? runtimeSidebarFactionKey(state) : "";
    const std::string key =
        (sidebarResource ? sidebarFaction + "|" : "")
        + toLowerAsciiLocal(subdirectory)
        + "|"
        + toLowerAsciiLocal(imageId)
        + "|"
        + std::to_string(frameIndex);
    RuntimeUiShpCacheEntry& entry = state.uiShpByKey[key];
    if (entry.loadAttempted) {
        return entry.loaded ? &entry : nullptr;
    }
    entry.loadAttempted = true;

    RuntimeShpFrameImage image;
    std::string errorMessage;
    const auto acceptShp = [&](const std::string& sourcePath) {
        entry.loaded = true;
        entry.pcxFallback = false;
        entry.image = std::move(image);
        entry.embeddedPalette.clear();
        entry.sourcePath = sourcePath;
        return &entry;
    };
    const auto acceptPcx = [
        &entry,
        &image
    ](
        std::vector<RuntimePaletteColor>& palette,
        const std::string& sourcePath
    ) {
        entry.loaded = true;
        entry.pcxFallback = true;
        entry.image = std::move(image);
        entry.embeddedPalette = std::move(palette);
        entry.sourcePath = sourcePath;
        return &entry;
    };

    // A loose mod layer overrides stock archives. Within that layer SHP/SHA is
    // still authoritative and an indexed PCX is its single-frame fallback.
    const std::string authoredShpExtension =
        toLowerAsciiLocal(std::filesystem::path(imageId).extension().string())
                == ".sha"
            ? ".sha"
            : ".shp";
    if (const std::optional<std::filesystem::path> modShp =
            findRuntimeLooseUiResourcePath(
                state,
                subdirectory,
                imageId,
                authoredShpExtension,
                true
            )) {
        if (decodeRuntimeShpFrameFile(
                pathString(*modShp),
                frameIndex,
                image,
                errorMessage
            )) {
            return acceptShp(pathString(*modShp));
        }
        entry.errorMessage = errorMessage;
    }
    {
        if (const std::optional<std::filesystem::path> modPcx =
                findRuntimeLooseUiResourcePath(
                    state,
                    subdirectory,
                    imageId,
                    ".pcx",
                    true
                )) {
            std::vector<RuntimePaletteColor> palette;
            if (decodeRuntimePcxImageFile(
                    pathString(*modPcx),
                    image,
                    palette,
                    errorMessage
                )) {
                return acceptPcx(palette, pathString(*modPcx));
            }
            entry.errorMessage = errorMessage;
        }
    }
    // Yuri adds PersonPurple before the rank/health frames. The RA2
    // conquer.mix PIPS has a rank badge at frame 12 instead. Global MD
    // artwork must override the older RA2 sidebar PIPS, after mods.
    if (toLowerAsciiLocal(imageId) == "pips") {
        std::string sourcePath;
        if (loadRuntimeShpFrameFromMixArchive(
                pathString(std::filesystem::path(runtimeAssetRootPath(state.config)) / "ra2md" / "conqmd.mix"),
                state.renderCache, imageId, frameIndex, image, sourcePath, errorMessage)) {
            return acceptShp(sourcePath);
        }
    }

    // GRFXTXT is localized artwork. The explicit mod layer above wins,
    // followed by the installed language export and then archive lookup.
    if (runtimeUiResourceFileName(imageId, ".shp") == "grfxtxt.shp") {
        if (const auto localized = findRuntimeLooseUiResourcePath(
                state, subdirectory, imageId, ".shp", false
            )) {
            if (decodeRuntimeShpFrameFile(
                    pathString(*localized), frameIndex, image, errorMessage
                )) {
                return acceptShp(pathString(*localized));
            }
        }
    }
    const std::filesystem::path campaignScoreMix =
        runtimeCampaignScoreResourceMixPath(state, imageId);
    if (!campaignScoreMix.empty()) {
        std::string sourcePath;
        if (loadRuntimeShpFrameFromMixArchive(
                pathString(campaignScoreMix),
                state.renderCache,
                imageId,
                frameIndex,
                image,
                sourcePath,
                errorMessage
            )) {
            return acceptShp(sourcePath);
        }
        entry.errorMessage = errorMessage;
    }

    if (sidebarResource) {
        std::string sourcePath;
        const std::string yuriOverrideImageId =
            sidebarFaction == "yuri"
                ? runtimeYuriSidebarOverrideImageId(imageId)
                : "";
        if (!yuriOverrideImageId.empty()
            && loadRuntimeShpFrameFromMixArchive(
                pathString(runtimeYuriSidebarOverrideMixPath(state)),
                state.renderCache,
                yuriOverrideImageId,
                frameIndex,
                image,
                sourcePath,
                errorMessage
            )) {
            return acceptShp(sourcePath);
        }
        if (loadRuntimeShpFrameFromMixArchive(
                pathString(runtimeSidebarMixPath(state)),
                state.renderCache,
                imageId,
                frameIndex,
                image,
                sourcePath,
                errorMessage
            )) {
            return acceptShp(sourcePath);
        }
    }

    RuntimeMapRenderContext renderContext;
    renderContext.theater = state.theaterLoaded ? &state.theater : nullptr;
    renderContext.art = state.artLoaded ? &state.art : nullptr;
    renderContext.rules = state.rulesLoaded ? &state.rules : nullptr;
    renderContext.mapFacts = state.mapFactsLoaded ? &state.mapFacts : nullptr;
    renderContext.ownerRemapColors =
        state.ownerRemapColors.empty() ? nullptr : &state.ownerRemapColors;
    renderContext.neutralRemapOwners =
        state.neutralRemapOwners.empty() ? nullptr : &state.neutralRemapOwners;
    renderContext.tileRootPath = runtimeTileRootPath(state.config, state.report.map);
    renderContext.palettePath = runtimePalettePath(state.config, state.report.map);
    renderContext.assetRootPath = runtimeAssetRootPath(state.config);
    renderContext.structureRootPath =
        runtimeStructureRootPath(state.config, state.report.map);
    renderContext.structurePalettePath =
        runtimeStructurePalettePath(state.config, state.report.map);
    renderContext.animationTick = state.tick;
    renderContext.fixedTickHz = state.config.fixedTickHz;

    std::string resolvedImageId;
    std::string sourcePath;
    std::string mixError;
    int auxiliaryFrameCount = 0;
    if (loadRuntimeAuxiliaryShpFrameImage(
            renderContext,
            state.renderCache,
            imageId,
            frameIndex,
            image,
            resolvedImageId,
            sourcePath,
            mixError,
            false,
            &auxiliaryFrameCount
        )
        && frameIndex >= 0
        && frameIndex < auxiliaryFrameCount) {
        return acceptShp(sourcePath);
    }
    if (auxiliaryFrameCount > 0
        && (frameIndex < 0 || frameIndex >= auxiliaryFrameCount)) {
        mixError = "UI SHP frame is outside the authored range: "
            + std::to_string(frameIndex)
            + "/" + std::to_string(auxiliaryFrameCount);
    }

    {
        std::vector<RuntimePaletteColor> palette;
        if (sidebarResource) {
            std::string pcxSourcePath;
            const std::string yuriOverrideImageId =
                sidebarFaction == "yuri"
                    ? runtimeYuriSidebarOverrideImageId(imageId)
                    : "";
            if (!yuriOverrideImageId.empty()
                && loadRuntimePcxImageFromMixArchive(
                    pathString(runtimeYuriSidebarOverrideMixPath(state)),
                    state.renderCache,
                    yuriOverrideImageId,
                    image,
                    palette,
                    pcxSourcePath,
                    errorMessage
                )) {
                return acceptPcx(palette, pcxSourcePath);
            }
            if (loadRuntimePcxImageFromMixArchive(
                    pathString(runtimeSidebarMixPath(state)),
                    state.renderCache,
                    imageId,
                    image,
                    palette,
                    pcxSourcePath,
                    errorMessage
                )) {
                return acceptPcx(palette, pcxSourcePath);
            }
        }

        if (const std::optional<std::filesystem::path> loosePcx =
                findRuntimeLooseUiResourcePath(
                    state,
                    subdirectory,
                    imageId,
                    ".pcx",
                    false
                )) {
            if (decodeRuntimePcxImageFile(
                    pathString(*loosePcx),
                    image,
                    palette,
                    errorMessage
                )) {
                return acceptPcx(palette, pathString(*loosePcx));
            }
            entry.errorMessage = errorMessage;
        }
    }

    if (entry.errorMessage.empty()) {
        entry.errorMessage = mixError.empty()
            ? "missing ui shp/pcx"
            : mixError;
    }
    return nullptr;
}

RuntimeUiShpCacheEntry* loadRuntimeUiShpFrame(
    RuntimeWindowState& state, const std::string& subdirectory,
    const std::string& imageId, int frameIndex
) {
    auto* batch = RuntimeInteractionUiResourceScope::forState(state);
    if (!batch) return loadRuntimeUiShpFrameUnmemoized(state, subdirectory, imageId, frameIndex);
    RuntimeInteractionUiResourceScope::FrameKey key{subdirectory, imageId, frameIndex};
    const auto found = batch->frames.find(key);
    if (found != batch->frames.end()) return found->second;
    auto* result = loadRuntimeUiShpFrameUnmemoized(state, subdirectory, imageId, frameIndex);
    batch->frames.emplace(std::move(key), result);
    return result;
}

const std::vector<RuntimePaletteColor>* runtimeUiPaletteForEntry(
    RuntimeWindowState& state,
    const RuntimeUiShpCacheEntry* entry,
    const std::string& paletteId
) {
    if (entry == nullptr) {
        return nullptr;
    }
    if (!entry->embeddedPalette.empty()) {
        return &entry->embeddedPalette;
    }
    return runtimeUiPalette(state, paletteId);
}

struct RuntimePixelSurfaceTarget {
    std::uint32_t* pixels = nullptr;
    int width = 0;
    int height = 0;
};

RuntimePixelSurfaceTarget runtimePixelSurfaceTargetForDc(
    RuntimeWindowState& state,
    HDC dc
) {
    if (dc != state.backBuffer.memoryDc
        || state.backBuffer.pixels == nullptr
        || state.backBuffer.width <= 0
        || state.backBuffer.height <= 0) {
        return {};
    }
    return {
        static_cast<std::uint32_t*>(state.backBuffer.pixels),
        state.backBuffer.width,
        state.backBuffer.height
    };
}

constexpr int runtimeIndexedOpaqueAlpha = 256;
constexpr int runtimeTransLucent50Alpha = 128;

unsigned char runtimeBlendIndexedChannel(
    unsigned char source,
    unsigned char target,
    int sourceAlpha
) {
    const int alpha = std::clamp(
        sourceAlpha,
        0,
        runtimeIndexedOpaqueAlpha
    );
    if (alpha == runtimeTransLucent50Alpha) {
        // Retail's TransLucent50 table truncates each channel before adding,
        // equivalent to the classic 0xFEFEFE half-blend operation.
        return static_cast<unsigned char>(
            (static_cast<int>(source) >> 1)
            + (static_cast<int>(target) >> 1)
        );
    }
    return static_cast<unsigned char>(
        (
            static_cast<int>(source) * alpha
            + static_cast<int>(target) * (256 - alpha)
        ) >> 8
    );
}

bool drawRuntimeIndexedImage(
    HDC dc,
    const RECT& rect,
    const RuntimeShpFrameImage& image,
    const std::vector<RuntimePaletteColor>& palette,
    bool enabled,
    bool stretch,
    bool preserveTransparency = false,
    std::uint32_t* targetPixels = nullptr,
    int targetWidth = 0,
    int targetHeight = 0,
    bool dimDisabledColors = false,
    int sourceAlpha = runtimeIndexedOpaqueAlpha,
    bool paletteZeroIsColor = false,
    bool useMagentaChroma = false
) {
    if (image.width <= 0
        || image.height <= 0
        || palette.empty()
        || rect.right <= rect.left
        || rect.bottom <= rect.top) {
        return false;
    }

    sourceAlpha = std::clamp(
        sourceAlpha,
        0,
        runtimeIndexedOpaqueAlpha
    );
    const auto displayColor = [&](RuntimePaletteColor color) {
        if (enabled) {
            return color;
        }
        if (dimDisabledColors) {
            return RuntimePaletteColor{
                static_cast<unsigned char>(color.r / 2),
                static_cast<unsigned char>(color.g / 2),
                static_cast<unsigned char>(color.b / 2)
            };
        }
        const unsigned char gray = static_cast<unsigned char>(
            (static_cast<int>(color.r)
                + static_cast<int>(color.g)
                + static_cast<int>(color.b))
            / 3
        );
        return RuntimePaletteColor{gray, gray, gray};
    };
    const auto isMagentaChroma = [&](unsigned char paletteIndex) {
        if (static_cast<std::size_t>(paletteIndex) >= palette.size()) {
            return false;
        }
        const RuntimePaletteColor& color = palette[paletteIndex];
        return color.r >= 240 && color.b >= 240 && color.g <= 32;
    };

    const int availableWidth =
        std::max(1, static_cast<int>(rect.right - rect.left));
    const int availableHeight =
        std::max(1, static_cast<int>(rect.bottom - rect.top));
    int drawWidth = availableWidth;
    int drawHeight = availableHeight;
    int startX = rect.left;
    int startY = rect.top;
    if (!stretch) {
        const double scale = std::min(
            static_cast<double>(availableWidth) / static_cast<double>(image.width),
            static_cast<double>(availableHeight) / static_cast<double>(image.height)
        );
        drawWidth = std::max(
            1,
            static_cast<int>(std::floor(image.width * std::min(1.0, scale)))
        );
        drawHeight = std::max(
            1,
            static_cast<int>(std::floor(image.height * std::min(1.0, scale)))
        );
        startX = rect.left + ((availableWidth - drawWidth) / 2);
        startY = rect.top + ((availableHeight - drawHeight) / 2);
    }

    if (targetPixels != nullptr && targetWidth > 0 && targetHeight > 0) {
        for (int y = 0; y < drawHeight; ++y) {
            const int destinationY = startY + y;
            if (destinationY < 0 || destinationY >= targetHeight) {
                continue;
            }
            const int sourceY = std::clamp(
                (y * image.height) / drawHeight,
                0,
                image.height - 1
            );
            for (int x = 0; x < drawWidth; ++x) {
                const int destinationX = startX + x;
                if (destinationX < 0 || destinationX >= targetWidth) {
                    continue;
                }
                const int sourceX = std::clamp(
                    (x * image.width) / drawWidth,
                    0,
                    image.width - 1
                );
                const std::size_t sourceIndex =
                    (static_cast<std::size_t>(sourceY)
                        * static_cast<std::size_t>(image.width))
                    + static_cast<std::size_t>(sourceX);
                if (sourceIndex >= image.pixels.size()) {
                    continue;
                }

                const unsigned char paletteIndex = image.pixels[sourceIndex];
                if (preserveTransparency
                    && (paletteIndex == 0
                        || (useMagentaChroma
                            && isMagentaChroma(paletteIndex)))) {
                    continue;
                }

                RuntimePaletteColor color{0, 0, 0};
                if ((paletteIndex != 0 || paletteZeroIsColor)
                    && static_cast<std::size_t>(paletteIndex) < palette.size()) {
                    color = displayColor(palette[paletteIndex]);
                }
                const std::size_t destinationIndex =
                    (static_cast<std::size_t>(destinationY)
                        * static_cast<std::size_t>(targetWidth))
                    + static_cast<std::size_t>(destinationX);
                if (sourceAlpha < runtimeIndexedOpaqueAlpha) {
                    const std::uint32_t destination =
                        targetPixels[destinationIndex];
                    color = {
                        runtimeBlendIndexedChannel(
                            color.r,
                            static_cast<unsigned char>((destination >> 16) & 0xFFU),
                            sourceAlpha
                        ),
                        runtimeBlendIndexedChannel(
                            color.g,
                            static_cast<unsigned char>(
                                (destination >> 8) & 0xFFU
                            ),
                            sourceAlpha
                        ),
                        runtimeBlendIndexedChannel(
                            color.b,
                            static_cast<unsigned char>(destination & 0xFFU),
                            sourceAlpha
                        )
                    };
                }
                targetPixels[destinationIndex] =
                    static_cast<std::uint32_t>(color.b)
                    | (static_cast<std::uint32_t>(color.g) << 8)
                    | (static_cast<std::uint32_t>(color.r) << 16);
            }
        }
        return true;
    }

    if (!preserveTransparency
        && sourceAlpha >= runtimeIndexedOpaqueAlpha) {
        static thread_local std::vector<std::uint32_t> rgbaPixels;
        const std::size_t outputPixelCount =
            static_cast<std::size_t>(drawWidth)
            * static_cast<std::size_t>(drawHeight);
        if (rgbaPixels.size() < outputPixelCount) {
            rgbaPixels.resize(outputPixelCount);
        }
        for (int y = 0; y < drawHeight; ++y) {
            const int sourceY = std::clamp(
                (y * image.height) / drawHeight,
                0,
                image.height - 1
            );
            for (int x = 0; x < drawWidth; ++x) {
                const int sourceX = std::clamp(
                    (x * image.width) / drawWidth,
                    0,
                    image.width - 1
                );
                const std::size_t pixelIndex =
                    (static_cast<std::size_t>(sourceY)
                        * static_cast<std::size_t>(image.width))
                    + static_cast<std::size_t>(sourceX);
                if (pixelIndex >= image.pixels.size()) {
                    continue;
                }
                const std::size_t outputIndex =
                    (static_cast<std::size_t>(y)
                        * static_cast<std::size_t>(drawWidth))
                    + static_cast<std::size_t>(x);
                const unsigned char paletteIndex = image.pixels[pixelIndex];
                RuntimePaletteColor color{0, 0, 0};
                if ((paletteIndex != 0 || paletteZeroIsColor)
                    && static_cast<std::size_t>(paletteIndex) < palette.size()) {
                    color = displayColor(palette[paletteIndex]);
                }
                rgbaPixels[outputIndex] =
                    (static_cast<std::uint32_t>(color.b))
                    | (static_cast<std::uint32_t>(color.g) << 8)
                    | (static_cast<std::uint32_t>(color.r) << 16);
            }
        }

        BITMAPINFO bitmapInfo{};
        bitmapInfo.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
        bitmapInfo.bmiHeader.biWidth = drawWidth;
        bitmapInfo.bmiHeader.biHeight = -drawHeight;
        bitmapInfo.bmiHeader.biPlanes = 1;
        bitmapInfo.bmiHeader.biBitCount = 32;
        bitmapInfo.bmiHeader.biCompression = BI_RGB;
        SetDIBitsToDevice(
            dc,
            startX,
            startY,
            drawWidth,
            drawHeight,
            0,
            0,
            0,
            drawHeight,
            rgbaPixels.data(),
            &bitmapInfo,
            DIB_RGB_COLORS
        );
        return true;
    }

    for (int y = 0; y < drawHeight; ++y) {
        const int sourceY = std::clamp(
            (y * image.height) / drawHeight,
            0,
            image.height - 1
        );
        for (int x = 0; x < drawWidth; ++x) {
            const int sourceX = std::clamp(
                (x * image.width) / drawWidth,
                0,
                image.width - 1
            );
            const std::size_t pixelIndex =
                (static_cast<std::size_t>(sourceY)
                    * static_cast<std::size_t>(image.width))
                + static_cast<std::size_t>(sourceX);
            if (pixelIndex >= image.pixels.size()) {
                continue;
            }
            const unsigned char paletteIndex = image.pixels[pixelIndex];
            if ((preserveTransparency && paletteIndex == 0)
                || (preserveTransparency && useMagentaChroma
                    && isMagentaChroma(paletteIndex))
                || static_cast<std::size_t>(paletteIndex) >= palette.size()) {
                continue;
            }
            RuntimePaletteColor color{0, 0, 0};
            if (paletteIndex != 0 || paletteZeroIsColor) {
                color = displayColor(palette[paletteIndex]);
            }
            if (sourceAlpha < runtimeIndexedOpaqueAlpha) {
                const COLORREF destination = concord::ui::win32::MapNativeOverlayWin32::readPixel(
                    dc,
                    startX + x,
                    startY + y
                );
                if (destination != CLR_INVALID) {
                    color = {
                        runtimeBlendIndexedChannel(
                            color.r,
                            GetRValue(destination),
                            sourceAlpha
                        ),
                        runtimeBlendIndexedChannel(
                            color.g,
                            GetGValue(destination),
                            sourceAlpha
                        ),
                        runtimeBlendIndexedChannel(
                            color.b,
                            GetBValue(destination),
                            sourceAlpha
                        )
                    };
                }
            }
            SetPixelV(
                dc,
                startX + x,
                startY + y,
                RGB(color.r, color.g, color.b)
            );
        }
    }
    return true;
}

bool drawRuntimeUiShpFrame(
    HDC dc,
    RuntimeWindowState& state,
    const std::string& subdirectory,
    const std::string& imageId,
    int frameIndex,
    const std::string& paletteId,
    const RECT& rect,
    bool enabled,
    bool stretch
) {
    RuntimeUiShpCacheEntry* image =
        loadRuntimeUiShpFrame(state, subdirectory, imageId, frameIndex);
    const std::vector<RuntimePaletteColor>* palette =
        runtimeUiPaletteForEntry(state, image, paletteId);
    if (image == nullptr || palette == nullptr) {
        return false;
    }

    const RuntimePixelSurfaceTarget target =
        runtimePixelSurfaceTargetForDc(state, dc);
    return drawRuntimeIndexedImage(
        dc,
        rect,
        image->image,
        *palette,
        enabled,
        stretch,
        false,
        target.pixels,
        target.width,
        target.height,
        false,
        runtimeIndexedOpaqueAlpha,
        image->pcxFallback,
        image->pcxFallback
    );
}

bool drawRuntimeUiShpFrameTransparent(
    HDC dc,
    RuntimeWindowState& state,
    const std::string& subdirectory,
    const std::string& imageId,
    int frameIndex,
    const std::string& paletteId,
    const RECT& rect,
    bool enabled,
    bool stretch
) {
    RuntimeUiShpCacheEntry* image =
        loadRuntimeUiShpFrame(state, subdirectory, imageId, frameIndex);
    const std::vector<RuntimePaletteColor>* palette =
        runtimeUiPaletteForEntry(state, image, paletteId);
    if (image == nullptr || palette == nullptr) {
        return false;
    }
    const RuntimePixelSurfaceTarget target =
        runtimePixelSurfaceTargetForDc(state, dc);
    return drawRuntimeIndexedImage(
        dc,
        rect,
        image->image,
        *palette,
        enabled,
        stretch,
        true,
        target.pixels,
        target.width,
        target.height,
        false,
        runtimeIndexedOpaqueAlpha,
        image->pcxFallback,
        image->pcxFallback
    );
}

RECT runtimeUiShpCanvasFrameRect(
    const RECT& canvasRect,
    const RuntimeShpFrameImage& image
) {
    const int canvasWidth = std::max(
        1,
        static_cast<int>(canvasRect.right - canvasRect.left)
    );
    const int canvasHeight = std::max(
        1,
        static_cast<int>(canvasRect.bottom - canvasRect.top)
    );
    const int globalWidth = image.globalWidth > 0
        ? image.globalWidth
        : image.width;
    const int globalHeight = image.globalHeight > 0
        ? image.globalHeight
        : image.height;
    if (globalWidth <= 0
        || globalHeight <= 0
        || image.width <= 0
        || image.height <= 0) {
        return {0, 0, 0, 0};
    }
    return {
        canvasRect.left + MulDiv(image.offsetX, canvasWidth, globalWidth),
        canvasRect.top + MulDiv(image.offsetY, canvasHeight, globalHeight),
        canvasRect.left + MulDiv(
            image.offsetX + image.width,
            canvasWidth,
            globalWidth
        ),
        canvasRect.top + MulDiv(
            image.offsetY + image.height,
            canvasHeight,
            globalHeight
        )
    };
}

bool drawRuntimeUiShpFrameCanvasTransparent(
    HDC dc,
    RuntimeWindowState& state,
    const std::string& subdirectory,
    const std::string& imageId,
    int frameIndex,
    const std::string& paletteId,
    const RECT& canvasRect,
    bool enabled,
    int sourceAlpha = runtimeIndexedOpaqueAlpha
) {
    RuntimeUiShpCacheEntry* image =
        loadRuntimeUiShpFrame(state, subdirectory, imageId, frameIndex);
    const std::vector<RuntimePaletteColor>* palette =
        runtimeUiPaletteForEntry(state, image, paletteId);
    if (image == nullptr || palette == nullptr) {
        return false;
    }
    const RECT frameRect = runtimeUiShpCanvasFrameRect(
        canvasRect,
        image->image
    );
    if (frameRect.right <= frameRect.left
        || frameRect.bottom <= frameRect.top) {
        return false;
    }
    const RuntimePixelSurfaceTarget target =
        runtimePixelSurfaceTargetForDc(state, dc);
    return drawRuntimeIndexedImage(
        dc,
        frameRect,
        image->image,
        *palette,
        enabled,
        true,
        true,
        target.pixels,
        target.width,
        target.height,
        false,
        sourceAlpha,
        image->pcxFallback,
        image->pcxFallback
    );
}

bool drawRuntimeUiShpFrameNativeAt(
    HDC dc,
    RuntimeWindowState& state,
    const std::string& subdirectory,
    const std::string& imageId,
    int frameIndex,
    const std::string& paletteId,
    int left,
    int top,
    bool enabled
) {
    RuntimeUiShpCacheEntry* image =
        loadRuntimeUiShpFrame(state, subdirectory, imageId, frameIndex);
    const std::vector<RuntimePaletteColor>* palette =
        runtimeUiPaletteForEntry(state, image, paletteId);
    if (image == nullptr
        || palette == nullptr
        || image->image.width <= 0
        || image->image.height <= 0) {
        return false;
    }

    const RECT rect{
        left,
        top,
        left + image->image.width,
        top + image->image.height
    };
    const RuntimePixelSurfaceTarget target =
        runtimePixelSurfaceTargetForDc(state, dc);
    return drawRuntimeIndexedImage(
        dc,
        rect,
        image->image,
        *palette,
        enabled,
        false,
        true,
        target.pixels,
        target.width,
        target.height,
        false,
        runtimeIndexedOpaqueAlpha,
        image->pcxFallback,
        image->pcxFallback
    );
}


bool runtimeObjectShouldDrawHealthBar(
    const RuntimeWindowState& state,
    const WorldObjectInstance& object
) {
    return object.alive && !runtimeObjectIgnoresDamage(state, object);
}


bool runtimeUiShpFrameAvailable(
    RuntimeWindowState& state,
    const std::string& subdirectory,
    const std::string& imageId,
    int frameIndex,
    const std::string& paletteId
) {
    RuntimeUiShpCacheEntry* entry =
        loadRuntimeUiShpFrame(state, subdirectory, imageId, frameIndex);
    return entry != nullptr
        && runtimeUiPaletteForEntry(state, entry, paletteId) != nullptr;
}

int runtimeUiShpFrameCount(
    RuntimeWindowState& state,
    const std::string& subdirectory,
    const std::string& imageId,
    const std::string& paletteId,
    int maxProbeFrame = 96
) {
    const bool sidebarResource =
        toLowerAsciiLocal(subdirectory) == "sidebar";
    const std::string cacheKey =
        (sidebarResource ? runtimeSidebarFactionKey(state) + "|" : "")
        + subdirectory
        + "|"
        + toLowerAsciiLocal(imageId)
        + "|"
        + toLowerAsciiLocal(paletteId)
        + "|"
        + std::to_string(maxProbeFrame);
    const auto cached = state.uiShpFrameCountByKey.find(cacheKey);
    if (cached != state.uiShpFrameCountByKey.end()) {
        return cached->second;
    }

    int count = 0;
    bool sawFrame = false;
    for (int frame = 0; frame < maxProbeFrame; ++frame) {
        RuntimeUiShpCacheEntry* entry =
            loadRuntimeUiShpFrame(state, subdirectory, imageId, frame);
        if (entry == nullptr
            || runtimeUiPaletteForEntry(state, entry, paletteId) == nullptr) {
            if (!sawFrame) {
                continue;
            }
            break;
        }
        if (entry->pcxFallback) {
            // A PCX is a static one-frame substitute even when the caller
            // asked for an animated SHP frame. Do not manufacture a 96-frame
            // count by returning that same image for every probe index. If
            // real SHP frames were already found, the later PCX must not
            // collapse their authored frame count back to one.
            if (!sawFrame) {
                count = 1;
            }
            break;
        }
        sawFrame = true;
        count = frame + 1;
    }
    state.uiShpFrameCountByKey.emplace(cacheKey, count);
    return count;
}

RuntimeCameoIconCacheEntry* loadRuntimeCameoIcon(
    RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item
);
bool ensureRuntimeCameoPalette(RuntimeWindowState& state);

RuntimeUiResourceRenderSummary buildRuntimeUiResourceRenderSummary(
    RuntimeWindowState& state
) {
    RuntimeUiResourceRenderSummary summary;
    const bool sidebarPalette = runtimeUiPalette(state, "sidebar") != nullptr;
    const bool gamePalette = runtimeUiPalette(state, "palette") != nullptr;
    const bool cameoPalette = ensureRuntimeCameoPalette(state);
    summary.paletteCandidates = 3;
    summary.palettesDecoded =
        (sidebarPalette ? 1 : 0)
        + (gamePalette ? 1 : 0)
        + (cameoPalette ? 1 : 0);
    summary.palettesUnsupported =
        summary.paletteCandidates - summary.palettesDecoded;

    const struct {
        const char* subdirectory;
        const char* imageId;
        int frameIndex;
        const char* category;
        const char* paletteId;
    } resources[] = {
        {"sidebar", "credits", 0, "sidebar", "sidebar"},
        {"sidebar", "top", 0, "sidebar", "sidebar"},
        {"sidebar", "side1", 0, "sidebar", "sidebar"},
        {"sidebar", "side2", 0, "sidebar", "sidebar"},
        {"sidebar", "side3", 0, "sidebar", "sidebar"},
        {"sidebar", "addon", 0, "sidebar", "sidebar"},
        {"sidebar", "diplobtn", 0, "sidebar", "sidebar"},
        {"sidebar", "optbtn", 0, "sidebar", "sidebar"},
        {"sidebar", "repair", 0, "sidebar", "sidebar"},
        {"sidebar", "sell", 0, "sidebar", "sidebar"},
        {"sidebar", "tab00", 1, "sidebar", "sidebar"},
        {"sidebar", "tab01", 1, "sidebar", "sidebar"},
        {"sidebar", "tab02", 1, "sidebar", "sidebar"},
        {"sidebar", "tab03", 1, "sidebar", "sidebar"},
        {"sidebar", "r-dn", 0, "sidebar", "sidebar"},
        {"sidebar", "r-up", 0, "sidebar", "sidebar"},
        {"sidebar", "gclock2", 1, "sidebar", "sidebar"},
        {"sidebar", "powerp", 1, "power", "sidebar"},
        {"sidebar", "radar", 0, "radar", "radar"},
        {"sidebar", "pips", 0, "pips", "palette"},
        {"sidebar", "pips2", 0, "pips", "palette"},
        {"sidebar", "pipbrd", 0, "pips", "palette"}
    };

    for (const auto& resource : resources) {
        ++summary.resourceCandidates;
        const bool decoded =
            runtimeUiShpFrameAvailable(
                state,
                resource.subdirectory,
                resource.imageId,
                resource.frameIndex,
                resource.paletteId
            );
        if (decoded) {
            ++summary.resourcesDecoded;
        } else {
            ++summary.resourcesMissing;
        }

        const std::string category = resource.category;
        if (category == "sidebar") {
            ++summary.sidebarCandidates;
        } else if (category == "radar") {
            ++summary.radarCandidates;
        } else if (category == "pips") {
            ++summary.pipCandidates;
        } else if (category == "power") {
            ++summary.powerCandidates;
        }
    }

    int cameoCandidates = 0;
    int cameoDecoded = 0;
    for (const RuntimeBuildCatalogItem& item : state.economy.catalog) {
        ++cameoCandidates;
        ++summary.resourceCandidates;
        if (loadRuntimeCameoIcon(state, item) != nullptr) {
            ++cameoDecoded;
            ++summary.resourcesDecoded;
        } else {
            ++summary.resourcesMissing;
        }
    }
    summary.cameoCandidates = cameoCandidates;
    return summary;
}

struct RuntimeSidebarPowerSegmentCounts {
    int used = 0;
    int yellow = 0;
    int green = 0;
};

RuntimeSidebarPowerSegmentCounts runtimeSidebarPowerSegmentCounts(
    const RuntimeSidebarPowerDisplay& display,
    int maxSegments
) {
    maxSegments = std::max(1, maxSegments);
    // Keep ten units per segment for small grids, then scale both values
    // together. Independent clipping hid every surplus segment on large
    // bases and made adding an ordinary consumer look like a blackout.
    const long long scale = std::max(10LL * maxSegments,
        static_cast<long long>(std::max(display.produced, display.used)));
    const int producedSegments = static_cast<int>(std::clamp(
        static_cast<long long>(display.produced) * maxSegments / scale, 0LL, static_cast<long long>(maxSegments)));
    const int usedSegments = static_cast<int>(std::clamp(
        static_cast<long long>(display.used) * maxSegments / scale, 0LL, static_cast<long long>(maxSegments)));
    const int surplusSegments = std::max(0, producedSegments - usedSegments);
    const int yellowSegments = std::min(3, surplusSegments);
    return {
        usedSegments,
        yellowSegments,
        std::max(0, surplusSegments - yellowSegments)
    };
}

bool drawRuntimePowerSegments(
    HDC dc,
    RuntimeWindowState& state,
    const RECT& powerTrack,
    const RuntimeSidebarPowerDisplay& display
) {
    if (!runtimeUiShpFrameAvailable(state, "sidebar", "powerp", 1, "sidebar")) {
        return false;
    }

    const int segmentStep = 3;
    const int maxSegments =
        std::max(1, static_cast<int>(powerTrack.bottom - powerTrack.top - 4)
            / segmentStep);
    const RuntimeSidebarPowerSegmentCounts counts =
        runtimeSidebarPowerSegmentCounts(display, maxSegments);

    struct RuntimePowerSegmentRun {
        int count = 0;
        int frameIndex = 0;
    };
    const RuntimePowerSegmentRun runs[] = {
        {counts.used, 3},
        {counts.yellow, 2},
        {counts.green, 1}
    };

    int segmentIndex = 0;
    for (const RuntimePowerSegmentRun& run : runs) {
        for (int index = 0;
            index < run.count && segmentIndex < maxSegments;
            ++index, ++segmentIndex) {
            const int y = powerTrack.bottom - 3 - (segmentIndex * segmentStep);
            const RECT segmentRect{
                powerTrack.left,
                y,
                powerTrack.left + 12,
                y + 2
            };
            drawRuntimeUiShpFrame(
                dc,
                state,
                "sidebar",
                "powerp",
                run.frameIndex,
                "sidebar",
                segmentRect,
                true,
                false
            );
        }
    }
    for (; segmentIndex < maxSegments; ++segmentIndex) {
        const int y = powerTrack.bottom - 3 - (segmentIndex * segmentStep);
        const RECT segmentRect{
            powerTrack.left,
            y,
            powerTrack.left + 12,
            y + 2
        };
        drawRuntimeUiShpFrame(
            dc,
            state,
            "sidebar",
            "powerp",
            0,
            "sidebar",
            segmentRect,
            true,
            false
        );
    }

    return true;
}

struct RuntimeSidebarLowPowerIndicatorRects {
    RECT border{0, 0, 0, 0};
    RECT fill{0, 0, 0, 0};
};

RuntimeSidebarLowPowerIndicatorRects runtimeSidebarLowPowerIndicatorRects(
    const RECT& iconRect
) {
    RuntimeSidebarLowPowerIndicatorRects rects;
    rects.border = {
        iconRect.left + 3,
        std::max<LONG>(iconRect.top, iconRect.bottom - 8),
        iconRect.right - 3,
        iconRect.bottom - 3
    };
    if (rects.border.right <= rects.border.left
        || rects.border.bottom <= rects.border.top) {
        rects.border = RECT{0, 0, 0, 0};
        return rects;
    }
    rects.fill = {
        rects.border.left + 1,
        rects.border.top + 1,
        rects.border.right - 1,
        rects.border.bottom - 1
    };
    return rects;
}

bool drawRuntimeSidebarLowPowerIndicator(HDC dc, const RECT& iconRect) {
    if (dc == nullptr) {
        return false;
    }
    const RuntimeSidebarLowPowerIndicatorRects rects =
        runtimeSidebarLowPowerIndicatorRects(iconRect);
    if (rects.border.right <= rects.border.left
        || rects.border.bottom <= rects.border.top
        || rects.fill.right <= rects.fill.left
        || rects.fill.bottom <= rects.fill.top) {
        return false;
    }

    HBRUSH borderBrush = CreateSolidBrush(RGB(72, 8, 8));
    HBRUSH fillBrush = CreateSolidBrush(RGB(228, 48, 40));
    if (borderBrush == nullptr || fillBrush == nullptr) {
        if (borderBrush != nullptr) {
            DeleteObject(borderBrush);
        }
        if (fillBrush != nullptr) {
            DeleteObject(fillBrush);
        }
        return false;
    }
    const bool borderDrawn = FillRect(dc, &rects.border, borderBrush) != 0;
    const bool fillDrawn = FillRect(dc, &rects.fill, fillBrush) != 0;
    DeleteObject(borderBrush);
    DeleteObject(fillBrush);
    return borderDrawn && fillDrawn;
}

bool ensureRuntimeCameoPalette(RuntimeWindowState& state) {
    if (state.cameoPaletteLoadAttempted) {
        return state.cameoPaletteLoaded;
    }
    state.cameoPaletteLoadAttempted = true;

    if (const std::vector<RuntimePaletteColor>* palette =
            runtimeUiPalette(state, "cameo")) {
        state.cameoPalette = *palette;
        state.cameoPalettePath = "cameo.pal";
        state.cameoPaletteLoaded = true;
        return true;
    }

    const std::string assetRootPath = runtimeAssetRootPath(state.config);
    if (assetRootPath.empty()) {
        return false;
    }

    const std::filesystem::path assetRoot(assetRootPath);
    const std::filesystem::path candidates[] = {
        assetRoot / "language" / "cameo.pal",
        assetRoot / "langmd" / "cameo.pal",
        assetRoot / "ra2md" / "localmd" / "dialogn.pal",
        assetRoot / "ra2md" / "localmd" / "dialogy.pal",
        assetRoot / "expandmd01" / "dialogn.pal",
        assetRoot / "expandmd01" / "mpyscrn.pal",
        assetRoot / "langmd" / "glsmd.pal",
        assetRoot / "ra2md" / "localmd" / "mpyscrn.pal"
    };

    std::string errorMessage;
    for (const std::filesystem::path& candidate : candidates) {
        std::error_code errorCode;
        if (!std::filesystem::exists(candidate, errorCode)
            || !std::filesystem::is_regular_file(candidate, errorCode)) {
            continue;
        }
        state.cameoPalettePath = pathString(candidate);
        state.cameoPaletteLoaded =
            loadRuntimePaletteFile(
                state.cameoPalettePath,
                state.cameoPalette,
                errorMessage
            );
        if (state.cameoPaletteLoaded) {
            return true;
        }
    }

    if (state.renderCache.structurePaletteLoaded) {
        state.cameoPalette = state.renderCache.structurePalette;
        state.cameoPaletteLoaded = true;
    }
    return state.cameoPaletteLoaded;
}

RuntimeCameoIconCacheEntry* loadRuntimeCameoIcon(
    RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item
) {
    const std::string itemLookupKey =
        std::to_string(static_cast<int>(item.kind))
        + "|"
        + toLowerAsciiLocal(item.typeId);
    const auto cachedKey = state.cameoCacheKeyByItem.find(itemLookupKey);
    if (cachedKey != state.cameoCacheKeyByItem.end()) {
        const auto cachedEntry = state.cameoIconsByKey.find(cachedKey->second);
        if (cachedEntry != state.cameoIconsByKey.end()
            && cachedEntry->second.loadAttempted) {
            return cachedEntry->second.loaded ? &cachedEntry->second : nullptr;
        }
    }

    const std::vector<std::string> candidates =
        runtimeCameoCandidateIds(state, item);
    std::string cacheKey = item.typeId + "|" + runtimeAssetRootPath(state.config);
    for (const std::string& candidate : candidates) {
        cacheKey += "|" + toLowerAsciiLocal(candidate);
    }
    state.cameoCacheKeyByItem[itemLookupKey] = cacheKey;

    auto [it, inserted] = state.cameoIconsByKey.try_emplace(cacheKey);
    RuntimeCameoIconCacheEntry& entry = it->second;
    if (entry.loadAttempted) {
        return entry.loaded ? &entry : nullptr;
    }
    entry.loadAttempted = true;

    if (!ensureRuntimeCameoPalette(state)) {
        entry.errorMessage = "missing cameo palette";
        return nullptr;
    }

    RuntimeMapRenderContext renderContext;
    renderContext.theater = state.theaterLoaded ? &state.theater : nullptr;
    renderContext.art = state.artLoaded ? &state.art : nullptr;
    renderContext.rules = state.rulesLoaded ? &state.rules : nullptr;
    renderContext.mapFacts = state.mapFactsLoaded ? &state.mapFacts : nullptr;
    renderContext.ownerRemapColors =
        state.ownerRemapColors.empty() ? nullptr : &state.ownerRemapColors;
    renderContext.neutralRemapOwners =
        state.neutralRemapOwners.empty() ? nullptr : &state.neutralRemapOwners;
    renderContext.tileRootPath = runtimeTileRootPath(state.config, state.report.map);
    renderContext.palettePath = runtimePalettePath(state.config, state.report.map);
    renderContext.assetRootPath = runtimeAssetRootPath(state.config);
    renderContext.structureRootPath =
        runtimeStructureRootPath(state.config, state.report.map);
    renderContext.structurePalettePath =
        runtimeStructurePalettePath(state.config, state.report.map);
    renderContext.animationTick = state.tick;
    renderContext.fixedTickHz = state.config.fixedTickHz;

    for (const std::string& cameoId : candidates) {
        RuntimeShpFrameImage image;
        std::string resolvedImageId;
        std::string sourcePath;
        std::string errorMessage;
        if (loadRuntimeAuxiliaryShpFrameImage(
                renderContext,
                state.renderCache,
                cameoId,
                0,
                image,
                resolvedImageId,
                sourcePath,
                errorMessage
            )) {
            entry.loaded = true;
            entry.image = std::move(image);
            entry.cameoId = !resolvedImageId.empty() ? resolvedImageId : cameoId;
            entry.sourcePath = sourcePath;
            return &entry;
        }
        entry.errorMessage = errorMessage;

        const std::optional<std::string> path =
            findRuntimeCameoPath(state, cameoId);
        if (!path.has_value()) {
            continue;
        }

        if (decodeRuntimeShpFrameFile(*path, 0, image, errorMessage)) {
            entry.loaded = true;
            entry.image = std::move(image);
            entry.cameoId = cameoId;
            entry.sourcePath = *path;
            return &entry;
        }
        entry.errorMessage = errorMessage;
    }

    entry.errorMessage = "missing cameo";
    return nullptr;
}

