std::vector<int> runtimeVisibleBuildCatalogIndices(
    const RuntimeWindowState& state,
    const RECT& sidebar
) {
    const std::vector<int> filtered = runtimeFilteredBuildCatalogIndices(state);
    const int perPage = runtimeBuildButtonsPerPage(sidebar);
    const int page = std::min(
        runtimeActiveBuildPage(state),
        runtimeBuildPageCount(state, sidebar) - 1
    );
    const int begin = std::min(static_cast<int>(filtered.size()), page * perPage);
    const int end = std::min(static_cast<int>(filtered.size()), begin + perPage);
    return std::vector<int>(filtered.begin() + begin, filtered.begin() + end);
}

std::vector<const SuperWeaponSidebarSnapshot*>
runtimeVisibleSuperWeaponsOnBuildPage(
    const RuntimeWindowState& state,
    const RECT& sidebar
) {
    if (state.activeBuildTab != RuntimeBuildKind::Defense) {
        return {};
    }

    const std::vector<const SuperWeaponSidebarSnapshot*> superWeapons =
        runtimeVisibleSuperWeapons(state);
    if (superWeapons.empty()) {
        return {};
    }

    const int buildCount = static_cast<int>(
        runtimeFilteredBuildCatalogIndices(state).size()
    );
    const int perPage = runtimeBuildButtonsPerPage(sidebar);
    const int page = std::min(
        runtimeActiveBuildPage(state),
        runtimeBuildPageCount(state, sidebar) - 1
    );
    const int pageStart = page * perPage;
    const int buildSlotsOnPage = std::clamp(
        buildCount - pageStart,
        0,
        perPage
    );
    const int superWeaponBegin = std::clamp(
        pageStart - buildCount,
        0,
        static_cast<int>(superWeapons.size())
    );
    const int superWeaponEnd = std::min(
        static_cast<int>(superWeapons.size()),
        superWeaponBegin + perPage - buildSlotsOnPage
    );
    return std::vector<const SuperWeaponSidebarSnapshot*>(
        superWeapons.begin() + superWeaponBegin,
        superWeapons.begin() + superWeaponEnd
    );
}

RECT runtimeBuildButtonRect(const RECT& sidebar, int index) {
    constexpr int columns = 2;
    constexpr int buttonWidth = 60;
    constexpr int buttonHeight = 48;
    constexpr int rowHeight = 50;
    const int row = index / columns;
    const int column = index % columns;
    const int left = sidebar.left + (column == 0 ? 22 : 85);
    const int top =
        sidebar.top + runtimeSidebarListOffset + 1 + (row * rowHeight);
    return {
        left,
        top,
        left + buttonWidth,
        top + buttonHeight
    };
}

const SuperWeaponSidebarSnapshot* runtimeSuperWeaponAtPoint(
    const RuntimeWindowState& state,
    const RECT& sidebar,
    POINT point
) {
    if (!pointInRectInclusive(sidebar, point)
        || state.activeBuildTab != RuntimeBuildKind::Defense) {
        return nullptr;
    }

    const int firstSuperWeaponSlot = static_cast<int>(
        runtimeVisibleBuildCatalogIndices(state, sidebar).size()
    );
    const std::vector<const SuperWeaponSidebarSnapshot*> superWeapons =
        runtimeVisibleSuperWeaponsOnBuildPage(state, sidebar);
    for (int index = 0; index < static_cast<int>(superWeapons.size()); ++index) {
        const RECT rect = runtimeBuildButtonRect(
            sidebar,
            firstSuperWeaponSlot + index
        );
        if (PtInRect(&rect, point)) {
            return superWeapons[static_cast<std::size_t>(index)];
        }
    }
    return nullptr;
}

RECT runtimeBuildPageButtonRect(const RECT& sidebar, bool next) {
    const int width = 46;
    const int height = 25;
    const int top = runtimeSidebarSide3Top(sidebar) + 7;
    const int left = sidebar.left + (next ? 38 : 84);
    return {left, top, left + width, top + height};
}

int runtimeBuildPageButtonAtPoint(
    const RuntimeWindowState& state,
    const RECT& sidebar,
    POINT point
) {
    const int pageCount = runtimeBuildPageCount(state, sidebar);
    if (pageCount <= 1) {
        return 0;
    }
    const int page = runtimeActiveBuildPage(state);
    const RECT pageUpRect = runtimeBuildPageButtonRect(sidebar, false);
    const RECT pageDownRect = runtimeBuildPageButtonRect(sidebar, true);
    if (page > 0 && PtInRect(&pageUpRect, point)) {
        return -1;
    }
    if (page + 1 < pageCount && PtInRect(&pageDownRect, point)) {
        return 1;
    }
    return 0;
}

std::optional<int> runtimeBuildButtonAtPoint(
    const RuntimeWindowState& state,
    const RECT& sidebar,
    POINT point
) {
    if (!pointInRectInclusive(sidebar, point)) {
        return std::nullopt;
    }

    const std::vector<int> visibleIndices =
        runtimeVisibleBuildCatalogIndices(state, sidebar);
    for (int visibleIndex = 0;
        visibleIndex < static_cast<int>(visibleIndices.size());
        ++visibleIndex) {
        const RECT rect = runtimeBuildButtonRect(sidebar, visibleIndex);
        if (PtInRect(&rect, point)) {
            return visibleIndices[visibleIndex];
        }
    }

    return std::nullopt;
}

void drawRuntimeSidebarSkin(
    HDC dc,
    RuntimeWindowState& state,
    const RECT& sidebar
) {
    const RECT creditsRect{
        sidebar.left,
        sidebar.top,
        sidebar.right,
        sidebar.top + runtimeSidebarCreditsHeight
    };
    drawRuntimeUiShpFrame(
        dc,
        state,
        "sidebar",
        "credits",
        0,
        "sidebar",
        creditsRect,
        true,
        true
    );

    const RECT topRect{
        sidebar.left,
        sidebar.top + runtimeSidebarTopOffset,
        sidebar.right,
        sidebar.top + runtimeSidebarTopOffset + runtimeSidebarTopHeight
    };
    drawRuntimeUiShpFrame(
        dc,
        state,
        "sidebar",
        "top",
        0,
        "sidebar",
        topRect,
        true,
        true
    );

    const RECT upperPanel{
        sidebar.left,
        sidebar.top + runtimeSidebarSide1Offset,
        sidebar.right,
        sidebar.top + runtimeSidebarSide1Offset + runtimeSidebarSide1Height
    };
    drawRuntimeUiShpFrame(
        dc,
        state,
        "sidebar",
        "side1",
        0,
        "sidebar",
        upperPanel,
        true,
        true
    );

    const int listTop = sidebar.top + runtimeSidebarListOffset;
    const int listBottom = runtimeSidebarListBottom(sidebar);
    for (int y = listTop; y + runtimeSidebarSide2Height <= listBottom;
        y += runtimeSidebarSide2Height) {
        const RECT side2Panel{
            sidebar.left,
            y,
            sidebar.right,
            y + runtimeSidebarSide2Height
        };
        drawRuntimeUiShpFrame(
            dc,
            state,
            "sidebar",
            "side2",
            0,
            "sidebar",
            side2Panel,
            true,
            true
        );
    }

    const RECT bottomPanel{
        sidebar.left,
        runtimeSidebarSide3Top(sidebar),
        sidebar.right,
        runtimeSidebarAddonTop(sidebar)
    };
    drawRuntimeUiShpFrame(
        dc,
        state,
        "sidebar",
        "side3",
        0,
        "sidebar",
        bottomPanel,
        true,
        true
    );

    const int addonTop = runtimeSidebarAddonTop(sidebar);
    const RECT addonPanel{
        sidebar.left,
        addonTop,
        sidebar.right,
        std::min<int>(sidebar.bottom, addonTop + runtimeSidebarAddonHeight)
    };
    if (addonPanel.bottom > addonPanel.top) {
        if (drawRuntimeUiShpFrame(
            dc,
            state,
            "sidebar",
            "addon",
            0,
            "sidebar",
            addonPanel,
            true,
            true
        )) {
            ++state.lastSidebarAddonResourceDraws;
        }
    }

}

std::string runtimeSidebarStaticCacheKey(
    const RuntimeWindowState& state,
    const RECT& sidebar
) {
    std::ostringstream key;
    key
        << (sidebar.right - sidebar.left)
        << "x"
        << (sidebar.bottom - sidebar.top)
        << "|map="
        << state.report.map.path
        << "|theater="
        << state.report.map.theater
        << "|terrain="
        << state.world.getTerrainCells().size()
        << "|objects="
        << state.world.getObjects().size()
        << "|trips="
        << state.economy.resourceTrips
        << "|asset="
        << runtimeAssetRootPath(state.config)
        << "|faction="
        << runtimeSidebarFactionKey(state);
    return key.str();
}

void drawRuntimeSidebarStaticLayer(
    HDC dc,
    RuntimeWindowState& state,
    const RECT& sidebar
) {
    HBRUSH background = CreateSolidBrush(RGB(17, 24, 32));
    FillRect(dc, &sidebar, background);
    DeleteObject(background);
    drawRuntimeSidebarSkin(dc, state, sidebar);

    const RECT diplomacyRect{
        sidebar.left + 12,
        sidebar.top + runtimeSidebarCreditsHeight + 4,
        sidebar.left + 84,
        sidebar.top + runtimeSidebarCreditsHeight + 22
    };
    drawRuntimeUiShpFrame(
        dc,
        state,
        "sidebar",
        "diplobtn",
        0,
        "sidebar",
        diplomacyRect,
        true,
        true
    );

    const RECT optionsRect{
        sidebar.left + 84,
        sidebar.top + runtimeSidebarCreditsHeight + 4,
        sidebar.left + 156,
        sidebar.top + runtimeSidebarCreditsHeight + 22
    };
    drawRuntimeUiShpFrame(
        dc,
        state,
        "sidebar",
        "optbtn",
        0,
        "sidebar",
        optionsRect,
        true,
        true
    );
}

bool drawRuntimeSidebarStaticCache(
    HDC dc,
    RuntimeWindowState& state,
    const RECT& sidebar
) {
    const int width = sidebar.right - sidebar.left;
    const int height = sidebar.bottom - sidebar.top;
    if (width <= 0 || height <= 0) {
        return false;
    }

    const std::string key = runtimeSidebarStaticCacheKey(state, sidebar);
    if (state.sidebarStaticKey != key
        || state.sidebarStaticBuffer.width != width
        || state.sidebarStaticBuffer.height != height) {
        if (!ensureRuntimeBackBuffer(
                state.sidebarStaticBuffer,
                dc,
                width,
                height
            )) {
            state.sidebarStaticKey.clear();
            return false;
        }

        const RECT localSidebar{0, 0, width, height};
        drawRuntimeSidebarStaticLayer(
            state.sidebarStaticBuffer.memoryDc,
            state,
            localSidebar
        );
        state.sidebarStaticKey = key;
    }

    return BitBlt(
        dc,
        sidebar.left,
        sidebar.top,
        width,
        height,
        state.sidebarStaticBuffer.memoryDc,
        0,
        0,
        SRCCOPY
    ) != 0;
}

std::string runtimeRadarTerrainCacheKey(
    const RuntimeWindowState& state,
    const RECT& radarRect,
    const RuntimeRadarProjection& projection
) {
    std::ostringstream key;
    key
        << (radarRect.right - radarRect.left)
        << "x"
        << (radarRect.bottom - radarRect.top)
        << "|map="
        << state.report.map.path
        << "|theater="
        << state.report.map.theater
        << "|terrain="
        << state.world.getTerrainCells().size()
        << "|bounds="
        << projection.minX
        << ","
        << projection.minY
        << ","
        << projection.maxX
        << ","
        << projection.maxY
        << "|fullWidth="
        << projection.fullMapWidth
        << "|resources="
        << runtimeRadarResourceStateHash(state)
        << "|vision="
        << (state.visionEnabled
            ? state.vision.revisionFor(state.economy.owner)
            : 0);
    return key.str();
}

bool drawRuntimeRadarTerrainCache(
    HDC dc,
    RuntimeWindowState& state,
    const RECT& radarRect,
    const RuntimeRadarProjection& projection
) {
    RuntimePerfTraceScope radarTrace("drawRuntimeRadarTerrainCache", state.tick);
    const int width = radarRect.right - radarRect.left;
    const int height = radarRect.bottom - radarRect.top;
    if (!projection.valid || width <= 0 || height <= 0) {
        return false;
    }

    const std::string key =
        runtimeRadarTerrainCacheKey(state, radarRect, projection);
    if (state.radarTerrainKey != key
        || state.radarTerrainBuffer.width != width
        || state.radarTerrainBuffer.height != height) {
        RuntimeNestedStageDiagnosticScope radarDiagnostic(state, RuntimeFrameRadar);
        if (!ensureRuntimeBackBuffer(
                state.radarTerrainBuffer,
                dc,
                width,
                height
            )) {
            state.radarTerrainKey.clear();
            return false;
        }

        const RECT localRadar{0, 0, width, height};
        HBRUSH radarBrush = CreateSolidBrush(RGB(2, 8, 10));
        FillRect(state.radarTerrainBuffer.memoryDc, &localRadar, radarBrush);
        DeleteObject(radarBrush);
        RuntimeRadarPixelStore radarPixels(
            state.radarTerrainBuffer.memoryDc, state.radarTerrainBuffer.bitmap,
            state.radarTerrainBuffer.pixels, width, height, state.radarTerrainBuffer.topDownDib);

        state.lastRadarResourceCells = 0;
        state.lastRadarResourceOreCells = 0;
        state.lastRadarResourceGemCells = 0;
        state.lastRadarResourcePixels = 0;
        state.lastRadarResourceRuleColors = 0;
        state.lastRadarResourceFallbackColors = 0;
        state.lastRadarResourceHash = runtimeRadarResourceStateHash(state);
        const RuntimeOwnerRemapColorTable radarColorTable = [&] {
            RuntimeNestedStageDiagnosticScope rulesColorDiagnostic(state, RuntimeFrameRadarRulesColor);
            RuntimePerfTraceScope colorsTrace("radar.loadRulesColorTable", state.tick);
            if (runtimeRadarRulesColorReference())
                return loadRuntimeRemapColorTable(state.config);
            const RuntimeIniSource source = [&] {
                RuntimePerfTraceScope resolveTrace("radar.rules.resolve", state.tick);
                return resolveRuntimeIniSource(state.config, RuntimeCampaignIniKind::Rules);
            }();
            return state.radarRulesColorsMemo.load(source, buildRuntimeRemapColorTable, state.tick);
        }();

        RuntimeMapRenderContext renderContext;
        renderContext.theater = state.theaterLoaded ? &state.theater : nullptr;
        renderContext.art = state.artLoaded ? &state.art : nullptr;
        renderContext.rules = state.rulesLoaded ? &state.rules : nullptr;
        renderContext.mapFacts =
            state.mapFactsLoaded ? &state.mapFacts : nullptr;
        renderContext.ownerRemapColors = state.ownerRemapColors.empty()
            ? nullptr
            : &state.ownerRemapColors;
        renderContext.neutralRemapOwners = state.neutralRemapOwners.empty()
            ? nullptr
            : &state.neutralRemapOwners;
        if (runtimeLocalVisionRestricted(state)) {
            renderContext.vision = &state.vision;
            renderContext.visionObserverOwner = state.economy.owner;
        }
        renderContext.tileRootPath =
            runtimeTileRootPath(state.config, state.report.map);
        renderContext.palettePath =
            runtimePalettePath(state.config, state.report.map);
        renderContext.assetRootPath = runtimeAssetRootPath(state.config);
        renderContext.structureRootPath =
            runtimeStructureRootPath(state.config, state.report.map);
        renderContext.structurePalettePath =
            runtimeStructurePalettePath(state.config, state.report.map);
        renderContext.animationTick = state.tick;
        renderContext.fixedTickHz = state.config.fixedTickHz;

        RuntimeRadarTerrainColorsMemo radarColors(renderContext, state.renderCache);
        const bool referenceRadarQueries = runtimeRadarTerrainColorReference();
        const bool restrictedRadarVision = runtimeLocalVisionRestricted(state);
        RuntimeVisionGridView radarVision;
        const bool hasRadarVision = !referenceRadarQueries && restrictedRadarVision
            && state.vision.gridViewFor(state.economy.owner, radarVision);
        const RuntimeRadarLayout layout = runtimeRadarLayout(localRadar, projection);
        RuntimeRadarSampledTerrainKeys sampledTerrain;
        RuntimeRadarSampledTerrainObservation sampledObservation;
        if (sampledTerrain.begin(
                static_cast<std::int64_t>(layout.rect.right) - layout.rect.left,
                static_cast<std::int64_t>(layout.rect.bottom) - layout.rect.top,
                layout.scaleX, layout.scaleY,
                referenceRadarQueries || runtimeRadarSampledTerrainReference())) {
            RuntimePerfTraceScope sampledKeysTrace("radar.sampledKeys", state.tick);
            for (int pixelY = layout.rect.top; pixelY < layout.rect.bottom && sampledTerrain.active(); ++pixelY) {
                for (int pixelX = layout.rect.left; pixelX < layout.rect.right; ++pixelX) {
                    // Exact original pixel-sampling expression and order. No
                    // raster writes, resource counters or asset lookups here.
                    const RuntimeRadarDxyPoint sampledDxy{
                        projection.minX
                            + ((static_cast<double>(pixelX - layout.rect.left)
                                + 0.5) / layout.scaleX),
                        projection.minY
                            + ((static_cast<double>(pixelY - layout.rect.top)
                                + 0.5) / layout.scaleY)
                    };
                    if (!runtimeRadarProjectionContains(projection, sampledDxy)) continue;
                    int sampledKey;
                    if (!RuntimeRadarSampledTerrainKeys::exactLegacyKey(
                            std::floor((sampledDxy.x + sampledDxy.y + 2.0) / 2.0),
                            std::floor((sampledDxy.y - sampledDxy.x
                                + (2.0 * projection.fullMapWidth)) / 2.0), sampledKey)
                        || !sampledTerrain.add(sampledKey)) {
                        sampledTerrain.disable(); break;
                    }
                }
            }
        }
        sampledObservation.summary.active = sampledTerrain.active();
        sampledObservation.summary.sampledKeys = sampledTerrain.size();
        const bool observeSampledTerrain = runtimeRadarSampledTerrainObserver != nullptr;
        RuntimeRadarCellColors cellColors(state.world.getTerrainCells().size());
        {
        RuntimePerfTraceScope terrainColorLoopTrace("radar.terrainColorLoop", state.tick);
        for (const TerrainCell& terrain : state.world.getTerrainCells()) {
            if (!runtimeRadarTerrainCellIntersectsProjection(
                    projection,
                    terrain
                )) {
                continue;
            }

            const int terrainCellKey = runtimeCellKey(terrain.x, terrain.y);
            const bool sampledCell = sampledTerrain.contains(terrainCellKey);
            const bool potentialResource = terrain.hasOverlay
                && (terrain.overlayIsOre || terrain.overlayIsGem);
            if (!sampledCell && !potentialResource) {
                // Original first asset lookup and cached diagnostic replay
                // remain in the SAME terrain-author order, including failure.
                radarColors.visitWithoutColors(terrain);
                if (observeSampledTerrain) ++sampledObservation.summary.effectOnlyVisits;
                continue;
            }
            if (observeSampledTerrain && (referenceRadarQueries || restrictedRadarVision))
                ++sampledObservation.summary.visibilityQueries;
            const RuntimeCellVisibility visibility =
                (referenceRadarQueries ? runtimeLocalVisionRestricted(state) : restrictedRadarVision)
                    ? (hasRadarVision
                        ? RuntimeVisionSystem::visibilityForGridView(radarVision, terrain.x, terrain.y)
                        : state.vision.visibilityFor(
                        state.economy.owner,
                        terrain.x,
                        terrain.y
                    ))
                    : RuntimeCellVisibility::Visible;
            const bool shrouded =
                visibility == RuntimeCellVisibility::Shrouded;

            COLORREF dot = RGB(84, 116, 70);
            if (!sampledCell) {
                radarColors.visitWithoutColors(terrain);
                if (observeSampledTerrain) ++sampledObservation.summary.effectOnlyVisits;
            } else {
            if (observeSampledTerrain) ++sampledObservation.summary.colorVisits;
            RuntimePaletteColor radarLeft;
            RuntimePaletteColor radarRight;
            if (radarColors.resolve(
                    terrain,
                    radarLeft,
                    radarRight
                )) {
                dot = RGB(
                    radarLeft.r / 2,
                    radarLeft.g / 2,
                    radarLeft.b / 2
                );
            } else {
                const RuntimeTerrainInfo info =
                    runtimeCachedTerrainInfoForCell(state, terrain);
                if (info.water) {
                    dot = RGB(38, 70, 120);
                } else if (info.cliff) {
                    dot = RGB(128, 92, 54);
                } else if (info.shore || info.ramp) {
                    dot = RGB(112, 126, 78);
                }
            }
            }
            if (!shrouded) {
                const RuntimeRadarResourceColor resourceColor =
                    runtimeRadarResourceColorForTerrain(
                        state,
                        terrain,
                        radarColorTable
                    );
                if (resourceColor.visible) {
                    dot = resourceColor.color;
                    ++state.lastRadarResourceCells;
                    if (terrain.overlayIsGem) {
                        ++state.lastRadarResourceGemCells;
                    } else {
                        ++state.lastRadarResourceOreCells;
                    }
                    if (resourceColor.fromRule) {
                        ++state.lastRadarResourceRuleColors;
                    } else {
                        ++state.lastRadarResourceFallbackColors;
                    }
                    cellColors.markResource(runtimeCellKey(terrain.x, terrain.y));
                }
            }

            if (!sampledCell) continue;
            if (shrouded) {
                // Hide terrain information completely while retaining a tiny
                // cool variation so unexplored radar is not a dead flat fill.
                const int variation = ((terrain.x * 13) ^ (terrain.y * 7)) & 3;
                dot = RGB(
                    3 + variation,
                    6 + variation,
                    10 + variation
                );
            }
            cellColors.setColor(runtimeCellKey(terrain.x, terrain.y), dot);
        }
        }

        if (layout.scaleX > 0.0 && layout.scaleY > 0.0) {
            RuntimePerfTraceScope pixelRasterTrace("radar.pixelRaster", state.tick);
            for (int pixelY = layout.rect.top;
                pixelY < layout.rect.bottom;
                ++pixelY) {
                for (int pixelX = layout.rect.left;
                    pixelX < layout.rect.right;
                    ++pixelX) {
                    const RuntimeRadarDxyPoint sampledDxy{
                        projection.minX
                            + ((static_cast<double>(pixelX - layout.rect.left)
                                + 0.5) / layout.scaleX),
                        projection.minY
                            + ((static_cast<double>(pixelY - layout.rect.top)
                                + 0.5) / layout.scaleY)
                    };
                    if (!runtimeRadarProjectionContains(
                            projection,
                            sampledDxy
                        )) {
                        continue;
                    }
                    const int terrainX = static_cast<int>(std::floor(
                        (sampledDxy.x + sampledDxy.y + 2.0) / 2.0
                    ));
                    const int terrainY = static_cast<int>(std::floor(
                        (sampledDxy.y - sampledDxy.x
                            + (2.0 * projection.fullMapWidth)) / 2.0
                    ));
                    const int cellKey = runtimeCellKey(terrainX, terrainY);
                    RuntimeMapColorValue cellColor;
                    if (!cellColors.findColor(cellKey, cellColor)) {
                        continue;
                    }
                    radarPixels.store(pixelX, pixelY, cellColor);
                    if (cellColors.isResource(cellKey)) {
                        ++state.lastRadarResourcePixels;
                    }
                }
            }
        }
        state.radarTerrainKey = key;
    }

    return BitBlt(
        dc,
        radarRect.left,
        radarRect.top,
        width,
        height,
        state.radarTerrainBuffer.memoryDc,
        0,
        0,
        SRCCOPY
    ) != 0;
}

#include "ui/radar/diagnostics/RuntimeRadarPixelStoreContract.inl"
#include "ui/radar/diagnostics/RuntimeRadarTerrainColorsMemoContract.inl"
#include "ui/radar/diagnostics/RuntimeRadarRulesColorsMemoContract.inl"

bool probeRuntimeRadarResourceTerrain(
    RuntimeWindowState& state,
    int width,
    int height,
    std::string& errorMessage
) {
    HDC screenDc = GetDC(nullptr);
    if (screenDc == nullptr) {
        errorMessage = "could not acquire screen DC";
        return false;
    }

    HDC memoryDc = CreateCompatibleDC(screenDc);
    if (memoryDc == nullptr) {
        ReleaseDC(nullptr, screenDc);
        errorMessage = "could not create memory DC";
        return false;
    }

    HBITMAP bitmap = CreateCompatibleBitmap(screenDc, width, height);
    if (bitmap == nullptr) {
        DeleteDC(memoryDc);
        ReleaseDC(nullptr, screenDc);
        errorMessage = "could not create radar probe bitmap";
        return false;
    }

    HGDIOBJ oldBitmap = SelectObject(memoryDc, bitmap);
    const RuntimeRadarProjection projection = buildRuntimeRadarProjection(state);
    if (!projection.valid) {
        SelectObject(memoryDc, oldBitmap);
        DeleteObject(bitmap);
        DeleteDC(memoryDc);
        ReleaseDC(nullptr, screenDc);
        errorMessage = "radar projection was invalid";
        return false;
    }

    state.radarTerrainKey.clear();
    const RECT radarRect{0, 0, width, height};
    const bool drawn =
        drawRuntimeRadarTerrainCache(memoryDc, state, radarRect, projection);

    SelectObject(memoryDc, oldBitmap);
    DeleteObject(bitmap);
    DeleteDC(memoryDc);
    ReleaseDC(nullptr, screenDc);
    if (!drawn) {
        errorMessage = "radar terrain cache did not draw";
        return false;
    }
    return true;
}

bool runtimeRadarViewportBounds(
    RuntimeWindowState& state,
    const RECT& viewport,
    const RECT& radarRect,
    const RuntimeRadarProjection& projection,
    RECT& outBounds
) {
    if (!projection.valid || viewport.right <= viewport.left
        || viewport.bottom <= viewport.top) {
        return false;
    }

    const RuntimeRadarLayout layout = runtimeRadarLayout(radarRect, projection);
    if (layout.scaleX <= 0.0 || layout.scaleY <= 0.0) {
        return false;
    }

    const double tileWidth = std::max(1, state.camera.tileWidth);
    const double tileHeight = std::max(1, state.camera.tileHeight);
    const double leftDxy = projection.fullMapWidth - 1.0
        + ((2.0 * state.camera.worldOffsetX) / tileWidth);
    const double topDxy = -projection.fullMapWidth - 1.0
        + ((2.0 * state.camera.worldOffsetY) / tileHeight);
    const double rightDxy = leftDxy
        + ((2.0 * (viewport.right - viewport.left)) / tileWidth);
    const double bottomDxy = topDxy
        + ((2.0 * (viewport.bottom - viewport.top)) / tileHeight);
    if (rightDxy <= projection.minX
        || leftDxy >= projection.maxX
        || bottomDxy <= projection.minY
        || topDxy >= projection.maxY) {
        return false;
    }

    const double clippedLeft = std::max<double>(leftDxy, projection.minX);
    const double clippedTop = std::max<double>(topDxy, projection.minY);
    const double clippedRight = std::min<double>(rightDxy, projection.maxX);
    const double clippedBottom = std::min<double>(bottomDxy, projection.maxY);
    outBounds.left = static_cast<LONG>(std::floor(
        layout.rect.left
            + ((clippedLeft - projection.minX) * layout.scaleX)
    ));
    outBounds.top = static_cast<LONG>(std::floor(
        layout.rect.top
            + ((clippedTop - projection.minY) * layout.scaleY)
    ));
    outBounds.right = static_cast<LONG>(std::ceil(
        layout.rect.left
            + ((clippedRight - projection.minX) * layout.scaleX)
    ));
    outBounds.bottom = static_cast<LONG>(std::ceil(
        layout.rect.top
            + ((clippedBottom - projection.minY) * layout.scaleY)
    ));
    outBounds.left = std::clamp<LONG>(
        outBounds.left,
        layout.rect.left,
        layout.rect.right
    );
    outBounds.top = std::clamp<LONG>(
        outBounds.top,
        layout.rect.top,
        layout.rect.bottom
    );
    outBounds.right = std::clamp<LONG>(
        outBounds.right,
        layout.rect.left,
        layout.rect.right
    );
    outBounds.bottom = std::clamp<LONG>(
        outBounds.bottom,
        layout.rect.top,
        layout.rect.bottom
    );
    return outBounds.right > outBounds.left
        && outBounds.bottom > outBounds.top;
}

bool drawRuntimePlayerRadarBeacon(HDC dc, const RuntimeRadarLayout& layout,
    const RuntimeRadarProjection& projection, RuntimeWindowState& state,
    const RuntimePlayerBeacon& beacon);

void drawRuntimeRadarMarkerCell(
    HDC dc,
    const RuntimeRadarLayout& layout,
    const RuntimeRadarProjection& projection,
    double cellX,
    double cellY,
    COLORREF color
) {
    RuntimeRadarDxyPoint top = runtimeRadarDxyPoint(
        cellX,
        cellY,
        projection.fullMapWidth
    );
    RuntimeRadarDxyPoint center = top;
    center.y += 1.0;
    if (!runtimeRadarProjectionContains(projection, center)) {
        return;
    }

    const RuntimeRadarDxyPoint right{top.x + 1.0, top.y + 1.0};
    const RuntimeRadarDxyPoint bottom{top.x, top.y + 2.0};
    const RuntimeRadarDxyPoint left{top.x - 1.0, top.y + 1.0};
    POINT diamond[] = {
        runtimeRadarPointFromDxy(layout, projection, top),
        runtimeRadarPointFromDxy(layout, projection, right),
        runtimeRadarPointFromDxy(layout, projection, bottom),
        runtimeRadarPointFromDxy(layout, projection, left)
    };
    concord::ui::win32::MapNativeOverlayWin32::setBrushColor(dc, color);
    concord::ui::win32::MapNativeOverlayWin32::setPenColor(dc, color);
    Polygon(dc, diamond, 4);
    const POINT centerPixel =
        runtimeRadarPointFromDxy(layout, projection, center);
    SetPixelV(dc, centerPixel.x, centerPixel.y, color);
}



bool runtimeSuperWeaponHasReadyLabel(const SuperWeaponSidebarSnapshot& snapshot) {
    return snapshot.state == SuperWeaponRuntimeState::Ready
        || snapshot.state == SuperWeaponRuntimeState::SelectingTarget
        || snapshot.state == SuperWeaponRuntimeState::AwaitingSecondTarget;
}

void drawRuntimeSidebar(
    HDC dc,
    const RECT& clientRect,
    RuntimeWindowState& state,
    std::uint64_t presentationMs
) {
    RuntimeSidebarOwnedQueryDiagnostics::Phase sidebarQueryTracePhase(&state);
    RuntimePaintSecretLabPhaseScope secretLabReadonlyPhase(state, true);
    const RECT sidebar = runtimeSidebarRect(clientRect);
    if (!drawRuntimeSidebarStaticCache(dc, state, sidebar)) {
        drawRuntimeSidebarStaticLayer(dc, state, sidebar);
    }

    HGDIOBJ oldBrush = SelectObject(dc, GetStockObject(DC_BRUSH));
    HGDIOBJ oldPen = SelectObject(dc, GetStockObject(DC_PEN));

    const RECT creditsRect{
        sidebar.left,
        sidebar.top,
        sidebar.right,
        sidebar.top + runtimeSidebarCreditsHeight
    };
    SetTextColor(dc, RGB(236, 244, 252));
    const std::wstring creditsWide =
        widenUtf8(std::to_string(state.economy.credits));
    RECT creditsTextRect = creditsRect;
    DrawTextW(
        dc,
        creditsWide.c_str(),
        -1,
        &creditsTextRect,
        DT_SINGLELINE | DT_CENTER | DT_VCENTER | DT_END_ELLIPSIS
    );

    const RECT radarRect = runtimeRadarRect(sidebar);
    const RuntimeRadarProjection radarProjection =
        buildRuntimeRadarProjection(state);
    const bool radarActive =
        runtimeRadarAvailable(state) && radarProjection.valid;

    HBRUSH oldRadarBrush =
        static_cast<HBRUSH>(SelectObject(dc, GetStockObject(DC_BRUSH)));
    HPEN oldRadarPen =
        static_cast<HPEN>(SelectObject(dc, GetStockObject(DC_PEN)));

    const bool radarFrameDrawn = drawRuntimeUiShpFrame(
        dc,
        state,
        "sidebar",
        "radar",
        runtimeRadarFrameIndex(state, radarActive),
        "radar",
        radarRect,
        true,
        true
    );

    const RECT radarInterior = runtimeRadarInteriorRect(radarRect);

    if (runtimeRadarMapVisible(state, radarActive)) {
        drawRuntimeRadarTerrainCache(dc, state, radarInterior, radarProjection);
        const RuntimeRadarLayout radarLayout =
            runtimeRadarLayout(radarInterior, radarProjection);

        for (const WorldObjectInstance& object : state.world.getObjects()) {
            if (!object.alive
                || !runtimeObjectVisibleToOwner(
                    state,
                    state.economy.owner,
                    object
                )) {
                continue;
            }
            const RuntimeSpyObserverProjection spyProjection =
                runtimeSpyObserverProjectionForOwner(
                    state,
                    state.economy.owner,
                    object
                );
            const COLORREF objectColor =
                runtimeRadarColorForOwner(
                    state,
                    spyProjection.active
                        ? spyProjection.owner
                        : object.owner
                );
            if (object.kind == WorldObjectKind::Structure) {
                for (const RuntimeCellPoint& cell :
                    runtimeStructureFootprintCellsForObject(state, object)) {
                    drawRuntimeRadarMarkerCell(
                        dc,
                        radarLayout,
                        radarProjection,
                        cell.x,
                        cell.y,
                        objectColor
                    );
                }
            } else {
                drawRuntimeRadarMarkerCell(
                    dc,
                    radarLayout,
                    radarProjection,
                    runtimeObjectRenderX(object),
                    runtimeObjectRenderY(object),
                    objectColor
                );
            }
        }

        for (const auto& beacon : state.playerCommunication.beacons)
            drawRuntimePlayerRadarBeacon(dc,radarLayout,radarProjection,state,beacon);
        if ((state.tick / 4) % 2 == 0) {
            for (const auto& [id, location] : state.triggers.publicBuildingLocations) {
                (void)id;
                if (runtimePublicBuildingNoticeVisible(state, location)) {
                    drawRuntimeRadarMarkerCell(dc, radarLayout, radarProjection,
                        location.cell.x, location.cell.y, RGB(255, 226, 72));
                    drawRuntimeRadarMarkerCell(dc, radarLayout, radarProjection,
                        location.cell.x + 1, location.cell.y, RGB(255, 226, 72));
                }
            }
            for (const RuntimeCampaignRadarEvent& event :
                    state.triggers.campaignRadarEvents) {
                if (event.untilTick <= state.tick) {
                    continue;
                }
                const COLORREF eventColor = event.eventType == 5
                    ? RGB(255, 76, 64)
                    : (event.eventType == 11
                        ? RGB(104, 214, 255)
                        : RGB(255, 226, 72));
                drawRuntimeRadarMarkerCell(
                    dc,
                    radarLayout,
                    radarProjection,
                    event.cell.x,
                    event.cell.y,
                    eventColor
                );
                drawRuntimeRadarMarkerCell(
                    dc,
                    radarLayout,
                    radarProjection,
                    event.cell.x + 1,
                    event.cell.y,
                    eventColor
                );
            }
        }

        const RECT viewport = runtimeMapViewport(clientRect);
        RECT cameraRadarBounds{0, 0, 0, 0};
        if (runtimeRadarViewportBounds(
                state,
                viewport,
                radarInterior,
                radarProjection,
                cameraRadarBounds
            )) {
            concord::ui::win32::MapNativeOverlayWin32::setPenColor(dc, RGB(212, 232, 246));
            HGDIOBJ viewportBrush =
                SelectObject(dc, GetStockObject(NULL_BRUSH));
            Rectangle(
                dc,
                cameraRadarBounds.left,
                cameraRadarBounds.top,
                cameraRadarBounds.right,
                cameraRadarBounds.bottom
            );
            SelectObject(dc, viewportBrush);
        }
    } else if (!radarFrameDrawn) {
        concord::ui::win32::MapNativeOverlayWin32::setBrushColor(dc, RGB(4, 7, 11));
        concord::ui::win32::MapNativeOverlayWin32::setPenColor(dc, RGB(36, 48, 58));
        Rectangle(
            dc,
            radarInterior.left,
            radarInterior.top,
            radarInterior.right,
            radarInterior.bottom
        );
        SetTextColor(
            dc,
            runtimeHasOwnedRadar(state) ? RGB(224, 190, 82) : RGB(120, 132, 144)
        );
        const std::wstring radarStatusWide =
            widenUtf8(runtimeRadarStatusText(state));
        RECT textRect = radarInterior;
        DrawTextW(
            dc,
            radarStatusWide.c_str(),
            -1,
            &textRect,
            DT_SINGLELINE | DT_CENTER | DT_VCENTER | DT_END_ELLIPSIS
        );
    }
    SelectObject(dc, oldRadarPen);
    SelectObject(dc, oldRadarBrush);

    initializeRuntimeSidebarPowerAnimation(state);
    const RuntimeSidebarPowerDisplay powerDisplay =
        runtimeSidebarPowerDisplay(state);
    state.lastSidebarPowerDisplayedProduced = powerDisplay.produced;
    state.lastSidebarPowerDisplayedUsed = powerDisplay.used;
    state.lastSidebarPowerAnimationActive = powerDisplay.animating;
    const RECT powerTrack = runtimeSidebarPowerTrackRect(sidebar);
    const int powerTrackHeight =
        std::max(1, static_cast<int>(powerTrack.bottom - powerTrack.top - 2));
    const int powerScale =
        std::max(
            1,
            std::max(powerDisplay.produced, powerDisplay.used)
        );
    const int powerNet = powerDisplay.produced - powerDisplay.used;
    const int powerFillHeight =
        std::clamp(
            (powerTrackHeight * std::abs(powerNet)) / powerScale,
            1,
            powerTrackHeight
        );
    const RECT powerFill{
        powerTrack.left + 2,
        powerTrack.bottom - 1 - powerFillHeight,
        powerTrack.right - 1,
        powerTrack.bottom - 1
    };
    const bool realPowerDrawn =
        drawRuntimePowerSegments(dc, state, powerTrack, powerDisplay);
    if (!realPowerDrawn) {
        HBRUSH powerBrush = CreateSolidBrush(
            powerNet >= 0 ? RGB(80, 214, 96) : RGB(232, 76, 64)
        );
        FillRect(dc, &powerFill, powerBrush);
        DeleteObject(powerBrush);
    }

    const RuntimeSidebarTool tools[] = {
        RuntimeSidebarTool::Repair,
        RuntimeSidebarTool::Sell
    };
    for (RuntimeSidebarTool tool : tools) {
        const RECT toolRect = runtimeSidebarToolRect(sidebar, tool);
        const bool active = state.activeSidebarTool == tool;
        drawRuntimeUiShpFrame(
            dc,
            state,
            "sidebar",
            tool == RuntimeSidebarTool::Repair ? "repair" : "sell",
            active ? 1 : 0,
            "sidebar",
            toolRect,
            true,
            true
        );
    }

    const bool defenseTabFlashing = runtimeDefenseSidebarTabShouldFlash(state);
    const bool defenseTabHighlight = defenseTabFlashing
        && runtimeSuperWeaponFlashHighlightPhase(
            state.tick,
            state.config.fixedTickHz
        );
    for (int tab = 0; tab < 4; ++tab) {
        const RuntimeBuildKind kind = runtimeBuildKindForTabIndex(tab);
        const RECT tabRect = runtimeBuildTabRect(sidebar, tab);
        const bool active = kind == state.activeBuildTab;
        const bool available = runtimeSidebarTabAvailable(state, kind);
        const bool highlighted = kind == RuntimeBuildKind::Defense
            && defenseTabHighlight;
        drawRuntimeUiShpFrame(
            dc,
            state,
            "sidebar",
            "tab0" + std::to_string(tab),
            !available ? 2 : ((active || highlighted) ? 1 : 0),
            "sidebar",
            tabRect,
            true,
            true
        );
    }

    runtimeClampActiveBuildPage(state, sidebar);
    const std::vector<int> visibleIndices =
        runtimeVisibleBuildCatalogIndices(state, sidebar);
    state.lastSidebarLowPowerIndicators = 0;
    for (int visibleIndex = 0;
        visibleIndex < static_cast<int>(visibleIndices.size());
        ++visibleIndex) {
        const RuntimeBuildCatalogItem& item =
            state.economy.catalog[visibleIndices[visibleIndex]];
        const RECT rect = runtimeBuildButtonRect(sidebar, visibleIndex);
        const RuntimeBuildAvailability availability =
            runtimeBuildAvailability(state, item);
        const bool enabled = availability.canQueue;
        const bool ready = availability.canStart;
        RuntimeProductionLane itemLane = RuntimeProductionLane::Structures;
        const RuntimeProductionLaneOrder* activeOrder =
            runtimeActiveProductionForItem(state, item, &itemLane);
        const bool busy = activeOrder != nullptr;
        const bool onHold = busy
            && state.economy.localProductionLanes.lanes[
                runtimeProductionLaneIndex(itemLane)
            ].onHold;
        const RuntimeProductionLaneOrder* readyOrder =
            runtimeReadyProductionForItem(state, item, &itemLane);
        const bool placementReady = readyOrder != nullptr;
        const bool hovered =
            state.mouseClientPointValid
            && PtInRect(&rect, state.mouseClientPoint);
        const int queuedCount =
            runtimeQueuedProductionCountForItem(state, item);
        const bool multiQueueKind =
            item.kind == RuntimeBuildKind::Infantry
            || item.kind == RuntimeBuildKind::Unit;
        const int displayedQueueCount =
            multiQueueKind
                ? queuedCount + (busy ? 1 : 0)
                : queuedCount;
        RECT iconRect = rect;
        if (RuntimeCameoIconCacheEntry* icon =
                loadRuntimeCameoIcon(state, item)) {
            drawRuntimeCameoImage(
                dc,
                state,
                iconRect,
                icon->image,
                state.cameoPalette,
                enabled || ready || placementReady
            );
        } else {
            drawRuntimeMissingCameo(dc, iconRect, item, enabled || ready || placementReady);
        }

        if (busy && !item.wall && activeOrder != nullptr) {
            const double progressFraction = activeOrder->cost > 0
                ? static_cast<double>(activeOrder->creditsSpent)
                    / static_cast<double>(std::max(1, activeOrder->cost))
                : static_cast<double>(activeOrder->zeroCostProgressMicros)
                    / 1000000.0;
            if (!drawRuntimeBuildProgressClockOverlay(
                    dc,
                    state,
                    iconRect,
                    progressFraction,
                    onHold
                )) {
                drawRuntimeBuildProgressClockMask(
                    dc,
                    iconRect,
                    progressFraction,
                    onHold
                );
            }
        } else if (onHold && !item.wall) {
            if (!drawRuntimeBuildProgressClockOverlay(
                    dc,
                    state,
                    iconRect,
                    0.0,
                    true
                )) {
                drawRuntimeBuildProgressClockMask(dc, iconRect, 0.0, true);
            }
        }

        if (placementReady && runtimeUiReadyBlinkOn(presentationMs)) {
            RECT textRect{iconRect.left + 2, iconRect.top + 4, iconRect.right - 2, iconRect.bottom - 12};
            RECT shadowRect = textRect;
            OffsetRect(&shadowRect, 1, 1);
            const int oldMode = SetBkMode(dc, TRANSPARENT);
            const COLORREF oldColor = SetTextColor(dc, RGB(0, 0, 0));
            HGDIOBJ oldFont = SelectObject(dc, GetStockObject(DEFAULT_GUI_FONT));
            constexpr UINT flags = DT_SINGLELINE | DT_CENTER | DT_VCENTER | DT_NOPREFIX;
            DrawTextW(dc, L"就绪", -1, &shadowRect, flags);
            SetTextColor(dc, RGB(255, 255, 255));
            DrawTextW(dc, L"就绪", -1, &textRect, flags);
            SelectObject(dc, oldFont);
            SetTextColor(dc, oldColor);
            SetBkMode(dc, oldMode);
        }

        if (hovered || placementReady || busy || onHold || ready) {
            concord::ui::win32::MapNativeOverlayWin32::setPenColor(
                dc,
                placementReady ? RGB(120, 242, 220)
                    : onHold ? RGB(214, 182, 96)
                    : busy ? RGB(92, 204, 236)
                    : hovered ? RGB(152, 204, 236)
                    : RGB(96, 126, 156)
            );
            MoveToEx(dc, iconRect.left + 1, iconRect.top + 1, nullptr);
            LineTo(dc, iconRect.right - 1, iconRect.top + 1);
            LineTo(dc, iconRect.right - 1, iconRect.bottom - 1);
            LineTo(dc, iconRect.left + 1, iconRect.bottom - 1);
            LineTo(dc, iconRect.left + 1, iconRect.top + 1);
        }

        if (multiQueueKind && displayedQueueCount > 0) {
            const RECT countBack{
                iconRect.right - 25,
                iconRect.top + 3,
                iconRect.right - 3,
                iconRect.top + 19
            };
            HBRUSH countBrush = CreateSolidBrush(RGB(2, 5, 8));
            FillRect(dc, &countBack, countBrush);
            DeleteObject(countBrush);
            concord::ui::win32::MapNativeOverlayWin32::setPenColor(dc, RGB(180, 228, 252));
            MoveToEx(dc, countBack.left, countBack.top, nullptr);
            LineTo(dc, countBack.right, countBack.top);
            LineTo(dc, countBack.right, countBack.bottom);
            LineTo(dc, countBack.left, countBack.bottom);
            LineTo(dc, countBack.left, countBack.top);
            const std::wstring countWide =
                widenUtf8(std::to_string(displayedQueueCount));
            SetTextColor(dc, RGB(232, 248, 255));
            RECT countText = countBack;
            DrawTextW(
                dc,
                countWide.c_str(),
                -1,
                &countText,
                DT_SINGLELINE | DT_CENTER | DT_VCENTER
            );
        }

        if (runtimeSidebarLowPowerIndicatorVisible(item, availability)
            && drawRuntimeSidebarLowPowerIndicator(dc, iconRect)) {
            ++state.lastSidebarLowPowerIndicators;
        }

    }

    const int pageCount = runtimeBuildPageCount(state, sidebar);
    const int page = runtimeActiveBuildPage(state);
    const RECT pageDownRect = runtimeBuildPageButtonRect(sidebar, true);
    const RECT pageUpRect = runtimeBuildPageButtonRect(sidebar, false);
    drawRuntimeUiShpFrame(
        dc,
        state,
        "sidebar",
        "r-dn",
        page + 1 < pageCount ? 0 : 2,
        "sidebar",
        pageDownRect,
        true,
        false
    );
    drawRuntimeUiShpFrame(
        dc,
        state,
        "sidebar",
        "r-up",
        page > 0 ? 0 : 2,
        "sidebar",
        pageUpRect,
        true,
        false
    );

    const std::vector<const SuperWeaponSidebarSnapshot*> superWeapons =
        runtimeVisibleSuperWeaponsOnBuildPage(state, sidebar);
    const int firstSuperWeaponSlot = static_cast<int>(visibleIndices.size());
    for (int visibleIndex = 0;
        visibleIndex < static_cast<int>(superWeapons.size());
        ++visibleIndex) {
        const SuperWeaponSidebarSnapshot& snapshot =
            *superWeapons[static_cast<std::size_t>(visibleIndex)];
        const RECT rect = runtimeBuildButtonRect(
            sidebar,
            firstSuperWeaponSlot + visibleIndex
        );
        RECT iconRect = rect;
        if (RuntimeCameoIconCacheEntry* icon =
                loadRuntimeSuperWeaponIcon(state, snapshot)) {
            drawRuntimeCameoImage(
                dc,
                state,
                iconRect,
                icon->image,
                state.cameoPalette,
                snapshot.state != SuperWeaponRuntimeState::Unavailable
            );
        } else {
            HPEN placeholderPen = CreatePen(
                PS_SOLID,
                1,
                RGB(82, 96, 112)
            );
            HGDIOBJ previousPen = SelectObject(dc, placeholderPen);
            MoveToEx(dc, rect.left + 6, rect.top + 6, nullptr);
            LineTo(dc, rect.right - 6, rect.bottom - 6);
            MoveToEx(dc, rect.right - 6, rect.top + 6, nullptr);
            LineTo(dc, rect.left + 6, rect.bottom - 6);
            SelectObject(dc, previousPen);
            DeleteObject(placeholderPen);
        }
        if (snapshot.state != SuperWeaponRuntimeState::Ready
            && snapshot.state != SuperWeaponRuntimeState::Unavailable) {
            const bool paused = snapshot.chargePaused || snapshot.state == SuperWeaponRuntimeState::Suspended;
            if (!drawRuntimeBuildProgressClockOverlay(
                    dc,
                    state,
                    iconRect,
                    snapshot.progress,
                    paused
                )) {
                drawRuntimeBuildProgressClockMask(
                    dc,
                    iconRect,
                    snapshot.progress,
                    paused
                );
            }
        }
        const bool selected = snapshot.targetSelectionActive;
        const bool ready = snapshot.state == SuperWeaponRuntimeState::Ready;
        const bool hovered = state.mouseClientPointValid
            && PtInRect(&rect, state.mouseClientPoint);
        concord::ui::win32::MapNativeOverlayWin32::setPenColor(
            dc,
            selected ? RGB(255, 236, 116)
                : hovered ? RGB(152, 204, 236)
                : ready ? RGB(104, 238, 132)
                : snapshot.state == SuperWeaponRuntimeState::Suspended
                    ? RGB(224, 174, 82)
                    : RGB(70, 94, 116)
        );
        MoveToEx(dc, rect.left + 1, rect.top + 1, nullptr);
        LineTo(dc, rect.right - 1, rect.top + 1);
        LineTo(dc, rect.right - 1, rect.bottom - 1);
        LineTo(dc, rect.left + 1, rect.bottom - 1);
        LineTo(dc, rect.left + 1, rect.top + 1);
        if (runtimeSuperWeaponHasReadyLabel(snapshot)
            && runtimeUiReadyBlinkOn(presentationMs)) {
            // Use presentation time so game speed and pause do not accelerate
            // or freeze the cameo's ready indication.
            RECT textRect{rect.left + 2, rect.top + 4, rect.right - 2, rect.bottom - 12};
            RECT shadowRect = textRect;
            OffsetRect(&shadowRect, 1, 1);
            const int oldMode = SetBkMode(dc, TRANSPARENT);
            const COLORREF oldColor = SetTextColor(dc, RGB(0, 0, 0));
            HGDIOBJ oldFont = SelectObject(dc, GetStockObject(DEFAULT_GUI_FONT));
            constexpr UINT flags = DT_SINGLELINE | DT_CENTER | DT_VCENTER | DT_NOPREFIX;
            DrawTextW(dc, L"就绪", -1, &shadowRect, flags);
            SetTextColor(dc, RGB(255, 255, 255));
            DrawTextW(dc, L"就绪", -1, &textRect, flags);
            SelectObject(dc, oldFont);
            SetTextColor(dc, oldColor);
            SetBkMode(dc, oldMode);
        }

    }

    SelectObject(dc, oldPen);
    SelectObject(dc, oldBrush);
}

void drawRuntimeSidebar(HDC dc, const RECT& clientRect, RuntimeWindowState& state) {
    drawRuntimeSidebar(dc, clientRect, state, runtimeUiClockNow(state));
}



constexpr std::uint64_t runtimeGameplayObjectTooltipDelayMs = 3000U;
constexpr std::uint64_t runtimeGameplayBuildTooltipDelayMs = 1000U;
constexpr COLORREF runtimeGameplayObjectTooltipTextColor = RGB(255, 255, 0);

struct RuntimeGameplayTooltip {
    std::wstring text;
    COLORREF textColor = RGB(238, 232, 210);

    bool visible() const {
        return !text.empty();
    }
};

void resetRuntimeGameplayObjectTooltipHover(RuntimeWindowState& state) {
    state.runtimeGameplayTooltipHoverObjectId = -1;
    state.runtimeGameplayTooltipHoverStartedMs = 0;
}

bool runtimeGameplayObjectTooltipDelayElapsed(
    RuntimeWindowState& state,
    int objectId
) {
    const std::uint64_t nowMs = runtimeUiClockNow(state);
    if (state.runtimeGameplayTooltipHoverObjectId != objectId) {
        state.runtimeGameplayTooltipHoverObjectId = objectId;
        state.runtimeGameplayTooltipHoverStartedMs = nowMs;
        return false;
    }
    return runtimeUiHoverDelayElapsed(nowMs,
        state.runtimeGameplayTooltipHoverStartedMs, runtimeGameplayObjectTooltipDelayMs);
}

void resetRuntimeGameplayBuildTooltipHover(RuntimeWindowState& state) {
    state.runtimeGameplayTooltipHoverBuildButtonIndex = -1;
    state.runtimeGameplayTooltipHoverBuildStartedMs = 0;
}

bool runtimeGameplayBuildTooltipDelayElapsed(
    RuntimeWindowState& state,
    int buttonIndex
) {
    const std::uint64_t nowMs = runtimeUiClockNow(state);
    if (state.runtimeGameplayTooltipHoverBuildButtonIndex != buttonIndex) {
        state.runtimeGameplayTooltipHoverBuildButtonIndex = buttonIndex;
        state.runtimeGameplayTooltipHoverBuildStartedMs = nowMs;
        return false;
    }
    return runtimeUiHoverDelayElapsed(nowMs,
        state.runtimeGameplayTooltipHoverBuildStartedMs, runtimeGameplayBuildTooltipDelayMs);
}

void resetRuntimeGameplayTooltipHover(RuntimeWindowState& state) {
    resetRuntimeGameplayObjectTooltipHover(state);
    resetRuntimeGameplayBuildTooltipHover(state);
}

std::wstring runtimeGameplayTooltipObjectName(
    const RuntimeWindowState& state,
    const RuntimeProjectedObject& projected
);

std::wstring runtimeGameplayBuildTooltipName(
    const RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item
) {
    RuntimeProjectedObject projected;
    WorldObjectInstance object;
    object.type = item.typeId;
    projected.object = &object;
    const std::wstring resolved =
        runtimeGameplayTooltipObjectName(state, projected);
    return resolved.empty() ? widenUtf8(item.label) : resolved;
}

std::wstring runtimeGameplayTooltipObjectName(
    const RuntimeWindowState& state,
    const RuntimeProjectedObject& projected
) {
    if (projected.object == nullptr) {
        return {};
    }
    const std::string typeId = !projected.observerType.empty()
        ? projected.observerType
        : projected.object->type;
    std::string uiName;
    std::string fallbackName;
    if (const BuildingType* building =
            findRuntimeBuildingTypeById(state.rules, typeId)) {
        uiName = trimAsciiLocal(building->uiName);
        fallbackName = trimAsciiLocal(building->name);
    } else if (const UnitType* unit =
            findRuntimeUnitTypeById(state.rules, typeId)) {
        uiName = trimAsciiLocal(unit->uiName);
        fallbackName = trimAsciiLocal(unit->name);
    }
    if (!uiName.empty()) {
        const std::wstring localized = runtimeMenuLabel(state, uiName, L"");
        if (!localized.empty()) {
            return localized;
        }
    }
    return widenUtf8(fallbackName.empty() ? typeId : fallbackName);
}

std::wstring runtimeGameplayTooltipObjectText(
    const RuntimeWindowState& state,
    const RuntimeProjectedObject& projected
) {
    std::wstring text = runtimeGameplayTooltipObjectName(state, projected);
    if (projected.object != nullptr) {
        if (const auto* reactor = runtimeInfantryAbsorberType(state, *projected.object)) {
            if (reactor->passengers > 0) {
                text += L"\n已进驻 " + std::to_wstring(runtimeBuildingAbsorbedCount(
                    *reactor, *projected.object)) + L"/" + std::to_wstring(reactor->passengers);
            }
        }
    }
    return text;
}

std::wstring runtimeSuperWeaponDisplayName(
    const RuntimeWindowState& state,
    const SuperWeaponSidebarSnapshot& snapshot
) {
    const std::string key = trimAsciiLocal(snapshot.uiName);
    if (!key.empty()) {
        const std::wstring localized = runtimeMenuLabel(state, key, L"");
        if (!localized.empty()) {
            return localized;
        }
    }
    const std::string name = trimAsciiLocal(snapshot.name);
    return widenUtf8(name.empty() ? snapshot.superWeaponId : name);
}

std::wstring runtimeSuperWeaponTooltipState(
    const SuperWeaponSidebarSnapshot& snapshot
) {
    if (snapshot.chargePaused) return L"已暂停";
    switch (snapshot.state) {
    case SuperWeaponRuntimeState::Unavailable:
        return L"不可用";
    case SuperWeaponRuntimeState::Launching:
    case SuperWeaponRuntimeState::Active:
    case SuperWeaponRuntimeState::Cooldown:
    case SuperWeaponRuntimeState::Charging:
        return L"充能中 "
            + std::to_wstring(static_cast<int>(std::clamp(
                snapshot.progress,
                0.0,
                1.0
            ) * 100.0 + 0.5))
            + L"%";
    case SuperWeaponRuntimeState::Suspended:
        return L"已暂停";
    case SuperWeaponRuntimeState::Ready:
        return L"就绪";
    case SuperWeaponRuntimeState::SelectingTarget:
        return L"选择目标";
    case SuperWeaponRuntimeState::AwaitingSecondTarget:
        return L"选择第二个目标";

    }
    return {};
}

RuntimeGameplayTooltip runtimeGameplayTooltipAtPoint(
    RuntimeWindowState& state,
    const RECT& clientRect
) {
    RuntimeGameplayTooltip tooltip;
    if (!state.runtimeTooltipsEnabled
        || state.runtimeMenuOpen
        || state.skirmishMatchFinished
        || !state.mouseClientPointValid) {
        resetRuntimeGameplayObjectTooltipHover(state);
        resetRuntimeGameplayBuildTooltipHover(state);
        return tooltip;
    }

    const POINT point = state.mouseClientPoint;
    const RECT sidebar = runtimeSidebarRect(clientRect);
    if (pointInRectInclusive(sidebar, point)) {
        resetRuntimeGameplayObjectTooltipHover(state);
        if (const std::optional<int> buttonIndex =
                runtimeBuildButtonAtPoint(state, sidebar, point)) {
            if (*buttonIndex >= 0
                && *buttonIndex
                    < static_cast<int>(state.economy.catalog.size())) {
                const RuntimeBuildCatalogItem& item =
                    state.economy.catalog[static_cast<std::size_t>(*buttonIndex)];
                if (!runtimeGameplayBuildTooltipDelayElapsed(
                        state,
                        *buttonIndex
                    )) {
                    return tooltip;
                }
                tooltip.text = runtimeGameplayBuildTooltipName(state, item);
                tooltip.textColor = runtimeGameplayObjectTooltipTextColor;
                return tooltip;
            }
        }
        resetRuntimeGameplayBuildTooltipHover(state);
        if (const SuperWeaponSidebarSnapshot* superWeapon =
                runtimeSuperWeaponAtPoint(state, sidebar, point)) {
            tooltip.text = runtimeSuperWeaponDisplayName(state, *superWeapon)
                + L"\n"
                + runtimeSuperWeaponTooltipState(*superWeapon);
            return tooltip;
        }
        if (const std::optional<RuntimeSidebarTool> tool =
                runtimeSidebarToolAtPoint(sidebar, point)) {
            tooltip.text = widenUtf8(runtimeSidebarToolLabel(*tool));
            return tooltip;
        }
        const int pageDirection = runtimeBuildPageButtonAtPoint(
            state,
            sidebar,
            point
        );
        if (pageDirection != 0) {
            tooltip.text = pageDirection > 0 ? L"Next page" : L"Previous page";
            return tooltip;
        }
        if (pointInRectInclusive(runtimeRadarRect(sidebar), point)) {
            return tooltip;
        }
    }

    resetRuntimeGameplayBuildTooltipHover(state);
    const RECT viewport = runtimeMapViewport(clientRect);
    if (!pointInRectInclusive(viewport, point)) {
        resetRuntimeGameplayObjectTooltipHover(state);
        return tooltip;
    }
    const std::vector<RuntimeProjectedObject>& projectedObjects =
        runtimeProjectedObjectsForViewport(state, viewport);
    const RuntimeProjectedObject* projected =
        findProjectedObjectAtPoint(projectedObjects, point);
    if (projected == nullptr || projected->object == nullptr) {
        resetRuntimeGameplayObjectTooltipHover(state);
        return tooltip;
    }

    const WorldObjectInstance& object = *projected->object;
    if (!runtimeGameplayObjectTooltipDelayElapsed(
            state,
            object.instanceId
        )) {
        return tooltip;
    }
    tooltip.text = runtimeGameplayTooltipObjectText(state, *projected);
    tooltip.textColor = runtimeGameplayObjectTooltipTextColor;
    return tooltip;
}

void drawRuntimeGameplayTooltip(
    HDC dc,
    const RECT& clientRect,
    RuntimeWindowState& state
) {
    state.lastGameplayTooltipsDrawn = 0;
    state.lastGameplayTooltipText.clear();
    const RuntimeGameplayTooltip tooltip =
        runtimeGameplayTooltipAtPoint(state, clientRect);
    if (!tooltip.visible()) {
        return;
    }

    constexpr int padding = 7;
    constexpr int maximumTextWidth = 240;
    RECT measured{0, 0, maximumTextWidth, 0};
    DrawTextW(
        dc,
        tooltip.text.c_str(),
        -1,
        &measured,
        DT_CALCRECT | DT_WORDBREAK | DT_NOPREFIX
    );
    const int width = std::max(
        80,
        static_cast<int>(measured.right - measured.left)
    ) + padding * 2;
    const int height = std::max(
        18,
        static_cast<int>(measured.bottom - measured.top)
    ) + padding * 2;
    int left = state.mouseClientPoint.x + 18;
    int top = state.mouseClientPoint.y + 18;
    if (left + width > clientRect.right - 4) {
        left = state.mouseClientPoint.x - width - 12;
    }
    if (top + height > clientRect.bottom - 4) {
        top = state.mouseClientPoint.y - height - 12;
    }
    left = std::clamp(
        left,
        static_cast<int>(clientRect.left) + 4,
        std::max(static_cast<int>(clientRect.left) + 4,
            static_cast<int>(clientRect.right) - width - 4)
    );
    top = std::clamp(
        top,
        static_cast<int>(clientRect.top) + 4,
        std::max(static_cast<int>(clientRect.top) + 4,
            static_cast<int>(clientRect.bottom) - height - 4)
    );
    RECT panel{left, top, left + width, top + height};
    HBRUSH background = CreateSolidBrush(RGB(7, 12, 18));
    FillRect(dc, &panel, background);
    DeleteObject(background);
    HPEN outline = CreatePen(PS_SOLID, 1, RGB(184, 166, 112));
    HGDIOBJ oldPen = SelectObject(dc, outline);
    HGDIOBJ oldBrush = SelectObject(dc, GetStockObject(NULL_BRUSH));
    Rectangle(dc, panel.left, panel.top, panel.right, panel.bottom);
    SelectObject(dc, oldBrush);
    SelectObject(dc, oldPen);
    DeleteObject(outline);

    RECT textRect{
        panel.left + padding,
        panel.top + padding,
        panel.right - padding,
        panel.bottom - padding
    };
    const int oldBkMode = SetBkMode(dc, TRANSPARENT);
    const COLORREF oldTextColor = SetTextColor(dc, tooltip.textColor);
    DrawTextW(
        dc,
        tooltip.text.c_str(),
        -1,
        &textRect,
        DT_WORDBREAK | DT_NOPREFIX
    );
    SetTextColor(dc, oldTextColor);
    SetBkMode(dc, oldBkMode);
    state.lastGameplayTooltipsDrawn = 1;
    state.lastGameplayTooltipText = tooltip.text;
}
bool validateRuntimeSuperWeaponDefenseSidebar(
    const RuntimeWindowState& templateState,
    std::string& diagnostic
) {
    RuntimeWindowState probe;
    probe.config = templateState.config;
    probe.rules = templateState.rules;
    probe.rulesLoaded = true;
    probe.economy.owner = templateState.economy.owner.empty()
        ? "SidebarProbe"
        : templateState.economy.owner;
    probe.economy.credits = 1000;
    probe.economy.techLevel = 10;
    probe.activeBuildTab = RuntimeBuildKind::Defense;

    RuntimeBuildCatalogItem defenseItem;
    defenseItem.kind = RuntimeBuildKind::Defense;
    defenseItem.typeId = "SIDEBAR_DEFENSE_PROBE";
    defenseItem.label = defenseItem.typeId;
    defenseItem.techTreeAllowed = true;
    defenseItem.techLevel = 0;
    defenseItem.buildTicks = 1;
    probe.economy.catalog.push_back(defenseItem);

    const SuperWeaponRule* spyPlaneRule = nullptr;
    for (const SuperWeaponRule& rule : probe.rules.getSuperWeaponTypes()) {
        if (containsAsciiCaseInsensitive(rule.id, "spyplane")
            || containsAsciiCaseInsensitive(rule.type, "spyplane")
            || containsAsciiCaseInsensitive(rule.action, "spyplane")) {
            spyPlaneRule = &rule;
            break;
        }
    }
    if (spyPlaneRule == nullptr) {
        diagnostic = "missing SpyPlane superweapon rule";
        return false;
    }

    const std::string spyPlaneId = spyPlaneRule->id;
    probe.superWeapons.reset(probe.rules);
    probe.superWeaponsInitialized = true;
    SuperWeaponWorldContext context = runtimeSuperWeaponContext(probe);
    std::string reason;
    if (!probe.superWeapons.forceReady(
            probe.economy.owner,
            spyPlaneId,
            &context
        )
        || !probe.superWeapons.beginTargetSelection(
            probe.economy.owner,
            spyPlaneId,
            context,
            &reason
        )
        || !probe.superWeapons.cancelTargetSelection(
            probe.economy.owner,
            spyPlaneId,
            context,
            "sidebar layout probe"
        )) {
        diagnostic = "could not prepare SpyPlane: " + reason;
        return false;
    }

    const RECT clientRect{0, 0, 1024, 768};
    const RECT sidebar = runtimeSidebarRect(clientRect);
    const int perPage = runtimeBuildButtonsPerPage(sidebar);
    const int defenseBuildCount = static_cast<int>(
        runtimeFilteredBuildCatalogIndices(probe).size()
    );
    runtimeSetActiveBuildPage(probe, defenseBuildCount / perPage);
    const std::vector<int> visibleBuilds =
        runtimeVisibleBuildCatalogIndices(probe, sidebar);
    const std::vector<const SuperWeaponSidebarSnapshot*> visibleSuperWeapons =
        runtimeVisibleSuperWeaponsOnBuildPage(probe, sidebar);
    const int spyPlaneSlot = static_cast<int>(visibleBuilds.size());
    const RECT spyPlaneRect = runtimeBuildButtonRect(sidebar, spyPlaneSlot);
    const POINT spyPlanePoint{
        (spyPlaneRect.left + spyPlaneRect.right) / 2,
        (spyPlaneRect.top + spyPlaneRect.bottom) / 2
    };
    const SuperWeaponSidebarSnapshot* defenseHit =
        runtimeSuperWeaponAtPoint(probe, sidebar, spyPlanePoint);
    const bool defenseTabHit = defenseHit != nullptr
        && toLowerAsciiLocal(defenseHit->superWeaponId)
            == toLowerAsciiLocal(spyPlaneId);
    const bool defenseTabAvailable = runtimeSidebarTabAvailable(
        probe,
        RuntimeBuildKind::Defense
    );

    probe.activeBuildTab = RuntimeBuildKind::Building;
    const bool hiddenOutsideDefense =
        runtimeSuperWeaponAtPoint(probe, sidebar, spyPlanePoint) == nullptr;

    SuperWeaponSidebarSnapshot helperProbe;
    helperProbe.state = SuperWeaponRuntimeState::Charging;
    helperProbe.remainingTicks = 31;
    helperProbe.showTimer = false;
    const bool timerHiddenByRule =
        !runtimeSuperWeaponTimerVisible(helperProbe);
    helperProbe.showTimer = true;
    const bool timerCeiling = runtimeSuperWeaponTimerVisible(helperProbe)
        && runtimeSuperWeaponRemainingSeconds(helperProbe, 30) == 2;

    helperProbe.state = SuperWeaponRuntimeState::Ready;
    helperProbe.stateStartTick = 100;
    helperProbe.flashSidebarTabFrames = -1;
    const bool infiniteFlash = runtimeSuperWeaponShouldFlashSidebarTab(
        helperProbe,
        10000,
        30
    );
    helperProbe.flashSidebarTabFrames = 0;
    const bool zeroFlashDisabled = !runtimeSuperWeaponShouldFlashSidebarTab(
        helperProbe,
        100,
        30
    );
    helperProbe.flashSidebarTabFrames = 30;
    const bool finiteFlashBoundary =
        runtimeSuperWeaponShouldFlashSidebarTab(helperProbe, 159, 30)
        && !runtimeSuperWeaponShouldFlashSidebarTab(helperProbe, 160, 30);

    helperProbe.targetLineMultiplier = 3;
    const bool targetRingCount =
        runtimeSuperWeaponTargetRingCount(helperProbe) == 4;
    const bool aiDifficultyMapping =
        runtimeAiSuperDefenseProbabilityIndex("Hard") == 0
        && runtimeAiSuperDefenseProbabilityIndex("Brutal") == 0
        && runtimeAiSuperDefenseProbabilityIndex("Normal") == 1
        && runtimeAiSuperDefenseProbabilityIndex("Medium") == 1
        && runtimeAiSuperDefenseProbabilityIndex("Easy") == 2;
    const bool helperContracts = timerHiddenByRule
        && timerCeiling
        && infiniteFlash
        && zeroFlashDisabled
        && finiteFlashBoundary
        && targetRingCount
        && aiDifficultyMapping;
    diagnostic = "id=" + spyPlaneId
        + " page=" + std::to_string(defenseBuildCount / perPage + 1)
        + " slot=" + std::to_string(spyPlaneSlot)
        + " perPage=" + std::to_string(perPage)
        + " defenseHit=" + formatBool(defenseTabHit)
        + " defenseTab=" + formatBool(defenseTabAvailable)
        + " hiddenElsewhere=" + formatBool(hiddenOutsideDefense)
        + " timer=" + formatBool(timerHiddenByRule && timerCeiling)
        + " flash=" + formatBool(
            infiniteFlash && zeroFlashDisabled && finiteFlashBoundary
        )
        + " rings=" + formatBool(targetRingCount)
        + " aiProbability=" + formatBool(aiDifficultyMapping);
    return visibleSuperWeapons.size() == 1U
        && defenseTabHit
        && defenseTabAvailable
        && hiddenOutsideDefense
        && helperContracts;
}

bool validateRuntimeSidebarPowerUi(std::string& diagnostic) {
    RuntimeWindowState animationProbe;
    animationProbe.config.fixedTickHz = 60;
    animationProbe.tick = 100;
    animationProbe.economy.powerProduced = 100;
    animationProbe.economy.powerUsed = 40;
    initializeRuntimeSidebarPowerAnimation(animationProbe);

    const RuntimeSidebarPowerDisplay initial =
        runtimeSidebarPowerDisplay(animationProbe);
    retargetRuntimeSidebarPowerAnimation(animationProbe, 400, 340);
    const RuntimeSidebarPowerDisplay upStart =
        runtimeSidebarPowerDisplay(animationProbe);
    animationProbe.tick = 102;
    const RuntimeSidebarPowerDisplay upBeforeFirstStep =
        runtimeSidebarPowerDisplay(animationProbe);
    animationProbe.tick = 103;
    const RuntimeSidebarPowerDisplay upFirstStep =
        runtimeSidebarPowerDisplay(animationProbe);
    animationProbe.tick = 145;
    const RuntimeSidebarPowerDisplay upMiddle =
        runtimeSidebarPowerDisplay(animationProbe);
    animationProbe.tick = 190;
    const RuntimeSidebarPowerDisplay upEnd =
        runtimeSidebarPowerDisplay(animationProbe);

    retargetRuntimeSidebarPowerAnimation(animationProbe, 40, 10);
    const RuntimeSidebarPowerDisplay downStart =
        runtimeSidebarPowerDisplay(animationProbe);
    animationProbe.tick = 193;
    const RuntimeSidebarPowerDisplay downFirstStep =
        runtimeSidebarPowerDisplay(animationProbe);
    animationProbe.tick = 244;
    const RuntimeSidebarPowerDisplay downMiddle =
        runtimeSidebarPowerDisplay(animationProbe);
    animationProbe.tick = 298;
    const RuntimeSidebarPowerDisplay downEnd =
        runtimeSidebarPowerDisplay(animationProbe);

    RuntimeWindowState redirectProbe;
    redirectProbe.config.fixedTickHz = 60;
    redirectProbe.tick = 0;
    redirectProbe.economy.powerProduced = 100;
    redirectProbe.economy.powerUsed = 40;
    snapRuntimeSidebarPowerAnimation(redirectProbe);
    retargetRuntimeSidebarPowerAnimation(redirectProbe, 400, 340);
    redirectProbe.tick = 45;
    const RuntimeSidebarPowerDisplay beforeRedirect =
        runtimeSidebarPowerDisplay(redirectProbe);
    retargetRuntimeSidebarPowerAnimation(redirectProbe, 40, 500);
    const RuntimeSidebarPowerDisplay redirectStart =
        runtimeSidebarPowerDisplay(redirectProbe);
    redirectProbe.tick = 48;
    const RuntimeSidebarPowerDisplay redirectFirstStep =
        runtimeSidebarPowerDisplay(redirectProbe);

    RuntimeWindowState resetProbe;
    resetProbe.config.fixedTickHz = 60;
    resetProbe.tick = 900;
    resetProbe.economy.powerProduced = 275;
    resetProbe.economy.powerUsed = 125;
    snapRuntimeSidebarPowerAnimation(resetProbe);
    const RuntimeSidebarPowerDisplay resetDisplay =
        runtimeSidebarPowerDisplay(resetProbe);

    RuntimeWindowState slowRateProbe;
    slowRateProbe.config.fixedTickHz = 15;
    slowRateProbe.tick = 0;
    snapRuntimeSidebarPowerAnimation(slowRateProbe);
    slowRateProbe.tick = 1;
    RuntimeWindowState fastRateProbe;
    fastRateProbe.config.fixedTickHz = 75;
    fastRateProbe.tick = 0;
    snapRuntimeSidebarPowerAnimation(fastRateProbe);
    fastRateProbe.tick = 3;
    const long long fastStepsBefore =
        runtimeSidebarPowerAnimationElapsedSteps(fastRateProbe);
    fastRateProbe.tick = 4;
    const bool animationContract =
        runtimeSidebarPowerAnimationElapsedSteps(slowRateProbe) == 1
        && fastStepsBefore == 0
        && runtimeSidebarPowerAnimationElapsedSteps(fastRateProbe) == 1
        && initial.produced == 100
        && initial.used == 40
        && !initial.animating
        && upStart.produced == initial.produced
        && upStart.used == initial.used
        && upStart.animating
        && upBeforeFirstStep.produced == upStart.produced
        && upBeforeFirstStep.used == upStart.used
        && upBeforeFirstStep.animating
        && upFirstStep.produced == 110
        && upFirstStep.used == 50
        && upFirstStep.animating
        && upMiddle.produced == 250
        && upMiddle.used == 190
        && upMiddle.animating
        && upEnd.produced == 400
        && upEnd.used == 340
        && !upEnd.animating
        && downStart.produced == upEnd.produced
        && downStart.used == upEnd.used
        && downStart.animating
        && downFirstStep.produced == 390
        && downFirstStep.used == 330
        && downFirstStep.animating
        && downMiddle.produced == 220
        && downMiddle.used == 160
        && downMiddle.animating
        && downEnd.produced == 40
        && downEnd.used == 10
        && !downEnd.animating
        && beforeRedirect.produced == 250
        && beforeRedirect.used == 190
        && redirectStart.produced == beforeRedirect.produced
        && redirectStart.used == beforeRedirect.used
        && redirectStart.animating
        && redirectFirstStep.produced == 240
        && redirectFirstStep.used == 200
        && redirectFirstStep.animating
        && resetDisplay.produced == 275
        && resetDisplay.used == 125
        && !resetDisplay.animating;

    const RuntimeSidebarPowerSegmentCounts upStartSegments =
        runtimeSidebarPowerSegmentCounts(upStart, 64);
    const RuntimeSidebarPowerSegmentCounts upMiddleSegments =
        runtimeSidebarPowerSegmentCounts(upMiddle, 64);
    const RuntimeSidebarPowerSegmentCounts upEndSegments =
        runtimeSidebarPowerSegmentCounts(upEnd, 64);
    const auto segmentTotal = [](const RuntimeSidebarPowerSegmentCounts& value) {
        return value.used + value.yellow + value.green;
    };
    const bool intermediateSegmentContract =
        segmentTotal(upStartSegments) == 10
        && segmentTotal(upMiddleSegments) == 25
        && segmentTotal(upEndSegments) == 40
        && upStartSegments.used == 4
        && upMiddleSegments.used == 19
        && upEndSegments.used == 34;

    const RuntimeSidebarPowerSegmentCounts deficitSegments =
        runtimeSidebarPowerSegmentCounts({100, 300, false}, 64);
    const RuntimeSidebarPowerSegmentCounts surplusSegments =
        runtimeSidebarPowerSegmentCounts({300, 100, false}, 64);
    const bool segmentContract =
        deficitSegments.used == 30
        && deficitSegments.yellow == 0
        && deficitSegments.green == 0
        && surplusSegments.used == 10
        && surplusSegments.yellow == 3
        && surplusSegments.green == 17
        && intermediateSegmentContract;

    RuntimeBuildCatalogItem structureItem;
    structureItem.kind = RuntimeBuildKind::Building;
    RuntimeBuildCatalogItem unitItem;
    unitItem.kind = RuntimeBuildKind::Unit;
    RuntimeBuildAvailability currentLowPower;
    currentLowPower.lowPower = true;
    RuntimeBuildAvailability prospectiveLowPower;
    prospectiveLowPower.lowPowerAfterBuild = true;
    RuntimeBuildAvailability healthyPower;
    const bool indicatorSemantics =
        !runtimeSidebarLowPowerIndicatorVisible(
            structureItem,
            currentLowPower
        )
        && !runtimeSidebarLowPowerIndicatorVisible(
            structureItem,
            prospectiveLowPower
        )
        && !runtimeSidebarLowPowerIndicatorVisible(unitItem, currentLowPower)
        && !runtimeSidebarLowPowerIndicatorVisible(
            structureItem,
            healthyPower
        );

    const RECT iconRect{0, 0, 60, 48};
    const RuntimeSidebarLowPowerIndicatorRects indicatorRects =
        runtimeSidebarLowPowerIndicatorRects(iconRect);
    const int borderArea =
        (indicatorRects.border.right - indicatorRects.border.left)
        * (indicatorRects.border.bottom - indicatorRects.border.top);
    const int fillArea =
        (indicatorRects.fill.right - indicatorRects.fill.left)
        * (indicatorRects.fill.bottom - indicatorRects.fill.top);
    bool indicatorPixels = false;
    int redPixels = 0;
    int darkRedPixels = 0;
    HDC screenDc = GetDC(nullptr);
    if (screenDc != nullptr) {
        HDC memoryDc = CreateCompatibleDC(screenDc);
        HBITMAP bitmap = memoryDc == nullptr
            ? nullptr
            : CreateCompatibleBitmap(screenDc, 60, 48);
        HGDIOBJ oldBitmap = bitmap == nullptr
            ? nullptr
            : SelectObject(memoryDc, bitmap);
        if (oldBitmap != nullptr && oldBitmap != HGDI_ERROR) {
            HBRUSH blackBrush = CreateSolidBrush(RGB(0, 0, 0));
            if (blackBrush != nullptr) {
                FillRect(memoryDc, &iconRect, blackBrush);
                DeleteObject(blackBrush);
                const bool indicatorDrawn =
                    drawRuntimeSidebarLowPowerIndicator(memoryDc, iconRect);
                for (int y = 0; y < 48; ++y) {
                    for (int x = 0; x < 60; ++x) {
                        const COLORREF pixel = concord::ui::win32::MapNativeOverlayWin32::readPixel(memoryDc, x, y);
                        if (pixel == RGB(228, 48, 40)) {
                            ++redPixels;
                        } else if (pixel == RGB(72, 8, 8)) {
                            ++darkRedPixels;
                        }
                    }
                }
                indicatorPixels = indicatorDrawn
                    && redPixels == fillArea
                    && darkRedPixels == borderArea - fillArea;
            }
            SelectObject(memoryDc, oldBitmap);
        }
        if (bitmap != nullptr) {
            DeleteObject(bitmap);
        }
        if (memoryDc != nullptr) {
            DeleteDC(memoryDc);
        }
        ReleaseDC(nullptr, screenDc);
    }

    diagnostic = "stepMs="
        + std::to_string(runtimeSidebarPowerAnimationStepMs)
        + " up=" + std::to_string(upStart.produced)
        + "/" + std::to_string(upFirstStep.produced)
        + "/" + std::to_string(upMiddle.produced)
        + "/" + std::to_string(upEnd.produced)
        + " down=" + std::to_string(downStart.produced)
        + "/" + std::to_string(downFirstStep.produced)
        + "/" + std::to_string(downMiddle.produced)
        + "/" + std::to_string(downEnd.produced)
        + " deficitRed=" + std::to_string(deficitSegments.used)
        + " indicatorPixels=" + std::to_string(redPixels)
        + "/" + std::to_string(darkRedPixels);
    return animationContract
        && segmentContract
        && indicatorSemantics
        && indicatorPixels;
}

bool validateRuntimeSidebarLowPowerIntegration(
    RuntimeWindowState& state,
    std::string& diagnostic
) {
    const RECT clientRect{0, 0, 1024, 768};
    const RECT sidebar = runtimeSidebarRect(clientRect);
    if (!runtimeEconomyLowPower(state)) {
        diagnostic = "probe state is not low power";
        return false;
    }

    HDC screenDc = GetDC(nullptr);
    if (screenDc == nullptr) {
        diagnostic = "screen DC unavailable";
        return false;
    }
    HDC memoryDc = CreateCompatibleDC(screenDc);
    HBITMAP bitmap = memoryDc == nullptr
        ? nullptr
        : CreateCompatibleBitmap(screenDc, 1024, 768);
    HGDIOBJ oldBitmap = bitmap == nullptr
        ? nullptr
        : SelectObject(memoryDc, bitmap);
    if (oldBitmap == nullptr || oldBitmap == HGDI_ERROR) {
        if (bitmap != nullptr) {
            DeleteObject(bitmap);
        }
        if (memoryDc != nullptr) {
            DeleteDC(memoryDc);
        }
        ReleaseDC(nullptr, screenDc);
        diagnostic = "sidebar bitmap unavailable";
        return false;
    }

    HBRUSH blackBrush = CreateSolidBrush(RGB(0, 0, 0));
    if (blackBrush != nullptr) {
        FillRect(memoryDc, &clientRect, blackBrush);
        DeleteObject(blackBrush);
    }
    drawRuntimeSidebar(memoryDc, clientRect, state);

    const std::vector<int> visibleIndices =
        runtimeVisibleBuildCatalogIndices(state, sidebar);
    int expectedIndicators = 0;
    int exactFillPixels = 0;
    int normalCameos = 0;
    for (int visibleIndex = 0;
        visibleIndex < static_cast<int>(visibleIndices.size());
        ++visibleIndex) {
        const RuntimeBuildCatalogItem& item =
            state.economy.catalog[visibleIndices[visibleIndex]];
        const RuntimeBuildAvailability availability =
            runtimeBuildAvailability(state, item);
        if ((availability.canQueue || availability.canStart)
            && loadRuntimeCameoIcon(state, item) != nullptr) {
            ++normalCameos;
        }
        if (!runtimeSidebarLowPowerIndicatorVisible(item, availability)) {
            continue;
        }
        ++expectedIndicators;

        const RECT iconRect = runtimeBuildButtonRect(sidebar, visibleIndex);
        const RuntimeSidebarLowPowerIndicatorRects indicatorRects =
            runtimeSidebarLowPowerIndicatorRects(iconRect);
        for (int y = indicatorRects.fill.top;
            y < indicatorRects.fill.bottom;
            ++y) {
            for (int x = indicatorRects.fill.left;
                x < indicatorRects.fill.right;
                ++x) {
                if (concord::ui::win32::MapNativeOverlayWin32::readPixel(memoryDc, x, y) == RGB(228, 48, 40)) {
                    ++exactFillPixels;
                }
            }
        }
    }

    SelectObject(memoryDc, oldBitmap);
    DeleteObject(bitmap);
    DeleteDC(memoryDc);
    ReleaseDC(nullptr, screenDc);

    diagnostic = "indicators=" + std::to_string(
        state.lastSidebarLowPowerIndicators
    ) + "/" + std::to_string(expectedIndicators)
        + " redPixels=" + std::to_string(exactFillPixels)
        + " normalCameos=" + std::to_string(normalCameos);
    return expectedIndicators == 0
        && state.lastSidebarLowPowerIndicators == 0
        && exactFillPixels == 0
        && normalCameos > 0;
}

void updateRuntimePlacementPreview(
    RuntimeWindowState& state,
    const RECT& viewport,
    POINT point
) {
    const std::optional<RuntimeSelectedPlacement> placement =
        runtimeSelectedPlacement(state);
    if (!placement.has_value() || placement->item == nullptr) {
        return;
    }
    const RuntimeBuildCatalogItem& item = *placement->item;

    const POINT targetPoint =
        approximateCellFromScreenPoint(state, viewport, point);
    const RuntimeStructureFootprint footprint =
        runtimeStructureFootprintForBuildItem(
            state,
            item
        );
    const RuntimeCellPoint placementCell =
        runtimePlacementTopLeftForPreviewTarget(
            {targetPoint.x, targetPoint.y},
            footprint
        );
    const auto& multiplayerPlacement =
        state.multiplayerIntentRouter.placement();
    const RuntimeCellPoint previousCell =
        runtimeUsesGameplayIntentRouter(state)
            && multiplayerPlacement.has_value()
        ? RuntimeCellPoint{
            multiplayerPlacement->cell.x,
            multiplayerPlacement->cell.y
          }
        : state.economy.placementCell;
    if (previousCell == placementCell
        && runtimePlacementChecksCacheMatches(state, item, placementCell)) {
        return;
    }
    const std::vector<RuntimePlacementCellCheck>& checks =
        cachedRuntimePlacementCellChecks(
            state,
            item,
            placementCell
        );
    const bool placementValid = !checks.empty() && std::all_of(
        checks.begin(),
        checks.end(),
        [](const RuntimePlacementCellCheck& check) {
            return check.valid;
        }
    );
    if (runtimeUsesGameplayIntentRouter(state)) {
        std::string previewError;
        if (!state.multiplayerIntentRouter.previewPlacement(
                {placementCell.x, placementCell.y},
                placementValid,
                previewError
            )) {
            state.interactionStatus =
                "placement preview rejected: " + previewError;
        }
    } else {
        state.economy.placementCell = placementCell;
        state.economy.placementValid = placementValid;
    }
    if (!placementValid) {
        const auto blocked = std::find_if(
            checks.begin(),
            checks.end(),
            [](const RuntimePlacementCellCheck& check) {
                return !check.valid;
            }
        );
        if (blocked != checks.end()) {
            const std::string status =
                "blocked "
                + std::to_string(blocked->cell.x)
                + ","
                + std::to_string(blocked->cell.y)
                + " "
                + blocked->reason;
            if (runtimeUsesGameplayIntentRouter(state)) {
                state.interactionStatus = status;
            } else {
                state.economy.status = status;
            }
        }
    } else {
        const std::string status =
            item.typeId
            + " ready: click map to place";
        if (runtimeUsesGameplayIntentRouter(state)) {
            state.interactionStatus = status;
        } else {
            state.economy.status = status;
        }
    }
}

RuntimeCellPoint runtimePlacementCellForUi(
    const RuntimeWindowState& state
) {
    const auto& placement = state.multiplayerIntentRouter.placement();
    if (runtimeUsesGameplayIntentRouter(state) && placement.has_value()) {
        return {placement->cell.x, placement->cell.y};
    }
    return state.economy.placementCell;
}

bool runtimePlacementValidForUi(const RuntimeWindowState& state) {
    const auto& placement = state.multiplayerIntentRouter.placement();
    return runtimeUsesGameplayIntentRouter(state) && placement.has_value()
        ? placement->previewValid
        : state.economy.placementValid;
}

bool runtimePlacementPreviewValid(
    const RuntimeWindowState& state
) {
    const std::optional<RuntimeSelectedPlacement> placement =
        runtimeSelectedPlacement(state);
    if (!placement.has_value() || placement->item == nullptr) {
        return false;
    }
    return runtimeCellCanPlaceSidebarBuilding(
        state, *placement->item, runtimePlacementCellForUi(state)
    );
}

void drawRuntimePlacementPreview(
    HDC dc,
    const RECT& viewport,
    RuntimeWindowState& state,
    const RuntimeMapRenderContext& renderContext
) {
    state.lastPlacementPreviewSpriteDraws = 0;
    state.lastPlacementPreviewSpriteRect = RECT{0, 0, 0, 0};
    state.lastPlacementPreviewCells = 0;
    state.lastPlacementPreviewValidCells = 0;
    state.lastPlacementPreviewBounds = RECT{0, 0, 0, 0};
    const std::optional<RuntimeSelectedPlacement> placement =
        runtimeSelectedPlacement(state);
    if (!placement.has_value() || placement->item == nullptr) {
        return;
    }
    const RuntimeBuildCatalogItem& item = *placement->item;

    const RuntimeStructureFootprint footprint =
        runtimeStructureFootprintForBuildItem(
            state,
            item
        );
    const RuntimeCellPoint placementCell = runtimePlacementCellForUi(state);
    const std::vector<RuntimePlacementCellCheck>& checks =
        cachedRuntimePlacementCellChecks(
            state,
            item,
            placementCell
        );

    const std::vector<RuntimeCellPoint> wallConnectors =
        runtimeWallConnectorCells(
            state,
            item,
            placementCell
        );
    HPEN validPen = CreatePen(PS_SOLID, 2, RGB(80, 238, 128));
    HPEN blockedPen = CreatePen(PS_SOLID, 2, RGB(242, 86, 86));
    HBRUSH validBrush = CreateSolidBrush(RGB(80, 238, 128));
    HBRUSH blockedBrush = CreateSolidBrush(RGB(242, 86, 86));
    HGDIOBJ oldPen = SelectObject(dc, validPen);
    HGDIOBJ oldBrush = SelectObject(dc, validBrush);

    std::vector<RuntimeCellPoint> footprintCells =
        runtimeStructureFootprintCells(placementCell, footprint);
    footprintCells.insert(
        footprintCells.end(),
        wallConnectors.begin(),
        wallConnectors.end()
    );
    for (const RuntimeCellPoint& cell : footprintCells) {
        const auto checkIt = std::find_if(
            checks.begin(),
            checks.end(),
            [&cell](const RuntimePlacementCellCheck& check) {
                return check.cell == cell;
            }
        );
        const bool connectorCell =
            std::find(wallConnectors.begin(), wallConnectors.end(), cell)
            != wallConnectors.end();
        const bool validCell = connectorCell
            || (checkIt != checks.end() && checkIt->valid);
        ++state.lastPlacementPreviewCells;
        if (validCell) {
            ++state.lastPlacementPreviewValidCells;
        }
        SelectObject(dc, validCell ? validPen : blockedPen);
        SelectObject(dc, validCell ? validBrush : blockedBrush);
        const POINT center = runtimeScreenPointForCell(
            state,
            viewport,
            cell,
            terrainLevelAtRuntimeCell(state, cell.x, cell.y)
        );
        const int halfWidth = std::max(1, state.camera.tileWidth / 2);
        const int halfHeight = std::max(1, state.camera.tileHeight / 2);
        const RECT cellBounds{
            center.x - halfWidth,
            center.y - halfHeight,
            center.x + halfWidth,
            center.y + halfHeight
        };
        if (state.lastPlacementPreviewCells == 1) {
            state.lastPlacementPreviewBounds = cellBounds;
        } else {
            state.lastPlacementPreviewBounds.left = std::min(
                state.lastPlacementPreviewBounds.left,
                cellBounds.left
            );
            state.lastPlacementPreviewBounds.top = std::min(
                state.lastPlacementPreviewBounds.top,
                cellBounds.top
            );
            state.lastPlacementPreviewBounds.right = std::max(
                state.lastPlacementPreviewBounds.right,
                cellBounds.right
            );
            state.lastPlacementPreviewBounds.bottom = std::max(
                state.lastPlacementPreviewBounds.bottom,
                cellBounds.bottom
            );
        }
        drawRuntimeFilledIsoDiamond(
            dc,
            center,
            halfWidth,
            halfHeight
        );
    }

    // The original placement cursor exposes only the legal footprint.
    // Structure art enters the world after placement is confirmed.
    (void)renderContext;

    SelectObject(dc, oldBrush);
    SelectObject(dc, oldPen);
    DeleteObject(validPen);
    DeleteObject(blockedPen);
    DeleteObject(validBrush);
    DeleteObject(blockedBrush);
}

#include "ui/selection/RuntimeSelectedPathBatch.h"
#include "ui/selection/RuntimeSelectedPathRaster.h"

int drawRuntimeSelectedPaths(
    HDC dc,
    const RECT& viewport,
    RuntimeWindowState& state,
    bool usePathBatch = true,
    const std::vector<RuntimeProjectedObject>* projectedObjects = nullptr
) {
    RuntimePerfTraceScope trace("overlaySelectedPaths", state.tick);
    if (!state.runtimeTargetLinesEnabled || state.selectedObjectIds.empty()) {
        return 0;
    }
    // The overlay already has this frame's body geometry. Direct callers
    // resolve it once, never once per selected unit.
    if (projectedObjects == nullptr) {
        projectedObjects = &runtimeProjectedObjectsForViewport(state, viewport);
    }
    std::unordered_map<int, std::optional<POINT>> selectedOrigins;
    selectedOrigins.reserve(state.selectedObjectIds.size());
    for (int objectId : state.selectedObjectIds) selectedOrigins.emplace(objectId, std::nullopt);
    for (const RuntimeProjectedObject& projected : *projectedObjects) {
        if (projected.object == nullptr || projected.object->kind == WorldObjectKind::Structure) continue;
        const auto origin = selectedOrigins.find(projected.object->instanceId);
        if (origin == selectedOrigins.end()) continue;
        POINT center = runtimeRenderPlacementNativePoint(projected.renderCenter);
        const auto& body = projected.spriteBounds;
        if (projected.hasMobileSpriteBounds && body.left < body.right && body.top < body.bottom) {
            center = {
                static_cast<LONG>(static_cast<long long>(body.left) + (static_cast<long long>(body.right) - body.left) / 2),
                static_cast<LONG>(static_cast<long long>(body.top) + (static_cast<long long>(body.bottom) - body.top) / 2)
            };
        }
        origin->second = center;
    }

    int drawnOrders = 0;
    HPEN pathPen = CreatePen(PS_DOT, 1, RGB(105, 230, 190));
    HPEN targetPen = CreatePen(PS_SOLID, 2, RGB(126, 245, 118));
    HPEN attackTargetPen = CreatePen(PS_SOLID, 2, RGB(246, 138, 82));
    HGDIOBJ oldPen = SelectObject(dc, pathPen);
    HGDIOBJ oldBrush = SelectObject(dc, GetStockObject(NULL_BRUSH));
    const bool batchPaths = usePathBatch && RuntimeSelectedPathBatch::supported(dc);
    RuntimeSelectedPathRaster pathRaster(dc,
        dc == state.backBuffer.memoryDc ? static_cast<std::uint32_t*>(state.backBuffer.pixels) : nullptr,
        state.backBuffer.width, state.backBuffer.height, batchPaths);

    for (int objectId : state.selectedObjectIds) {
        const WorldObjectInstance* object = findObjectById(state, objectId);
        const auto behaviorIt = state.behaviors.find(objectId);
        if (object == nullptr || behaviorIt == state.behaviors.end()) {
            continue;
        }

        const RuntimeObjectBehavior& behavior = behaviorIt->second;
        if (behavior.kind != RuntimeBehaviorKind::Move
            && behavior.kind != RuntimeBehaviorKind::Attack) {
            continue;
        }
        ++drawnOrders;

        POINT previous = runtimeOverlayCenterForObject(
            state,
            *object,
            viewport
        );
        if (object->kind != WorldObjectKind::Structure) {
            const auto origin = selectedOrigins.find(objectId);
            if (origin != selectedOrigins.end() && origin->second.has_value()) {
                previous = *origin->second;
            }
        }
        int pathStepsDrawn = 0;
        RuntimeSelectedPathBatch pathBatch;
        for (const RuntimeCellPoint& step : behavior.path) {
            if (pathStepsDrawn >= 96) {
                break;
            }
            const POINT current = runtimeScreenPointForCell(
                state,
                viewport,
                step,
                terrainLevelAtRuntimeCell(state, step.x, step.y)
            );
            if (pathRaster.available()) {
                pathRaster.draw(RuntimePathRasterKind::PathLine, previous, current);
                pathRaster.draw(RuntimePathRasterKind::Waypoint, {}, current);
            } else if (batchPaths) {
                pathBatch.append(previous, current);
            } else {
                MoveToEx(dc, previous.x, previous.y, nullptr);
                LineTo(dc, current.x, current.y);
                Rectangle(dc, current.x - 2, current.y - 2, current.x + 3, current.y + 3);
            }
            previous = current;
            ++pathStepsDrawn;
        }
        if (batchPaths) pathBatch.draw(dc);

        if (behavior.kind == RuntimeBehaviorKind::Move) {
            SelectObject(dc, targetPen);
            const POINT target = runtimeScreenPointForCell(
                state,
                viewport,
                behavior.moveTarget,
                terrainLevelAtRuntimeCell(
                    state,
                    behavior.moveTarget.x,
                    behavior.moveTarget.y
                )
            );
            if (pathRaster.available())
                pathRaster.draw(RuntimePathRasterKind::MoveDiamond, {}, target);
            else
                drawRuntimeDiamond(dc, target, 10);
            SelectObject(dc, pathPen);
        } else if (behavior.kind == RuntimeBehaviorKind::Attack) {
            const WorldObjectInstance* targetObject =
                findObjectById(state, behavior.targetObjectId);
            if (targetObject != nullptr) {
                const POINT target =
                    runtimeOverlayCenterForObject(state, *targetObject, viewport);
                SelectObject(dc, attackTargetPen);
                if (pathRaster.available()) {
                    pathRaster.draw(RuntimePathRasterKind::AttackLine, previous, target);
                    pathRaster.draw(RuntimePathRasterKind::AttackDiamond, {}, target);
                } else {
                    MoveToEx(dc, previous.x, previous.y, nullptr);
                    LineTo(dc, target.x, target.y);
                    drawRuntimeDiamond(dc, target, 12);
                }
                SelectObject(dc, pathPen);
            }
        }
    }

    SelectObject(dc, oldBrush);
    SelectObject(dc, oldPen);
    DeleteObject(pathPen);
    DeleteObject(targetPen);
    DeleteObject(attackTargetPen);
    return drawnOrders;
}

void drawRuntimeTurretFacingOverlay(
    HDC dc,
    const std::vector<RuntimeProjectedObject>& projectedObjects,
    const RuntimeWindowState& state
) {
    HPEN turretPen = CreatePen(PS_SOLID, 2, RGB(255, 214, 92));
    HGDIOBJ oldPen = SelectObject(dc, turretPen);

    for (const RuntimeProjectedObject& projectedObject : projectedObjects) {
        const WorldObjectInstance* object = projectedObject.object;
        if (object == nullptr
            || object->turretFacing < 0
            || !runtimeObjectHasTurret(state, *object)) {
            continue;
        }

        const bool selected =
            selectionContains(state, object->instanceId);
        const bool attacking =
            state.behaviors.find(object->instanceId) != state.behaviors.end()
            && state.behaviors.at(object->instanceId).kind
                == RuntimeBehaviorKind::Attack;
        if (!selected && !attacking) {
            continue;
        }

        const double radians =
            (static_cast<double>(normalizeRuntimeFacing(object->turretFacing))
                / 256.0)
            * 6.283185307179586;
        const POINT selectionCenter =
            runtimeProjectedUnitSelectionCenter(projectedObject);
        const bool structure = runtimeObjectUsesStructureFootprint(
            state,
            *object
        );
        const POINT base{
            structure ? projectedObject.center.x : selectionCenter.x,
            structure
                ? projectedObject.center.y - 20
                : selectionCenter.y - 10
        };
        const POINT end{
            base.x + static_cast<LONG>(std::round(std::sin(radians) * 34.0)),
            base.y + static_cast<LONG>(std::round(-std::cos(radians) * 22.0))
        };
        MoveToEx(dc, base.x, base.y, nullptr);
        LineTo(dc, end.x, end.y);
    }

    SelectObject(dc, oldPen);
    DeleteObject(turretPen);
}

COLORREF runtimeProjectileColor(const RuntimeProjectileEffect& projectile) {
    if (projectile.bright) {
        return RGB(255, 246, 154);
    }

    const std::string projectileId = toLowerAsciiLocal(projectile.projectileId);
    const std::string projectileImageId =
        toLowerAsciiLocal(projectile.projectileImageId);
    const std::string weaponId = toLowerAsciiLocal(projectile.weaponId);
    if (projectileId.find("rocket") != std::string::npos
        || projectileId.find("missile") != std::string::npos
        || projectileImageId.find("rocket") != std::string::npos
        || projectileImageId.find("missile") != std::string::npos
        || weaponId.find("rocket") != std::string::npos
        || weaponId.find("missile") != std::string::npos) {
        return RGB(255, 185, 82);
    }
    if (projectileId.find("laser") != std::string::npos
        || projectileImageId.find("laser") != std::string::npos
        || weaponId.find("laser") != std::string::npos) {
        return RGB(255, 85, 85);
    }
    if (projectileId.find("shell") != std::string::npos
        || projectileImageId.find("shell") != std::string::npos
        || weaponId.find("shell") != std::string::npos
        || weaponId.find("cannon") != std::string::npos
        || weaponId.find("120mm") != std::string::npos
        || weaponId.find("105mm") != std::string::npos
        || projectileId.find("bullet") != std::string::npos
        || projectileImageId.find("bullet") != std::string::npos) {
        return RGB(206, 205, 188);
    }
    return RGB(246, 238, 132);
}

COLORREF runtimeProjectileHouseColor(const std::string& owner) {
    const std::string lower = toLowerAsciiLocal(owner);
    if (lower == "americans"
        || lower == "allies"
        || lower == "british"
        || lower == "french"
        || lower == "germans"
        || lower == "alliance") {
        return RGB(88, 168, 255);
    }
    if (lower == "russians"
        || lower == "soviet"
        || lower == "confederation"
        || lower == "africans"
        || lower == "arabs") {
        return RGB(255, 72, 64);
    }
    if (lower == "yuri" || lower == "yuricountry") {
        return RGB(190, 96, 238);
    }
    return RGB(96, 224, 144);
}

COLORREF runtimeImpactColor(const RuntimeImpactEffect& impact) {
    if (impact.death) {
        return RGB(255, 92, 64);
    }
    if (impact.bright) {
        return RGB(255, 238, 118);
    }

    const std::string anim = toLowerAsciiLocal(impact.animId);
    const std::string particle = toLowerAsciiLocal(impact.particleId);
    const std::string warhead = toLowerAsciiLocal(impact.warheadId);
    if (anim.find("sparks") != std::string::npos
        || anim.find("electric") != std::string::npos
        || anim.find("pulse") != std::string::npos
        || warhead.find("electric") != std::string::npos
        || particle.find("spark") != std::string::npos) {
        return RGB(122, 198, 255);
    }
    if (anim.find("fire") != std::string::npos
        || anim.find("flame") != std::string::npos
        || anim.find("explode") != std::string::npos
        || particle.find("fire") != std::string::npos
        || particle.find("flame") != std::string::npos) {
        return RGB(255, 156, 68);
    }
    if (anim.find("smoke") != std::string::npos
        || particle.find("smoke") != std::string::npos) {
        return RGB(172, 178, 174);
    }
    if (particle.find("water") != std::string::npos
        || particle.find("wake") != std::string::npos
        || particle.find("ripple") != std::string::npos
        || anim.find("water") != std::string::npos
        || anim.find("wake") != std::string::npos
        || anim.find("ripple") != std::string::npos) {
        return RGB(96, 164, 214);
    }
    return RGB(255, 222, 114);
}

bool drawRuntimeAnimPaletteShpAtPoint(
    HDC dc,
    const RECT& viewport,
    RuntimeWindowState& state,
    const std::string& imageId,
    int frameIndex,
    POINT center
) {
    RuntimeUiShpCacheEntry* image =
        loadRuntimeUiShpFrame(state, "animate", imageId, frameIndex);
    if (image == nullptr) {
        image = loadRuntimeUiShpFrame(state, "", imageId, frameIndex);
    }
    if (image == nullptr && frameIndex != 0) {
        image = loadRuntimeUiShpFrame(state, "animate", imageId, 0);
        if (image == nullptr) {
            image = loadRuntimeUiShpFrame(state, "", imageId, 0);
        }
    }
    const std::vector<RuntimePaletteColor>* palette =
        runtimeUiPaletteForEntry(state, image, "anim");
    if (image == nullptr || palette == nullptr) {
        return false;
    }

    const RuntimeShpFrameImage& frame = image->image;
    const int globalWidth =
        frame.globalWidth > 0 ? frame.globalWidth : frame.width;
    const int globalHeight =
        frame.globalHeight > 0 ? frame.globalHeight : frame.height;
    const int targetX = center.x - (globalWidth / 2) + frame.offsetX;
    const int targetY =
        center.y + (state.camera.tileHeight / 2) - globalHeight + frame.offsetY;
    const RECT imageRect{
        targetX,
        targetY,
        targetX + frame.width,
        targetY + frame.height
    };
    if (imageRect.left >= viewport.right
        || imageRect.right <= viewport.left
        || imageRect.top >= viewport.bottom
        || imageRect.bottom <= viewport.top) {
        return true;
    }

    const RuntimePixelSurfaceTarget target =
        runtimePixelSurfaceTargetForDc(state, dc);
    return drawRuntimeIndexedImage(
        dc,
        imageRect,
        frame,
        *palette,
        true,
        false,
        true,
        target.pixels,
        target.width,
        target.height,
        false,
        runtimeIndexedOpaqueAlpha,
        image->pcxFallback,
        image->pcxFallback
    );
}

void drawRuntimeCombatEffects(
    HDC dc,
    const RECT& viewport,
    RuntimeWindowState& state,
    const RuntimeMapRenderContext& renderContext
) {
    HGDIOBJ oldBrush = SelectObject(dc, GetStockObject(NULL_BRUSH));
    HGDIOBJ oldPen = SelectObject(dc, GetStockObject(DC_PEN));

    const bool rendererOwnsProjectileActors =
        renderContext.projectileActors != nullptr
        && !renderContext.projectileActors->empty();
    const bool rendererOwnsImpactActors =
        renderContext.impactActors != nullptr
        && !renderContext.impactActors->empty();

    if (!rendererOwnsProjectileActors) {
    for (const RuntimeProjectileEffect& projectile : state.projectiles) {
        if (runtimeProjectileIsNuclearDeathDetonation(projectile)
            || runtimeProjectileIsCrashDeathDetonation(projectile)) continue;
        const POINT from = runtimeScreenPointForCell(
            state,
            viewport,
            projectile.fromCell,
            projectile.fromLevel
        );
        const POINT to = runtimeScreenPointForCell(
            state,
            viewport,
            projectile.toCell,
            projectile.toLevel
        );
        const POINT projectilePoint = projectile.laser ? to
            : runtimeProjectileActorScreenPointWin32(
                makeRuntimeProjectileRenderActor(projectile, &state.rules, &state.art),
                viewport, state.camera);
        const std::string projectileImage =
            !projectile.projectileImageId.empty()
                ? projectile.projectileImageId
                : projectile.projectileId;
        const int projectileFrame =
            std::max(0, projectile.totalTicks - projectile.remainingTicks);
        const bool drewProjectileSprite =
            !projectile.laser
            && !projectileImage.empty()
            && (
                drawRuntimeAuxiliaryShpFrameWin32(
                    dc,
                    viewport,
                    projectilePoint,
                    renderContext,
                    state.camera,
                    state.renderCache,
                    projectileImage,
                    projectileFrame
                )
                || drawRuntimeAnimPaletteShpAtPoint(
                    dc,
                    viewport,
                    state,
                    projectileImage,
                    projectileFrame,
                    projectilePoint
                )
            );

        concord::ui::win32::MapNativeOverlayWin32::setPenColor(
            dc,
            projectile.houseColorLaser
                ? runtimeProjectileHouseColor(projectile.owner)
                : runtimeProjectileColor(projectile)
        );
        if (!drewProjectileSprite) {
            MoveToEx(dc, from.x, from.y, nullptr);
            LineTo(dc, projectilePoint.x, projectilePoint.y);
            if (projectile.laser) {
                MoveToEx(dc, from.x - 1, from.y, nullptr);
                LineTo(dc, projectilePoint.x - 1, projectilePoint.y);
                MoveToEx(dc, from.x + 1, from.y, nullptr);
                LineTo(dc, projectilePoint.x + 1, projectilePoint.y);
            }
        }
        if (!projectile.trailerAnimId.empty()
            || projectile.cluster > 0
            || projectile.bright) {
            const POINT trailStart{
                static_cast<LONG>(std::round(
                    projectilePoint.x - ((to.x - from.x) * 0.10)
                )),
                static_cast<LONG>(std::round(
                    projectilePoint.y - ((to.y - from.y) * 0.10)
                ))
            };
            MoveToEx(dc, trailStart.x, trailStart.y, nullptr);
            LineTo(dc, projectilePoint.x, projectilePoint.y);
        }
        if (!drewProjectileSprite) {
            HGDIOBJ oldProjectileBrush =
                SelectObject(dc, GetStockObject(DC_BRUSH));
            concord::ui::win32::MapNativeOverlayWin32::setBrushColor(dc, runtimeProjectileColor(projectile));
            const int radius =
                projectile.bright ? 5 : (projectile.animates ? 4 : 3);
            Ellipse(
                dc,
                projectilePoint.x - radius,
                projectilePoint.y - radius,
                projectilePoint.x + radius + 1,
                projectilePoint.y + radius + 1
            );
            if (projectile.cluster > 0) {
                const int sparkCount = std::min(projectile.cluster, 5);
                for (int spark = 0; spark < sparkCount; ++spark) {
                    const int offset = (spark - 2) * 3;
                    Ellipse(
                        dc,
                        projectilePoint.x + offset - 1,
                        projectilePoint.y + (spark % 2 == 0 ? -6 : 6) - 1,
                        projectilePoint.x + offset + 2,
                        projectilePoint.y + (spark % 2 == 0 ? -6 : 6) + 2
                    );
                }
            }
            SelectObject(dc, oldProjectileBrush);
        }
    }
    }

    if (!rendererOwnsImpactActors) {
    for (const RuntimeImpactEffect& impact : state.impactEffects) {
        if (!runtimeChronosphereSelectionVisibleToLocalOwner(state, impact)) continue;
        if (impact.lifecycleState == "GrindingAnimation"
            || impact.lifecycleState == "GrindingAnimationQueued") continue;
        const POINT center =
            runtimeScreenPointForCell(state, viewport, impact.cell, impact.level);
        const double age = 1.0
            - (static_cast<double>(impact.remainingTicks)
                / static_cast<double>(std::max(1, impact.totalTicks)));
        const std::string impactImage =
            !impact.animId.empty() ? impact.animId : impact.particleId;
        const int impactFrame =
            std::max(0, impact.totalTicks - impact.remainingTicks);
        const bool drewImpactSprite =
            !impactImage.empty()
            && (
                drawRuntimeAnimPaletteShpAtPoint(
                    dc,
                    viewport,
                    state,
                    impactImage,
                    impactFrame,
                    center
                )
                || drawRuntimeAuxiliaryShpFrameWin32(
                    dc,
                    viewport,
                    center,
                    renderContext,
                    state.camera,
                    state.renderCache,
                    impactImage,
                    impactFrame
                )
            );
        if (drewImpactSprite) {
            continue;
        }
        const int radius =
            std::max(2, static_cast<int>(std::round(impact.radius * (0.4 + age))));
        concord::ui::win32::MapNativeOverlayWin32::setPenColor(dc, runtimeImpactColor(impact));
        if (impact.cellSpread > 0.0) {
            const int spreadRadius =
                std::max(radius, static_cast<int>(std::round(impact.cellSpread * 18.0)));
            Ellipse(
                dc,
                center.x - spreadRadius,
                center.y - spreadRadius / 2,
                center.x + spreadRadius,
                center.y + spreadRadius / 2
            );
        }
        Ellipse(
            dc,
            center.x - radius,
            center.y - radius / 2,
            center.x + radius,
            center.y + radius / 2
        );
        const std::string particle = toLowerAsciiLocal(impact.particleId);
        const std::string anim = toLowerAsciiLocal(impact.animId);
        if (particle.find("smoke") != std::string::npos
            || anim.find("smoke") != std::string::npos) {
            const int smokeOffset =
                static_cast<int>(std::round(age * 18.0));
            Ellipse(
                dc,
                center.x - radius / 2,
                center.y - smokeOffset - radius,
                center.x + radius / 2,
                center.y - smokeOffset
            );
        }
        if (particle.find("fire") != std::string::npos
            || particle.find("flame") != std::string::npos
            || anim.find("fire") != std::string::npos
            || anim.find("flame") != std::string::npos) {
            MoveToEx(dc, center.x, center.y - radius, nullptr);
            LineTo(dc, center.x - radius / 2, center.y + radius / 2);
            LineTo(dc, center.x + radius / 2, center.y + radius / 2);
            LineTo(dc, center.x, center.y - radius);
        }
        if (impact.death) {
            MoveToEx(dc, center.x - radius, center.y - radius, nullptr);
            LineTo(dc, center.x + radius, center.y + radius);
            MoveToEx(dc, center.x + radius, center.y - radius, nullptr);
            LineTo(dc, center.x - radius, center.y + radius);
        }
    }
    if (const auto marker = runtimeLocalChronosphereRenderActor(state)) {
        const POINT center = runtimeScreenPoint(
            runtimeProjectCellXY(marker->x, marker->y, marker->level, state.camera),
            viewport, state.camera);
        if (!drawRuntimeAnimPaletteShpAtPoint(dc, viewport, state, marker->animId,
                marker->frameIndex, center)) {
            (void)drawRuntimeAuxiliaryShpFrameWin32(dc, viewport, center, renderContext,
                state.camera, state.renderCache, marker->animId, marker->frameIndex);
        }
    }
    }

    SelectObject(dc, oldPen);
    SelectObject(dc, oldBrush);
}

struct RuntimeCargoPipDisplay {
    bool available = false;
    int filledUnits = 0;
    int gemUnits = 0;
    int totalUnits = 0;
    int value = 0;
    int filledFrameIndex = 1;
};

int runtimeCargoPipFrameIndex(const std::string& pip) {
    const std::string normalized = toLowerAsciiLocal(trimAsciiLocal(pip));
    if (normalized == "yellow") {
        return 2;
    }
    if (normalized == "white" || normalized == "gray"
        || normalized == "grey") {
        return 3;
    }
    if (normalized == "red") {
        return 4;
    }
    if (normalized == "blue") {
        return 5;
    }
    return 1;
}

int runtimeGemCargoPipFrameIndex(RuntimeWindowState& state) {
    // The authored Tiberium PipScale reserves frame 2 for ore and frame 5
    // for gems. Falling back to another colored frame silently turns gems
    // red or yellow, so only use the stock blue frame when it really exists.
    if (runtimeUiShpFrameAvailable(
            state,
            "sidebar",
            "pips2",
            5,
            "palette"
        )) {
        return 5;
    }
    return -1;
}

RuntimeCargoPipDisplay runtimeCargoPipDisplayForObject(
    const RuntimeWindowState& state,
    const WorldObjectInstance& object
) {
    RuntimeCargoPipDisplay display;
    const RuntimeCachedCapabilityProfile& cached =
        runtimeCachedCapabilityProfileForObject(state, object);
    const std::string pipScale = toLowerAsciiLocal(cached.ui.pipScale);
    display.filledFrameIndex = runtimeCargoPipFrameIndex(cached.ui.pip);
    if (pipScale == "passengers" && cached.transport.passengerCapacity > 0) {
        display.totalUnits = cached.transport.passengerCapacity;
        display.filledUnits = std::clamp(
            runtimeTransportUsedSpace(state, object),
            0,
            display.totalUnits
        );
        display.available = true;
        return display;
    }
    if (pipScale == "ammo") {
        const UnitType* ammoRules = runtimeAmmoRulesForObject(
            state.rules,
            object
        );
        const BuildingType* buildingRules =
            object.kind == WorldObjectKind::Structure
            ? findRuntimeBuildingTypeById(state.rules, object.type)
            : nullptr;
        const int ammoCapacity = ammoRules != nullptr
                && ammoRules->ammo > 0
            ? ammoRules->ammo
            : runtimeInfantryServiceAmmoCapacity(buildingRules);
        if (ammoCapacity > 0) {
            display.totalUnits = ammoCapacity;
            display.filledUnits = std::clamp(
                object.currentAmmo,
                0,
                display.totalUnits
            );
            display.value = display.filledUnits;
            display.available = true;
        }
        return display;
    }
    if (pipScale != "tiberium"
        || runtimeObjectHidesRefineryStoragePips(state, object)) {
        return display;
    }
    display.filledFrameIndex = 2;

    if (runtimeObjectIsHarvester(state, object)) {
        display.totalUnits =
            std::max(1, runtimeHarvesterCargoCapacity(state, object));
        const auto taskIt = state.harvesterTasks.find(object.instanceId);
        if (taskIt != state.harvesterTasks.end()) {
            if (taskIt->second.cargoCapacity > 0) {
                display.totalUnits = std::max(1, taskIt->second.cargoCapacity);
            }
            display.filledUnits =
                std::clamp(taskIt->second.cargoUnits, 0, display.totalUnits);
            display.gemUnits =
                std::clamp(taskIt->second.cargoGemUnits, 0, display.filledUnits);
            display.value = std::max(0, taskIt->second.cargoValue);
        }
        display.available = display.totalUnits > 0;
        return display;
    }

    const int storageCapacity =
        runtimeResourceStorageCapacityForObject(state, object);
    if (storageCapacity > 0) {
        display.totalUnits = storageCapacity;
        display.filledUnits =
            runtimeResourceStorageFilledForCapacity(state, storageCapacity);
        display.gemUnits =
            std::clamp(
                runtimeResourceStorageUnitsForCapacity(
                    state,
                    state.economy.storedResourceGemUnits,
                    storageCapacity
                ),
                0,
                display.filledUnits
            );
        display.value = std::max(0, state.economy.storedResourceValue);
        display.available = true;
    }
    return display;
}

void drawRuntimeSelectedCargoPips(
    HDC dc,
    RuntimeWindowState& state,
    const RuntimeProjectedObject& projectedObject,
    const RECT& healthFrame
) {
    if (projectedObject.object == nullptr) {
        return;
    }

    const RuntimeCargoPipDisplay cargo =
        runtimeCargoPipDisplayForObject(state, *projectedObject.object);
    // Absorbing buildings use the native person pips along their foundation.
    if (!cargo.available || runtimeInfantryAbsorberType(state, *projectedObject.object) != nullptr) {
        return;
    }

    const int segmentCount = std::clamp(cargo.totalUnits, 1, 20);
    const int filledSegments =
        cargo.filledUnits <= 0
            ? 0
            : std::clamp(
                (cargo.filledUnits * segmentCount + cargo.totalUnits - 1)
                    / cargo.totalUnits,
                1,
                segmentCount
            );
    const int gemSegments =
        cargo.gemUnits <= 0 || filledSegments <= 0
            ? 0
            : std::clamp(
                (cargo.gemUnits * segmentCount + cargo.totalUnits - 1)
                    / cargo.totalUnits,
                1,
                filledSegments
            );
    const int segmentWidth = 4;
    const int segmentHeight = 4;
    const int gap = 1;
    const int totalWidth =
        (segmentCount * segmentWidth) + ((segmentCount - 1) * gap);
    const POINT selectionCenter =
        runtimeProjectedUnitSelectionCenter(projectedObject);
    const int left = selectionCenter.x - (totalWidth / 2);
    const int top = healthFrame.bottom + 2;
    bool objectCounted = false;

    const bool emptyFrameAvailable =
        runtimeUiShpFrameAvailable(state, "sidebar", "pips2", 0, "palette");
    const bool filledFrameAvailable =
        runtimeUiShpFrameAvailable(
            state,
            "sidebar",
            "pips2",
            cargo.filledFrameIndex,
            "palette"
        );
    const int pipFrameCount =
        runtimeUiShpFrameCount(state, "sidebar", "pips2", "palette", 24);
    const int gemFrameIndex =
        gemSegments > 0 ? runtimeGemCargoPipFrameIndex(state) : -1;
    state.lastSelectedCargoPipFrameCount = pipFrameCount;
    state.lastSelectedCargoPipGemFrameIndex =
        gemSegments > 0 ? gemFrameIndex : -1;
    for (int index = 0; index < segmentCount; ++index) {
        const RECT pipRect{
            left + (index * (segmentWidth + gap)),
            top,
            left + (index * (segmentWidth + gap)) + segmentWidth,
            top + segmentHeight
        };
        const bool filled = index < filledSegments;
        const bool gemFilled = filled && index < gemSegments;
        bool resourceDrawn = false;
        const bool selectedFilledFrameAvailable =
            gemFilled ? gemFrameIndex >= 0 : filledFrameAvailable;
        if (filled && selectedFilledFrameAvailable) {
            resourceDrawn = drawRuntimeUiShpFrameTransparent(
                dc,
                state,
                "sidebar",
                "pips2",
                gemFilled ? gemFrameIndex : cargo.filledFrameIndex,
                "palette",
                pipRect,
                true,
                true
            );
        } else if (!filled && emptyFrameAvailable) {
            resourceDrawn = drawRuntimeUiShpFrameTransparent(
                dc,
                state,
                "sidebar",
                "pips2",
                0,
                "palette",
                pipRect,
                true,
                true
            );
        }

        if (resourceDrawn) {
            ++state.lastSelectedCargoPipResourceDraws;
            if (gemFilled) {
                ++state.lastSelectedCargoPipGemResourceDraws;
            }
        } else {
            HBRUSH fallbackBrush = CreateSolidBrush(
                gemFilled
                    ? RGB(48, 112, 232)
                    : (filled ? RGB(220, 205, 64) : RGB(42, 46, 38))
            );
            FillRect(dc, &pipRect, fallbackBrush);
            DeleteObject(fallbackBrush);
            ++state.lastSelectedCargoPipFallbackDraws;
        }

        if (!objectCounted) {
            ++state.lastSelectedCargoPipObjects;
            objectCounted = true;
        }
        ++state.lastSelectedCargoPipSegments;
        if (filled) {
            ++state.lastSelectedCargoPipFilledSegments;
        }
        if (gemFilled) {
            ++state.lastSelectedCargoPipGemSegments;
        }
    }
}

struct RuntimeStructureSelectionFrameGeometry {
    POINT left{};
    POINT top{};
    POINT right{};
    POINT bottom{};
    RECT footprintBounds{0, 0, 0, 0};
    int verticalHeight = 0;
    bool valid = false;
};

POINT runtimeStructureFrameCrownPoint(
    POINT footprintCorner,
    int verticalHeight,
    int clearance = 0
) {
    footprintCorner.y -= std::max(0, verticalHeight)
        + std::max(0, clearance);
    return footprintCorner;
}

struct RuntimeStructureHealthBarLayout {
    POINT topEnd{};
    POINT leftEnd{};
    std::vector<POINT> segmentAnchors;
    RECT bounds{0, 0, 0, 0};
    bool valid = false;
};

RuntimeStructureHealthBarLayout runtimeStructureHealthBarLayout(
    const RuntimeStructureSelectionFrameGeometry& frameGeometry
) {
    RuntimeStructureHealthBarLayout layout;
    if (!frameGeometry.valid) {
        return layout;
    }

    constexpr int barClearance = 3;
    layout.topEnd = runtimeStructureFrameCrownPoint(
        frameGeometry.top,
        frameGeometry.verticalHeight,
        barClearance
    );
    layout.leftEnd = runtimeStructureFrameCrownPoint(
        frameGeometry.left,
        frameGeometry.verticalHeight,
        barClearance
    );
    if (layout.topEnd.x <= layout.leftEnd.x
        || layout.leftEnd.y <= layout.topEnd.y) {
        return layout;
    }

    // Preserve the crown edge's slope. Independently trimming the last
    // pip by its 10x7 bounding box tilts the whole strip by about 1.5 pixels.
    // Round each height from its actual raster X, keeping all pip centers
    // within half a pixel of one line parallel to the selection frame.
    const POINT firstAnchor{layout.topEnd.x - 5, layout.topEnd.y};
    const int deltaX = layout.leftEnd.x + 4 - firstAnchor.x;
    const int edgeRun = layout.topEnd.x - layout.leftEnd.x;
    const int edgeRise = layout.leftEnd.y - layout.topEnd.y;
    const int intervals = std::max(1, (std::abs(deltaX) + 3) / 4);
    layout.segmentAnchors.reserve(static_cast<std::size_t>(intervals + 1));
    for (int index = 0; index <= intervals; ++index) {
        const int x = firstAnchor.x + static_cast<int>(std::lround(
            static_cast<double>(deltaX) * index / intervals));
        const int y = firstAnchor.y + static_cast<int>(std::lround(
            static_cast<double>(firstAnchor.x - x) * edgeRise / edgeRun));
        layout.segmentAnchors.push_back(POINT{x, y});
    }
    layout.bounds = RECT{
        layout.leftEnd.x,
        layout.topEnd.y,
        layout.topEnd.x + 1,
        layout.segmentAnchors.back().y + 7
    };
    layout.valid = layout.bounds.right > layout.bounds.left
        && layout.bounds.bottom > layout.bounds.top
        && !layout.segmentAnchors.empty();
    return layout;
}

#include "simulation/buildings/RuntimeGarrisonPips.inl"

std::optional<std::pair<int, int>> runtimeVeterancyPipFrames(
    RuntimeWindowState& state
);

#include "ui/sidebar/RuntimeHealthPipStrip.inl"

void drawRuntimeSelectedHealthBar(
    HDC dc,
    RuntimeWindowState& state,
    const RuntimeProjectedObject& projectedObject,
    const RuntimeStructureSelectionFrameGeometry* selectionFrameGeometry
) {
    RuntimePerfTraceScope trace("overlayHealthBar", state.tick);
    if (projectedObject.object == nullptr) {
        return;
    }

    const WorldObjectInstance& object = *projectedObject.object;
#include "simulation/mod_extensions/RuntimeModShieldBar.inl"
    const int maxHealth = std::max(1, runtimeMaxHealthForObject(state, object));
    const int currentHealth = std::clamp(object.health, 0, maxHealth);
    const double healthRatio = static_cast<double>(currentHealth)
        / static_cast<double>(maxHealth);
    const SpecialMechanismRules& healthRules =
        state.rules.getSpecialMechanismRules();
    const double conditionRed = std::clamp(
        healthRules.conditionRed,
        0.0,
        1.0
    );
    const double conditionYellow = std::clamp(
        healthRules.conditionYellow,
        conditionRed,
        1.0
    );

    auto drawPixel = [&](int x, int y, COLORREF color) {
        SetPixelV(dc, x, y, color);
    };
    auto drawLine = [&](int x1, int y1, int x2, int y2, COLORREF color) {
        if (y1 == y2) {
            if (x2 < x1) {
                std::swap(x1, x2);
            }
            for (int x = x1; x <= x2; ++x) {
                drawPixel(x, y1, color);
            }
            return;
        }
        if (x1 == x2) {
            if (y2 < y1) {
                std::swap(y1, y2);
            }
            for (int y = y1; y <= y2; ++y) {
                drawPixel(x1, y, color);
            }
            return;
        }
        HPEN pen = CreatePen(PS_SOLID, 1, color);
        HGDIOBJ oldPen = SelectObject(dc, pen);
        MoveToEx(dc, x1, y1, nullptr);
        LineTo(dc, x2, y2);
        SelectObject(dc, oldPen);
        DeleteObject(pen);
    };

    if (runtimeObjectUsesStructureFootprint(state, object)) {
        if (selectionFrameGeometry == nullptr
            || !selectionFrameGeometry->valid) {
            return;
        }
        const RuntimeStructureHealthBarLayout layout =
            runtimeStructureHealthBarLayout(*selectionFrameGeometry);
        if (!layout.valid) {
            return;
        }
        const int maxSegments =
            static_cast<int>(layout.segmentAnchors.size());
        const int currentSegments = std::clamp(
            (currentHealth * maxSegments + maxHealth - 1) / maxHealth,
            currentHealth > 0 ? 1 : 0,
            maxSegments
        );

        COLORREF dark = RGB(0, 50, 0);
        COLORREF mid = RGB(0, 128, 0);
        COLORREF bright = RGB(0, 255, 0);
        if (healthRatio <= conditionYellow
            && healthRatio > conditionRed) {
            dark = RGB(50, 50, 0);
            mid = RGB(128, 128, 0);
            bright = RGB(255, 255, 0);
        } else if (healthRatio <= conditionRed) {
            dark = RGB(134, 17, 34);
            mid = RGB(204, 34, 34);
            bright = RGB(238, 68, 51);
        }
        const int filledFrameIndex = healthRatio <= conditionRed
            ? 4
            : healthRatio <= conditionYellow ? 2 : 1;
        const bool originalPipsAvailable =
            runtimeUiShpFrameAvailable(
                state,
                "sidebar",
                "pips",
                0,
                "palette"
            )
            && runtimeUiShpFrameAvailable(
                state,
                "sidebar",
                "pips",
                filledFrameIndex,
                "palette"
            );

        auto drawFilledSegment = [&](int x, int y) {
            drawLine(x, y, x + 1, y, mid);
            drawLine(x - 2, y + 1, x - 1, y + 1, mid);
            drawLine(x, y + 1, x + 1, y + 1, bright);
            drawLine(x + 2, y + 1, x + 3, y + 1, mid);
            drawLine(x - 4, y + 2, x - 3, y + 2, mid);
            drawLine(x - 2, y + 2, x + 3, y + 2, bright);
            drawLine(x + 4, y + 2, x + 5, y + 2, mid);
            drawLine(x - 2, y + 3, x - 1, y + 3, mid);
            drawLine(x, y + 3, x + 1, y + 3, bright);
            drawLine(x + 2, y + 3, x + 3, y + 3, mid);
            drawLine(x, y + 4, x + 1, y + 4, mid);
            drawLine(x - 4, y + 3, x - 4, y + 4, dark);
            drawLine(x - 4, y + 4, x - 3, y + 4, dark);
            drawLine(x - 3, y + 3, x - 3, y + 3, bright);
            drawLine(x - 2, y + 4, x - 1, y + 4, bright);
            drawLine(x, y + 5, x + 3, y + 5, dark);
            drawLine(x, y + 6, x + 1, y + 6, dark);
            drawLine(x + 2, y + 4, x + 3, y + 4, mid);
        };
        auto drawEmptySegment = [&](int x, int y) {
            const COLORREF gray = RGB(180, 180, 180);
            drawLine(x, y, x + 1, y, gray);
            drawLine(x - 2, y + 1, x - 1, y + 1, gray);
            drawLine(x + 2, y + 1, x + 3, y + 1, gray);
            drawLine(x - 4, y + 2, x - 3, y + 2, gray);
            drawLine(x + 4, y + 2, x + 5, y + 2, gray);
            drawLine(x - 2, y + 3, x - 1, y + 3, gray);
            drawLine(x + 2, y + 3, x + 3, y + 3, gray);
            drawLine(x, y + 4, x + 1, y + 4, gray);
            drawLine(x - 4, y + 3, x - 4, y + 4, RGB(0, 0, 0));
            drawLine(x - 4, y + 4, x - 3, y + 4, RGB(0, 0, 0));
            drawLine(x, y + 5, x + 3, y + 5, RGB(0, 0, 0));
            drawLine(x, y + 6, x + 1, y + 6, RGB(0, 0, 0));
        };

        for (int index = 0; index < maxSegments; ++index) {
            const POINT anchor = layout.segmentAnchors[
                static_cast<std::size_t>(index)
            ];
            const bool filled = index < currentSegments;
            if (originalPipsAvailable
                && drawRuntimeUiShpFrameNativeAt(
                    dc,
                    state,
                    "sidebar",
                    "pips",
                    filled ? filledFrameIndex : 0,
                    "palette",
                    anchor.x - 4,
                    anchor.y,
                    true
                )) {
                ++state.lastHealthPipResourceDraws;
            } else if (filled) {
                drawFilledSegment(anchor.x, anchor.y);
                ++state.lastHealthPipFallbackDraws;
            } else {
                drawEmptySegment(anchor.x, anchor.y);
                ++state.lastHealthPipFallbackDraws;
            }
        }
        drawRuntimeGarrisonPips(dc, state, object, *selectionFrameGeometry);
        state.lastStructureHealthBarBounds = layout.bounds;
        state.lastStructureHealthBarSegments = maxSegments;
        state.lastStructureHealthBarFilledSegments = currentSegments;
        drawRuntimeSelectedCargoPips(
            dc,
            state,
            projectedObject,
            layout.bounds
        );
        return;
    }

    const int barPixels = object.kind == WorldObjectKind::Unit ? 34 : 16;
    const RECT frame = runtimeUnitHealthFrame(projectedObject);
    const int left = frame.left;
    const int top = frame.top;
    const int borderFrameIndex = object.kind == WorldObjectKind::Unit ? 0 : 1;
    const bool originalBorderDrawn = drawRuntimeUiShpFrameNativeAt(
        dc,
        state,
        "sidebar",
        "pipbrd",
        borderFrameIndex,
        "palette",
        left,
        top,
        true
    );
    if (originalBorderDrawn) {
        ++state.lastHealthPipResourceDraws;
    } else {
        HBRUSH frameBrush = CreateSolidBrush(RGB(230, 230, 230));
        FrameRect(dc, &frame, frameBrush);
        DeleteObject(frameBrush);
        ++state.lastHealthPipFallbackDraws;
    }

    const int fillPixels = std::clamp(
        (currentHealth * barPixels + maxHealth - 1) / maxHealth,
        currentHealth > 0 ? 1 : 0,
        barPixels
    );
    bool originalFillDrawn = fillPixels == 0;
    if (fillPixels > 0) {
        if (const std::optional<std::pair<int, int>> rankFrames =
                runtimeVeterancyPipFrames(state)) {
            const int greenFrame = rankFrames->second + 1;
            const int fillFrame = healthRatio <= conditionRed
                ? greenFrame + 2
                : healthRatio <= conditionYellow ? greenFrame + 1 : greenFrame;
            RuntimeUiShpCacheEntry* fillImage = loadRuntimeUiShpFrame(
                state,
                "sidebar",
                "pips",
                fillFrame
            );
            const auto* fillPalette = fillImage != nullptr
                && fillImage->image.width == 2 && fillImage->image.height == 2
                ? runtimeUiPaletteForEntry(state, fillImage, "palette") : nullptr;
            if (fillPalette != nullptr) {
                originalFillDrawn = true;
                if (drawRuntimeHealthPipStrip(dc, state, *fillImage, *fillPalette,
                        frame.left + 1, frame.top + 1, fillPixels)) {
                    // Keep the original logical pip count, including clipped pips.
                    state.lastHealthPipResourceDraws += (fillPixels + 1) / 2;
                } else for (int x = 0; x < fillPixels; x += 2) {
                    const RECT fillRect{
                        frame.left + 1 + x,
                        frame.top + 1,
                        frame.left + 1 + std::min(fillPixels, x + 2),
                        frame.top + 3
                    };
                    const bool drawn = drawRuntimeUiShpFrameTransparent(
                        dc,
                        state,
                        "sidebar",
                        "pips",
                        fillFrame,
                        "palette",
                        fillRect,
                        true,
                        true
                    );
                    originalFillDrawn = originalFillDrawn && drawn;
                    if (drawn) {
                        ++state.lastHealthPipResourceDraws;
                    }
                }
            }
        }
    }
    if (!originalFillDrawn) {
        const COLORREF bright =
            healthRatio > conditionYellow ? RGB(0, 255, 0)
                : healthRatio > conditionRed ? RGB(255, 255, 0)
                : RGB(255, 0, 0);
        const COLORREF dim =
            healthRatio > conditionYellow ? RGB(0, 176, 0)
                : healthRatio > conditionRed ? RGB(176, 176, 0)
                : RGB(184, 32, 32);
        for (int x = 0; x < fillPixels; ++x) {
            const COLORREF color = (x % 2 == 0) ? bright : dim;
            drawPixel(frame.left + 1 + x, frame.top + 1, color);
            drawPixel(frame.left + 1 + x, frame.top + 2, color);
        }
        ++state.lastHealthPipFallbackDraws;
    }

    // Retail 0x6F6A8E positions capacity pips independently of the bracket delta.
    drawRuntimeSelectedCargoPips(dc, state, projectedObject,
        runtimeUnitHealthFrame(projectedObject, false));
}

std::optional<std::pair<int, int>> runtimeVeterancyPipFramesUnmemoized(
    RuntimeWindowState& state
) {
    // RA2 stores the 8x5 veteran chevron at frame 13 and the 8x13 elite
    // stack at 14. YR inserts one earlier pip, shifting the pair to 14/15.
    // Dimension-based discovery also keeps compatible modded atlases working.
    for (int veteranFrame = 10; veteranFrame < 20; ++veteranFrame) {
        RuntimeUiShpCacheEntry* veteran = loadRuntimeUiShpFrame(
            state,
            "sidebar",
            "pips",
            veteranFrame
        );
        if (veteran == nullptr
            || veteran->image.width != 8
            || veteran->image.height != 5) {
            continue;
        }
        RuntimeUiShpCacheEntry* elite = loadRuntimeUiShpFrame(
            state,
            "sidebar",
            "pips",
            veteranFrame + 1
        );
        if (elite != nullptr
            && elite->image.width == 8
            && elite->image.height == 13
            && runtimeUiPaletteForEntry(state, elite, "palette") != nullptr) {
            return std::pair<int, int>{veteranFrame, veteranFrame + 1};
        }
    }
    return std::nullopt;
}

std::optional<std::pair<int, int>> runtimeVeterancyPipFrames(RuntimeWindowState& state) {
    auto* batch = RuntimeInteractionUiResourceScope::forState(state);
    if (!batch) return runtimeVeterancyPipFramesUnmemoized(state);
    if (!batch->veterancyResolved) {
        batch->veterancyFrames = runtimeVeterancyPipFramesUnmemoized(state);
        batch->veterancyResolved = true;
    }
    return batch->veterancyFrames;
}

POINT runtimeVeterancyBadgeTopLeft(const RuntimeProjectedObject& projected, int width, int height) {
    if (projected.observerKind == WorldObjectKind::Structure) {
        return {projected.bounds.right - width - 2, projected.bounds.bottom - height - 2};
    }
    if (projected.observerKind == WorldObjectKind::Infantry
        && projected.spriteBounds.right > projected.spriteBounds.left
        && projected.spriteBounds.bottom > projected.spriteBounds.top) {
        // The SHP's cropped feet can be far above the fixed selection box.
        return {projected.spriteBounds.right - width / 2, projected.spriteBounds.bottom + 1};
    }
    return {projected.renderCenter.x + 4, projected.renderCenter.y + 4 - height};
}
void drawRuntimeVeterancyBadge(
    HDC dc,
    RuntimeWindowState& state,
    const RuntimeProjectedObject& projectedObject
) {
    if (projectedObject.object == nullptr
        || projectedObject.object->veterancy <= 0) {
        return;
    }
    const bool elite = projectedObject.object->veterancy >= 2;
    if (const std::optional<std::pair<int, int>> frames =
            runtimeVeterancyPipFrames(state)) {
        const int frameIndex = elite ? frames->second : frames->first;
        RuntimeUiShpCacheEntry* badgeImage = loadRuntimeUiShpFrame(
            state,
            "sidebar",
            "pips",
            frameIndex
        );
        if (badgeImage != nullptr) {
            const POINT badgePosition = runtimeVeterancyBadgeTopLeft(
                projectedObject, badgeImage->image.width, badgeImage->image.height);
            if (drawRuntimeUiShpFrameNativeAt(
                    dc,
                    state,
                    "sidebar",
                    "pips",
                    frameIndex,
                    "palette",
                    badgePosition.x,
                    badgePosition.y,
                    true
                )) {
                ++state.lastVeterancyResourceDraws;
                return;
            }
        }
    }

    ++state.lastVeterancyFallbackDraws;
    const std::wstring label = elite ? L"E" : L"V";
    const POINT fallbackPosition = runtimeVeterancyBadgeTopLeft(projectedObject, 14, 14);
    RECT badge{fallbackPosition.x, fallbackPosition.y, fallbackPosition.x + 14, fallbackPosition.y + 14};
    const int oldBkMode = SetBkMode(dc, TRANSPARENT);
    const COLORREF oldTextColor = SetTextColor(
        dc,
        elite ? RGB(255, 214, 64) : RGB(214, 232, 255)
    );
    DrawTextW(
        dc,
        label.c_str(),
        -1,
        &badge,
        DT_SINGLELINE | DT_CENTER | DT_VCENTER
    );
    SetTextColor(dc, oldTextColor);
    SetBkMode(dc, oldBkMode);
}

RuntimeStructureSelectionFrameGeometry
runtimeStructureSelectionFrameGeometry(
    const std::vector<POINT>& footprintCenters,
    int halfTileWidth,
    int halfTileHeight,
    int verticalHeight
) {
    RuntimeStructureSelectionFrameGeometry geometry;
    if (footprintCenters.empty()) {
        return geometry;
    }

    POINT leftCenter = footprintCenters.front();
    POINT topCenter = footprintCenters.front();
    POINT rightCenter = footprintCenters.front();
    POINT bottomCenter = footprintCenters.front();
    for (const POINT& center : footprintCenters) {
        if (center.x < leftCenter.x
            || (center.x == leftCenter.x && center.y > leftCenter.y)) {
            leftCenter = center;
        }
        if (center.y < topCenter.y
            || (center.y == topCenter.y && center.x < topCenter.x)) {
            topCenter = center;
        }
        if (center.x > rightCenter.x
            || (center.x == rightCenter.x && center.y > rightCenter.y)) {
            rightCenter = center;
        }
        if (center.y > bottomCenter.y
            || (center.y == bottomCenter.y && center.x > bottomCenter.x)) {
            bottomCenter = center;
        }
    }

    const int halfWidth = std::max(1, halfTileWidth);
    const int halfHeight = std::max(1, halfTileHeight);
    geometry.left = POINT{leftCenter.x - halfWidth, leftCenter.y};
    geometry.top = POINT{topCenter.x, topCenter.y - halfHeight};
    geometry.right = POINT{rightCenter.x + halfWidth, rightCenter.y};
    geometry.bottom = POINT{bottomCenter.x, bottomCenter.y + halfHeight};
    geometry.footprintBounds = RECT{
        geometry.left.x,
        geometry.top.y,
        geometry.right.x,
        geometry.bottom.y
    };
    // The cage describes the fixed foundation, not the current animation's
    // opaque envelope. Barrels, flags and recoil may extend outside it; their
    // separately collected sprite spans still participate in hit testing.
    geometry.verticalHeight = std::clamp(verticalHeight, 18, 4096);
    geometry.valid = true;
    return geometry;
}

POINT runtimeStructureFrameLegEnd(POINT from, POINT toward) {
    const double dx = static_cast<double>(toward.x - from.x);
    const double dy = static_cast<double>(toward.y - from.y);
    const double distance = std::hypot(dx, dy);
    if (distance <= 0.5) {
        return from;
    }
    const double length = std::clamp(distance * 0.28, 8.0, 42.0);
    return POINT{
        from.x + static_cast<int>(std::lround(dx * length / distance)),
        from.y + static_cast<int>(std::lround(dy * length / distance))
    };
}

int runtimeStructureFrameFoundationOverlap(int halfTileHeight) {
    return std::clamp(std::max(1, halfTileHeight) / 3, 4, 6);
}

POINT runtimeStructureFrameFoundationLegEnd(
    POINT footprintCorner,
    int halfTileHeight
) {
    footprintCorner.y +=
        runtimeStructureFrameFoundationOverlap(halfTileHeight);
    return footprintCorner;
}

int runtimeStructureSelectionArtHeight(
    const RuntimeWindowState& state,
    const WorldObjectInstance& object
) {
    const ArtType* art = runtimeArtTypeForObject(state, object);
    return art == nullptr ? 0 : std::max(0, art->height);
}

int runtimeStructureSelectionVerticalHeight(
    const RuntimeWindowState& state,
    const WorldObjectInstance& object
) {
    const long long artHeight = runtimeStructureSelectionArtHeight(state, object);
    const long long artHeightPixels = artHeight
        * std::max(4, state.camera.tileHeight / 3);
    return static_cast<int>(std::clamp(artHeightPixels, 18LL, 4096LL));
}

std::vector<POINT> runtimeStructureSelectionFootprintCenters(
    const RuntimeWindowState& state,
    const WorldObjectInstance& object,
    const RECT& viewport
) {
    const auto footprint = runtimeStructureFootprintForObject(state, object);
    const auto origin = runtimeCellPointForObject(object);
    const int level = terrainLevelAtRuntimeCell(state, origin.x, origin.y);
    std::vector<POINT> centers;
    centers.reserve(4);
    // A building has one foundation plane. Even a map-authored building
    // straddling a slope keeps a rectangular cage; terrain-aware hit cells
    // remain separate and unchanged.
    for (int dy : {0, std::max(1, footprint.height) - 1}) {
        for (int dx : {0, std::max(1, footprint.width) - 1}) {
            centers.push_back(runtimeScreenPoint(runtimeProjectCellXY(
                origin.x + dx, origin.y + dy, level, state.camera), viewport, state.camera));
        }
    }
    return centers;
}

void drawRuntimeStructureFootprintCornerFrame(
    HDC dc,
    const std::vector<POINT>& footprintCenters,
    int halfTileWidth,
    int halfTileHeight,
    int verticalHeight
) {
    const RuntimeStructureSelectionFrameGeometry geometry =
        runtimeStructureSelectionFrameGeometry(
            footprintCenters,
            halfTileWidth,
            halfTileHeight,
            verticalHeight
        );
    if (!geometry.valid) {
        return;
    }

    const auto drawCorner = [dc, &geometry, halfTileHeight](
        POINT footprintCorner,
        POINT firstFootprintNeighbor,
        POINT secondFootprintNeighbor
    ) {
        const POINT crown = runtimeStructureFrameCrownPoint(
            footprintCorner,
            geometry.verticalHeight
        );
        const POINT firstCrownNeighbor = runtimeStructureFrameCrownPoint(
            firstFootprintNeighbor,
            geometry.verticalHeight
        );
        const POINT secondCrownNeighbor = runtimeStructureFrameCrownPoint(
            secondFootprintNeighbor,
            geometry.verticalHeight
        );
        const POINT firstEnd = runtimeStructureFrameLegEnd(
            crown,
            firstCrownNeighbor
        );
        const POINT secondEnd = runtimeStructureFrameLegEnd(
            crown,
            secondCrownNeighbor
        );
        const POINT foundationEnd =
            runtimeStructureFrameFoundationLegEnd(
                footprintCorner,
                halfTileHeight
            );
        // The original bracket has its short corner legs on the crown and
        // drops vertically through the foundation edge. A small overlap keeps
        // the four posts visually attached to low ramps and building skirts;
        // drawing the short legs on the ground end would still flip the cage.
        MoveToEx(dc, crown.x, crown.y, nullptr);
        LineTo(dc, foundationEnd.x, foundationEnd.y);
        MoveToEx(dc, crown.x, crown.y, nullptr);
        LineTo(dc, firstEnd.x, firstEnd.y);
        MoveToEx(dc, crown.x, crown.y, nullptr);
        LineTo(dc, secondEnd.x, secondEnd.y);
    };
    drawCorner(geometry.left, geometry.top, geometry.bottom);
    drawCorner(geometry.top, geometry.left, geometry.right);
    drawCorner(geometry.right, geometry.top, geometry.bottom);
    drawCorner(geometry.bottom, geometry.left, geometry.right);
}

#include "render/buildings/RuntimeBuildingRepairRender.inl"

int drawRuntimeSkirmishCrates(
    HDC dc,
    const RECT& viewport,
    RuntimeWindowState& state,
    const RuntimeMapRenderContext& renderContext
) {
    if (state.skirmishCrates.empty()) {
        return 0;
    }

    int drawn = 0;
    const CrateRules& crateRules = state.rules.getCrateRules();
    for (const RuntimeCrateState& crate : state.skirmishCrates) {
        // This overlay is drawn after the world shroud compositor. Respect
        // exploration (including Gap Generator shroud) before drawing here.
        if (!crate.active || (!crate.authored && !state.config.crates && !state.campaignMode)
            || (runtimeLocalVisionRestricted(state)
                && !state.vision.isCellExploredBy(
                    state.economy.owner, crate.cell.x, crate.cell.y))) {
            continue;
        }
        const RuntimeProjectedPoint projected = runtimeProjectCellXY(
            crate.cell.x,
            crate.cell.y,
            terrainLevelAtRuntimeCell(state, crate.cell.x, crate.cell.y),
            state.camera
        );
        const POINT center = runtimeScreenPoint(projected, viewport, state.camera);
        if (!pointInRectInclusive(viewport, center)) {
            continue;
        }
        const std::string imageId = !trimAsciiLocal(crate.imageId).empty()
            ? trimAsciiLocal(crate.imageId)
            : runtimeCrateArtImageId(
                state.rules,
                crate.water ? crateRules.waterImage : crateRules.image
            );
        if (!imageId.empty()
            && drawRuntimeAuxiliaryShpFrameWin32(
                dc,
                viewport,
                center,
                renderContext,
                state.camera,
                state.renderCache,
                imageId,
                0,
                0,
                0,
                true
            )) {
            ++drawn;
        }
    }
    return drawn;
}

std::string runtimeFormatSuperWeaponTimer(int seconds) {
    seconds = std::max(0, seconds);
    std::ostringstream text;
    text << (seconds / 60)
         << ":"
         << std::setw(2)
         << std::setfill('0')
         << (seconds % 60);
    return text.str();
}

COLORREF runtimeSuperWeaponTimerColor(
    const RuntimeWindowState& state,
    const std::string& owner
) {
    const std::string ownerKey = toLowerAsciiLocal(trimAsciiLocal(owner));
    const auto found = state.ownerRemapColors.find(ownerKey);
    // LocalRadarColor deliberately overrides the local player's radar dots.
    // Timers identify houses by their actual chosen unit/building remap color.
    return found == state.ownerRemapColors.end()
        ? runtimeOwnerRadarColor(ownerKey)
        : found->second;
}

int runtimeSuperWeaponTimerTextWidth(const RuntimeWindowState&, const std::wstring&);
void drawRuntimeSuperWeaponTimerText(HDC, RECT, const RuntimeWindowState&, const std::wstring&, COLORREF);

void drawRuntimeSuperWeaponTimerList(
    HDC dc,
    const RECT& viewport,
    const RuntimeWindowState& state
) {
    std::vector<const SuperWeaponSidebarSnapshot*> timers;
    for (const SuperWeaponSidebarSnapshot& snapshot :
            state.superWeapons.sidebarSnapshots()) {
        if (runtimeSuperWeaponTimerVisible(snapshot)) {
            timers.push_back(&snapshot);
        }
    }
    if (timers.empty()) {
        return;
    }
    std::sort(
        timers.begin(),
        timers.end(),
        [](const SuperWeaponSidebarSnapshot* left,
           const SuperWeaponSidebarSnapshot* right) {
            return std::tie(
                left->owner,
                left->name,
                left->superWeaponId
            ) < std::tie(
                right->owner,
                right->name,
                right->superWeaponId
            );
        }
    );

    constexpr int margin = 8;
    constexpr int rowHeight = 18;
    const int availableWidth = std::max(
        0,
        static_cast<int>(viewport.right - viewport.left) - (margin * 2)
    );
    int contentWidth = 120;
    for (const auto* timer : timers) {
        const std::wstring label = runtimeSuperWeaponDisplayName(state, *timer);
        contentWidth = std::max(contentWidth, runtimeSuperWeaponTimerTextWidth(state, label) + 60);
    }
    const int width = std::min({320, availableWidth, contentWidth});
    const int bottom = static_cast<int>(viewport.bottom) - margin;
    const int right = static_cast<int>(viewport.right) - margin;
    const int availableHeight = std::max(
        0,
        bottom - static_cast<int>(viewport.top) - margin
    );
    const int rowCount = std::min(
        static_cast<int>(timers.size()),
        availableHeight / rowHeight
    );
    if (width < 120 || rowCount <= 0) {
        return;
    }

    // Grow upward beside the sidebar, on a compact translucent backdrop.
    const RECT listRect{
        right - width,
        bottom - (rowCount * rowHeight),
        right,
        bottom
    };
    const int savedDc = SaveDC(dc);
    IntersectClipRect(
        dc,
        viewport.left,
        viewport.top,
        viewport.right,
        viewport.bottom
    );
    HDC backdropDc = CreateCompatibleDC(dc);
    HBITMAP backdropPixel = CreateCompatibleBitmap(dc, 1, 1);
    if (backdropDc != nullptr && backdropPixel != nullptr) {
        HGDIOBJ oldBackdrop = SelectObject(backdropDc, backdropPixel);
        SetPixelV(backdropDc, 0, 0, RGB(0, 0, 0));
        const BLENDFUNCTION blend{AC_SRC_OVER, 0, 160, 0};
        GdiAlphaBlend(dc, listRect.left - 4, listRect.top - 3,
            width + 8, rowCount * rowHeight + 6, backdropDc, 0, 0, 1, 1, blend);
        SelectObject(backdropDc, oldBackdrop);
    }
    if (backdropPixel != nullptr) DeleteObject(backdropPixel);
    if (backdropDc != nullptr) DeleteDC(backdropDc);
    SetBkMode(dc, TRANSPARENT);

    for (int index = 0; index < rowCount; ++index) {
        const SuperWeaponSidebarSnapshot& snapshot = *timers[index];
        // Remaining ticks are simulation time. Game speed already controls
        // their consumption; using the pacing rate here would apply it twice.
        const int seconds = runtimeSuperWeaponRemainingSeconds(
            snapshot,
            state.config.fixedTickHz
        );
        const std::wstring label = runtimeSuperWeaponDisplayName(state, snapshot);
        const std::wstring timer = widenUtf8(runtimeFormatSuperWeaponTimer(seconds));
        const int rowTop = listRect.top + (index * rowHeight);
        const RECT labelRect{
            listRect.left,
            rowTop,
            listRect.right - 60,
            rowTop + rowHeight
        };
        const RECT timerRect{
            listRect.right - 54,
            rowTop,
            listRect.right,
            rowTop + rowHeight
        };
        const COLORREF color = runtimeSuperWeaponTimerColor(state, snapshot.owner);
        drawRuntimeSuperWeaponTimerText(dc, labelRect, state, label, color);
        drawRuntimeSuperWeaponTimerText(dc, timerRect, state, timer, color);
    }

    RestoreDC(dc, savedDc);
}

bool runtimeSuperWeaponTargetsGroundArea(
    const RuntimeWindowState& state,
    const std::string& superWeaponId
) {
    const SuperWeaponRule* rule = state.rules.findSuperWeaponType(superWeaponId);
    return rule != nullptr
        && (toLowerAsciiLocal(trimAsciiLocal(rule->type)) == "chronosphere"
            || toLowerAsciiLocal(trimAsciiLocal(rule->action)) == "chronosphere");
}

const SuperWeaponSidebarSnapshot* runtimeActiveLocalSuperWeaponTargeting(
    const RuntimeWindowState& state
) {
    const std::string localOwner = toLowerAsciiLocal(
        trimAsciiLocal(state.economy.owner)
    );
    const auto& multiplayerTarget =
        state.multiplayerIntentRouter.superWeapon();
    for (const SuperWeaponSidebarSnapshot* snapshot :
            runtimeVisibleSuperWeapons(state)) {
        if (snapshot == nullptr) {
            continue;
        }
        const bool localMultiplayerTargeting =
            runtimeUsesGameplayIntentRouter(state)
            && multiplayerTarget.has_value()
            && toLowerAsciiLocal(snapshot->superWeaponId)
                == toLowerAsciiLocal(multiplayerTarget->superWeaponId);
        if ((snapshot->targetSelectionActive || localMultiplayerTargeting)
            && (localOwner.empty()
                || toLowerAsciiLocal(trimAsciiLocal(snapshot->owner))
                    == localOwner)) {
            return snapshot;
        }
    }
    return nullptr;
}

void drawRuntimeSuperWeaponTargetRings(
    HDC dc,
    const RECT& viewport,
    const RuntimeWindowState& state
) {
    if (!state.mouseClientPointValid || state.rightPointer.active
        || !pointInRectInclusive(viewport, state.mouseClientPoint)) {
        return;
    }
    const SuperWeaponSidebarSnapshot* snapshot =
        runtimeActiveLocalSuperWeaponTargeting(state);
    if (snapshot == nullptr || snapshot->targetRange <= 0.0) {
        return;
    }

    const POINT target = approximateCellFromScreenPoint(
        state,
        viewport,
        state.mouseClientPoint
    );
    const double level = static_cast<double>(
        terrainLevelAtRuntimeCell(state, target.x, target.y)
    );
    const int ringCount = runtimeSuperWeaponTargetRingCount(*snapshot);
    if (ringCount <= 0) {
        return;
    }

    const int savedDc = SaveDC(dc);
    IntersectClipRect(
        dc,
        viewport.left,
        viewport.top,
        viewport.right,
        viewport.bottom
    );
    HPEN ringPen = CreatePen(
        PS_DOT,
        1,
        snapshot->firstTargetAccepted
            ? RGB(255, 224, 104)
            : RGB(112, 220, 248)
    );
    HGDIOBJ oldPen = SelectObject(dc, ringPen);
    HGDIOBJ oldBrush = SelectObject(dc, GetStockObject(NULL_BRUSH));
    constexpr int segments = 64;
    constexpr double tau = 6.28318530717958647692;
    for (int ring = 0; ring < ringCount; ++ring) {
        const double radius = snapshot->targetRange
            * static_cast<double>(ring + 1)
            / static_cast<double>(ringCount);
        std::array<POINT, segments + 1> points{};
        for (int segment = 0; segment <= segments; ++segment) {
            const double angle = tau
                * static_cast<double>(segment)
                / static_cast<double>(segments);
            const RuntimeProjectedPoint projected = runtimeProjectCellXY(
                static_cast<double>(target.x) + std::cos(angle) * radius,
                static_cast<double>(target.y) + std::sin(angle) * radius,
                level,
                state.camera
            );
            points[segment] = runtimeScreenPoint(
                projected,
                viewport,
                state.camera
            );
        }
        Polyline(dc, points.data(), static_cast<int>(points.size()));
    }

    if (snapshot->firstTargetAccepted
        && snapshot->firstTargetCell.x >= 0
        && snapshot->firstTargetCell.y >= 0) {
        const RuntimeProjectedPoint firstProjected = runtimeProjectCellXY(
            snapshot->firstTargetCell.x,
            snapshot->firstTargetCell.y,
            terrainLevelAtRuntimeCell(
                state,
                snapshot->firstTargetCell.x,
                snapshot->firstTargetCell.y
            ),
            state.camera
        );
        const POINT first = runtimeScreenPoint(
            firstProjected,
            viewport,
            state.camera
        );
        const RuntimeProjectedPoint targetProjected = runtimeProjectCellXY(
            target.x,
            target.y,
            level,
            state.camera
        );
        const POINT targetCenter = runtimeScreenPoint(
            targetProjected,
            viewport,
            state.camera
        );
        drawRuntimeIsoDiamond(dc, first, 9, 5);
        MoveToEx(dc, first.x, first.y, nullptr);
        LineTo(dc, targetCenter.x, targetCenter.y);
    }

    SelectObject(dc, oldBrush);
    SelectObject(dc, oldPen);
    DeleteObject(ringPen);
    RestoreDC(dc, savedDc);
}

#include "ui/selection/RuntimeSelectionFrameRaster.h"

#include "simulation/production/RuntimeFactoryRallyUi.inl"

bool runtimeInteractionNeedsProjectedObjects(const RuntimeWindowState& state,
    const RECT& viewport, bool forceProjection = false) {
    return forceProjection || !state.selectedObjectIds.empty()
        || !state.repairingStructureTicks.empty()
        || (state.mouseClientPointValid && pointInRectInclusive(viewport, state.mouseClientPoint))
        || std::getenv("CONCORD_DEBUG_TURRET_FACING") != nullptr
        || std::any_of(state.world.getObjects().begin(), state.world.getObjects().end(),
            [](const WorldObjectInstance& object) { return object.alive && object.veterancy > 0; });
}

void drawRuntimeInteractionOverlay(
    HDC dc,
    const RECT& clientRect,
    RuntimeWindowState& state,
    const RuntimeMapRenderContext& renderContext,
    bool forceProjection = false,
    bool useResourceBatch = true,
    bool usePathBatch = true
) {
    RuntimePerfTraceScope trace("overlayInteraction", state.tick);
    state.lastSelectedCargoPipObjects = 0;
    state.lastSelectedCargoPipSegments = 0;
    state.lastSelectedCargoPipFilledSegments = 0;
    state.lastSelectedCargoPipGemSegments = 0;
    state.lastSelectedCargoPipResourceDraws = 0;
    state.lastSelectedCargoPipGemResourceDraws = 0;
    state.lastSelectedCargoPipFallbackDraws = 0;
    state.lastSelectedCargoPipGemFrameIndex = -1;
    state.lastSelectedCargoPipFrameCount = 0;
    state.lastTargetLineOrdersDrawn = 0;
    if (!state.world.getSummary().loaded) {
        return;
    }

    const RECT viewport = runtimeMapViewport(clientRect);
    RuntimeInteractionUiResourceScope uiResourceBatch(state, useResourceBatch);
    // Body geometry is only needed for an actual overlay or hit test. With
    // no selection/hover/repair/rank badge, replaying every body and turret
    // cannot contribute a pixel to this layer. Input paths still request the
    // full projection immediately when they need it.
    const bool needsProjectedObjects = runtimeInteractionNeedsProjectedObjects(state,
        viewport, forceProjection);
    static const std::vector<RuntimeProjectedObject> noProjectedObjects;
    if (!needsProjectedObjects) ensureRuntimeCameraForViewport(state, viewport);
    const std::vector<RuntimeProjectedObject>& projectedObjects = needsProjectedObjects
        ? runtimeProjectedObjectsForViewport(state, viewport) : noProjectedObjects;

    state.lastPlacementPreviewSpriteDraws = 0;
    state.lastPlacementPreviewSpriteRect = RECT{0, 0, 0, 0};
    state.lastPlacementPreviewCells = 0;
    state.lastPlacementPreviewValidCells = 0;
    state.lastStructureSelectionFrames = 0;
    state.lastStructureSelectionMaxHeight = 0;
    state.lastStructureSelectionMaxArtHeight = 0;
    state.lastStructureSelectionFootprintBounds = RECT{0, 0, 0, 0};
    state.lastStructureSelectionHitBounds = RECT{0, 0, 0, 0};
    state.lastUnitSelectionFrames = 0;
    state.lastUnitSelectionBounds = RECT{0, 0, 0, 0};
    state.lastUnitSelectionHitBounds = RECT{0, 0, 0, 0};
    state.lastUnitSelectionSpriteBounds = RECT{0, 0, 0, 0};
    state.lastUnitSelectionRenderCenter = POINT{0, 0};
    state.lastStructureHealthBarBounds = RECT{0, 0, 0, 0};
    state.lastStructureHealthBarSegments = 0;
    state.lastStructureHealthBarFilledSegments = 0;
    state.lastHealthPipResourceDraws = 0;
    state.lastHealthPipFallbackDraws = 0;
    state.lastVeterancyResourceDraws = 0;
    state.lastVeterancyFallbackDraws = 0;
    state.lastSelectedHealthBars = 0;
    state.lastHoveredStructureHealthBars = 0;
    state.lastHoveredUnitHealthBars = 0;

    drawRuntimePlacementPreview(dc, viewport, state, renderContext);
    if (state.runtimeTargetLinesEnabled) {
        state.lastTargetLineOrdersDrawn =
            drawRuntimeSelectedPaths(dc, viewport, state, usePathBatch, &projectedObjects);
    }
    drawRuntimeCombatEffects(dc, viewport, state, renderContext);
    if (state.campaignMode
        && state.tick
            < state.triggers.campaignChronoScreenEffectUntilTick
        && (state.tick / 2) % 2 == 0) {
        PatBlt(
            dc,
            viewport.left,
            viewport.top,
            viewport.right - viewport.left,
            viewport.bottom - viewport.top,
            DSTINVERT
        );
    }
    drawRuntimeSkirmishCrates(dc, viewport, state, renderContext);
    if (std::getenv("CONCORD_DEBUG_TURRET_FACING") != nullptr) {
        drawRuntimeTurretFacingOverlay(dc, projectedObjects, state);
    }
    drawRuntimeRepairOverlays(dc, viewport, state, projectedObjects);
    drawRuntimeSuperWeaponTargetRings(dc, viewport, state);
    drawRuntimeFactoryRallyPoint(dc, viewport, state);

    HGDIOBJ oldBrush = SelectObject(dc, GetStockObject(NULL_BRUSH));
    HPEN selectedPen = CreatePen(PS_SOLID, 2, RGB(113, 181, 255));
    HPEN structureSelectionPen = CreatePen(PS_SOLID, 2, RGB(236, 242, 238));
    HGDIOBJ oldPen = SelectObject(dc, selectedPen);
    RuntimeSelectionFrameRaster selectionFrameRaster(dc,
        dc == state.backBuffer.memoryDc ? static_cast<std::uint32_t*>(state.backBuffer.pixels) : nullptr,
        state.backBuffer.width, state.backBuffer.height);
    selectionFrameRaster.beginTrustedRestoredDcStateBatch();

    const RuntimeProjectedObject* hoveredObject = nullptr;
    if (state.mouseClientPointValid
        && pointInRectInclusive(viewport, state.mouseClientPoint)) {
        hoveredObject =
            findProjectedObjectAtPoint(projectedObjects, state.mouseClientPoint);
    }

    for (const RuntimeProjectedObject& projectedObject : projectedObjects) {
        if (projectedObject.object == nullptr) {
            continue;
        }

        const bool selected =
            selectionContains(state, projectedObject.object->instanceId);
        const bool hovered =
            hoveredObject != nullptr
            && hoveredObject->object != nullptr
            && hoveredObject->object->instanceId
                == projectedObject.object->instanceId;
        if (!selected && !hovered) {
            // Veterancy is an always-visible decoration in the original UI;
            // health and cargo pips remain selection/hover driven below.
            drawRuntimeVeterancyBadge(dc, state, projectedObject);
            selectionFrameRaster.markNativeGdiWrites();
            continue;
        }

        std::vector<POINT> structureFootprintCenters;
        const bool usesStructureFootprint =
            runtimeObjectUsesStructureFootprint(
                state,
                *projectedObject.object
            );
        RuntimeStructureSelectionFrameGeometry frameGeometry;
        int selectionHeight = 0;
        int artHeight = 0;
        if ((selected || hovered) && usesStructureFootprint) {
            structureFootprintCenters = runtimeStructureSelectionFootprintCenters(
                state, *projectedObject.object, viewport);
            if (!structureFootprintCenters.empty()) {
                selectionHeight = runtimeStructureSelectionVerticalHeight(
                    state,
                    *projectedObject.object
                );
                artHeight = runtimeStructureSelectionArtHeight(
                    state,
                    *projectedObject.object
                );
                frameGeometry = runtimeStructureSelectionFrameGeometry(
                    structureFootprintCenters,
                    projectedObject.footprintHalfWidth,
                    projectedObject.footprintHalfHeight,
                    selectionHeight
                );
            }
        }

        if (selected && frameGeometry.valid) {
            SelectObject(dc, structureSelectionPen);
            drawRuntimeStructureFootprintCornerFrame(
                dc,
                structureFootprintCenters,
                projectedObject.footprintHalfWidth,
                projectedObject.footprintHalfHeight,
                selectionHeight
            );
            ++state.lastStructureSelectionFrames;
            state.lastStructureSelectionMaxHeight = std::max(
                state.lastStructureSelectionMaxHeight,
                selectionHeight
            );
            state.lastStructureSelectionMaxArtHeight = std::max(
                state.lastStructureSelectionMaxArtHeight,
                artHeight
            );
            state.lastStructureSelectionFootprintBounds =
                frameGeometry.footprintBounds;
            state.lastStructureSelectionHitBounds = runtimeRenderPlacementNativeRect(projectedObject.bounds);
            SelectObject(dc, selectedPen);
            selectionFrameRaster.markNativeGdiWrites();
        } else if (selected
            && projectedObject.usesFootprintHit
            && !projectedObject.footprintHitCenters.empty()) {
            for (const RuntimeInputPixelPoint& footprintCenter : projectedObject.footprintHitCenters) {
                drawRuntimeIsoDiamond(
                    dc,
                    runtimeRenderPlacementNativePoint(footprintCenter),
                    projectedObject.footprintHalfWidth,
                    projectedObject.footprintHalfHeight
                );
            }
            selectionFrameRaster.markNativeGdiWrites();
        } else if (selected && !usesStructureFootprint) {
            RuntimePerfTraceScope selectionFrameTrace("overlaySelectionFrame", state.tick);
            const RECT selectionBounds = runtimeRenderPlacementNativeRect(projectedObject.selectionBounds);
            const POINT selectionCenter =
                runtimeProjectedUnitSelectionCenter(projectedObject);
            if (!selectionFrameRaster.draw(selectionBounds, selectionCenter)) {
                Rectangle(dc, selectionBounds.left, selectionBounds.top,
                    selectionBounds.right, selectionBounds.bottom);
                MoveToEx(dc, selectionCenter.x - 8, selectionCenter.y, nullptr);
                LineTo(dc, selectionCenter.x + 9, selectionCenter.y);
                MoveToEx(dc, selectionCenter.x, selectionCenter.y - 8, nullptr);
                LineTo(dc, selectionCenter.x, selectionCenter.y + 9);
                selectionFrameRaster.markNativeGdiWrites();
            }
            ++state.lastUnitSelectionFrames;
            state.lastUnitSelectionBounds = selectionBounds;
            state.lastUnitSelectionHitBounds = runtimeRenderPlacementNativeRect(projectedObject.bounds);
            state.lastUnitSelectionSpriteBounds =
                runtimeRenderPlacementNativeRect(projectedObject.spriteBounds);
            state.lastUnitSelectionRenderCenter =
                runtimeRenderPlacementNativePoint(projectedObject.renderCenter);
        }

        if ((selected || hovered)
            && runtimeObjectShouldDrawHealthBar(state, *projectedObject.object)) {
            drawRuntimeSelectedHealthBar(
                dc,
                state,
                projectedObject,
                frameGeometry.valid ? &frameGeometry : nullptr
            );
            selectionFrameRaster.markNativeGdiWrites();
            if (selected) {
                ++state.lastSelectedHealthBars;
            }
            if (hovered && usesStructureFootprint) {
                ++state.lastHoveredStructureHealthBars;
            } else if (hovered) {
                ++state.lastHoveredUnitHealthBars;
            }
        }
        drawRuntimeVeterancyBadge(dc, state, projectedObject);
        selectionFrameRaster.markNativeGdiWrites();
    }

    SelectObject(dc, oldPen);
    DeleteObject(structureSelectionPen);
    DeleteObject(selectedPen);

    if (state.leftPointer.active && state.leftPointer.moved && !state.forceAttackHeld) {
        HPEN dragPen = CreatePen(PS_DOT, 1, RGB(228, 238, 250));
        oldPen = SelectObject(dc, dragPen);
        const RECT dragRect =
            normalizedRect(POINT{state.leftPointer.start.x, state.leftPointer.start.y}, POINT{state.leftPointer.current.x, state.leftPointer.current.y});
        Rectangle(dc, dragRect.left, dragRect.top, dragRect.right, dragRect.bottom);
        SelectObject(dc, oldPen);
        DeleteObject(dragPen);
    }

    drawRuntimeSuperWeaponTimerList(dc, viewport, state);

    SelectObject(dc, oldBrush);
}

HCURSOR loadRuntimeStockCursor(int resourceId) {
    return LoadCursorW(nullptr, MAKEINTRESOURCEW(resourceId));
}

struct RuntimeMouseCursorFrame {
    int frameIndex = 0;
    int offsetX = 0;
    int offsetY = 0;
    std::string atlasId = "mouse";
};

RuntimeMouseCursorFrame runtimeSuperWeaponMouseCursorFrame(
    const SuperWeaponRule* rule,
    const std::string& fallbackId,
    bool valid,
    int phase
) {
    std::string signature = fallbackId;
    if (rule != nullptr) {
        signature += " " + rule->id;
        signature += " " + rule->type;
        signature += " " + rule->action;
    }
    signature = toLowerAsciiLocal(signature);
    const auto contains = [&signature](const char* token) {
        return signature.find(token) != std::string::npos;
    };
    const auto animated = [phase](int first, int count) {
        return RuntimeMouseCursorFrame{
            first + (std::max(0, phase) % std::max(1, count)),
            27,
            21,
            "mouse.sha"
        };
    };

    if (contains("forceshield") || contains("force shield")) {
        return animated(valid ? 450 : 460, 10);
    }
    if (contains("genetic") || contains("mutator")) {
        return valid ? animated(470, 10)
                     : RuntimeMouseCursorFrame{41, 27, 21};
    }
    if (contains("airstrike") || contains("air strike")) {
        return valid ? animated(480, 8)
                     : RuntimeMouseCursorFrame{41, 27, 21};
    }
    if (contains("dominator")) {
        return valid ? animated(488, 8)
                     : RuntimeMouseCursorFrame{41, 27, 21};
    }
    if (contains("psychicreveal") || contains("psychic reveal")) {
        return valid ? animated(496, 8)
                     : RuntimeMouseCursorFrame{41, 27, 21};
    }
    if (contains("spyplane") || contains("spy plane")) {
        return valid ? animated(504, 8)
                     : RuntimeMouseCursorFrame{41, 27, 21};
    }
    if (contains("paradrop") || contains("para drop")) {
        return valid ? animated(259, 10)
                     : RuntimeMouseCursorFrame{41, 27, 21};
    }
    if (contains("lightning")) {
        return valid ? animated(279, 20)
                     : RuntimeMouseCursorFrame{41, 27, 21};
    }
    if (contains("multimissile") || contains("nuke")) {
        return valid ? animated(319, 10)
                     : RuntimeMouseCursorFrame{41, 27, 21};
    }
    if (contains("ironcurtain") || contains("iron curtain")) {
        return valid ? animated(346, 5)
                     : RuntimeMouseCursorFrame{41, 27, 21};
    }
    if (contains("chronosphere") || contains("chronowarp")
        || contains("chrono sphere") || contains("chrono warp")) {
        return valid ? animated(357, 12)
                     : RuntimeMouseCursorFrame{41, 27, 21};
    }
    return valid
        ? RuntimeMouseCursorFrame{53 + (std::max(0, phase) % 5), 27, 21}
        : RuntimeMouseCursorFrame{41, 27, 21};
}

RECT runtimeMouseCursorImageRect(
    POINT point,
    const RuntimeMouseCursorFrame& cursor,
    const RuntimeShpFrameImage& image
) {
    const int left = point.x - cursor.offsetX + image.offsetX;
    const int top = point.y - cursor.offsetY + image.offsetY;
    return {
        left,
        top,
        left + image.width,
        top + image.height
    };
}

bool runtimeSelectedFactoryCanBePrimary(
    const RuntimeWindowState& state, const WorldObjectInstance& object
) {
    const auto* factory = runtimeSelectedUnitProductionFactory(state);
    return factory && factory->instanceId == object.instanceId
        && !state.playerLocalCommands.rallyTargeting && !state.playerLocalCommands.followTargeting;
}

bool runtimeCursorOverSelectedSecondaryAction(
    RuntimeWindowState& state,
    const RECT& viewport,
    POINT point
) {
    const std::vector<RuntimeProjectedObject>& projectedObjects =
        runtimeProjectedObjectsForViewport(state, viewport);
    for (const RuntimeProjectedObject& projectedObject : projectedObjects) {
        const WorldObjectInstance* object = projectedObject.object;
        if (object == nullptr
            || !pointInRectInclusive(projectedObject.bounds, point)
            || !selectionContains(state, object->instanceId)
            || !runtimeObjectHasSecondaryAction(state, *object)) {
            continue;
        }

        return true;
    }

    return false;
}

const WorldObjectInstance* runtimeCursorObjectAtPoint(
    RuntimeWindowState& state,
    const RECT& viewport,
    POINT point
) {
    const std::vector<RuntimeProjectedObject>& projectedObjects =
        runtimeProjectedObjectsForViewport(state, viewport);
    const RuntimeProjectedObject* projected =
        findProjectedObjectAtPoint(projectedObjects, point);
    return projected == nullptr ? nullptr : projected->object;
}

enum class RuntimeTargetCursorIntent {
    Attack,
    AttackOutOfRange,
    NoAction,
    Enter,
    InfantryAbsorb,
    Capture,
    UnitRepair,
    EngineerRepair,
    InfantryHeal,
    IvanBomb,
    Disarm,
    Disguise,
    MindControl,
    C4,
    NoEnter
};

RuntimeTargetCursorIntent runtimeTargetCursorIntent(
    RuntimeWindowState& state,
    const WorldObjectInstance& target
) {
    if (runtimeSelectionOffersSlaveDelivery(state, target))
        return RuntimeTargetCursorIntent::Enter;
    if (runtimeSelectionOffersHarvesterUnload(state, target)) {
        return RuntimeTargetCursorIntent::Enter;
    }
    if (runtimeSelectionCanUseRepairDepot(state, target)) {
        return RuntimeTargetCursorIntent::Enter;
    }

    std::vector<int> selectedIds = state.selectedObjectIds;
    std::sort(selectedIds.begin(), selectedIds.end());
    selectedIds.erase(
        std::unique(selectedIds.begin(), selectedIds.end()),
        selectedIds.end()
    );
    std::vector<const WorldObjectInstance*> selectedObjects;
    selectedObjects.reserve(selectedIds.size());
    for (int objectId : selectedIds) {
        const WorldObjectInstance* selected = findObjectById(state, objectId);
        if (selected != nullptr && selected->tankBunkerOccupantId >= 0) {
            selected = findObjectById(state, selected->tankBunkerOccupantId);
        }
        if (selected != nullptr
            && selected->alive
            && !runtimeObjectDisabledByParasite(state, objectId)
            && selected->instanceId != target.instanceId) {
            selectedObjects.push_back(selected);
        }
    }

    bool blockedEnterRelationship = false;
    const RuntimeTransportProfile transport =
        runtimeTransportProfileForObject(state, target);
    const BuildingType* targetBuilding =
        target.kind == WorldObjectKind::Structure
            ? findRuntimeBuildingTypeById(state.rules, target.type)
            : nullptr;
    const bool targetHasTimedBomb = state.specialMechanismsInitialized
        && state.specialMechanisms.timedBombs().find(target.instanceId)
            != state.specialMechanisms.timedBombs().end();

    if (targetBuilding != nullptr && targetBuilding->bunker) {
        bool alliedVehicle = false;
        for (const auto* selected : selectedObjects) {
            if (selected->kind != WorldObjectKind::Unit
                || !runtimeOwnersAreAllied(state, selected->owner, target.owner)) continue;
            alliedVehicle = true;
            if (runtimeObjectCanEnterTankBunker(state, *selected, target, true)
                && runtimeTankBunkerEntryCell(state, *selected, target)) return RuntimeTargetCursorIntent::Enter;
        }
        if (alliedVehicle) return RuntimeTargetCursorIntent::NoEnter;
    }
    if (targetBuilding != nullptr && targetBuilding->infantryAbsorb) {
        bool alliedInfantry = false;
        for (const auto* selected : selectedObjects) {
            if (selected->kind != WorldObjectKind::Infantry
                || !runtimeOwnersAreAllied(state, selected->owner, target.owner)) {
                continue;
            }
            alliedInfantry = true;
            if (runtimeObjectCanEnterTransport(state, *selected, target, true)
                && runtimeTransportEntryCell(state, *selected, target).has_value()) {
                return RuntimeTargetCursorIntent::InfantryAbsorb;
            }
        }
        if (alliedInfantry) return RuntimeTargetCursorIntent::NoEnter;
    }

    // Match queueRuntimeTargetAbility precedence: explicit Ivan/disarm
    // weapon relationships win first, then a legal C4 source, then the
    // enter/capture/repair/attack relationships below.
    for (const WorldObjectInstance* selected : selectedObjects) {
        const RuntimeWeaponProfile weapon = runtimeWeaponProfileForObject(
            state,
            *selected,
            &target
        );
        if (!runtimeBridgeHutDemolitionCommandLegal(state, target, weapon.weapon, weapon.warhead,
                runtimeObjectHasC4Capability(state.rules, *selected))) continue;
        if (weapon.warhead != nullptr) {
            if (weapon.warhead->bombDisarm && targetHasTimedBomb) {
                return RuntimeTargetCursorIntent::Disarm;
            }
            if (weapon.warhead->ivanBomb && !targetHasTimedBomb
                && runtimeBuildingBombOrderRelationLegal(state, *selected, target, false)) {
                return RuntimeTargetCursorIntent::IvanBomb;
            }
        }
    }
    const std::optional<int> c4Source =
        runtimeSelectedC4SourceIdForTarget(state, target);
    if (c4Source.has_value()) {
        // A pending lease consumes the same click in the command path. Keep
        // the cursor blocked instead of falling through to an attack that
        // will never be issued.
        return runtimeTargetHasPendingC4Lease(state, target.instanceId)
            ? RuntimeTargetCursorIntent::NoAction
            : RuntimeTargetCursorIntent::C4;
    }

    for (const WorldObjectInstance* selected : selectedObjects) {
        const RuntimeWeaponProfile profile = runtimeWeaponProfileForObject(
            state, *selected, &target);
        if (runtimeWeaponRepairTargetLegal(state, *selected, target, profile)) {
            return target.kind == WorldObjectKind::Infantry
                ? RuntimeTargetCursorIntent::InfantryHeal
                : RuntimeTargetCursorIntent::UnitRepair;
        }
    }

    // Target abilities are classified for the full selection before any
    // ordinary attacker is considered. This mirrors queueRuntimeTargetAbility
    // and keeps a leading tank from hiding a later engineer/spy/occupier.
    for (const WorldObjectInstance* selected : selectedObjects) {
        if (transport.canTransport
            && (selected->kind == WorldObjectKind::Infantry || selected->kind == WorldObjectKind::Unit)
            && runtimeOwnersAreAllied(
                state,
                selected->owner,
                target.owner
            )) {
            if (runtimeObjectCanEnterTransport(
                    state,
                    *selected,
                    target,
                    true
                ) && (!runtimeAmphibiousTransport(state, target)
                    || runtimeTransportEntryCell(state, *selected, target).has_value())) {
                return RuntimeTargetCursorIntent::Enter;
            }
            blockedEnterRelationship = true;
        }
    }

    if (targetBuilding != nullptr) {
        for (const WorldObjectInstance* selected : selectedObjects) {
            const RuntimeInfantryServiceEvaluation service =
                runtimeInfantryServiceEvaluationFor(
                    state,
                    *selected,
                    target
                );
            if (!service.relationship) {
                continue;
            }
            if (service.usable
                && findRuntimeEngineerEntryCell(
                    state,
                    *selected,
                    target,
                    "infantry-service-cursor",
                    2
                ).has_value()) {
                return RuntimeTargetCursorIntent::Enter;
            }
            blockedEnterRelationship = true;
        }

        for (const WorldObjectInstance* selected : selectedObjects) {
            const UnitType* selectedRules = findRuntimeUnitType(
                state.rules,
                *selected
            );
            if (selectedRules != nullptr && selectedRules->infiltrate) {
                if (runtimeSpyCanInfiltrateTarget(state, *selected, target)) {
                    return RuntimeTargetCursorIntent::Enter;
                }
                blockedEnterRelationship = true;
            }
        }

        if (targetBuilding->grinding) {
            for (const WorldObjectInstance* selected : selectedObjects) {
                if (runtimeGrindingTeamEligibility(
                        state,
                        target.instanceId,
                        selected->instanceId
                    ) == RuntimeGrindingTeamEligibility::Accepted
                    && (runtimeGrindingEntryContinuesToHost(state, target.instanceId, selected->instanceId)
                        || runtimeGrindingEntryCell(state, *selected, target).has_value())) {
                    return RuntimeTargetCursorIntent::Enter;
                }
            }
            // queueRuntimeGrindingTarget consumes clicks on a grinder even
            // when every selected source is ineligible, so do not let a
            // later engineer/weapon branch advertise a different action.
            return RuntimeTargetCursorIntent::NoEnter;
        }

        for (const WorldObjectInstance* selected : selectedObjects) {
            const RuntimeEngineerProfile engineer =
                runtimeEngineerProfileForObject(state, *selected);
            if (engineer.canCapture || engineer.canRepair
                || engineer.canBridgeRepair) {
                const RuntimeEngineerAction action =
                    runtimeEngineerActionForStructure(
                        state,
                        *selected,
                        target
                    );
                if (action == RuntimeEngineerAction::Capture) {
                    return RuntimeTargetCursorIntent::Capture;
                }
                if (action == RuntimeEngineerAction::Repair
                    || action == RuntimeEngineerAction::BridgeRepair) {
                    return RuntimeTargetCursorIntent::EngineerRepair;
                }
                blockedEnterRelationship = true;
            }
        }

        for (const WorldObjectInstance* selected : selectedObjects) {
            const RuntimeOccupyProfile occupy =
                runtimeOccupyProfileForObject(state, *selected);
            if (occupy.canOccupy) {
                if (runtimeObjectCanOccupyTarget(
                        state,
                        *selected,
                        target,
                        true
                )) {
                    return RuntimeTargetCursorIntent::Enter;
                }
                // Ordinary own buildings offer no garrison action. Keep the
                // original NoAction cursor rather than advertising blocked
                // entry just because the selected infantry is an Occupier.
                const bool ordinaryOwnBuilding =
                    selected->owner == state.economy.owner
                    && target.owner == state.economy.owner
                    && !(targetBuilding->canBeOccupied
                        && targetBuilding->maxNumberOccupants > 0);
                if (!ordinaryOwnBuilding) blockedEnterRelationship = true;
            }
        }
    }

    for (const WorldObjectInstance* selected : selectedObjects) {
        const RuntimeWeaponProfile weapon = runtimeWeaponProfileForObject(
            state,
            *selected,
            &target
        );
        const bool allied = runtimeOwnersAreAllied(
            state,
            selected->owner,
            target.owner
        );
        if (weapon.weapon != nullptr
            && weapon.warhead != nullptr
            && weapon.warhead->mindControl
            && (weapon.weapon->damage > 0 || runtimeWeaponHasAttachEffect(state.rules, weapon.weapon))
            && weapon.weapon->range > 0.0
            && runtimeObjectHasAttackAmmo(state.rules, *selected)
            && !runtimeSpyDisguiseBlocksAttack(
                state,
                *selected,
                target,
                false
            )
            && runtimePsychicCanAttackTarget(
                state,
                *selected,
                target,
                true,
                !allied
            )) {
            return RuntimeTargetCursorIntent::MindControl;
        }
    }

    for (const WorldObjectInstance* selected : selectedObjects) {
        const RuntimeWeaponProfile weapon = runtimeWeaponProfileForObject(
            state,
            *selected,
            &target
        );
        if (weapon.warhead != nullptr
            && weapon.warhead->makesDisguise
            && runtimeSpyCanApplyMakesDisguise(
                state,
                selected->instanceId,
                target.instanceId,
                weapon.warhead->id
            )) {
            return RuntimeTargetCursorIntent::Disguise;
        }
    }

    bool attackRelationship = false;
    for (const WorldObjectInstance* selected : selectedObjects) {
        const RuntimeWeaponProfile weapon = runtimeWeaponProfileForObject(
            state,
            *selected,
            &target
        );
        if (weapon.warhead != nullptr && weapon.warhead->ivanBomb
            && !runtimeBuildingBombOrderRelationLegal(state, *selected, target, false)) continue;
        if (!runtimeBridgeHutDemolitionCommandLegal(state, target, weapon.weapon, weapon.warhead,
                runtimeObjectHasC4Capability(state.rules, *selected))) continue;
        if (!selected->garrisonOccupantIds.empty()
            && runtimeGarrisonHostCanAttackTarget(state, *selected, target)) {
            attackRelationship = true;
            const double distanceToTarget =
                runtimeCellDistanceToObjectFootprint(
                    state,
                    runtimeCellPointForObject(*selected),
                    target
                );
            if (distanceToTarget
                    <= state.garrisons.config().occupyWeaponRange) {
                return RuntimeTargetCursorIntent::Attack;
            }
            continue;
        }
        if (weapon.weapon != nullptr
            && (weapon.weapon->damage > 0 || runtimeWeaponHasAttachEffect(state.rules, weapon.weapon))
            && runtimeWeaponHasAttackRange(*weapon.weapon)
            && runtimeObjectHasAttackAmmo(state.rules, *selected)
            && !runtimeSpyDisguiseBlocksAttack(
                state,
                *selected,
                target,
                false
            )
            && runtimePsychicCanAttackTarget(
                state,
                *selected,
                target,
                true,
                runtimeOrdinaryAttackRelationLegal(state, *selected, target)
            )) {
            attackRelationship = true;
            const double distanceToTarget = runtimeWeaponDistanceToTarget(
                state,
                *selected,
                target,
                *weapon.weapon
            );
            const bool inRange = distanceToTarget
                    <= runtimeEffectiveWeaponRange(
                        state,
                        *selected,
                        target,
                        *weapon.weapon
                    )
                && runtimeWeaponHasLineOfSight(
                    state,
                    *selected,
                    target,
                    *weapon.weapon
                );
            if (inRange) {
                return RuntimeTargetCursorIntent::Attack;
            }
        }
    }

    if (attackRelationship) {
        return RuntimeTargetCursorIntent::AttackOutOfRange;
    }
    return blockedEnterRelationship
        ? RuntimeTargetCursorIntent::NoEnter
        : RuntimeTargetCursorIntent::NoAction;
}

#include "ui/cursor/RuntimeHarvesterCursor.inl"
#include "ui/cursor/RuntimePanCursor.inl"

std::optional<RuntimeMouseCursorFrame> runtimeMouseCursorFrameForPoint(
    RuntimeWindowState& state,
    const RECT& clientRect,
    POINT point
) {
    if (state.playerCommunication.diplomacyOpen) return std::nullopt;
    const RECT viewport = runtimeMapViewport(clientRect);
    if (!state.mouseClientPointValid
        || !pointInRectInclusive(viewport, point)) {
        return std::nullopt;
    }

    // The pan cross temporarily overrides targeting without changing its state.
    if (state.rightPointer.active) {
        return runtimePanMouseCursorFrame(state);
    }
    const int phase = std::max(0, state.tick / 4);

    const WorldObjectInstance* target =
        runtimeCursorObjectAtPoint(state, viewport, point);
    if (const SuperWeaponSidebarSnapshot* activeSuperWeapon =
            runtimeActiveLocalSuperWeaponTargeting(state)) {
        const POINT targetPoint = approximateCellFromScreenPoint(
            state,
            viewport,
            point
        );
        const int objectId = runtimeSuperWeaponTargetsGroundArea(
                state, activeSuperWeapon->superWeaponId) || target == nullptr
            ? -1 : target->instanceId;
        SuperWeaponWorldContext context = runtimeSuperWeaponContext(state);
        std::string reason;
        const bool valid = state.superWeapons.previewTarget(
            activeSuperWeapon->owner,
            activeSuperWeapon->superWeaponId,
            {{targetPoint.x, targetPoint.y}, objectId},
            context,
            &reason
        );
        return runtimeSuperWeaponMouseCursorFrame(
            state.rules.findSuperWeaponType(activeSuperWeapon->superWeaponId),
            activeSuperWeapon->superWeaponId,
            valid,
            phase
        );
    }
    if (state.activeSidebarTool == RuntimeSidebarTool::Sell) {
        if (target == nullptr || !runtimeStructureCanBeSold(state, *target)) {
            return RuntimeMouseCursorFrame{149, 27, 21};
        }
        return RuntimeMouseCursorFrame{129 + (phase % 10), 27, 21};
    }
    if (state.activeSidebarTool == RuntimeSidebarTool::Repair) {
        if (target == nullptr
            || !runtimeStructureCanStartRepair(state, *target)) {
            return RuntimeMouseCursorFrame{190, 27, 21};
        }
        // Bare wrench rocks about its head. The rotating wrench with green
        // arrows (150..169) belongs to unit/engineer repair orders.
        return RuntimeMouseCursorFrame{170 + runtimeRepairCursorPhase(state), 27, 21};
    }
    if (runtimeSelectedPlacement(state).has_value()
        && !runtimePlacementValidForUi(state)) {
        return RuntimeMouseCursorFrame{41, 27, 21};
    }
    if (state.forceAttackHeld && !state.selectedObjectIds.empty()
        && !runtimeSelectedPlacement(state).has_value()) {
        return RuntimeMouseCursorFrame{53 + (phase % 5), 27, 21};
    }
    if (state.leftPointer.active) {
        // Pressing or box-selecting uses the original silver arrow.
        return RuntimeMouseCursorFrame{0, 0, 0};
    }
    if ((target == nullptr || state.playerLocalCommands.rallyTargeting)
        && runtimeSelectedFactoryCanSetRallyPoint(state)
        && !(GetKeyState(VK_SHIFT) & 0x8000) && !(GetKeyState(VK_CONTROL) & 0x8000)
        && !(GetKeyState(VK_MENU) & 0x8000)) {
        const POINT cell = approximateCellFromScreenPoint(state, viewport, point);
        return RuntimeMouseCursorFrame{findRuntimeTerrainCellAt(state, {cell.x, cell.y})
            ? 31 + (phase % 10) : 41, 27, 21};
    }
    if (target != nullptr && runtimeSelectedFactoryCanBePrimary(state, *target)) {
        return RuntimeMouseCursorFrame{110 + (phase % 9), 27, 21};
    }
    if (runtimeCursorOverSelectedSecondaryAction(state, viewport, point)) {
        if (target != nullptr && runtimeInfantryAbsorberType(state, *target) != nullptr) {
            return RuntimeMouseCursorFrame{413 + (phase % 9), 27, 21};
        }
        return RuntimeMouseCursorFrame{110 + (phase % 9), 27, 21};
    }
    const auto terrainWallTarget = visibleTerrainWallTargetAtPoint(state, viewport, point);
    if (terrainWallTarget) target = &*terrainWallTarget;
    if (target != nullptr
        && !selectionContains(state, target->instanceId)
        && !state.selectedObjectIds.empty()) {
        switch (runtimeTargetCursorIntent(state, *target)) {
        case RuntimeTargetCursorIntent::Attack:
        case RuntimeTargetCursorIntent::MindControl:
            return RuntimeMouseCursorFrame{53 + (phase % 5), 27, 21};
        case RuntimeTargetCursorIntent::AttackOutOfRange:
            return RuntimeMouseCursorFrame{58 + (phase % 5), 27, 21};
        case RuntimeTargetCursorIntent::InfantryAbsorb:
            // Original YR MouseClass::Cursors[0x49]: frame 422, count 9, interval 4.
            return RuntimeMouseCursorFrame{422 + (phase % 9), 27, 21};
        case RuntimeTargetCursorIntent::Enter:
        case RuntimeTargetCursorIntent::Capture:
            return RuntimeMouseCursorFrame{89 + (phase % 10), 27, 21};
        case RuntimeTargetCursorIntent::UnitRepair:
        case RuntimeTargetCursorIntent::EngineerRepair:
            return RuntimeMouseCursorFrame{150 + runtimeRepairCursorPhase(state), 27, 21};
        case RuntimeTargetCursorIntent::InfantryHeal:
            return RuntimeMouseCursorFrame{355, 27, 21};
        case RuntimeTargetCursorIntent::IvanBomb:
            return RuntimeMouseCursorFrame{204 + (phase % 5), 27, 21};
        case RuntimeTargetCursorIntent::Disarm:
            return RuntimeMouseCursorFrame{369, 27, 21};
        case RuntimeTargetCursorIntent::Disguise:
            return RuntimeMouseCursorFrame{199 + (phase % 4), 27, 21};
        case RuntimeTargetCursorIntent::C4:
            return RuntimeMouseCursorFrame{309 + (phase % 10), 27, 21};
        case RuntimeTargetCursorIntent::NoEnter:
            return RuntimeMouseCursorFrame{99, 27, 21};
        case RuntimeTargetCursorIntent::NoAction:
            return RuntimeMouseCursorFrame{41, 27, 21};
        }
    }
    if (selectedMovableObjectCount(state) > 0) {
        const POINT cell = approximateCellFromScreenPoint(state, viewport, point);
        if (runtimeSelectionOffersHarvestCursor(state, {cell.x, cell.y}))
            return RuntimeMouseCursorFrame{53 + (phase % 5), 27, 21};
        const bool allowed = std::any_of(state.selectedObjectIds.begin(), state.selectedObjectIds.end(), [&](int id) {
            const auto* actor = findObjectById(state, id);
            return actor && (runtimeObjectCanReceiveMoveCommand(state, *actor)
                    || (actor->owner == state.economy.owner
                        && (runtimeStructureCanRepack(state, *actor)
                            || runtimeStructureIsRepacking(*actor))))
                && runtimeObjectAllowsMoveToCell(state, *actor, {cell.x, cell.y});
        });
        return RuntimeMouseCursorFrame{allowed ? 31 + (phase % 10) : 41, 27, 21};
    }
    return RuntimeMouseCursorFrame{0, 0, 0};
}

void drawRuntimeMouseCursorOverlay(
    HDC dc,
    const RECT& clientRect,
    RuntimeWindowState& state,
    const RECT* clipRect = nullptr
) {
    const std::optional<RuntimeMouseCursorFrame> cursor =
        runtimeMouseCursorFrameForPoint(
            state,
            clientRect,
            state.mouseClientPoint
        );
    if (!cursor.has_value()) {
        return;
    }

    RuntimeUiShpCacheEntry* image = loadRuntimeUiShpFrame(
        state,
        "",
        cursor->atlasId,
        cursor->frameIndex
    );
    RuntimeMouseCursorFrame fallbackCursor = *cursor;
    if (image == nullptr && cursor->atlasId != "mouse") {
        fallbackCursor.atlasId = "mouse";
        image = loadRuntimeUiShpFrame(
            state,
            "",
            fallbackCursor.atlasId,
            fallbackCursor.frameIndex
        );
    }
    if (image == nullptr && cursor->frameIndex != 0) {
        fallbackCursor = RuntimeMouseCursorFrame{0, 0, 0};
        image = loadRuntimeUiShpFrame(state, "", "mouse", 0);
    }
    const std::vector<RuntimePaletteColor>* palette =
        runtimeUiPaletteForEntry(state, image, "mousepal");
    if (image == nullptr || palette == nullptr) {
        return;
    }

    const RECT cursorRect = runtimeMouseCursorImageRect(
        state.mouseClientPoint,
        fallbackCursor,
        image->image
    );
    int savedDc = 0;
    if (clipRect != nullptr) {
        RECT overlap{};
        if (!IntersectRect(&overlap, &cursorRect, clipRect)) return;
        savedDc = SaveDC(dc);
        if (savedDc == 0) return;
        IntersectClipRect(dc, overlap.left, overlap.top, overlap.right, overlap.bottom);
    }
    // The direct-pixel path does not consult the HDC clip region.
    const RuntimePixelSurfaceTarget target = clipRect == nullptr
        ? runtimePixelSurfaceTargetForDc(state, dc) : RuntimePixelSurfaceTarget{};
    drawRuntimeIndexedImage(
        dc,
        cursorRect,
        image->image,
        *palette,
        true,
        false,
        true,
        target.pixels,
        target.width,
        target.height,
        false,
        runtimeIndexedOpaqueAlpha,
        image->pcxFallback,
        image->pcxFallback
    );
    if (savedDc != 0) RestoreDC(dc, savedDc);
}

