struct RuntimeMenuBackgroundLayout {
    const char* imageId = "bkgdmd.shp";
    RECT contentRect{0, 0, 0, 0};
    RECT imageRect{0, 0, 0, 0};
};

RuntimeMenuBackgroundLayout runtimeMenuBackgroundLayout(
    const RECT& clientRect
) {
    constexpr int actionBarHeight = 32;
    const int clientWidth = clientRect.right - clientRect.left;
    const int clientHeight = clientRect.bottom - clientRect.top;
    RuntimeMenuBackgroundLayout layout;
    int imageWidth = 856;
    int imageHeight = 736;
    layout.imageId = "bkgdlg.shp";
    if (clientWidth < 800 || clientHeight < 600) {
        layout.imageId = "bkgdsm.shp";
        imageWidth = 472;
        imageHeight = 448;
    } else if (clientWidth < 1024 || clientHeight < 768) {
        layout.imageId = "bkgdmd.shp";
        imageWidth = 632;
        imageHeight = 568;
    }
    layout.contentRect = {
        clientRect.left,
        clientRect.top,
        std::max(clientRect.left, clientRect.right - runtimeSidebarWidth),
        std::max(clientRect.top, clientRect.bottom - actionBarHeight)
    };
    const int contentWidth =
        layout.contentRect.right - layout.contentRect.left;
    const int contentHeight =
        layout.contentRect.bottom - layout.contentRect.top;
    const int left = layout.contentRect.left
        + ((contentWidth - imageWidth) / 2);
    const int top = layout.contentRect.top
        + ((contentHeight - imageHeight) / 2);
    layout.imageRect = {
        left,
        top,
        left + imageWidth,
        top + imageHeight
    };
    return layout;
}

struct RuntimeMenuDialogLayout {
    const char* imageId = "pudlgbgn.shp";
    const char* paletteId = "dialogn";
    RECT imageRect{0, 0, 0, 0};
};

RuntimeMenuDialogLayout runtimeMenuDialogLayout(
    const RuntimeWindowState& state,
    const RECT& clientRect
) {
    RuntimeMenuDialogLayout dialog;
    std::string country;
    if (!state.economy.owner.empty()) {
        country = toUpperAsciiLocal(
            trimAsciiLocal(
                runtimeCountryForOwner(state, state.economy.owner)
            )
        );
    }
    if (country.empty()) {
        country = toUpperAsciiLocal(
            trimAsciiLocal(state.config.playerCountry)
        );
    }

    int imageWidth = 451;
    constexpr int imageHeight = 326;
    if (country == "YURI" || country == "YURICOUNTRY") {
        dialog.imageId = "pudlgbgy.shp";
        dialog.paletteId = "dialogy";
        imageWidth = 452;
    } else if (country == "RUSSIANS"
        || country == "CONFEDERATION"
        || country == "AFRICANS"
        || country == "ARABS"
        || country == "SOVIET") {
        dialog.imageId = "pudlgbgs.shp";
        dialog.paletteId = "dialog";
    } else if (!country.empty()) {
        dialog.imageId = "pudlgbga.shp";
        dialog.paletteId = "dialog";
    }

    const RuntimeMenuBackgroundLayout background =
        runtimeMenuBackgroundLayout(clientRect);
    const int contentWidth =
        background.contentRect.right - background.contentRect.left;
    const int contentHeight =
        background.contentRect.bottom - background.contentRect.top;
    const int left = background.contentRect.left
        + ((contentWidth - imageWidth) / 2);
    const int top = background.contentRect.top
        + ((contentHeight - imageHeight) / 2);
    dialog.imageRect = {
        left,
        top,
        left + imageWidth,
        top + imageHeight
    };
    return dialog;
}

struct RuntimeKeyboardBindingDefinition {
    const char* id = "";
    int defaultKey = 0;
    RuntimeMenuAction action = RuntimeMenuAction::None;
};

const std::array<RuntimeKeyboardBindingDefinition, 6>&
runtimeKeyboardBindingDefinitions() {
    static const std::array<RuntimeKeyboardBindingDefinition, 6> definitions{{
        {"Options", VK_ESCAPE, RuntimeMenuAction::RebindOptions},
        {"StopObject", 'S', RuntimeMenuAction::RebindStopObject},
        {"GuardObject", 'G', RuntimeMenuAction::RebindGuardObject},
        {"ScatterObject", 'X', RuntimeMenuAction::RebindScatterObject},
        {"DeployObject", 'D', RuntimeMenuAction::RebindDeployObject},
        {"CenterView", VK_CLEAR, RuntimeMenuAction::RebindCenterView}
    }};
    return definitions;
}

int runtimeKeyboardBindingIndexForAction(RuntimeMenuAction action) {
    const int index=static_cast<int>(action)-4096;
    if (index>=6 && index<6+static_cast<int>(runtimePlayerCommandBindings().size())) return index;
    const auto& definitions = runtimeKeyboardBindingDefinitions();
    for (std::size_t index = 0; index < definitions.size(); ++index) {
        if (definitions[index].action == action) {
            return static_cast<int>(index);
        }
    }
    return -1;
}

#include "ui/input/RuntimeKeyboardMenu.inl"

void ensureRuntimeMenuKeyboardLoaded(RuntimeWindowState& state) {
    if (state.runtimeMenuKeyboardLoadAttempted) {
        return;
    }
    state.runtimeMenuKeyboardLoadAttempted = true;
    const auto& definitions = runtimeKeyboardBindingDefinitions();
    state.runtimeMenuKeyboardBindings.clear();
    state.runtimeMenuKeyboardBindings.reserve(definitions.size());
    for (const RuntimeKeyboardBindingDefinition& definition : definitions) {
        state.runtimeMenuKeyboardBindings.emplace_back(
            definition.id,
            definition.defaultKey
        );
    }
    for (const auto& binding : runtimePlayerCommandBindings())
        state.runtimeMenuKeyboardBindings.push_back(binding);
    state.runtimeMenuKeyboardSource = "built-in retail defaults";

    const std::filesystem::path candidates[] = {
        std::filesystem::path(state.config.resourceRootPath)
            / "GameMD" / "keyboardmd.ini",
        std::filesystem::path(state.config.resourceRootPath)
            / "keyboardmd.ini",
        std::filesystem::path(state.config.localDataRootPath)
            / "resources" / "mix_exports" / "langmd" / "keyboardmd.ini"
    };
    for (const std::filesystem::path& candidate : candidates) {
        std::error_code errorCode;
        if (!std::filesystem::exists(candidate, errorCode)
            || !std::filesystem::is_regular_file(candidate, errorCode)) {
            continue;
        }
        IniFile keyboard;
        if (!keyboard.loadFromFile(pathString(candidate))) {
            continue;
        }
        bool loadedAny = false;
        for (std::size_t index = 0; index < state.runtimeMenuKeyboardBindings.size(); ++index) {
            const auto& definitionId = state.runtimeMenuKeyboardBindings[index].first;
            const std::string raw = keyboard.getValue(
                "Hotkey",
                definitionId,
                ""
            );
            if (trimAsciiLocal(raw).empty()) {
                continue;
            }
            const int keyCode = parseRuntimeIntOrDefault(raw, 0);
            if (!runtimePlayerValidKeyCode(keyCode)) {
                continue;
            }
            state.runtimeMenuKeyboardBindings[index].second = keyCode;
            loadedAny = true;
        }
        if (loadedAny) {
            state.runtimeMenuKeyboardSource = pathString(candidate);
            break;
        }
    }

    for (const auto& [configuredId, configuredKey] :
            state.config.keyBindings) {
        if (!runtimePlayerValidKeyCode(configuredKey)) {
            continue;
        }
        const std::string wanted = toLowerAsciiLocal(
            trimAsciiLocal(configuredId)
        );
        for (auto& [id, keyCode] : state.runtimeMenuKeyboardBindings) {
            if (toLowerAsciiLocal(id) == wanted) {
                const int previous=keyCode;
                for (auto& other:state.runtimeMenuKeyboardBindings)
                    if (other.first!=id && other.second==configuredKey) other.second=previous;
                keyCode = configuredKey;
                break;
            }
        }
    }
    // Migrate older INI/persisted bindings once. The supplied reference wins all
    // conflicts; subsequent edits saved from this layout remain configurable.
    if (!state.config.keyboardReferenceLayout) {
        state.runtimeMenuKeyboardBindings.clear();
        for (const auto& definition : definitions)
            state.runtimeMenuKeyboardBindings.emplace_back(definition.id, definition.defaultKey);
        for (const auto& binding : runtimePlayerCommandBindings())
            state.runtimeMenuKeyboardBindings.push_back(binding);
        state.config.keyboardReferenceLayout = true;
        state.config.keyBindings = state.runtimeMenuKeyboardBindings;
        state.runtimeMenuKeyboardSource = "reference keyboard layout 20260913";
    }
}

int runtimeMenuKeyboardBindingCode(
    RuntimeWindowState& state,
    const std::string& id,
    int fallback
) {
    ensureRuntimeMenuKeyboardLoaded(state);
    const std::string wanted = toLowerAsciiLocal(trimAsciiLocal(id));
    for (const auto& [bindingId, keyCode] :
            state.runtimeMenuKeyboardBindings) {
        if (toLowerAsciiLocal(bindingId) == wanted) {
            return keyCode;
        }
    }
    return fallback;
}

std::wstring runtimeKeyboardKeyName(int keyCode) {
    if ((keyCode & ~0xff) != 0) {
        std::wstring prefix;
        if (keyCode & runtimePlayerControlKey) prefix += L"Ctrl+";
        if (keyCode & runtimePlayerShiftKey) prefix += L"Shift+";
        if (keyCode & runtimePlayerAltKey) prefix += L"Alt+";
        return prefix + runtimeKeyboardKeyName(keyCode & 0xff);
    }
    if (keyCode >= 'A' && keyCode <= 'Z') {
        return std::wstring(1, static_cast<wchar_t>(keyCode));
    }
    if (keyCode >= '0' && keyCode <= '9') {
        return std::wstring(1, static_cast<wchar_t>(keyCode));
    }
    if (keyCode >= VK_F1 && keyCode <= VK_F24) {
        return L"F" + std::to_wstring(keyCode - VK_F1 + 1);
    }
    switch (keyCode) {
    case VK_ESCAPE: return L"Esc";
    case VK_RETURN: return L"Enter";
    case VK_SPACE: return L"Space";
    case VK_TAB: return L"Tab";
    case VK_BACK: return L"Backspace";
    case VK_DELETE: return L"Delete";
    case VK_INSERT: return L"Insert";
    case VK_HOME: return L"Home";
    case VK_END: return L"End";
    case VK_PRIOR: return L"Page Up";
    case VK_NEXT: return L"Page Down";
    case VK_LEFT: return L"Left";
    case VK_RIGHT: return L"Right";
    case VK_UP: return L"Up";
    case VK_DOWN: return L"Down";
    case VK_CLEAR: return L"Num 5";
    default:
        break;
    }

    const UINT scanCode = MapVirtualKeyW(
        static_cast<UINT>(keyCode),
        MAPVK_VK_TO_VSC
    );
    if (scanCode != 0U) {
        LONG keyNameCode = static_cast<LONG>(scanCode << 16U);
        if (keyCode == VK_INSERT || keyCode == VK_DELETE
            || keyCode == VK_HOME || keyCode == VK_END
            || keyCode == VK_PRIOR || keyCode == VK_NEXT
            || keyCode == VK_LEFT || keyCode == VK_RIGHT
            || keyCode == VK_UP || keyCode == VK_DOWN) {
            keyNameCode |= (1L << 24);
        }
        wchar_t name[64] = {};
        if (GetKeyNameTextW(keyNameCode, name, 64) > 0) {
            return name;
        }
    }
    return L"Key " + std::to_wstring(keyCode);
}

void applyRuntimeConfigPreferences(RuntimeWindowState& state) {
    state.runtimeScrollRate = std::clamp(state.config.scrollRate, 0, 6);
    state.runtimeVisualDetail = std::clamp(state.config.visualDetail, 0, 2);
    state.runtimeTooltipsEnabled = state.config.tooltipsEnabled;
    state.runtimeTargetLinesEnabled = state.config.targetLinesEnabled;
    state.runtimeScrollCoastingEnabled = state.config.scrollCoastingEnabled;
    state.runtimeMusicEnabled = state.config.musicEnabled;
    state.runtimeSoundEffectsEnabled = state.config.soundEffectsEnabled;
    state.runtimeMusicVolume = std::clamp(state.config.musicVolume, 0, 100);
    state.runtimeSoundVolume = std::clamp(state.config.soundVolume, 0, 100);
    state.runtimeVoiceVolume = std::clamp(state.config.voiceVolume, 0, 100);
}

void syncRuntimeMenuPreferencesToConfig(RuntimeWindowState& state) {
    state.config.scrollRate = std::clamp(state.runtimeScrollRate, 0, 6);
    state.config.visualDetail = std::clamp(state.runtimeVisualDetail, 0, 2);
    state.config.tooltipsEnabled = state.runtimeTooltipsEnabled;
    state.config.targetLinesEnabled = state.runtimeTargetLinesEnabled;
    state.config.scrollCoastingEnabled = state.runtimeScrollCoastingEnabled;
    state.config.musicEnabled = state.runtimeMusicEnabled;
    state.config.soundEffectsEnabled = state.runtimeSoundEffectsEnabled;
    state.config.musicVolume = std::clamp(state.runtimeMusicVolume, 0, 100);
    state.config.soundVolume = std::clamp(state.runtimeSoundVolume, 0, 100);
    state.config.voiceVolume = std::clamp(state.runtimeVoiceVolume, 0, 100);
    ensureRuntimeMenuKeyboardLoaded(state);
    state.config.keyBindings = state.runtimeMenuKeyboardBindings;
}

bool persistRuntimeMenuPreferences(RuntimeWindowState& state) {
    syncRuntimeMenuPreferencesToConfig(state);
    if (!state.runtimePreferencePersistenceEnabled) {
        return true;
    }
    std::string errorMessage;
    if (saveRuntimeConfigPreferences(state.config, errorMessage)) {
        return true;
    }
    state.runtimeMenuStatus = L"Could not save settings: "
        + widenUtf8(errorMessage);
    state.interactionStatus = "settings save failed: " + errorMessage;
    return false;
}

void copyRuntimePlayerPreferences(
    const RuntimeConfig& source,
    RuntimeConfig& destination
) {
    destination.windowWidth = source.windowWidth;
    destination.windowHeight = source.windowHeight;
    destination.targetFps = source.targetFps;
    destination.gameSpeed = source.gameSpeed;
    destination.scrollRate = source.scrollRate;
    destination.visualDetail = source.visualDetail;
    destination.tooltipsEnabled = source.tooltipsEnabled;
    destination.targetLinesEnabled = source.targetLinesEnabled;
    destination.scrollCoastingEnabled = source.scrollCoastingEnabled;
    destination.seeHiddenObjects = source.seeHiddenObjects;
    destination.musicEnabled = source.musicEnabled;
    destination.soundEffectsEnabled = source.soundEffectsEnabled;
    destination.musicVolume = source.musicVolume;
    destination.soundVolume = source.soundVolume;
    destination.voiceVolume = source.voiceVolume;
    destination.keyBindings = source.keyBindings;
    destination.keyboardReferenceLayout = source.keyboardReferenceLayout;
}

