    int oreGrowthProbeAfterBails = 0;
    int oreInitialSeeded = 0;
    int oreInitialDensified = 0;
    int oreInitialFootprintOverlapCells = 0;
    int oreGrowthProbeEventTick = 0;
    int oreGrowthProbeRingChanges = 0;
    bool oreGrowthProbeOverlayOk = false;
    RuntimeCellPoint oreGrowthProbeSampleCell{-1, -1};
