    std::string oreArtSpawnProbeType;
    std::string oreArtSpawnProbeFamily;
    int oreArtSpawnProbeBails = 0;
    int oreArtSpawnProbeSpawnBails = 0;
    int oreArtSpawnProbeSpreadRadius = -1;
    int oreArtSpawnProbeRadiusCenterBails = 0;
    int oreArtSpawnProbeRadiusNeighborCells = 0;
