    const int cameraHalfTileWidth = std::max(1, state.camera.tileWidth / 2);
    const int cameraHalfTileHeight = std::max(1, state.camera.tileHeight / 2);
    const auto appendExpectedCameraCell = [&](RuntimeCameraWorldBounds& bounds,
                                               const TerrainCell& terrain) {
        const int projectedX =
            ((terrain.x - terrain.y) * state.camera.tileWidth) / 2;
        const int projectedY =
            ((terrain.x + terrain.y) * state.camera.tileHeight) / 2
            - ((terrain.level * state.camera.tileHeight) / 2);
        const RuntimeCameraWorldBounds cellBounds{
            projectedX - cameraHalfTileWidth,
            projectedY - cameraHalfTileHeight,
            projectedX + cameraHalfTileWidth,
            projectedY + cameraHalfTileHeight,
            true
        };
        if (!bounds.valid) {
            bounds = cellBounds;
            return;
        }
        bounds.left = std::min(bounds.left, cellBounds.left);
        bounds.top = std::min(bounds.top, cellBounds.top);
        bounds.right = std::max(bounds.right, cellBounds.right);
        bounds.bottom = std::max(bounds.bottom, cellBounds.bottom);
    };
