        // 25 leptons/rule frame * Faster=1.2 gives exactly 256 ticks
        // over 15 cells. Preserve the fractional carry across every cell.
        int elapsed = 0;
        for (const int interval : intervals) elapsed += interval;
        if (elapsed != 256 || std::abs(timing.moveIntervalRemainderQ16) > 1) {
            return fail("fractional Faster lost retail Q16 cadence");
        }
        // At 1 Hz the same speed would need less than one tick per cell.
        // Keep the simulation's one-tick floor without accumulating debt.
        state.config.fixedTickHz = 1;
        timing.moveIntervalRemainderQ16 = 0;
