        state.world.accessObjects()[0].chargeTurretStartTick = 654;
        RuntimeObjectBehavior savedBehavior;
        savedBehavior.kind = RuntimeBehaviorKind::Move;
        savedBehavior.state = RuntimeBehaviorState::Moving;
        savedBehavior.moveTarget = {4, 1};
        savedBehavior.moveCooldownTicks = 2;
