        const std::string savedText{
            std::istreambuf_iterator<char>(savedInput),
            std::istreambuf_iterator<char>()
        };
        const bool savedReadFailed =
            !savedInput.good() && !savedInput.eof();
        savedInput.close();
        const std::size_t objectsSection = savedText.find("[Objects]");
        const std::size_t recordKey = objectsSection == std::string::npos
            ? std::string::npos
            : savedText.find("\n0=", objectsSection);
        const std::size_t recordValueBegin = recordKey == std::string::npos
            ? std::string::npos
            : recordKey + 3U;
        const std::size_t recordLineEnd = recordValueBegin == std::string::npos
            ? std::string::npos
            : savedText.find('\n', recordValueBegin);
        std::size_t recordValueEnd = recordLineEnd;
        if (recordValueEnd != std::string::npos
            && recordValueEnd > recordValueBegin
            && savedText[recordValueEnd - 1U] == '\r') {
            --recordValueEnd;
        }
        if (savedReadFailed) {
            return fail("could not read the XP save record");
        }
        if (recordValueBegin == std::string::npos
            || recordValueEnd == std::string::npos
            || recordValueEnd <= recordValueBegin) {
            return fail("XP save omitted the object record");
        }
        const std::string objectRecord = savedText.substr(
            recordValueBegin,
            recordValueEnd - recordValueBegin
        );
        const std::vector<std::string> objectTokens =
            splitRuntimeSaveFields(objectRecord);
        const std::size_t behaviorsSection = savedText.find("[Behaviors]");
        const std::size_t behaviorKey =
            behaviorsSection == std::string::npos
                ? std::string::npos
                : savedText.find("\n0=", behaviorsSection);
        const std::size_t behaviorValueBegin =
            behaviorKey == std::string::npos
                ? std::string::npos
                : behaviorKey + 3U;
        const std::size_t behaviorLineEnd =
            behaviorValueBegin == std::string::npos
                ? std::string::npos
                : savedText.find('\n', behaviorValueBegin);
        std::size_t behaviorValueEnd = behaviorLineEnd;
        if (behaviorValueEnd != std::string::npos
            && behaviorValueEnd > behaviorValueBegin
            && savedText[behaviorValueEnd - 1U] == '\r') {
            --behaviorValueEnd;
        }
        const std::vector<std::string> behaviorTokens =
            behaviorValueBegin == std::string::npos
                || behaviorValueEnd == std::string::npos
                || behaviorValueEnd <= behaviorValueBegin
                ? std::vector<std::string>{}
                : splitRuntimeSaveFields(savedText.substr(
                    behaviorValueBegin,
                    behaviorValueEnd - behaviorValueBegin
                ));
        if (objectTokens.size() < 50U
            || parseRuntimeIntOrDefault(objectTokens[20], -1) != 1
            || parseRuntimeIntOrDefault(objectTokens[34], -1) != 123
            || parseRuntimeIntOrDefault(objectTokens[42], -1) != 456
            || parseRuntimeIntOrDefault(objectTokens[43], -1) != 789
            || parseRuntimeIntOrDefault(objectTokens[48], -2) != 321
            || parseRuntimeIntOrDefault(objectTokens[49], -2) != 654
            || behaviorTokens.size() != 12U
            || parseRuntimeIntOrDefault(behaviorTokens[11], 0) != -32768) {
            return fail("save did not preserve XP, movement timing, or deployment timing");
        }

        state.world.accessObjects()[0].veterancy = 0;
        state.world.accessObjects()[0].veterancyExperience = 0;
        state.world.accessObjects()[0].specialCashNextTick = -1;
        state.world.accessObjects()[0].specialCloneDeliveryObjectId = -1;
        state.world.accessObjects()[0].deployStateTicksRemaining = -1;
