    WeaponType disarmWeapon;
    disarmWeapon.id = "RuntimeBombDisarmSmoke";
    disarmWeapon.damage = 1;
    disarmWeapon.range = 2.0;
    disarmWeapon.projectile = ivanWeapon->projectile;
    disarmWeapon.warhead = bombDisarmWarhead->id;
    const WorldObjectInstance* disarmTarget = findObjectById(disarmProbe, 401);
