    if (std::getenv("CONCORD_COMMAND_SMOKE_HELICOPTER_GROUND_ONLY")) {
        std::string error;
        const WeaponType* groundWeapon = state.rules.findWeaponType("M60");
        const WeaponType* airWeapon = state.rules.findWeaponType("FlakWeapon");
        const ProjectileType* groundProjectile = groundWeapon
            ? state.rules.findProjectileType(groundWeapon->projectile) : nullptr;
        const ProjectileType* airProjectile = airWeapon
            ? state.rules.findProjectileType(airWeapon->projectile) : nullptr;
        if (!groundProjectile || !airProjectile || groundProjectile->aa
            || !groundProjectile->ag || !airProjectile->aa || airProjectile->ag) {
            std::cerr << "Helicopter ground smoke: original AA/AG weapons unavailable\n";
            return 1;
        }
        RuntimeProjectileEffect groundShot, airShot;
        groundShot.aa = groundProjectile->aa; groundShot.ag = groundProjectile->ag;
        airShot.aa = airProjectile->aa; airShot.ag = airProjectile->ag;
        int domainChecks = 0;
        for (const std::string type : {"SHAD", "HIND", "SCHP", "SCHD", "JUMPJET",
                "LUNR", "ZEP", "DISK", "ORCA", "BEAG", "HTNK", "E1"}) {
            WorldObjectInstance target;
            target.instanceId = -92701;
            target.type = type;
            target.alive = true;
            target.kind = state.rules.findUnitType("infantry", type)
                ? WorldObjectKind::Infantry : WorldObjectKind::Unit;
            target.owner = "RuntimeEnemy";
            const UnitType* unit = findRuntimeUnitType(state.rules, target);
            if (!unit) { std::cerr << "Helicopter ground smoke: missing " << type << '\n'; return 1; }
            target.health = unit->strength;
            for (bool flying : {false, true}) {
                target.airborne = flying;
                if (runtimeObjectIsAirTarget(state, target) != flying
                    || runtimeWeaponCanTargetObject(state, *groundWeapon, target) == flying
                    || runtimeWeaponCanTargetObject(state, *airWeapon, target) != flying
                    || runtimeProjectileCanHitTarget(state, groundShot, target) == flying
                    || runtimeProjectileCanHitTarget(state, airShot, target) != flying) {
                    std::cerr << "Helicopter ground smoke: original weapon/projectile domain "
                              << type << " airborne=" << flying << '\n';
                    return 1;
                }
                domainChecks += 4;
            }
        }
        RuntimeMapRenderContext render;
        render.rules = &state.rules;
        render.art = &state.art;
        render.assetRootPath = runtimeAssetRootPath(state.config);
        render.palettePath = runtimePalettePath(state.config, state.report.map);
        render.structurePalettePath = runtimeStructurePalettePath(state.config, state.report.map);
        if (!runRuntimeJumpjetKinematicsSmoke(config, error)
            || !runRuntimeUnitIdleAnimationContractCheck(render, error)
            || !runRuntimeMovementRenderContractCheck(error)) {
            std::cerr << error << '\n'; return 1;
        }
        std::cout << "Helicopter ground smoke PASS: originalDomainChecks=" << domainChecks
                  << " naturalFlightLandingSave/groundedRotorPixels/airborneRotor/geometry=ok\n";
        return 0;
    }

