        WorldObjectInstance borisVoiceObject;
        borisVoiceObject.instanceId = 950401;
        borisVoiceObject.kind = WorldObjectKind::Infantry;
        borisVoiceObject.owner = voiceRouteProbe.economy.owner;
        borisVoiceObject.type = "BORIS";
        borisVoiceObject.health = std::max(1, borisVoiceRules->strength);
        borisVoiceObject.x = 10;
        borisVoiceObject.y = 10;
        borisVoiceObject.cell = runtimeCellKey(10, 10);
        borisVoiceObject.alive = true;
        WorldObjectInstance secondaryVoiceTarget;
