    RuntimeConfig restoredConfig = config;
    restoredConfig.defaultMapPath = menuSave.mapPath;
    restoredConfig.gameMode = menuSave.gameMode;
    restoredConfig.gameModeRulesOverride = menuSave.gameModeRulesOverride;
    restoredConfig.playerCountry = menuSave.playerCountry;
