    restoredConfig.mcvRepacks = menuSave.mcvRepacks;
    restoredConfig.crates = menuSave.crates;
    restoredConfig.superweapons = menuSave.superweapons;
    restoredConfig.buildOffAlly = menuSave.buildOffAlly;
    restoredConfig.noCooldown = menuSave.noCooldown;
    restoredConfig.playerSlots.clear();
    for (const SkirmishSavePlayerInfo& savedPlayer : menuSave.players) {
        RuntimeConfig::PlayerSlot player;
        player.enabled = savedPlayer.enabled;
        player.human = savedPlayer.human;
        player.name = savedPlayer.name;
        player.country = savedPlayer.country;
        player.color = savedPlayer.color;
        player.team = savedPlayer.team;
        player.difficulty = savedPlayer.difficulty;
        player.startPosition = savedPlayer.startPosition;
        restoredConfig.playerSlots.push_back(std::move(player));
    }
    restoredConfig.skirmishLoadSavePath = saveSmokePath;
    restoredConfig.campaignLoadSavePath.clear();

