    auto baseState = std::make_unique<RuntimeWindowState>();
    if (!configure(*baseState, false, false)) {
        return fail("baseline subsystem fixture did not initialize");
    }
    std::string errorMessage;
    const std::uint64_t baseHash = runtimeMultiplayerAuthoritativeStateHash(
        *baseState,
        errorMessage
    );
    if (baseHash == 0 || !errorMessage.empty()) {
        return fail("baseline rejected: " + errorMessage);
    }
    const bool normalSkirmishTriggerAccepted = std::any_of(
        baseState->triggers.triggers.begin(),
        baseState->triggers.triggers.end(),
        [](const RuntimeTriggerDefinition& trigger) {
            return trigger.id == "2PEAKS_ENVIRONMENT_SOUND";
        }
    );
    if (!normalSkirmishTriggerAccepted) {
        return fail("2peaks-style environment trigger fixture is missing");
    }

    auto perspectiveState = std::make_unique<RuntimeWindowState>();
    if (!configure(*perspectiveState, true, false)) {
        return fail("alternate local facade fixture did not initialize");
    }
    errorMessage.clear();
    const std::uint64_t perspectiveHash =
        runtimeMultiplayerAuthoritativeStateHash(
            *perspectiveState,
            errorMessage
        );
    if (perspectiveHash != baseHash || !errorMessage.empty()) {
        return fail("local facade changed the cross-peer hash");
    }

    auto reverseState = std::make_unique<RuntimeWindowState>();
    if (!configure(*reverseState, false, true)) {
        return fail("reverse insertion fixture did not initialize");
    }
    errorMessage.clear();
    const std::uint64_t reverseHash =
        runtimeMultiplayerAuthoritativeStateHash(
            *reverseState,
            errorMessage
        );
    if (reverseHash != baseHash || !errorMessage.empty()) {
        return fail("canonical containers retained insertion order");
    }

    std::vector<std::string> failedDomains;
    using RuntimeAuthoritativeHashMutation =
        std::function<void(RuntimeWindowState&)>;
    const std::function<void(
        const std::string&,
        const RuntimeAuthoritativeHashMutation&
    )> expectChanged = [&] (
        const std::string& domain,
        const RuntimeAuthoritativeHashMutation& mutate
    ) {
        auto probe = std::make_unique<RuntimeWindowState>();
        if (!configure(*probe, false, false)) {
            failedDomains.push_back(domain + "(fixture)");
            return;
        }
        mutate(*probe);
        std::string reason;
        const std::uint64_t hash =
            runtimeMultiplayerAuthoritativeStateHash(*probe, reason);
        if (hash == 0 || hash == baseHash || !reason.empty()) {
            failedDomains.push_back(domain);
        }
    };
    const std::function<void(
        const std::string&,
        const RuntimeAuthoritativeHashMutation&
    )> expectUnchanged = [&] (
        const std::string& domain,
        const RuntimeAuthoritativeHashMutation& mutate
    ) {
        auto probe = std::make_unique<RuntimeWindowState>();
        if (!configure(*probe, false, false)) {
            failedDomains.push_back(domain + "(fixture)");
            return;
        }
        mutate(*probe);
        std::string reason;
        const std::uint64_t hash =
            runtimeMultiplayerAuthoritativeStateHash(*probe, reason);
        if (hash != baseHash || !reason.empty()) {
            failedDomains.push_back(domain);
        }
    };

